    def _delete_workspace_runtime_children(self, task: BinarySecurityTask) -> None:
        workspace_root = Path(task.workspace_root)
        ensure_dir(workspace_root / "input")
        for folder_name in ("output", "run", "logs"):
            target = workspace_root / folder_name
            if target.exists():
                shutil.rmtree(target, ignore_errors=True)
            ensure_dir(target)
        ensure_dir(workspace_root / "run" / "upload-tmp")

    def _validate_hard_restart_cleanup(self, db: Session, task: BinarySecurityTask) -> dict[str, int]:
        if hasattr(db, "stage_items") and hasattr(db, "stage_runs") and hasattr(db, "archive_jobs") and hasattr(db, "events") and hasattr(db, "state_events"):
            checks = {
                "stage_item_count": len([row for row in db.stage_items if str(getattr(row, "task_id", "") or "").strip() == task.id]),
                "stage_run_count": len([row for row in db.stage_runs if str(getattr(row, "task_id", "") or "").strip() == task.id]),
                "archive_job_count": len([row for row in db.archive_jobs if str(getattr(row, "task_id", "") or "").strip() == task.id]),
                "timeline_event_count": len([row for row in db.events if str(getattr(row, "task_id", "") or "").strip() == task.id]),
                "state_event_count": len([row for row in db.state_events if str(getattr(row, "task_id", "") or "").strip() == task.id]),
            }
        else:
            checks = {
                "stage_item_count": int(db.query(func.count(BinarySecurityStageItem.id)).filter(BinarySecurityStageItem.task_id == task.id).scalar() or 0),
                "stage_run_count": int(db.query(func.count(BinarySecurityStageRun.id)).filter(BinarySecurityStageRun.task_id == task.id).scalar() or 0),
                "archive_job_count": int(db.query(func.count(BinarySecurityArchiveJob.id)).filter(BinarySecurityArchiveJob.task_id == task.id).scalar() or 0),
                "timeline_event_count": int(db.query(func.count(BinarySecurityEvent.id)).filter(BinarySecurityEvent.task_id == task.id).scalar() or 0),
                "state_event_count": int(db.query(func.count(BinarySecurityStateEvent.id)).filter(BinarySecurityStateEvent.task_id == task.id).scalar() or 0),
            }
        non_zero = {key: value for key, value in checks.items() if int(value or 0) > 0}
        if non_zero:
            raise ValidationError(f"硬重启清理未完成，仍有残留: {non_zero}")
        return checks

    async def _prepare_hard_restart_task(self, db: Session, task: BinarySecurityTask) -> dict[str, Any]:
        stage_sequence = self._stage_sequence_for_task(task)
        cleanup_snapshot: dict[str, Any] = {
            "requested_at": _isoformat_or_none(_now()),
            "previous_epoch": int(getattr(task, "execution_epoch", 0) or 0),
            "stage_sequence": stage_sequence,
            "downstream_refs": [],
            "orphan_downstream_refs": [],
            "deferred_downstream_refs": [],
            "remaining_downstream_refs": [],
            "service_scan_unavailable": [],
            "cleanup_partial_failed": False,
            "cleanup_counts": {},
        }
        self._invalidate_task_execution(task)
        refs, orphan_refs, scan_errors = self._retry_cleanup_refs_for_hard_restart(db, task, stage_sequence)
        cleanup_snapshot["downstream_refs"] = refs
        cleanup_snapshot["orphan_downstream_refs"] = orphan_refs
        cleanup_snapshot["service_scan_unavailable"] = scan_errors
        self._record_event(
            db,
            task,
            "task_retry_cleanup_collected",
            "清空并从头开始已收集下游清理计划",
            level="info",
            payload={
                "downstream_ref_count": len(refs),
                "orphan_ref_count": len(orphan_refs),
                "service_scan_unavailable_count": len(scan_errors),
            },
        )
        for ref in orphan_refs:
            self._record_event(
                db,
                task,
                "retry_cleanup_orphan_child_detected",
                "任务重跑识别到历史 orphan 下游子任务",
                level="warning",
                payload=ref,
            )
        for error in scan_errors:
            self._record_event(
                db,
                task,
                "task_retry_cleanup_scan_unavailable",
                "下游服务扫描不可用，可能影响历史子任务清理完整性",
                level="warning",
                payload=error,
            )
        if refs:
            await self._cleanup_downstream_refs(db, task, refs, self._service_token())
        cleanup_results = [
            dict(result)
            for result in list(getattr(self, "_last_downstream_cleanup_results", []) or [])
            if isinstance(result, dict)
        ]
        cleanup_snapshot["downstream_cleanup_results"] = cleanup_results
        deferred_refs = [dict(result) for result in cleanup_results if bool(result.get("deferred"))]
        remaining_refs = self._verify_remaining_parent_linked_downstream_refs(db, task, refs)
        cleanup_snapshot["deferred_downstream_refs"] = deferred_refs
        cleanup_snapshot["remaining_downstream_refs"] = remaining_refs
        cleanup_snapshot["remaining_downstream_count"] = len(remaining_refs)
        cleanup_snapshot["cleanup_partial_failed"] = bool(deferred_refs or remaining_refs)
        if remaining_refs:
            self._record_event(
                db,
                task,
                "task_retry_cleanup_remaining_downstream_detected",
                "清空并从头开始后仍检测到历史下游任务残留",
                level="warning",
                payload={
                    "remaining_downstream_count": len(remaining_refs),
                    "remaining_downstream_refs": remaining_refs,
                },
            )
        if cleanup_snapshot["cleanup_partial_failed"]:
            self._record_event(
                db,
                task,
                "task_retry_cleanup_partial_failed",
                "清空并从头开始存在未完全清理的下游任务，系统将暴露残留信息供排查",
                level="warning",
                payload={
                    "deferred_ref_count": len(deferred_refs),
                    "remaining_downstream_count": len(remaining_refs),
                    "service_scan_unavailable_count": len(scan_errors),
                },
            )
        self._clear_stage_outputs_from(task, stage_sequence[0], mark_stale=False)
        cleanup_snapshot["cleanup_counts"]["archive_jobs_deleted"] = self._delete_archive_children_for_stages(db, task, stage_sequence)
        cleanup_snapshot["cleanup_counts"]["stage_items_deleted"] = self._delete_stage_items_for_stages(db, task.id, stage_sequence)
        cleanup_snapshot["cleanup_counts"]["stage_runs_deleted"] = self._delete_stage_run_rows(db, task.id)
        self._delete_task_event_payload_dirs(task)
        self._delete_workspace_runtime_children(task)
        self._delete_task_summary_file(task)
        cleanup_snapshot["cleanup_counts"]["timeline_events_deleted"] = self._delete_task_timeline_rows(db, task.id)
        cleanup_snapshot["cleanup_counts"]["state_events_deleted"] = self._delete_task_state_event_rows(db, task.id)
        task.cleanup_snapshot = cleanup_snapshot
        self._validate_hard_restart_cleanup(db, task)
        self._reset_task_for_hard_restart(task)
        task.cleanup_snapshot = cleanup_snapshot
        return cleanup_snapshot

    def _expand_stage_name_aliases(self, stage_names: list[str] | tuple[str, ...]) -> list[str]:
        expanded: list[str] = []
        seen: set[str] = set()
        alias_map = {
            "dataflow_vuln_scan": ("dataflow_vuln_scan", "dataflow_analysis", "vuln_scan"),
            "dataflow_analysis": ("dataflow_analysis", "dataflow_vuln_scan"),
            "vuln_scan": ("vuln_scan", "dataflow_vuln_scan"),
        }
        for stage_name in stage_names:
            raw = str(stage_name or "").strip()
            if not raw:
                continue
            for candidate in alias_map.get(raw, (raw,)):
                if candidate not in seen:
                    seen.add(candidate)
                    expanded.append(candidate)
        return expanded

    async def _seed_work_queues(self) -> None:
        session_factory = get_session_factory()
        db = session_factory()
        try:
            await self._reconcile_work_queues(db, force=True)
        finally:
            db.close()

    async def _reconcile_work_queues(self, db: Session, *, force: bool = False) -> None:
        if not self.cfg.queue.enabled:
            return
        now = _now()
        interval = max(5, int(self.cfg.queue.reconcile_interval_seconds or 30))
        if not force and self._last_queue_reconcile_at and (now - self._last_queue_reconcile_at).total_seconds() < interval:
            return
        self._last_queue_reconcile_at = now
        (
            stale_dispatching_reclaimed,
            orphaned_owned_execution_requeued,
            stale_stage_item_reclaimed,
            stale_running_reclaimed,
            released_running_requeued,
            recovered_missing_terminal_events,
        ) = self._run_parent_reclaim_pass(db)
        idle_tail_recovered = self._recover_idle_tail_reconciliation_tasks_locked(db)
        if (
            stale_dispatching_reclaimed
            or orphaned_owned_execution_requeued
            or stale_stage_item_reclaimed
            or stale_running_reclaimed
            or released_running_requeued
            or recovered_missing_terminal_events
            or idle_tail_recovered
        ):
            # Persist the reclaimed task state before seeding Redis queues.
            # Otherwise the surrounding loop closes the session and rolls the
            # reclaim back, leaving tasks permanently stuck on dead workers.
            db.commit()
        task_queue_runtime = await get_task_queue().cleanup_dedupe_orphans(self.cfg.queue.task_queue_key)
        operation_queue_runtime = await get_task_queue().cleanup_dedupe_orphans(self.cfg.queue.operation_queue_key)
        seed_batch = max(1, int(self.cfg.queue.seed_batch_size or 20))
        pending_ids = [
            row[0]
            for row in db.query(BinarySecurityTask.id)
            .filter(
                or_(
                    BinarySecurityTask.status == "pending",
                    and_(
                        BinarySecurityTask.status == "dispatching",
                        BinarySecurityTask.lease_expires_at.isnot(None),
                        BinarySecurityTask.lease_expires_at < now,
                    ),
                    and_(
                        BinarySecurityTask.runtime_phase == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION,
                        BinarySecurityTask.status.in_(["pending", "running"]),
                    ),
                )
            )
            .order_by(BinarySecurityTask.updated_at.asc(), BinarySecurityTask.created_at.asc(), BinarySecurityTask.id.asc())
            .limit(seed_batch)
            .all()
        ]
        tail_takeover_ids = [
            str(task.id)
            for task in db.query(BinarySecurityTask)
            .filter(
                BinarySecurityTask.status.in_(["pending", "running"]),
                BinarySecurityTask.runtime_phase.in_([TASK_RUNTIME_PHASE_TAIL_RECONCILIATION, TASK_RUNTIME_PHASE_OWNED_EXECUTION]),
            )
            .order_by(BinarySecurityTask.updated_at.asc(), BinarySecurityTask.created_at.asc(), BinarySecurityTask.id.asc())
            .limit(seed_batch * 2)
            .all()
            if self._tail_requires_execution_takeover(db, task)
        ]
        pending_ids = list(dict.fromkeys([*pending_ids, *tail_takeover_ids]))
        operation_ids = [
            row[0]
            for row in db.query(BinarySecurityTaskOperation.id)
            .filter(BinarySecurityTaskOperation.status.in_(["accepted", "queued"]))
            .order_by(BinarySecurityTaskOperation.updated_at.asc(), BinarySecurityTaskOperation.created_at.asc(), BinarySecurityTaskOperation.id.asc())
            .limit(seed_batch)
            .all()
        ]
        for task_id in pending_ids:
            if task_queue_runtime.get("orphan_ids") and task_id in set(task_queue_runtime["orphan_ids"]):
                await get_task_queue().force_requeue_task(task_id)
            else:
                await get_task_queue().push_task(task_id)
        for operation_id in operation_ids:
            if operation_queue_runtime.get("orphan_ids") and operation_id in set(operation_queue_runtime["orphan_ids"]):
                await get_task_queue().force_requeue_operation(operation_id)
            else:
                await get_task_queue().push_operation(operation_id)

    def _run_parent_reclaim_pass(self, db: Session) -> tuple[bool, bool, bool, bool, bool, bool]:
        if not isinstance(db, Session):
            return (
                self._reclaim_stale_dispatching_locked(db),
                self._requeue_orphaned_owned_execution_locked(db),
                self._reclaim_stale_streaming_stage_items_locked(db),
                self._reclaim_stale_running_locked(db),
                self._requeue_released_running_locked(db),
                self._recover_missing_stage_terminal_events_locked(db),
            )
        if not self._acquire_coordinator_lease(PARENT_RECLAIM_COORDINATOR_LEASE):
            return False, False, False, False, False, False
        return (
            self._reclaim_stale_dispatching_locked(db),
            self._requeue_orphaned_owned_execution_locked(db),
            self._reclaim_stale_streaming_stage_items_locked(db),
            self._reclaim_stale_running_locked(db),
            self._requeue_released_running_locked(db),
            self._recover_missing_stage_terminal_events_locked(db),
        )

    def _recover_idle_tail_reconciliation_tasks_locked(self, db: Session) -> bool:
        rows = (
            db.query(BinarySecurityTask)
            .filter(
                BinarySecurityTask.runtime_phase == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION,
                BinarySecurityTask.status == "pending",
            )
            .all()
        )
        if not rows:
            return False
        recovered = False
        for task in rows:
            active_stage_name, active_item_count, has_downstream_refs = self._streaming_tail_active_context(db, task)
            if active_item_count > 0 or has_downstream_refs:
                continue
            next_stage = self._next_incomplete_stage(db, task)
            if next_stage and self._is_streaming_tail_stage(task, next_stage):
                continue
            previous_stage = str(task.current_stage or "").strip() or None
            self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
            task.tail_reconcile_state = "idle"
            task.dispatcher_instance_id = None
            task.dispatch_started_at = None
            task.lease_expires_at = None
            task.finished_at = None
            task.last_error = None
            if next_stage:
                task.current_stage = next_stage
            self._clear_runtime_lease(db, task.id)
            self._release_tail_reconcile_owner(task.id)
            self._record_event(
                db,
                task,
                "tail_reconciliation_released_idle",
                "流式尾段已无活跃子任务，父任务已退出 tail 收口并回到普通调度态",
                level="warning",
                stage_name=previous_stage or task.current_stage,
                payload={
                    "previous_stage": previous_stage,
                    "next_stage": next_stage,
                    "active_item_count": active_item_count,
                    "has_downstream_refs": has_downstream_refs,
                },
            )
            recovered = True
        if recovered:
            db.flush()
        return recovered

    def _should_finalize_without_entries(
        self,
        db: Session,
        task: BinarySecurityTask,
        stage_name: str,
    ) -> bool:
        normalized_stage = normalize_stage_name(stage_name)
        if normalized_stage != "entry_analysis":
            return False
        task_type = self._task_type(task)
        if task_type not in {TASK_TYPE_SOURCE, TASK_TYPE_BINARY_MODULE}:
            return False
        # Source tasks do not produce entry_count during system_analysis.
        # They must still execute entry_analysis to discover real entries.
        if task_type == TASK_TYPE_SOURCE:
            return False
        if self._stage_items(db, task.id, stage_name):
            return False
        if db.query(BinarySecurityStageRun).filter(
            BinarySecurityStageRun.task_id == task.id,
            BinarySecurityStageRun.stage_name == stage_name,
        ).first() is not None:
            return False
        metrics = dict(task.metrics or {})
        summary = dict(task.summary or {})
        entry_count = int(metrics.get("entry_count") or 0)
        if entry_count > 0:
            return False
        if summary.get("entry_results"):
            return False
        selected_modules = list(summary.get("selected_modules") or [])
        if task_type == TASK_TYPE_BINARY_MODULE and not selected_modules:
            return False
        upstream_run = db.query(BinarySecurityStageRun).filter(
            BinarySecurityStageRun.task_id == task.id,
            BinarySecurityStageRun.stage_name == "system_analysis",
        ).first()
        return upstream_run is not None and str(upstream_run.status or "").strip() == "success"

    async def sync_downstream_status(
        self,
        db: Session,
        *,
        project_id: str,
        task_id: str,
        stage_name: str | None = None,
        item_id: str | None = None,
        item_ids: list[str] | None = None,
        force: bool = False,
        token: str | None = None,
        record_request_event: bool = True,
        record_noop_events: bool = True,
        apply_state: bool = False,
    ) -> BinarySecurityActionResponse:
        task = self._task_or_404(db, project_id, task_id)
        if (
            self._task_runtime_phase(task) == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION
            and self._is_reducer_role()
            and str(task.status or "").strip().lower() == "pending"
        ):
            active_stage_name, active_item_count, has_downstream_refs = self._streaming_tail_active_context(db, task)
            if self._tail_requires_execution_takeover(db, task):
                task.status = "pending"
                task.current_stage = active_stage_name or task.current_stage
                task.dispatcher_instance_id = None
                task.dispatch_started_at = None
                task.lease_expires_at = None
                task.finished_at = None
                task.last_error = None
                self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
                task.tail_reconcile_state = "idle"
                self._clear_runtime_lease(db, task.id)
                self._release_tail_reconcile_owner(task.id)
                self._record_event(
                    db,
                    task,
                    "tail_execution_takeover_resumed",
                    "检测到尾段阶段尚未完成，已退出 reducer 收口并重新交给 worker 继续执行",
                    level="warning",
                    stage_name=task.current_stage,
                    payload={"reason": "incomplete_tail_stage"},
                )
                self._clear_task_abnormal_reason_snapshot(db, task)
                db.commit()
                self._enqueue_task(task.id)
                task = self._task_or_404(db, project_id, task_id)
            elif active_item_count > 0 or has_downstream_refs:
                task.status = "running"
                task.current_stage = active_stage_name or task.current_stage
                task.dispatcher_instance_id = None
                task.dispatch_started_at = None
                task.lease_expires_at = None
                task.finished_at = None
                task.last_error = None
                lease = self._activate_tail_reconciliation(
                    db,
                    task,
                    now_value=_now(),
                    fallback_status="pending",
                    takeover_result="sync_reclaim",
                )
                if self._runtime_lease_is_active(lease):
                    self._clear_task_abnormal_reason_snapshot(db, task)
                    db.commit()
                    task = self._task_or_404(db, project_id, task_id)
        batch_size = max(1, int(getattr(self.cfg.scheduler, "downstream_sync_batch_size", 50) or 50))
        if stage_name and stage_name not in self._stage_sequence_for_task(task):
            raise ValidationError(f"无效阶段: {stage_name}")
        if item_id and item_ids:
            raise ValidationError("item_id 与 item_ids 不能同时指定")
        items = self._task_reconcile_candidate_items(
            db,
            task,
            stage_name=stage_name,
            item_id=item_id,
            force=force,
        )
        if item_ids:
            ordered_ids = [str(current_id).strip() for current_id in list(item_ids or []) if str(current_id).strip()]
            matched = {str(item.id): item for item in items if str(item.id or "").strip()}
            items = [matched[current_id] for current_id in ordered_ids if current_id in matched]
        if item_id and not items:
            raise NotFoundError("阶段子任务不存在")
        if item_ids and not items:
            raise NotFoundError("阶段子任务不存在")
        if not item_id and not item_ids and items:
            items = sorted(
                items,
                key=lambda current_item: self._stage_item_sync_priority(current_item),
            )[:batch_size]

        if record_request_event:
            self._record_event(
                db,
                task,
                "downstream_status_sync_requested",
                "请求同步下游子任务状态",
                stage_name=stage_name,
                payload={
                    "stage_name": stage_name,
                    "item_id": item_id,
                    "item_ids": [str(item.id) for item in items] if item_ids else None,
                    "force": force,
                    "batch_size": batch_size,
                    "candidate_item_count": len(items),
                    "selected_stage_names": sorted({str(item.stage_name or "") for item in items if str(item.stage_name or "").strip()}),
                    "selected_items": len(items),
                },
            )
            db.commit()

        synced_count = 0
        skipped_count = 0
        failed_count = 0
        binding_mismatch_count = 0
        revived_count = 0
        revival_rejected_count = 0
        touched_stages: set[str] = set()
        auth_token = token or self._service_token()
        ready_items: list[BinarySecurityStageItem] = []
        for item in items:
            if self._item_needs_downstream_binding_reconcile(item):
                recovered, outcome = await self._attempt_vuln_downstream_binding_recovery(
                    db,
                    task,
                    item,
                    token=auth_token,
                    force=force,
                )
                if recovered:
                    synced_count += 1
                    touched_stages.add(item.stage_name)
                else:
                    if outcome in {"retry_not_due", "invalid_input", "failed_final", "create_failed"}:
                        skipped_count += 1
                    else:
                        failed_count += 1
                if not str(item.downstream_task_id or "").strip():
                    continue
            if not item.downstream_service or not item.downstream_task_id:
                skipped_count += 1
                if record_noop_events:
                    self._record_event(
                        db,
                        task,
                        "downstream_status_sync_skipped",
                        "跳过同步：子任务缺少下游服务或任务ID",
                        level="warning",
                        stage_name=item.stage_name,
                        item=item,
                        payload={"binding_state": self._downstream_binding_state(item)},
                    )
                continue
            ready_items.append(item)

        fetch_results = await self._run_with_limits(
            ready_items,
            lambda current_item: self._fetch_downstream_task_payload(task, current_item, auth_token),
            concurrency=self.cfg.scheduler.downstream_sync_concurrency,
            timeout_seconds=self.cfg.scheduler.downstream_request_timeout_seconds,
        )
        for item, payload, exc in fetch_results:
            item_stage_name = item.stage_name
            item_downstream_service = item.downstream_service
            item_downstream_task_id = item.downstream_task_id
            before_status = item.status
            observed_apply_state = bool(apply_state)
            sync_observed_at = _now()
            if force:
                observed_apply_state = True
            try:
                if exc is not None:
                    raise exc
                assert isinstance(payload, dict)
                if item.downstream_service == "entry_analyse":
                    payload, rebound_notice_payload = await self._reconcile_entry_payload_binding(task, item, payload, auth_token)
                    if rebound_notice_payload is not None:
                        self._record_event(
                            db,
                            task,
                            "downstream_parent_mismatch",
                            "下游子任务绑定到旧轮次阶段项，已阻断旧轮次状态回写",
                            level="warning",
                            stage_name=item.stage_name,
                            item=item,
                            payload=rebound_notice_payload,
                        )
                    if payload is None:
                        if not self._persist_child_sync_observation(
                            db,
                            task=task,
                            item=item,
                            change_source="downstream_sync",
                            sync_status="binding_mismatch",
                            synced_at=sync_observed_at,
                            error_message="下游子任务仍绑定旧轮次阶段项",
                            error_type="parent_mismatch",
                            state_applied=False,
                            extra_payload={"operation": "downstream_sync"},
                        ):
                            failed_count += 1
                            continue
                        skipped_count += 1
                        continue
                if not self._payload_matches_current_child(item, payload):
                    replacement_state = self._replacement_in_progress_state(item)
                    if not self._persist_child_sync_observation(
                        db,
                        task=task,
                        item=item,
                        change_source="downstream_sync",
                        sync_status="binding_mismatch",
                        synced_at=sync_observed_at,
                        error_message="下游状态来自旧 child，本次仅记录观测",
                        error_type="binding_mismatch",
                        state_applied=False,
                        extra_payload={"operation": "downstream_sync"},
                    ):
                        failed_count += 1
                        continue
                    binding_mismatch_count += 1
                    skipped_count += 1
                    self._record_binding_mismatch_event(
                        db,
                        task,
                        item,
                        event_type="stale_downstream_payload_ignored",
                        message="旧 child 的下游状态已忽略，不再回写当前阶段项",
                        payload=self._binding_mismatch_payload(
                            source="downstream_sync",
                            expected_downstream_task_id=self._current_downstream_task_id(item),
                            actual_downstream_task_id=self._payload_downstream_task_id(payload),
                            payload_downstream_task_id=self._payload_downstream_task_id(payload),
                        ),
                    )
                    if replacement_state["replacement_in_progress"] or replacement_state["binding_cleared"]:
                        self._record_event(
                            db,
                            task,
                            "stale_downstream_terminal_ignored",
                            "旧 child 终态在重建切换期间晚到，已忽略",
                            stage_name=item.stage_name,
                            item=item,
                            level="warning",
                            payload={
                                "downstream_service": item.downstream_service,
                                "current_downstream_task_id": self._current_downstream_task_id(item),
                                "payload_downstream_task_id": self._payload_downstream_task_id(payload),
                                "superseded": True,
                            },
                        )
                    continue
                downstream_status = str(payload.get("status") or "").lower()
                mapped_status = self._map_downstream_status(downstream_status)
                current_item_status = self._normalize_downstream_status(item.status) or str(item.status or "").strip().lower() or None
                if not observed_apply_state and stage_name and not item_id:
                    observed_apply_state = bool(
                        force
                        or str(before_status or "").strip().lower() in {"queued", "running", "dispatching", "cancelled"}
                        or mapped_status == "downstream_missing"
                    )
                observe_downstream_reconcile_observation(
                    stage=item_stage_name,
                    service=item_downstream_service,
                    result=mapped_status or downstream_status or "unknown",
                )
                if not mapped_status:
                    if not self._persist_child_sync_observation(
                        db,
                        task=task,
                        item=item,
                        change_source="downstream_sync",
                        sync_status="skipped",
                        synced_at=sync_observed_at,
                        status_raw=downstream_status or None,
                        mapped_status=None,
                        downstream_status=downstream_status or None,
                        state_applied=False,
                    ):
                        failed_count += 1
                        continue
                    skipped_count += 1
                    if record_noop_events:
                        self._record_event(
                            db,
                            task,
                            "downstream_status_sync_skipped",
                            f"跳过同步：无法识别下游状态 {downstream_status or '-'}",
                            level="warning",
                            stage_name=item.stage_name,
                            item=item,
                            payload={
                                "downstream_service": item.downstream_service,
                                "downstream_task_id": item.downstream_task_id,
                                "http_status": None,
                                "error_type": None,
                                "status_raw": downstream_status or None,
                                "mapped_status": None,
                                "state_applied": False,
                                "downstream_status": downstream_status,
                            },
                        )
                    continue
                terminal_status = mapped_status in {"success", "partial_success", "failed", "cancelled", "downstream_missing"}
                replacement_state = self._replacement_in_progress_state(item)
                if (
                    terminal_status
                    and current_item_status in {"success", "partial_success", "failed", "cancelled", "downstream_missing"}
                    and self._should_preserve_terminal_status(
                        item,
                        mapped_status=mapped_status,
                        current_item_status=current_item_status,
                        payload=payload,
                    )
                ):
                    mapped_status = current_item_status
                    downstream_status = current_item_status
                if terminal_status and current_item_status in {"success", "partial_success", "failed", "cancelled", "downstream_missing"} and mapped_status != current_item_status:
                    revival_rejected_count += 1
                if terminal_status:
                    observed_error_message = (
                        payload.get("error") or payload.get("error_message") or payload.get("message") or item.error_message
                        if mapped_status in {"failed", "cancelled", "downstream_missing"}
                        else None
                    )
                    self_healing_failure = self._is_self_healing_downstream_failure_observation(
                        mapped_status=mapped_status,
                        downstream_status=downstream_status,
                        payload=payload,
                        error_message=observed_error_message,
                        error_type=None,
                    )
                    if self_healing_failure:
                        if not self._persist_child_sync_observation(
                            db,
                            task=task,
                            item=item,
                            change_source="downstream_sync",
                            sync_status="observed",
                            synced_at=sync_observed_at,
                            error_message=observed_error_message,
                            status_raw=downstream_status,
                            mapped_status=mapped_status,
                            downstream_status=downstream_status,
                            state_applied=False,
                        ):
                            failed_count += 1
                            continue
                        if force or mapped_status != before_status or record_noop_events:
                            self._record_event(
                                db,
                                task,
                                "downstream_status_sync_skipped",
                                "下游 failed 观测属于自愈/恢复态，本次仅记录观测，不回写父任务失败状态",
                                stage_name=item.stage_name,
                                item=item,
                                level="warning",
                                payload={
                                    "downstream_service": item.downstream_service,
                                    "downstream_task_id": item.downstream_task_id,
                                    "http_status": None,
                                    "error_type": None,
                                    "status_raw": downstream_status,
                                    "mapped_status": mapped_status,
                                    "state_applied": False,
                                    "before_status": before_status,
                                    "downstream_status": downstream_status,
                                    "after_status": before_status,
                                    "self_healing_failure": True,
                                },
                            )
                        skipped_count += 1
                        continue
                    if mapped_status == "downstream_missing":
                        if normalize_stage_name(item.stage_name) == "dataflow_vuln_scan" and (
                            replacement_state["replacement_in_progress"] or replacement_state["binding_cleared"]
                        ):
                            if not self._persist_child_sync_observation(
                                db,
                                task=task,
                                item=item,
                                change_source="downstream_sync",
                                sync_status="binding_missing_during_recreate",
                                synced_at=sync_observed_at,
                                error_message="旧下游绑定在重建期间已失效，本次仅记录观测",
                                status_raw=downstream_status,
                                mapped_status="downstream_missing",
                                downstream_status=downstream_status,
                                state_applied=False,
                            ):
                                failed_count += 1
                                continue
                            skipped_count += 1
                            if force or mapped_status != before_status or record_noop_events:
                                self._record_event(
                                    db,
                                    task,
                                    "downstream_status_sync_skipped",
                                    "旧下游绑定在重建期间已失效，本次不将不存在状态回写到父任务",
                                    stage_name=item.stage_name,
                                    item=item,
                                    level="warning",
                                    payload={
                                        "downstream_service": item.downstream_service,
                                        "downstream_task_id": item.downstream_task_id,
                                        "http_status": None,
                                        "error_type": "binding_missing_during_recreate",
                                        "status_raw": downstream_status,
                                        "mapped_status": mapped_status,
                                        "state_applied": False,
                                        "before_status": before_status,
                                        "downstream_status": downstream_status,
                                        "after_status": before_status,
                                        "replacement_in_progress": True,
                                        "old_downstream_task_id": replacement_state["old_downstream_task_id"],
                                    },
                                )
                            continue
                        should_apply = observed_apply_state and (mapped_status != before_status or force)
                        if should_apply:
                            if not self._apply_child_state_with_savepoint(
                                db,
                                task=task,
                                item=item,
                                change_source="downstream_sync",
                                target_status=mapped_status,
                                sync_status="synced",
                                downstream_status_raw=downstream_status,
                                downstream_status_mapped=mapped_status,
                                downstream_status=downstream_status,
                                error_message="下游子任务不存在",
                                http_status=404,
                                error_type="not_found",
                                apply_fn=lambda: (
                                    self._enqueue_downstream_terminal_event(
                                        db,
                                        task=task,
                                        item=item,
                                        mapped_status=mapped_status,
                                        before_status=before_status,
                                        downstream_status=downstream_status,
                                        payload=payload,
                                        error_message="下游子任务不存在",
                                        http_status=None,
                                        error_type=None,
                                        status_raw=downstream_status,
                                        force=force,
                                    ),
                                    self._apply_downstream_status_inline(
                                        item,
                                        mapped_status=mapped_status,
                                        downstream_payload=payload,
                                        error_message="下游子任务不存在",
                                        synced_at=sync_observed_at,
                                    ),
                                    self._reconcile_stage_and_task_state_after_item_update(db, task, item.stage_name),
                                    self._mark_stage_item_sync_observation(
                                        item,
                                        sync_status="synced",
                                        synced_at=sync_observed_at,
                                        status_raw=downstream_status,
                                        mapped_status=mapped_status,
                                        downstream_status=downstream_status,
                                        state_applied=True,
                                    ),
                                ),
                            ):
                                failed_count += 1
                                continue
                            touched_stages.add(item.stage_name)
                            synced_count += 1
                            if current_item_status in {"pending", "queued", "dispatching", "running"}:
                                revived_count += 1
                        else:
                            if not self._persist_child_sync_observation(
                                db,
                                task=task,
                                item=item,
                                change_source="downstream_sync",
                                sync_status="skipped",
                                synced_at=sync_observed_at,
                                status_raw=downstream_status,
                                mapped_status=mapped_status,
                                downstream_status=downstream_status,
                                state_applied=False,
                            ):
                                failed_count += 1
                                continue
                            skipped_count += 1
                        if force or mapped_status != before_status or record_noop_events or not apply_state:
                            self._record_event(
                                db,
                                task,
                                "downstream_status_synced" if should_apply else "downstream_status_sync_skipped",
                                "下游子任务不存在，已更新当前阶段子任务状态" if should_apply else "下游子任务不存在，本次仅观测未写回状态",
                                stage_name=item.stage_name,
                                item=item,
                                level="warning",
                                payload={
                                    "downstream_service": item.downstream_service,
                                    "downstream_task_id": item.downstream_task_id,
                                    "http_status": None,
                                    "error_type": None,
                                    "status_raw": downstream_status,
                                    "mapped_status": mapped_status,
                                    "state_applied": bool(should_apply),
                                    "before_status": before_status,
                                    "downstream_status": downstream_status,
                                    "after_status": mapped_status,
                                },
                            )
                        continue
                    if mapped_status not in ARCHIVE_SUCCESS_MAPPED_STATUSES:
                        error_message = observed_error_message
                        sync_supervisor_state = self._read_stage_item_sync_supervisor_state(item)
                        recovered_after_errors = (
                            sync_supervisor_state.consecutive_error_count > 0
                            and str(sync_supervisor_state.last_result or "").strip() == "error"
                            and mapped_status not in {"failed", "cancelled", "downstream_missing"}
                        )
                        should_apply = observed_apply_state and (mapped_status != before_status or force)
                        if should_apply:
                            if not self._apply_child_state_with_savepoint(
                                db,
                                task=task,
                                item=item,
                                change_source="downstream_sync",
                                target_status=mapped_status,
                                sync_status="synced",
                                downstream_status_raw=downstream_status,
                                downstream_status_mapped=mapped_status,
                                downstream_status=downstream_status,
                                error_message=error_message,
                                http_status=None,
                                error_type=None,
                                apply_fn=lambda: (
                                    self._enqueue_downstream_terminal_event(
                                        db,
                                        task=task,
                                        item=item,
                                        mapped_status=mapped_status,
                                        before_status=before_status,
                                        downstream_status=downstream_status,
                                        payload=payload,
                                        error_message=error_message,
                                        http_status=None,
                                        error_type=None,
                                        status_raw=downstream_status,
                                        force=force,
                                    ),
                                    self._apply_downstream_status_inline(
                                        item,
                                        mapped_status=mapped_status,
                                        downstream_payload=payload,
                                        error_message=error_message,
                                        synced_at=sync_observed_at,
                                    ),
                                    self._reconcile_stage_and_task_state_after_item_update(db, task, item.stage_name),
                                    self._mark_stage_item_sync_observation(
                                        item,
                                        sync_status="synced",
                                        synced_at=sync_observed_at,
                                        error_message=error_message,
                                        status_raw=downstream_status,
                                        mapped_status=mapped_status,
                                        downstream_status=downstream_status,
                                        state_applied=True,
                                    ),
                                ),
                            ):
                                failed_count += 1
                                continue
                            touched_stages.add(item.stage_name)
                            synced_count += 1
                        else:
                            if not self._persist_child_sync_observation(
                                db,
                                task=task,
                                item=item,
                                change_source="downstream_sync",
                                sync_status="skipped",
                                synced_at=sync_observed_at,
                                error_message=error_message,
                                status_raw=downstream_status,
                                mapped_status=mapped_status,
                                downstream_status=downstream_status,
                                state_applied=False,
                            ):
                                failed_count += 1
                                continue
                            skipped_count += 1
                        if recovered_after_errors:
                            self._record_event(
                                db,
                                task,
                                "downstream_poll_recovered_after_errors",
                                "下游状态同步已从异常中恢复",
                                stage_name=item.stage_name,
                                item=item,
                                payload={
                                    "downstream_status": downstream_status,
                                    "downstream_task_id": item.downstream_task_id,
                                    "consecutive_error_count_before_recovery": sync_supervisor_state.consecutive_error_count,
                                },
                            )
                        if force or mapped_status != before_status or record_noop_events or not apply_state:
                            self._record_event(
                                db,
                                task,
                                "downstream_status_synced" if should_apply else "downstream_status_sync_skipped",
                                "下游终态已同步，当前子任务不再进入归档" if should_apply else "下游终态已观测，本次仅观测未写回状态",
                                stage_name=item.stage_name,
                                item=item,
                                level="warning" if mapped_status in {"failed", "cancelled"} else "info",
                                payload={
                                    "downstream_service": item.downstream_service,
                                    "downstream_task_id": item.downstream_task_id,
                                    "http_status": None,
                                    "error_type": None,
                                    "status_raw": downstream_status,
                                    "mapped_status": mapped_status,
                                    "state_applied": bool(should_apply),
                                    "before_status": before_status,
                                    "downstream_status": downstream_status,
                                    "after_status": mapped_status,
                                    "archive_skipped": True,
                                },
                            )
                        continue
                    job = self._ensure_downstream_archive_job(
                        db,
                        task,
                        item,
                        payload=payload,
                        mapped_status=mapped_status,
                        before_status=before_status,
                        force=force,
                    )
                    if job.archive_status == "success":
                        # The archive job may already have finished in an earlier
                        # reconcile pass while the item/stage/task state was not
                        # fully applied back to the orchestrator. Re-apply the
                        # persisted archive result idempotently so the main task
                        # can leave the stale running state.
                        db.commit()
                        await self._apply_archive_job_status(job.id, job.archive_root)
                        db.expire_all()
                        refreshed_item = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.id == item.id).first()
                        if refreshed_item is not None:
                            if not self._persist_child_sync_observation(
                                db,
                                task=task,
                                item=refreshed_item,
                                change_source="downstream_sync",
                                sync_status="synced",
                                synced_at=sync_observed_at,
                                status_raw=downstream_status,
                                mapped_status=mapped_status,
                                downstream_status=downstream_status,
                                state_applied=True,
                            ):
                                failed_count += 1
                                continue
                        touched_stages.add(item.stage_name)
                        synced_count += 1
                        continue
                    if job.archive_status == "failed":
                        if not self._persist_child_sync_observation(
                            db,
                            task=task,
                            item=item,
                            change_source="downstream_sync",
                            sync_status="skipped",
                            synced_at=sync_observed_at,
                            status_raw=downstream_status,
                            mapped_status=mapped_status,
                            downstream_status=downstream_status,
                            state_applied=False,
                        ):
                            failed_count += 1
                            continue
                        if force or mapped_status != before_status or record_noop_events:
                            self._record_event(
                                db,
                                task,
                                "downstream_status_sync_skipped",
                                "下游状态已获取，但当前阶段的归档失败需要人工处理；不会自动重新排队",
                                stage_name=item.stage_name,
                                item=item,
                                level="warning",
                                payload={
                                    "archive_job_id": job.id,
                                    "archive_status": job.archive_status,
                                    "downstream_service": item.downstream_service,
                                    "downstream_task_id": item.downstream_task_id,
                                    "http_status": None,
                                    "error_type": None,
                                    "status_raw": downstream_status,
                                    "mapped_status": mapped_status,
                                    "state_applied": False,
                                    "downstream_status": downstream_status,
                                    "archive_retry_required": True,
                                },
                            )
                        skipped_count += 1
                        continue
                    if record_noop_events or force or mapped_status != before_status:
                        if not self._persist_child_sync_observation(
                            db,
                            task=task,
                            item=item,
                            change_source="downstream_sync",
                            sync_status="skipped",
                            synced_at=sync_observed_at,
                            status_raw=downstream_status,
                            mapped_status=mapped_status,
                            downstream_status=downstream_status,
                            state_applied=False,
                        ):
                            failed_count += 1
                            continue
                        self._record_event(
                            db,
                            task,
                            "downstream_archive_job_queued" if job.archive_status in {"pending", "running"} else "downstream_archive_job_reused",
                            "下游状态已获取，等待产物归档完成后更新状态",
                            stage_name=item.stage_name,
                            item=item,
                            payload={
                                "archive_job_id": job.id,
                                "archive_status": job.archive_status,
                                "downstream_service": item.downstream_service,
                                "downstream_task_id": item.downstream_task_id,
                                "http_status": None,
                                "error_type": None,
                                "status_raw": downstream_status,
                                "mapped_status": mapped_status,
                                "state_applied": False,
                                "downstream_status": downstream_status,
                            },
                        )
                    touched_stages.add(item.stage_name)
                    skipped_count += 1
                    continue
                should_apply = observed_apply_state and mapped_status != before_status
                if should_apply and mapped_status in {"pending", "queued", "running"}:
                    should_apply = self._should_apply_downstream_intermediate_status(
                        item,
                        mapped_status=mapped_status,
                        payload=payload,
                    )
                if should_apply:
                    apply_error_message = None if mapped_status in {"queued", "running", "success"} else (
                        payload.get("error") or payload.get("error_message") or payload.get("message") or item.error_message
                    )
                    if not self._apply_child_state_with_savepoint(
                        db,
                        task=task,
                        item=item,
                        change_source="downstream_sync",
                        target_status=mapped_status,
                        sync_status="synced",
                        downstream_status_raw=downstream_status,
                        downstream_status_mapped=mapped_status,
                        downstream_status=downstream_status,
                        error_message=apply_error_message,
                        http_status=None,
                        error_type=None,
                        apply_fn=lambda: (
                            self._enqueue_downstream_status_event(
                                db,
                                task=task,
                                item=item,
                                mapped_status=mapped_status,
                                before_status=before_status,
                                downstream_status=downstream_status,
                                payload=payload,
                                error_message=apply_error_message,
                                http_status=None,
                                error_type=None,
                                status_raw=downstream_status,
                                force=force,
                            ),
                            self._apply_downstream_status_inline(
                                item,
                                mapped_status=mapped_status,
                                downstream_payload=payload,
                                error_message=apply_error_message,
                                synced_at=sync_observed_at,
                            ),
                            self._reconcile_stage_and_task_state_after_item_update(db, task, item.stage_name),
                            self._mark_stage_item_sync_observation(
                                item,
                                sync_status="synced",
                                synced_at=sync_observed_at,
                                error_message=apply_error_message,
                                status_raw=downstream_status,
                                mapped_status=mapped_status,
                                downstream_status=downstream_status,
                                state_applied=True,
                            ),
                        ),
                    ):
                        failed_count += 1
                        continue
                    touched_stages.add(item.stage_name)
                    synced_count += 1
                else:
                    if not self._persist_child_sync_observation(
                        db,
                        task=task,
                        item=item,
                        change_source="downstream_sync",
                        sync_status="skipped",
                        synced_at=sync_observed_at,
                        status_raw=downstream_status,
                        mapped_status=mapped_status,
                        downstream_status=downstream_status,
                        state_applied=False,
                    ):
                        failed_count += 1
                        continue
                    skipped_count += 1
                if force or mapped_status != before_status or record_noop_events or not apply_state:
                    self._record_event(
                        db,
                        task,
                        "downstream_status_synced" if should_apply else "downstream_status_sync_skipped",
                        "下游子任务状态已同步" if should_apply else "下游子任务状态已观测，本次未写回",
                        stage_name=item.stage_name,
                        item=item,
                        payload={
                            "downstream_service": item.downstream_service,
                            "downstream_task_id": item.downstream_task_id,
                            "http_status": None,
                            "error_type": None,
                            "status_raw": downstream_status,
                            "mapped_status": mapped_status,
                            "state_applied": bool(should_apply),
                            "before_status": before_status,
                            "downstream_status": downstream_status,
                            "after_status": mapped_status,
                        },
                    )
            except NotFoundError:
                # The exception is raised by downstream fetch only. Rolling the
                # whole session back here would also discard already-synced
                # sibling items from earlier loop iterations.
                replacement_state = self._replacement_in_progress_state(item)
                if normalize_stage_name(item.stage_name) == "dataflow_vuln_scan" and (
                    replacement_state["replacement_in_progress"] or replacement_state["binding_cleared"]
                ):
                    if not self._persist_child_sync_observation(
                        db,
                        task=task,
                        item=item,
                        change_source="downstream_sync",
                        sync_status="binding_missing_during_recreate",
                        error_message="旧下游绑定在重建期间已失效，本次仅记录观测",
                        http_status=404,
                        error_type="binding_missing_during_recreate",
                        status_raw="downstream_missing",
                        mapped_status="downstream_missing",
                        downstream_status="downstream_missing",
                        state_applied=False,
                    ):
                        failed_count += 1
                        continue
                    skipped_count += 1
                    self._record_event(
                        db,
                        task,
                        "downstream_status_sync_skipped",
                        "旧下游绑定在重建期间已失效，本次不将不存在状态回写到父任务",
                        level="warning",
                        stage_name=item_stage_name,
                        item=item,
                        payload={
                            "downstream_service": item_downstream_service,
                            "downstream_task_id": item_downstream_task_id,
                            "http_status": 404,
                            "error_type": "binding_missing_during_recreate",
                            "status_raw": "downstream_missing",
                            "mapped_status": "downstream_missing",
                            "state_applied": False,
                            "before_status": before_status,
                            "downstream_status": "downstream_missing",
                            "after_status": before_status,
                            "replacement_in_progress": True,
                            "old_downstream_task_id": replacement_state["old_downstream_task_id"],
                        },
                    )
                    continue
                notfound_apply_state = bool(apply_state)
                if not notfound_apply_state and stage_name and not item_id:
                    notfound_apply_state = bool(
                        force
                        or str(before_status or "").strip().lower() in {"queued", "running", "dispatching"}
                    )
                if notfound_apply_state:
                    if not self._apply_child_state_with_savepoint(
                        db,
                        task=task,
                        item=item,
                        change_source="downstream_sync",
                        target_status="downstream_missing",
                        sync_status="synced",
                        downstream_status_raw="downstream_missing",
                        downstream_status_mapped="downstream_missing",
                        downstream_status="downstream_missing",
                        error_message="下游子任务不存在",
                        http_status=404,
                        error_type="not_found",
                        apply_fn=lambda: (
                            self._enqueue_downstream_terminal_event(
                                db,
                                task=task,
                                item=item,
                                mapped_status="downstream_missing",
                                before_status=before_status,
                                downstream_status="downstream_missing",
                                payload={"status": "downstream_missing", "error": "下游子任务不存在"},
                                error_message="下游子任务不存在",
                                http_status=404,
                                error_type="not_found",
                                status_raw="downstream_missing",
                                force=True,
                            ),
                            self._apply_downstream_status_inline(
                                item,
                                mapped_status="downstream_missing",
                                downstream_payload={"status": "downstream_missing", "error": "下游子任务不存在"},
                                error_message="下游子任务不存在",
                            ),
                            self._reconcile_stage_and_task_state_after_item_update(db, task, item.stage_name),
                            self._mark_stage_item_sync_observation(
                                item,
                                sync_status="synced",
                                error_message="下游子任务不存在",
                                http_status=404,
                                error_type="not_found",
                                status_raw="downstream_missing",
                                mapped_status="downstream_missing",
                                downstream_status="downstream_missing",
                                state_applied=True,
                            ),
                        ),
                    ):
                        failed_count += 1
                        continue
                    touched_stages.add(item.stage_name)
                    synced_count += 1
                else:
                    if not self._persist_child_sync_observation(
                        db,
                        task=task,
                        item=item,
                        change_source="downstream_sync",
                        sync_status="skipped",
                        error_message="下游子任务不存在",
                        http_status=404,
                        error_type="not_found",
                        status_raw="downstream_missing",
                        mapped_status="downstream_missing",
                        downstream_status="downstream_missing",
                        state_applied=False,
                    ):
                        failed_count += 1
                        continue
                    skipped_count += 1
                self._record_event(
                    db,
                    task,
                    "downstream_status_synced" if notfound_apply_state else "downstream_status_sync_skipped",
                    "下游子任务不存在，已投递 reducer 串行更新事件" if notfound_apply_state else "下游子任务不存在，本次仅观测未写回状态",
                    level="warning",
                    stage_name=item_stage_name,
                    item=item,
                    payload={
                        "downstream_service": item_downstream_service,
                        "downstream_task_id": item_downstream_task_id,
                        "http_status": 404,
                        "error_type": "not_found",
                        "status_raw": "downstream_missing",
                        "mapped_status": "downstream_missing",
                        "state_applied": bool(notfound_apply_state),
                        "before_status": before_status,
                        "downstream_status": "downstream_missing",
                        "after_status": "downstream_missing",
                    },
                )
            except Exception as exc:
                # Keep previously synchronized item updates intact; this branch
                # only records the current item's fetch failure.
                failed_count += 1
                repair_applied = False
                current_item_status = self._normalize_downstream_status(item.status) or str(item.status or "").strip().lower() or None
                item_result = self._load_stage_item_result_payload(item)
                current_observed = self._normalize_downstream_status(
                    self._string_or_none(dict(item_result.get("sync_observation") or {}).get("downstream_status"))
                )
                if current_item_status in {"success", "partial_success", "failed", "cancelled", "downstream_missing"} and current_observed in {"pending", "dispatching", "running"}:
                    repair_applied = self._repair_stage_item_terminal_downstream_observation(
                        db,
                        task,
                        item,
                        reason="sync_fetch_failed_but_item_terminal",
                    )
                    if repair_applied:
                        touched_stages.add(item.stage_name)
                if repair_applied:
                    state = DownstreamSyncSupervisorState(
                        consecutive_error_count=0,
                        budget_exhausted=False,
                        next_retry_at=None,
                        last_result="success",
                    )
                    if not self._persist_child_sync_observation(
                        db,
                        task=task,
                        item=item,
                        change_source="transport_error",
                        sync_status="synced",
                        error_message=str(exc),
                        http_status=self._extract_http_status_from_exception(exc),
                        error_type=self._classify_downstream_sync_error(exc),
                        state_applied=True,
                        extra_payload={"operation": "downstream_sync"},
                        consecutive_error_count=state.consecutive_error_count,
                        budget_exhausted=state.budget_exhausted,
                        next_retry_at=state.next_retry_at,
                        last_sync_result=state.last_result,
                    ):
                        failed_count += 1
                        continue
                elif not self._persist_downstream_sync_failure(
                    db,
                    task=task,
                    item=item,
                    error=exc,
                    change_source="transport_error",
                    operation="downstream_sync",
                    before_status=before_status,
                ):
                    failed_count += 1
                    continue
                if repair_applied:
                    self._log_child_status_event(
                        db,
                        task=task,
                        item=item,
                        event_type="child_transport_failed",
                        change_source="transport_error",
                        before_status=before_status,
                        after_status=str(item.status or "").strip().lower() or before_status,
                        sync_status="synced",
                        downstream_status_raw=None,
                        downstream_status_mapped=None,
                        downstream_status=None,
                        state_applied=True,
                        error_message=str(exc),
                        error_type=self._classify_downstream_sync_error(exc),
                        http_status=self._extract_http_status_from_exception(exc),
                        extra_payload={
                            "operation": "downstream_sync",
                            "repair_applied": True,
                        },
                    )
        for current_stage in touched_stages:
            if current_stage == "system_analysis":
                self._refresh_system_analysis_stage_from_synced_items(db, task)
            else:
                self._refresh_stage_run_from_items(db, task, current_stage)
        if touched_stages:
            self._refresh_task_status_after_sync(db, task)
            await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
        db.commit()
        response_synced_count = synced_count if apply_state else min(synced_count, len(touched_stages))
        return BinarySecurityActionResponse(
            task_id=task.id,
            message=f"下游状态同步完成：更新 {response_synced_count} 个，跳过 {skipped_count} 个，失败 {failed_count} 个，绑定不匹配 {binding_mismatch_count} 个",
            synced_downstream_count=response_synced_count,
            skipped_downstream_count=skipped_count,
            failed_downstream_count=failed_count,
            binding_mismatch_count=binding_mismatch_count,
            revived_count=revived_count,
            revival_rejected_count=revival_rejected_count,
        )

    def _persist_downstream_sync_failure(
        self,
        db: Session,
        *,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        error: Exception,
        change_source: str,
        operation: str,
        before_status: str | None = None,
    ) -> bool:
        error_type = self._classify_downstream_sync_error(error)
        observed_at = _now()
        http_status = self._extract_http_status_from_exception(error)
        is_http_429 = http_status == 429
        state = self._build_next_http_429_failure_state(item, observed_at=observed_at) if is_http_429 else self._build_next_downstream_sync_failure_state(item, observed_at=observed_at)
        sync_status = "rate_limited" if is_http_429 else "transport_error"
        persisted = self._persist_child_sync_observation(
            db,
            task=task,
            item=item,
            change_source=change_source,
            sync_status=sync_status,
            synced_at=observed_at,
            error_message=str(error),
            http_status=http_status,
            error_type=error_type,
            state_applied=False,
            extra_payload={"operation": operation, **self._downstream_sync_failure_payload(item, error_type=error_type, error_message=str(error), state=state)},
            consecutive_error_count=state.consecutive_error_count,
            budget_exhausted=state.budget_exhausted,
            next_retry_at=state.next_retry_at,
            last_sync_result="error",
        )
        if not persisted:
            return False
        failure_payload = self._downstream_sync_failure_payload(
            item,
            error_type=error_type,
            error_message=str(error),
            state=state,
        )
        self._log_child_status_event(
            db,
            task=task,
            item=item,
            event_type="downstream_http_429_retry_scheduled" if is_http_429 else "child_transport_failed",
            change_source=change_source,
            before_status=before_status or (str(item.status or "").strip().lower() or None),
            after_status=str(item.status or "").strip().lower() or before_status,
            sync_status=sync_status,
            downstream_status_raw=None,
            downstream_status_mapped=None,
            downstream_status=None,
            state_applied=False,
            error_message=str(error),
            error_type=error_type,
            http_status=http_status,
            extra_payload={
                "operation": operation,
                "retry_attempt_count": state.consecutive_error_count,
                "retry_delay_seconds": self._next_http_429_retry_backoff_seconds(state.consecutive_error_count) if is_http_429 else None,
                **failure_payload,
            },
        )
        event_type = (
            "downstream_http_429_retry_scheduled"
            if is_http_429
            else "downstream_sync_error_budget_exhausted" if state.budget_exhausted else "downstream_poll_retry_scheduled"
        )
        self._log_child_status_event(
            db,
            task=task,
            item=item,
            event_type=event_type,
            change_source=change_source,
            before_status=before_status or (str(item.status or "").strip().lower() or None),
            after_status=str(item.status or "").strip().lower() or before_status,
            sync_status=sync_status,
            downstream_status_raw=None,
            downstream_status_mapped=None,
            downstream_status=None,
            state_applied=False,
            error_message=str(error),
            error_type=error_type,
            http_status=http_status,
            extra_payload={
                "operation": operation,
                "retry_attempt_count": state.consecutive_error_count,
                "retry_delay_seconds": self._next_http_429_retry_backoff_seconds(state.consecutive_error_count) if is_http_429 else None,
                **failure_payload,
            },
        )
        return True

    def _clear_archive_jobs_for_stage_items(self, db: Session, task_id: str, stage_name: str, item_ids: list[str]) -> int:
        normalized_item_ids = [str(item_id or "").strip() for item_id in item_ids if str(item_id or "").strip()]
        if not normalized_item_ids:
            return 0
        deleted = 0
        remaining_ids = list(normalized_item_ids)
        while remaining_ids:
            current_ids = remaining_ids[:100]
            remaining_ids = remaining_ids[100:]
            for attempt in range(3):
                try:
                    with self._savepoint(db):
                        deleted += int(
                            db.query(BinarySecurityArchiveJob)
                            .filter(
                                BinarySecurityArchiveJob.task_id == task_id,
                                BinarySecurityArchiveJob.stage_name == stage_name,
                                BinarySecurityArchiveJob.item_id.in_(current_ids),
                            )
                            .delete(synchronize_session=False)
                            or 0
                        )
                    break
                except Exception as exc:
                    if attempt >= 2 or not self._is_retryable_lock_error(exc):
                        raise
                    db.rollback()
        if hasattr(db, "archive_jobs") and isinstance(getattr(db, "archive_jobs"), list):
            blocked_ids = set(normalized_item_ids)
            db.archive_jobs = [
                row for row in db.archive_jobs
                if not (
                    str(getattr(row, "task_id", "") or "").strip() == task_id
                    and str(getattr(row, "stage_name", "") or "").strip() == stage_name
                    and str(getattr(row, "item_id", "") or "").strip() in blocked_ids
                )
            ]
        return deleted

    def _clear_archive_jobs_for_stages(
        self,
        db: Session,
        task_id: str,
        stage_names: list[str],
        *,
        batch_size: int = 100,
        max_retries: int = 3,
    ) -> int:
        normalized = [str(stage_name or "").strip() for stage_name in stage_names if str(stage_name or "").strip()]
        if not normalized:
            return 0
        deleted = 0
        while True:
            job_ids = [
                row[0]
                for row in db.query(BinarySecurityArchiveJob.id)
                .filter(
                    BinarySecurityArchiveJob.task_id == task_id,
                    BinarySecurityArchiveJob.stage_name.in_(normalized),
                )
                .order_by(BinarySecurityArchiveJob.created_at.asc(), BinarySecurityArchiveJob.id.asc())
                .limit(max(1, int(batch_size)))
                .all()
            ]
            if not job_ids:
                if hasattr(db, "archive_jobs") and isinstance(getattr(db, "archive_jobs"), list):
                    allowed_stage_names = set(normalized)
                    db.archive_jobs = [
                        row for row in db.archive_jobs
                        if not (
                            str(getattr(row, "task_id", "") or "").strip() == task_id
                            and str(getattr(row, "stage_name", "") or "").strip() in allowed_stage_names
                        )
                    ]
                return deleted
            for attempt in range(max(1, int(max_retries))):
                try:
                    with self._savepoint(db):
                        deleted += int(
                            db.query(BinarySecurityArchiveJob)
                            .filter(
                                BinarySecurityArchiveJob.task_id == task_id,
                                BinarySecurityArchiveJob.id.in_(job_ids),
                            )
                            .delete(synchronize_session=False)
                            or 0
                        )
                    break
                except Exception as exc:
                    if attempt >= max(1, int(max_retries)) - 1 or not self._is_retryable_lock_error(exc):
                        raise
                    db.rollback()

    def _delete_archive_children_for_stages(self, db: Session, task: BinarySecurityTask, stage_names: list[str]) -> int:
        normalized = [str(stage_name or "").strip() for stage_name in stage_names if str(stage_name or "").strip()]
        if not normalized:
            return 0
        jobs = self._archive_jobs_for_stages(db, task.id, normalized)
        self._delete_archive_roots_for_jobs(task, jobs)
        self._clear_stage_output_artifacts(task, normalized)
        if hasattr(db, "archive_jobs") and isinstance(getattr(db, "archive_jobs"), list):
            allowed_stage_names = set(normalized)
            matching = [
                row
                for row in db.archive_jobs
                if str(getattr(row, "task_id", "") or "").strip() == task.id
                and str(getattr(row, "stage_name", "") or "").strip() in allowed_stage_names
            ]
            if matching:
                db.archive_jobs = [row for row in db.archive_jobs if row not in matching]
                return len(matching)
        return self._clear_archive_jobs_for_stages(db, task.id, normalized)

    def _archive_retry_blocked_reason(self, db: Session, task: BinarySecurityTask) -> str | None:
        active_operation = self._active_operation(db, task.id)
        if active_operation is not None:
            return f"当前任务正在执行 {active_operation.operation_type}，请稍后重试"
        if task.status in {"dispatching", "running"}:
            return f"当前任务正在执行中，当前状态 {task.status} 下不可手工重试归档"
        if task.status in {"pending_upload", "uploading", "ready_to_start", "pending"}:
            return f"当前任务状态不允许重试归档: {task.status}"
        return None

    def _archive_job_retry_support(
        self,
        db: Session,
        task: BinarySecurityTask,
        job: BinarySecurityArchiveJob,
        *,
        ignore_operation_lock: bool = False,
    ) -> tuple[bool, str | None]:
        if not ignore_operation_lock:
            blocked_reason = self._archive_retry_blocked_reason(db, task)
            if blocked_reason:
                return False, blocked_reason
        if job.task_id != task.id:
            return False, "归档任务不属于当前任务"
        if str(job.archive_status or "").strip() != "failed":
            return False, f"当前归档任务状态不允许重试: {job.archive_status or '-'}"
        mapped_status = str((job.payload or {}).get("mapped_status") or "").strip()
        if mapped_status not in {"success", "partial_success"}:
            return False, f"当前归档任务目标状态不允许重试: {mapped_status or '-'}"
        return True, None

    def _archive_retry_support(
        self,
        db: Session,
        task: BinarySecurityTask,
        stage_name: str,
        *,
        ignore_operation_lock: bool = False,
    ) -> tuple[bool, str | None, list[BinarySecurityArchiveJob]]:
        if not ignore_operation_lock:
            blocked_reason = self._archive_retry_blocked_reason(db, task)
            if blocked_reason:
                return False, blocked_reason, []
        jobs = (
            db.query(BinarySecurityArchiveJob)
            .filter(
                BinarySecurityArchiveJob.task_id == task.id,
                BinarySecurityArchiveJob.stage_name == stage_name,
            )
            .order_by(BinarySecurityArchiveJob.created_at.asc())
            .all()
        )
        jobs = [
            job
            for job in jobs
            if str(job.task_id or "") == str(task.id) and str(job.stage_name or "") == str(stage_name)
        ]
        if not jobs:
            return False, "当前阶段暂无归档任务", []
        retryable_jobs: list[BinarySecurityArchiveJob] = []
        for job in jobs:
            supported, _ = self._archive_job_retry_support(db, task, job, ignore_operation_lock=ignore_operation_lock)
            if supported:
                retryable_jobs.append(job)
        if not retryable_jobs:
            return False, "当前阶段暂无可重试的失败归档任务", []
        return True, None, retryable_jobs

    def _archive_full_retry_support(
        self,
        db: Session,
        task: BinarySecurityTask,
        stage_name: str,
        *,
        ignore_operation_lock: bool = False,
    ) -> tuple[bool, str | None, list[BinarySecurityArchiveJob], list[BinarySecurityStageItem]]:
        if not ignore_operation_lock:
            blocked_reason = self._archive_retry_blocked_reason(db, task)
            if blocked_reason:
                return False, blocked_reason, [], []
        jobs = (
            db.query(BinarySecurityArchiveJob)
            .filter(
                BinarySecurityArchiveJob.task_id == task.id,
                BinarySecurityArchiveJob.stage_name == stage_name,
            )
            .order_by(BinarySecurityArchiveJob.created_at.asc())
            .all()
        )
        jobs = [
            job
            for job in jobs
            if str(job.task_id or "") == str(task.id) and str(job.stage_name or "") == str(stage_name)
        ]
        stage_items = [
            item
            for item in self._stage_items(db, task.id, stage_name)
            if self._normalize_item_status(item.status) in ARCHIVE_SUCCESS_MAPPED_STATUSES
        ]
        if not jobs and not stage_items:
            return False, "当前阶段暂无可重建的归档子任务", [], []
        return True, None, jobs, stage_items

    def _requeue_archive_jobs(
        self,
        db: Session,
        task: BinarySecurityTask,
        jobs: list[BinarySecurityArchiveJob],
        *,
        stage_name: str,
        event_type: str,
        event_message: str,
    ) -> None:
        if not jobs:
            return
        now = _now()
        touched_stage_names: set[str] = set()
        for job in jobs:
            item = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.id == job.item_id).first()
            mapped_status = str((job.payload or {}).get("mapped_status") or "success").strip()
            if item is not None:
                item.status = mapped_status
                item.error_message = None
                item.started_at = item.started_at or now
                item.finished_at = item.finished_at or now
                if item.stage_name == "firmware_unpack":
                    self._refresh_firmware_unpack_item_result(task, item, archived_dir=Path(job.archive_root) if job.archive_root else None)
                touched_stage_names.add(item.stage_name)
            job.payload = self._clear_archive_job_retry_metadata(job)
            job.archive_status = "pending"
            job.owner_id = None
            job.error_message = None
            job.archive_root = None
            job.started_at = None
            job.completed_at = None
            job.updated_at = now
            self._record_event(
                db,
                task,
                event_type,
                event_message,
                stage_name=stage_name,
                item=item,
                payload={
                    "archive_job_id": job.id,
                    "downstream_service": job.downstream_service,
                    "downstream_task_id": job.downstream_task_id,
                    "mapped_status": mapped_status,
                },
            )
        for current_stage in sorted(touched_stage_names):
            if current_stage == "system_analysis":
                self._refresh_system_analysis_stage_from_synced_items(db, task)
            else:
                self._refresh_stage_run_from_items(db, task, current_stage)
        self._write_task_metadata(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)

    def _retry_failed_archive_jobs_for_stage(
        self,
        db: Session,
        task: BinarySecurityTask,
        stage_name: str,
        *,
        event_type: str = "downstream_archive_retry_requested",
    ) -> bool:
        supported, _, jobs = self._archive_retry_support(db, task, stage_name)
        if not supported:
            return False
        self._requeue_archive_jobs(
            db,
            task,
            jobs,
            stage_name=stage_name,
            event_type=event_type,
            event_message="产物归档已重新排队",
        )
        return True

    def _rebuild_archive_jobs_for_stage(
        self,
        db: Session,
        task: BinarySecurityTask,
        stage_name: str,
        stage_items: list[BinarySecurityStageItem],
    ) -> int:
        rebuilt = 0
        for item in stage_items:
            mapped_status = self._normalize_item_status(item.status)
            if mapped_status not in ARCHIVE_SUCCESS_MAPPED_STATUSES:
                continue
            payload = dict((item.result or {}).get("downstream") or {})
            payload.setdefault("status", mapped_status)
            job = self._queue_downstream_archive_job(
                db,
                task,
                item,
                payload=payload,
                mapped_status=mapped_status,
                before_status=mapped_status,
            )
            rebuilt += 1 if job else 0
        return rebuilt

    def _mark_task_waiting_for_archive_retry(self, db: Session, task: BinarySecurityTask, stage_name: str) -> None:
        task.status = "running"
        task.current_stage = stage_name
        task.execution_mode = None
        task.target_stage_name = None
        task.last_error = None
        self._clear_task_abnormal_reason_snapshot(db, task)
        task.dispatcher_instance_id = None
        task.dispatch_started_at = None
        task.lease_expires_at = None
        task.finished_at = None
        self._write_task_metadata(task, Path(task.workspace_root) / "input" / "task-metadata.json", status="running")
        self._record_event(
            db,
            task,
            "task_archive_retry_requeued",
            "失败任务的产物归档已重新排队，等待归档 worker 完成后继续推进",
            stage_name=stage_name,
            payload={"stage_name": stage_name, "retry_semantics": "archive_retry"},
        )

    async def _prepare_archive_retry_failed_items(
        self,
        db: Session,
        task: BinarySecurityTask,
        target_stage: str,
    ) -> list[str]:
        supported, reason, jobs = self._archive_retry_support(db, task, target_stage, ignore_operation_lock=True)
        if not supported:
            raise ValidationError(reason or f"阶段 {target_stage} 暂无可重试的归档任务")
        self._delete_archive_roots_for_jobs(task, jobs)
        self._requeue_archive_jobs(
            db,
            task,
            jobs,
            stage_name=target_stage,
            event_type="archive_stage_retry_requested",
            event_message="阶段归档任务已重新排队",
        )
        self._mark_task_waiting_for_archive_retry(db, task, target_stage)
        return [target_stage]

    async def _prepare_archive_retry_full(
        self,
        db: Session,
        task: BinarySecurityTask,
        target_stage: str,
    ) -> list[str]:
        supported, reason, jobs, stage_items = self._archive_full_retry_support(db, task, target_stage, ignore_operation_lock=True)
        if not supported:
            raise ValidationError(reason or f"阶段 {target_stage} 暂无可完全重试的归档任务")
        if jobs:
            self._delete_archive_roots_for_jobs(task, jobs)
            self._clear_archive_jobs_for_stages(db, task.id, [target_stage])
        rebuilt = self._rebuild_archive_jobs_for_stage(db, task, target_stage, stage_items)
        self._mark_task_waiting_for_archive_retry(db, task, target_stage)
        self._record_event(
            db,
            task,
            "archive_stage_full_retry_requested",
            "阶段归档任务已清空并重建",
            stage_name=target_stage,
            payload={
                "stage_name": target_stage,
                "rebuild_count": rebuilt,
                "retry_semantics": "archive_full",
            },
        )
        return [target_stage]

    async def _prepare_cancel_task(self, db: Session, task: BinarySecurityTask) -> list[str]:
        token = self._service_token()
        target_stage = str(task.current_stage or "").strip() or None
        if task.status == "cancelled":
            running_items = db.query(BinarySecurityStageItem).filter(
                BinarySecurityStageItem.task_id == task.id,
                BinarySecurityStageItem.status.in_(["pending", "queued", "dispatching", "running"]),
            ).all()
            for item in running_items:
                item.status = "cancelled"
                item.finished_at = item.finished_at or _now()
            active_stage_runs = db.query(BinarySecurityStageRun).filter(
                BinarySecurityStageRun.task_id == task.id,
                BinarySecurityStageRun.status.in_(["pending", "dispatching", "queued", "running"]),
            ).all()
            for stage_run in active_stage_runs:
                stage_run.status = "cancelled"
                stage_run.finished_at = stage_run.finished_at or _now()
            downstream_refs = self._dedupe_downstream_refs(self._collect_downstream_refs(task, running_items))
            self._record_event(
                db,
                task,
                "manual_cancel_noop",
                "任务已经是取消状态，已归一化仍活跃的阶段与子任务",
                stage_name=target_stage,
                payload={
                    "cancelled_item_count": len(running_items),
                    "cancelled_stage_run_count": len(active_stage_runs),
                    "downstream_ref_count": len(downstream_refs),
                },
            )
            # Persist the normalized cancelled state before issuing downstream
            # cancel requests so archive/status writers do not block on these
            # rows while we wait on external IO.
            db.commit()
            if downstream_refs:
                await self._cancel_downstream_refs(db, task, downstream_refs, token)
            return [stage.stage_name for stage in active_stage_runs]

        task.status = TASK_STATUS_CANCELLING
        self._invalidate_task_execution(task)
        task.finished_at = None
        running_items = db.query(BinarySecurityStageItem).filter(
            BinarySecurityStageItem.task_id == task.id,
            BinarySecurityStageItem.status.in_(["pending", "queued", "dispatching", "running"]),
        ).all()
        for item in running_items:
            item.status = "cancelled"
            item.finished_at = _now()
        active_stage_runs = db.query(BinarySecurityStageRun).filter(
            BinarySecurityStageRun.task_id == task.id,
            BinarySecurityStageRun.status.in_(["pending", "dispatching", "queued", "running"]),
        ).all()
        for stage_run in active_stage_runs:
            stage_run.status = "cancelled"
            stage_run.finished_at = stage_run.finished_at or _now()
        downstream_refs = self._dedupe_downstream_refs(self._collect_downstream_refs(task, running_items))
        self._record_event(
            db,
            task,
            "task_cancelling",
            "任务进入取消中，后台正在停止下游执行并等待收敛",
            stage_name=target_stage,
            payload={
                "cancelled_item_count": len(running_items),
                "cancelled_downstream_count": len(downstream_refs),
            },
        )
        observe_task_error("cancel", stage=str(task.current_stage or "none"), result="accepted")
        # Commit parent/stage-item cancellation first so concurrent archive
        # apply and downstream sync updates do not wait on a long-running
        # transaction while we perform metadata writes and downstream IO.
        db.commit()
        await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=TASK_STATUS_CANCELLING)
        await self._cancel_local_worker(task.id)
        for item in running_items:
            if str(item.downstream_task_id or "").strip():
                await self._cancel_downstream(item, token)
        if downstream_refs:
            await self._cancel_downstream_refs(db, task, downstream_refs, token)
        return sorted({str(stage_run.stage_name or "").strip() for stage_run in active_stage_runs if str(stage_run.stage_name or "").strip()})

    def _cancel_target_observation_status(self, payload: dict[str, Any] | None) -> str:
        raw_payload = dict(payload or {})
        mapped_status = self._map_downstream_status(str(raw_payload.get("status") or "")) or ""
        if mapped_status == "cancelled":
            return "cancelled"
        if mapped_status == "downstream_missing":
            return "missing"
        if mapped_status in {"success", "partial_success"}:
            return "success"
        if mapped_status == "failed":
            return "failed"
        if bool(raw_payload.get("cancel_requested")):
            return "cancelling"
        raw_status = str(raw_payload.get("status") or "").strip().lower()
        if raw_status == "cancelling":
            return "cancelling"
        normalized_status = self._normalize_downstream_status(raw_status) or raw_status
        if normalized_status in {"success", "partial_success"}:
            return "success"
        if normalized_status == "failed":
            return "failed"
        if normalized_status == "cancelled":
            return "cancelled"
        if normalized_status == "downstream_missing":
            return "missing"
        if mapped_status in {"running", "dispatching", "pending"}:
            return mapped_status
        if normalized_status in {"running", "dispatching", "pending", "queued"}:
            return normalized_status
        return "unknown"

    async def _run_cancel_operation_steps(
        self,
        db: Session,
        task: BinarySecurityTask,
        operation: BinarySecurityTaskOperation,
        resume_step: str,
    ) -> None:
        cancel_steps = TASK_CANCEL_SAGA_STEPS
        current_step = resume_step if resume_step in cancel_steps else TASK_OPERATION_STEP_MARK_TASK_CANCELLING
        step_order = {name: index for index, name in enumerate(cancel_steps)}

        async def _run_step(
            step_name: str,
            *,
            message: str,
            next_step: str | None,
            fn,
        ) -> Any:
            nonlocal current_step
            if step_order[current_step] > step_order[step_name]:
                return None
            self._record_operation_step_started(
                db,
                task,
                operation,
                step_name=step_name,
                message=message,
                stage_name=operation.target_stage,
                payload={"operation_type": operation.operation_type},
            )
            self._commit_or_rollback(db)
            try:
                result = await fn()
            except Exception as exc:
                self._record_operation_step_failed(
                    db,
                    task,
                    operation,
                    step_name=step_name,
                    error=exc,
                    stage_name=operation.target_stage,
                )
                self._commit_or_rollback(db)
                raise
            payload = result if isinstance(result, dict) else None
            self._record_operation_step_finished(
                db,
                task,
                operation,
                step_name=step_name,
                message=message,
                stage_name=operation.target_stage,
                payload=payload,
                next_step=next_step,
            )
            current_step = next_step or step_name
            self._commit_or_rollback(db)
            return result

        async def _mark_task_cancelling() -> dict[str, Any]:
            task.status = TASK_STATUS_CANCELLING
            task.finished_at = None
            task.last_error = None
            task.current_operation_id = operation.id
            self._record_operation_event(
                db,
                task,
                operation,
                "task_cancelling",
                "取消操作已开始，任务进入取消中",
                stage_name=operation.target_stage,
            )
            return {"task_status": task.status}

        async def _collect_targets() -> dict[str, Any]:
            targets = self._collect_cancel_targets(db, task)
            self._store_cancel_targets(operation, targets, workspace_root=task.workspace_root)
            for target in targets:
                self._record_operation_event(
                    db,
                    task,
                    operation,
                    "cancel_target_collected",
                    f"取消目标已纳入收敛检查: {self._cancel_target_display(target)}",
                    stage_name=str(target.get("stage_name") or operation.target_stage or "").strip() or None,
                    payload=dict(target),
                )
            return {"targets_total": len(targets)}

        async def _cancel_local() -> dict[str, Any]:
            cancelled_stages = await self._prepare_cancel_task(db, task)
            targets = [dict(target) for target in list(self._operation_result_data(operation).get("cancel_targets") or []) if isinstance(target, dict)]
            for target in targets:
                if str(target.get("target_type") or "") == "local_worker":
                    target["cancel_request_status"] = "requested"
                    target["terminal_observation_status"] = "cancelled"
                    target["last_observed_at"] = _isoformat_or_none(_now())
            self._store_cancel_targets(operation, targets, workspace_root=task.workspace_root)
            return {"cancelled_stage_names": cancelled_stages}

        async def _cancel_downstream_targets() -> dict[str, Any]:
            targets = [dict(target) for target in list(self._operation_result_data(operation).get("cancel_targets") or []) if isinstance(target, dict)]
            for target in targets:
                if str(target.get("target_type") or "") == "downstream_task":
                    target["cancel_request_status"] = "requested"
                    target["last_observed_at"] = _isoformat_or_none(_now())
            self._store_cancel_targets(operation, targets, workspace_root=task.workspace_root)
            return {
                "downstream_target_count": sum(
                    1 for target in targets if str(target.get("target_type") or "") == "downstream_task"
                )
            }

        async def _verify_quiesced() -> dict[str, Any]:
            timeout_seconds = self._cancel_verify_timeout_seconds()
            deadline = _now() + timedelta(seconds=timeout_seconds)
            token = self._service_token()
            last_blocking_snapshot: list[str] = []
            while True:
                refreshed_targets: list[dict[str, Any]] = []
                blocking_targets: list[dict[str, Any]] = []
                stored_targets = [
                    dict(target)
                    for target in list(self._operation_result_data(operation).get("cancel_targets") or [])
                    if isinstance(target, dict)
                ]
                task_items = {
                    item.id: item
                    for item in db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.task_id == task.id).all()
                }
                for target in stored_targets:
                    target_type = str(target.get("target_type") or "").strip()
                    previous_observed_status = str(target.get("terminal_observation_status") or "unknown")
                    observed_status = previous_observed_status
                    if target_type == "local_worker":
                        local_worker = self._workers.get(task.id)
                        observed_status = "running" if local_worker is not None and not local_worker.done() else "cancelled"
                    elif target_type == "stage_item":
                        item = task_items.get(str(target.get("item_id") or ""))
                        observed_status = self._normalize_item_status(item.status) if item is not None else "missing"
                    elif target_type == "downstream_task":
                        ref = {
                            "service": target.get("downstream_service"),
                            "task_id": target.get("downstream_task_id"),
                            "project_id": target.get("project_id"),
                            "stage_name": target.get("stage_name"),
                            "item_id": target.get("item_id"),
                            "item_key": target.get("item_key"),
                        }
                        try:
                            payload = await self._downstream_tasks().fetch_child_ref_payload(ref, token)
                        except NotFoundError:
                            observed_status = "missing"
                        except Exception as exc:
                            observed_status = "unknown"
                            target["error"] = str(exc)
                        else:
                            observed_status = self._cancel_target_observation_status(payload)
                            target["error"] = None
                            target["status_raw"] = payload.get("status")
                    target["terminal_observation_status"] = observed_status
                    target["last_observed_at"] = _isoformat_or_none(_now())
                    refreshed_targets.append(target)
                    if bool(target.get("blocking")) and not self._cancel_target_is_terminal(observed_status):
                        blocking_targets.append(target)
                    if observed_status != previous_observed_status or previous_observed_status == "unknown":
                        self._record_operation_event(
                            db,
                            task,
                            operation,
                            "cancel_target_terminal_observed",
                            (
                                f"取消目标仍未收敛: {self._cancel_target_display(target)} -> {observed_status}"
                                if bool(target.get("blocking")) and not self._cancel_target_is_terminal(observed_status)
                                else f"取消目标已收敛: {self._cancel_target_display(target)} -> {observed_status}"
                            ),
                            stage_name=str(target.get("stage_name") or operation.target_stage or "").strip() or None,
                            payload=dict(target),
                        )
                self._store_cancel_targets(operation, refreshed_targets, workspace_root=task.workspace_root)
                self._commit_or_rollback(db)
                if not blocking_targets:
                    return {
                        "targets_total": len(refreshed_targets),
                        "targets_blocking": 0,
                    }
                blocking_snapshot = sorted(self._cancel_target_display(target) for target in blocking_targets)
                if blocking_snapshot != last_blocking_snapshot:
                    self._record_operation_event(
                        db,
                        task,
                        operation,
                        "task_cancel_waiting_for_convergence",
                        f"取消仍在等待 {len(blocking_targets)} 个目标收敛",
                        level="warning",
                        stage_name=operation.target_stage,
                        payload={"blocking_targets": blocking_targets},
                    )
                    self._commit_or_rollback(db)
                    last_blocking_snapshot = blocking_snapshot
                if _now() >= deadline:
                    raise ValidationError(
                        "取消收敛超时，仍有目标未进入终态: "
                        + ", ".join(self._cancel_target_display(target) for target in blocking_targets[:5])
                    )
                await asyncio.sleep(max(1, int(self.cfg.scheduler.stage_poll_interval_seconds or 5)))
                db.expire_all()
                task_refreshed = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == task.id).first()
                operation_refreshed = db.query(BinarySecurityTaskOperation).filter(BinarySecurityTaskOperation.id == operation.id).first()
                if task_refreshed is not None:
                    task.status = task_refreshed.status
                    task.current_operation_id = task_refreshed.current_operation_id
                    task.updated_at = task_refreshed.updated_at
                if operation_refreshed is not None:
                    operation.result_payload = dict(operation_refreshed.result_payload or {})
                    operation.request_payload = dict(operation_refreshed.request_payload or {})
                    operation.step_payload = dict(operation_refreshed.step_payload or {})
                    operation.step_attempts = dict(operation_refreshed.step_attempts or {})
                    operation.resume_cursor = dict(operation_refreshed.resume_cursor or {})
                    operation.current_step = operation_refreshed.current_step

        async def _finalize_cancelled() -> dict[str, Any]:
            task.status = "cancelled"
            task.finished_at = _now()
            task.last_error = None
            self._invalidate_task_execution(task)
            self._record_operation_event(
                db,
                task,
                operation,
                "task_cancel_succeeded",
                "任务取消已确认完成",
                stage_name=operation.target_stage,
                payload={"cancel_state": self._cancel_state_from_operation(task, operation)},
            )
            observe_task_lifecycle("finished", status=task.status, task_type=self._task_type(task))
            await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status="cancelled")
            return {"task_status": task.status}

        async def _finalize_cancel_failed(error: Exception) -> dict[str, Any]:
            task.status = TASK_STATUS_CANCEL_FAILED
            task.finished_at = _now()
            task.last_error = str(error)
            self._invalidate_task_execution(task)
            self._record_operation_event(
                db,
                task,
                operation,
                "task_cancel_failed",
                f"任务取消失败: {error}",
                level="error",
                stage_name=operation.target_stage,
                payload={"cancel_state": self._cancel_state_from_operation(task, operation)},
            )
            await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=TASK_STATUS_CANCEL_FAILED)
            return {"task_status": task.status, "error": str(error)}

        try:
            await _run_step(
                TASK_OPERATION_STEP_MARK_TASK_CANCELLING,
                message="取消操作已进入任务状态切换",
                next_step=TASK_OPERATION_STEP_COLLECT_CANCEL_TARGETS,
                fn=_mark_task_cancelling,
            )
            await _run_step(
                TASK_OPERATION_STEP_COLLECT_CANCEL_TARGETS,
                message="取消操作已收集需要收敛的目标",
                next_step=TASK_OPERATION_STEP_CANCEL_LOCAL_EXECUTION,
                fn=_collect_targets,
            )
            await _run_step(
                TASK_OPERATION_STEP_CANCEL_LOCAL_EXECUTION,
                message="取消操作已停止本地执行链",
                next_step=TASK_OPERATION_STEP_CANCEL_DOWNSTREAM_TARGETS,
                fn=_cancel_local,
            )
            await _run_step(
                TASK_OPERATION_STEP_CANCEL_DOWNSTREAM_TARGETS,
                message="取消操作已向下游发出取消请求",
                next_step=TASK_OPERATION_STEP_VERIFY_DOWNSTREAM_QUIESCED,
                fn=_cancel_downstream_targets,
            )
            await _run_step(
                TASK_OPERATION_STEP_VERIFY_DOWNSTREAM_QUIESCED,
                message="取消操作已完成下游收敛核验",
                next_step=TASK_OPERATION_STEP_FINALIZE_TASK_CANCELLED,
                fn=_verify_quiesced,
            )
        except Exception as exc:
            await _run_step(
                TASK_OPERATION_STEP_FINALIZE_TASK_CANCEL_FAILED,
                message="取消操作已收口为失败",
                next_step=TASK_OPERATION_STEP_FINALIZE_TASK_CANCEL_FAILED,
                fn=lambda: _finalize_cancel_failed(exc),
            )
            raise

        await _run_step(
            TASK_OPERATION_STEP_FINALIZE_TASK_CANCELLED,
            message="取消操作已收口为已取消",
            next_step=TASK_OPERATION_STEP_SUCCEEDED,
            fn=_finalize_cancelled,
        )

    async def _prepare_delete_task(self, db: Session, task: BinarySecurityTask) -> list[str]:
        operation = None
        force_delete = False
        if getattr(task, "current_operation_id", None):
            operation = (
                db.query(BinarySecurityTaskOperation)
                .filter(BinarySecurityTaskOperation.id == task.current_operation_id)
                .first()
            )
        request_payload = dict(getattr(operation, "request_payload", None) or {})
        force_delete = bool(request_payload.get("force_delete"))
        task.status = "cancelled"
        self._invalidate_task_execution(task)
        task.finished_at = task.finished_at or _now()
        self._record_event(
            db,
            task,
            "task_force_delete_requested" if force_delete else "task_delete_requested",
            "任务强制删除已受理，开始清理下游与工作区" if force_delete else "任务删除已受理，开始清理下游与工作区",
            stage_name=task.current_stage,
            level="warning" if force_delete else "info",
            payload={"force_delete": force_delete},
        )
        items = db.query(BinarySecurityStageItem).options(
            load_only(
                BinarySecurityStageItem.id,
                BinarySecurityStageItem.task_id,
                BinarySecurityStageItem.stage_name,
                BinarySecurityStageItem.item_key,
                BinarySecurityStageItem.status,
                BinarySecurityStageItem.retry_count,
                BinarySecurityStageItem.downstream_service,
                BinarySecurityStageItem.downstream_task_id,
                BinarySecurityStageItem.error_message,
                BinarySecurityStageItem.started_at,
                BinarySecurityStageItem.finished_at,
                BinarySecurityStageItem.created_at,
            )
        ).filter(BinarySecurityStageItem.task_id == task.id).all()
        downstream_refs = self._dedupe_downstream_refs(
            self._collect_downstream_refs(task, items)
            + self._discover_parent_linked_downstream_refs(db, task)
        )
        for item in items:
            if item.status in {"pending", "queued", "running"}:
                item.status = "cancelled"
                item.finished_at = _now()
        await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status="cancelled")
        db.flush()

        await self._cancel_local_worker(task.id)
        token = self._service_token()
        await self._cancel_downstream_refs(db, task, downstream_refs, token)
        deleted_downstream_count = await self._delete_downstream_refs(
            db,
            task,
            downstream_refs,
            token,
            force_delete=force_delete,
            best_effort=True,
            cleanup_scope="delete",
        )
        downstream_cleanup_results = [
            dict(result)
            for result in list(getattr(self, "_last_downstream_cleanup_results", []) or [])
            if isinstance(result, dict)
        ]
        deferred_refs = [dict(result) for result in downstream_cleanup_results if bool(result.get("deferred"))]
        cleanup_partial_failed = bool(deferred_refs)
        cleanup_status = await self._cleanup_task_workspace(task, token)
        next_retry_at = (
            _isoformat_or_none(_now() + timedelta(seconds=max(DEFERRED_CLEANUP_RETRY_MIN_SECONDS, int(self.cfg.scheduler.downstream_reconcile_interval_seconds or 30) * 2)))
            if deferred_refs else None
        )
        cleanup_snapshot = {
            **dict(task.cleanup_snapshot or {}),
            "delete_cleanup_status": cleanup_status,
            "workspace_root": task.workspace_root,
            "downstream_ref_count": len(downstream_refs),
            "deleted_downstream_count": int(deleted_downstream_count or 0),
            "force_delete": force_delete,
            "cleanup_partial_failed": cleanup_partial_failed,
            "downstream_cleanup_results": downstream_cleanup_results,
            "downstream_cleanup_blocking_refs": [],
            "deferred_downstream_refs": deferred_refs,
            "deferred_cleanup_attempts": int((dict(task.cleanup_snapshot or {}).get("deferred_cleanup_attempts") or 0)) + (1 if deferred_refs else 0),
            "deferred_cleanup_last_error": deferred_refs[0].get("error") if deferred_refs else None,
            "deferred_cleanup_last_attempt_at": _isoformat_or_none(_now()) if deferred_refs else dict(task.cleanup_snapshot or {}).get("deferred_cleanup_last_attempt_at"),
            "deferred_cleanup_next_retry_at": next_retry_at,
            "deferred_cleanup_status": "partial_failed" if deferred_refs else "succeeded",
        }
        task.cleanup_snapshot = cleanup_snapshot
        if operation is not None:
            self._update_operation_result_payload(
                operation,
                {
                    "cleanup_result": {
                        "cleanup_mode": "best_effort",
                        "cleanup_partial_failed": cleanup_partial_failed,
                        "cleanup_failed_ref_count": len(deferred_refs),
                        "downstream_cleanup_results": downstream_cleanup_results,
                        "downstream_cleanup_blocking_refs": [],
                        "downstream_cleanup_deferred_refs": deferred_refs,
                    }
                },
                workspace_root=task.workspace_root,
            )
        if cleanup_status != "deleted":
            task.status = TASK_STATUS_DELETE_FAILED
            task.last_error = f"任务目录清理失败: cleanup_status={cleanup_status}"
            task.cleanup_snapshot = {**dict(task.cleanup_snapshot or {}), "delete_failed_at": _isoformat_or_none(_now())}
            self._record_event(
                db,
                task,
                "task_delete_failed",
                (
                    f"强制删除未完成，本地工作区清理失败，任务保留为 delete_failed: {cleanup_status}"
                    if force_delete
                    else f"任务目录清理失败，任务保留为 delete_failed: {cleanup_status}"
                ),
                stage_name=task.current_stage,
                level="error",
                payload={
                    "cleanup_status": cleanup_status,
                    "workspace_root": task.workspace_root,
                    "downstream_ref_count": len(downstream_refs),
                    "deleted_downstream_count": int(deleted_downstream_count or 0),
                    "force_delete": force_delete,
                    "failure_reason": "workspace_cleanup_failed",
                },
            )
            raise ValidationError(f"任务目录清理失败: {cleanup_status}")

        if deferred_refs:
            self._record_event(
                db,
                task,
                "task_delete_cleanup_deferred",
                "任务本地删除已完成，部分下游资源转入后台补偿清理",
                stage_name=task.current_stage,
                level="warning",
                payload={
                    "downstream_ref_count": len(downstream_refs),
                    "deleted_downstream_count": int(deleted_downstream_count or 0),
                    "deferred_ref_count": len(deferred_refs),
                    "force_delete": force_delete,
                },
            )
        if force_delete:
            self._record_event(
                db,
                task,
                "task_force_delete_completed",
                "已强制删除主任务；部分下游删除失败已忽略",
                stage_name=task.current_stage,
                level="warning",
                payload={
                    "force_delete": True,
                    "downstream_ref_count": len(downstream_refs),
                    "deleted_downstream_count": int(deleted_downstream_count or 0),
                },
            )
        else:
            self._record_event(
                db,
                task,
                "task_delete_completed",
                "任务删除已完成",
                stage_name=task.current_stage,
                level="info",
                payload={
                    "downstream_ref_count": len(downstream_refs),
                    "deleted_downstream_count": int(deleted_downstream_count or 0),
                    "cleanup_partial_failed": cleanup_partial_failed,
                },
            )

        stage_items_deleted = int(
            db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.task_id == task.id).delete(synchronize_session=False) or 0
        )
        stage_runs_deleted = int(
            db.query(BinarySecurityStageRun).filter(BinarySecurityStageRun.task_id == task.id).delete(synchronize_session=False) or 0
        )
        events_deleted = int(
            db.query(BinarySecurityEvent).filter(BinarySecurityEvent.task_id == task.id).delete(synchronize_session=False) or 0
        )
        archive_jobs_deleted = int(
            db.query(BinarySecurityArchiveJob).filter(BinarySecurityArchiveJob.task_id == task.id).delete(synchronize_session=False) or 0
        )
        task.cleanup_snapshot = {
            **cleanup_snapshot,
            "cleanup_counts": {
                **dict(cleanup_snapshot.get("cleanup_counts") or {}),
                "stage_items_deleted": stage_items_deleted,
                "stage_runs_deleted": stage_runs_deleted,
                "timeline_events_deleted": events_deleted,
                "archive_jobs_deleted": archive_jobs_deleted,
            },
        }
        if deferred_refs:
            task.status = "cancelled"
            task.finished_at = task.finished_at or _now()
            task.last_error = None
            task.current_operation_id = None
        else:
            db.delete(task)
        return []

    def _ensure_downstream_archive_job(
        self,
        db: Session,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        *,
        payload: dict[str, Any],
        mapped_status: str,
        before_status: str | None,
        force: bool = False,
        extra_paths: list[str | Path] | None = None,
    ) -> BinarySecurityArchiveJob:
        downstream_task_id = str(item.downstream_task_id or "").strip()
        job_dedupe_key = build_archive_job_dedupe_key(item.id, downstream_task_id)
        next_payload = self._build_archive_job_payload(
            mapped_status=mapped_status,
            before_status=before_status,
            force=force,
            payload=payload,
            bound_downstream_task_id=downstream_task_id,
            extra_paths=extra_paths,
        )
        lock_digest = hashlib.sha1(f"{item.id}:{downstream_task_id}".encode("utf-8")).hexdigest()
        lock_name = f"bs_archive:{lock_digest}"
        locked = False
        try:
            try:
                locked = bool(db.execute(text("SELECT GET_LOCK(:name, :timeout)"), {"name": lock_name, "timeout": 5}).scalar())
            except Exception:
                locked = False
            if not locked:
                # Avoid a best-effort local race when the DB lock is unavailable
                # (for example in tests or if the DB rejects named locks).
                import time as _time
                _time.sleep(0.05)
            existing = (
                db.query(BinarySecurityArchiveJob)
                .filter(
                    BinarySecurityArchiveJob.task_id == task.id,
                    BinarySecurityArchiveJob.stage_name == item.stage_name,
                    BinarySecurityArchiveJob.job_dedupe_key == job_dedupe_key,
                    BinarySecurityArchiveJob.archive_status.in_(["pending", "running", "archived", "applying", "success"]),
                )
                .order_by(BinarySecurityArchiveJob.created_at.desc())
                .first()
            )
            if existing is not None:
                try:
                    db.commit()
                except Exception:
                    db.rollback()
                    raise
                return existing
            failed = (
                db.query(BinarySecurityArchiveJob)
                .filter(
                    BinarySecurityArchiveJob.task_id == task.id,
                    BinarySecurityArchiveJob.stage_name == item.stage_name,
                    BinarySecurityArchiveJob.job_dedupe_key == job_dedupe_key,
                    BinarySecurityArchiveJob.archive_status == "failed",
                )
                .order_by(BinarySecurityArchiveJob.created_at.desc())
                .first()
            )
            if failed is not None:
                try:
                    db.commit()
                except Exception:
                    db.rollback()
                    raise
                return failed
            job = BinarySecurityArchiveJob(
                id=f"aj_{uuid.uuid4().hex[:24]}",
                task_id=task.id,
                project_id=task.project_id,
                stage_name=item.stage_name,
                item_id=item.id,
                item_key=item.item_key,
                downstream_service=item.downstream_service,
                downstream_task_id=downstream_task_id,
                job_dedupe_key=job_dedupe_key,
            )
            job.task_id = task.id
            job.project_id = task.project_id
            job.stage_name = item.stage_name
            job.item_key = item.item_key
            job.downstream_service = item.downstream_service
            job.downstream_task_id = downstream_task_id
            job.job_dedupe_key = job_dedupe_key
            job.archive_status = "pending"
            job.owner_id = None
            job.error_message = None
            job.archive_root = None
            job.started_at = None
            job.completed_at = None
            job.updated_at = _now()
            job.payload = self._build_archive_job_payload(
                mapped_status=mapped_status,
                before_status=before_status,
                force=force,
                payload=payload,
                bound_downstream_task_id=downstream_task_id,
                extra_paths=extra_paths,
            )
            db.add(job)
            max_attempts = self._retryable_write_attempts()
            for attempt in range(max_attempts):
                try:
                    with self._savepoint(db):
                        db.flush()
                    break
                except IntegrityError:
                    existing = (
                        db.query(BinarySecurityArchiveJob)
                        .filter(
                            BinarySecurityArchiveJob.task_id == task.id,
                            BinarySecurityArchiveJob.stage_name == item.stage_name,
                            BinarySecurityArchiveJob.job_dedupe_key == job_dedupe_key,
                        )
                        .order_by(BinarySecurityArchiveJob.created_at.desc())
                        .first()
                    )
                    if existing is None:
                        raise
                    return existing
                except OperationalError as exc:
                    if not self._is_retryable_lock_error(exc) or attempt >= max_attempts - 1:
                        raise
                    db.rollback()
                    self._sleep_after_retryable_lock_error(attempt + 1)
            # The archive worker may run in another process/session. Persist the
            # queued job before releasing the named lock so a concurrent sync path
            # can observe and reuse it instead of creating a duplicate job.
            for attempt in range(max_attempts):
                try:
                    db.commit()
                    break
                except OperationalError as exc:
                    db.rollback()
                    if not self._is_retryable_lock_error(exc) or attempt >= max_attempts - 1:
                        raise
                    self._sleep_after_retryable_lock_error(attempt + 1)
                except Exception:
                    db.rollback()
                    raise
            return job
        finally:
            if locked:
                try:
                    db.execute(text("SELECT RELEASE_LOCK(:name)"), {"name": lock_name})
                except Exception:
                    pass

    def _queue_downstream_archive_job(
        self,
        db: Session,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        *,
        payload: dict[str, Any],
        mapped_status: str,
        before_status: str | None,
        extra_paths: list[str | Path] | None = None,
    ) -> BinarySecurityArchiveJob | None:
        if mapped_status not in ARCHIVE_SUCCESS_MAPPED_STATUSES:
            raise ValidationError(f"当前状态不生成归档任务: {mapped_status}")
        allowed, ignored_reason = self._may_queue_archive_for_current_binding(
            item,
            payload=payload,
            mapped_status=mapped_status,
        )
        if not allowed:
            self._record_event(
                db,
                task,
                "stale_archive_trigger_ignored",
                "旧 child 的终态归档触发已忽略",
                stage_name=item.stage_name,
                item=item,
                level="warning",
                payload={
                    "downstream_service": item.downstream_service,
                    "downstream_task_id": item.downstream_task_id,
                    "payload_downstream_task_id": self._payload_downstream_task_id(payload),
                    "mapped_status": mapped_status,
                    "ignored_reason": ignored_reason,
                    "superseded": True,
                },
            )
            return None
        job = self._ensure_downstream_archive_job(
            db,
            task,
            item,
            payload=payload,
            mapped_status=mapped_status,
            before_status=before_status,
            force=False,
            extra_paths=extra_paths,
        )
        self._record_event(
            db,
            task,
            "downstream_archive_job_queued" if job.archive_status in {"pending", "running"} else "downstream_archive_job_reused",
            "下游子任务已终态，产物归档已入队",
            stage_name=item.stage_name,
            item=item,
            payload={
                "archive_job_id": job.id,
                "archive_status": job.archive_status,
                "downstream_service": item.downstream_service,
                "downstream_task_id": item.downstream_task_id,
                "mapped_status": mapped_status,
            },
        )
        return job

    async def _queue_archive_and_wait(
        self,
        db: Session,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        *,
        payload: dict[str, Any],
        mapped_status: str,
        before_status: str | None,
        extra_paths: list[str | Path] | None = None,
    ) -> tuple[Path | None, BinarySecurityArchiveJob | None]:
        if mapped_status not in ARCHIVE_SUCCESS_MAPPED_STATUSES:
            return None, None
        job = self._queue_downstream_archive_job(
            db,
            task,
            item,
            payload=payload,
            mapped_status=mapped_status,
            before_status=before_status,
            extra_paths=extra_paths,
        )
        if job is None:
            return None, None
        db.commit()
        completed = await self._wait_archive_job_completion(job.id, task.id)
        try:
            db.refresh(item)
        except Exception:
            db.rollback()
        if completed is None or completed.archive_status != "success":
            error = completed.error_message if completed is not None else "归档任务不存在"
            self._record_event(
                db,
                task,
                "downstream_archive_blocking_failed",
                "总任务产物归档未完成，阶段结果不能用于后续推进",
                stage_name=item.stage_name,
                item=item,
                level="warning",
                payload={"archive_job_id": job.id, "error": error or "下游产物归档失败"},
            )
            db.commit()
            return None, completed
        return Path(completed.archive_root) if completed.archive_root else None, completed

    def get_project_config(self, db: Session, project_id: str) -> BinarySecurityProjectConfigResponse:
        row = db.query(BinarySecurityProjectConfig).filter(BinarySecurityProjectConfig.project_id == project_id).first()
        config = BinarySecurityProjectConfigPayload(**(row.config if row else {}))
        config.pipeline_mode = _normalize_pipeline_mode(config.pipeline_mode)
        config.partial_success_stage_advancement = self._normalized_partial_success_stage_advancement_map(
            config.partial_success_stage_advancement,
            allowed_stages=PARTIAL_SUCCESS_ADVANCEMENT_STAGES,
            default_map=DEFAULT_PARTIAL_SUCCESS_STAGE_ADVANCEMENT,
            strict=False,
        )
        return BinarySecurityProjectConfigResponse(project_id=project_id, config=config)

    def save_project_config(self, db: Session, project_id: str, payload: BinarySecurityProjectConfigPayload) -> BinarySecurityProjectConfigResponse:
        normalized_payload = payload.model_copy(deep=True)
        normalized_payload.pipeline_mode = _normalize_pipeline_mode(payload.pipeline_mode)
        normalized_payload.partial_success_stage_advancement = self._normalized_partial_success_stage_advancement_map(
            payload.partial_success_stage_advancement,
            allowed_stages=PARTIAL_SUCCESS_ADVANCEMENT_STAGES,
            default_map=DEFAULT_PARTIAL_SUCCESS_STAGE_ADVANCEMENT,
        )
        row = db.query(BinarySecurityProjectConfig).filter(BinarySecurityProjectConfig.project_id == project_id).first()
        if row is None:
            row = BinarySecurityProjectConfig(project_id=project_id)
            db.add(row)
        row.config = normalized_payload.model_dump(mode="json")
        db.commit()
        return BinarySecurityProjectConfigResponse(project_id=project_id, config=normalized_payload)

    def get_service_config(self, db: Session) -> BinarySecurityServiceConfigResponse:
        return BinarySecurityServiceConfigResponse(config=self._load_service_config(db))

    def save_service_config(self, db: Session, payload: BinarySecurityServiceConfigPayload) -> BinarySecurityServiceConfigResponse:
        row = db.query(BinarySecurityServiceConfig).filter(BinarySecurityServiceConfig.config_key == "global").first()
        if row is None:
            row = BinarySecurityServiceConfig(config_key="global")
            db.add(row)
        row.config = payload.model_dump(mode="json")
        db.commit()
        return BinarySecurityServiceConfigResponse(config=payload)

    async def _operation_dispatch_loop(self) -> None:
        session_factory = get_session_factory()
        while self._running:
            operation_id = None
            db = session_factory()
            try:
                with observe_scheduler_loop("operation_dispatch"):
                    self._mark_loop_heartbeat("operation_dispatch")
                    self._maybe_requeue_stale_operations(db)
                    operation_id = await get_task_queue().pop_operation(self.cfg.queue.block_timeout_seconds)
                    if operation_id:
                        async with self._operation_worker_lock:
                            existing = self._operation_workers.get(operation_id)
                            if existing is None or existing.done():
                                self._operation_workers[operation_id] = asyncio.create_task(
                                    self._run_task_operation(operation_id),
                                    name=f"binary-security-operation-{operation_id}",
                                )
                    else:
                        self._maybe_requeue_stale_operations(db)
                    self._mark_loop_heartbeat("operation_dispatch")
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                self._recover_loop_db_error("operation_dispatch", db, exc)
                logger.exception("binary-security operation dispatch loop crashed and recovered")
                await asyncio.sleep(1)
            finally:
                with suppress(Exception):
                    db.close()

    async def _run_task_operation(self, operation_id: str) -> None:
        session_factory = get_session_factory()
        db = session_factory()
        started = time.perf_counter()
        operation_type = "unknown"
        task_deleted = False
        heartbeat_task: asyncio.Task | None = None
        try:
            operation = self._claim_operation_by_id(db, operation_id)
            if operation is None:
                return
            task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == operation.task_id).first()
            if task is None:
                operation.status = "failed"
                operation.error_code = "task_not_found"
                operation.error_message = f"任务不存在: {operation.task_id}"
                operation.finished_at = _now()
                db.commit()
                return
            operation_type = operation.operation_type
            task.current_operation_id = operation.id
            heartbeat_task = asyncio.create_task(
                self._operation_lease_heartbeat(operation.id),
                name=f"binary-security-operation-heartbeat-{operation.id}",
            )
            self._record_operation_event(
                db,
                task,
                operation,
                "operation_started",
                f"后台操作已开始: {operation.operation_type}",
                stage_name=operation.target_stage,
            )
            db.commit()
            await self._run_task_operation_steps(db, task, operation)
            if operation.operation_type == TASK_ACTION_DELETE:
                task_deleted = db.query(BinarySecurityTask.id).filter(BinarySecurityTask.id == operation.task_id).first() is None
            operation.heartbeat_at = _now()
            operation.claim_lease_expires_at = _now()
            operation.status = "succeeded"
            operation.current_step = TASK_OPERATION_STEP_SUCCEEDED
            operation.finished_at = _now()
            if not task_deleted:
                task.current_operation_id = None
                self._record_operation_event(
                    db,
                    task,
                    operation,
                    "operation_succeeded",
                    f"后台操作已完成: {operation.operation_type}",
                    stage_name=operation.target_stage,
                )
            db.commit()
            observe_control_operation(operation_type, "succeeded")
        except Exception as exc:
            db.rollback()
            operation = db.query(BinarySecurityTaskOperation).filter(BinarySecurityTaskOperation.id == operation_id).first()
            if operation is not None:
                operation_type = operation.operation_type
                operation.status = "failed"
                operation.error_code = "operation_failed"
                operation.error_message = str(exc)
                operation.finished_at = _now()
            task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == getattr(operation, "task_id", None)).first() if operation is not None else None
            if task is not None:
                if operation is not None and operation.operation_type == TASK_ACTION_DELETE:
                    task.status = TASK_STATUS_DELETE_FAILED
                    task.finished_at = _now()
                    task.current_operation_id = operation.id
                else:
                    task.current_operation_id = None
                task.last_error = str(exc)
                self._record_operation_event(
                    db,
                    task,
                    operation,
                    "operation_failed",
                    f"后台操作失败: {exc}",
                    level="error",
                    stage_name=operation.target_stage,
                )
                if operation is not None and operation.operation_type == TASK_ACTION_DELETE:
                    self._record_event(
                        db,
                        task,
                        "task_delete_failed",
                        "删除失败，任务已保留为 delete_failed",
                        stage_name=operation.target_stage,
                        level="error",
                        payload={
                            "failure_reason": "delete_operation_failed",
                            "operation_id": operation.id,
                            "operation_error": str(exc),
                            "force_delete": bool(dict(operation.request_payload or {}).get("force_delete")),
                        },
                    )
            db.commit()
            observe_control_operation(operation_type, "failed")
        finally:
            if heartbeat_task is not None:
                heartbeat_task.cancel()
                with suppress(asyncio.CancelledError):
                    await heartbeat_task
            async with self._operation_worker_lock:
                self._operation_workers.pop(operation_id, None)
            observe_control_operation_duration(
                operation_type=operation_type,
                status="finished",
                duration_seconds=time.perf_counter() - started,
            )
            db.close()

    async def _run_task_operation_steps(
        self,
        db: Session,
        task: BinarySecurityTask,
        operation: BinarySecurityTaskOperation,
    ) -> None:
        resume_step = self._operation_resume_step(operation)
        if operation.operation_type == TASK_ACTION_CANCEL:
            await self._run_cancel_operation_steps(db, task, operation, resume_step)
            return
        if operation.operation_type in {TASK_ACTION_RETRY_FAILED_ITEMS, TASK_ACTION_RETRY_STAGE_FAILED_ITEMS}:
            await self._run_retry_failed_items_operation_steps(db, task, operation, resume_step)
            return
        if operation.operation_type == TASK_ACTION_RETRY_STAGE_FULL:
            resume_step = await self._run_retry_stage_full_operation_steps(db, task, operation, resume_step)
        else:
            prepare_step = TASK_OPERATION_STEP_COLLECT_CLEANUP_PLAN
            if resume_step == prepare_step:
                self._record_operation_step_started(
                    db,
                    task,
                    operation,
                    step_name=prepare_step,
                    message=f"后台操作开始执行准备步骤: {operation.operation_type}",
                    stage_name=operation.target_stage,
                    payload={"operation_type": operation.operation_type},
                )
                db.commit()
                try:
                    if operation.operation_type == TASK_ACTION_CONTINUE:
                        await self._prepare_continue_task(db, task, str(operation.target_stage or "").strip())
                    elif operation.operation_type == TASK_ACTION_RETRY:
                        await self._prepare_retry_task(db, task)
                    elif operation.operation_type == TASK_ACTION_RETRY_FAILED_ITEMS:
                        await self._prepare_retry_failed_items(db, task, str(operation.target_stage or "").strip())
                    elif operation.operation_type == TASK_ACTION_RETRY_STAGE_FAILED_ITEMS:
                        await self._prepare_retry_failed_items(db, task, str(operation.target_stage or "").strip())
                    elif operation.operation_type == TASK_ACTION_RETRY_ARCHIVE_FAILED_ITEMS:
                        await self._prepare_archive_retry_failed_items(db, task, str(operation.target_stage or "").strip())
                    elif operation.operation_type == TASK_ACTION_RETRY_ARCHIVE_FULL:
                        await self._prepare_archive_retry_full(db, task, str(operation.target_stage or "").strip())
                    elif operation.operation_type == TASK_ACTION_DELETE:
                        await self._prepare_delete_task(db, task)
                        self._record_operation_step_finished(
                            db,
                            task,
                            operation,
                            step_name=prepare_step,
                            message=f"后台操作准备步骤已完成: {operation.operation_type}",
                            stage_name=operation.target_stage,
                            next_step=TASK_OPERATION_STEP_SUCCEEDED,
                        )
                        operation.current_step = TASK_OPERATION_STEP_SUCCEEDED
                        db.commit()
                        return
                    else:
                        raise ValidationError(f"未知操作类型: {operation.operation_type}")
                except Exception as exc:
                    self._record_operation_step_failed(
                        db,
                        task,
                        operation,
                        step_name=prepare_step,
                        error=exc,
                        stage_name=operation.target_stage,
                    )
                    db.commit()
                    raise

                if operation.operation_type in {TASK_ACTION_RETRY_FAILED_ITEMS, TASK_ACTION_RETRY_STAGE_FAILED_ITEMS}:
                    prepare_result = self._build_retry_prepare_result(
                        db,
                        task,
                        target_stage=str(operation.target_stage or "").strip(),
                    )
                    self._update_operation_result_payload(
                        operation,
                        prepare_result,
                        workspace_root=task.workspace_root,
                    )
                    validation = dict(prepare_result.get("validation") or {})
                    if not bool(validation.get("validated")):
                        self._record_operation_event(
                            db,
                            task,
                            operation,
                            "retry_prepare_validation_failed",
                            "失败项重试准备校验失败",
                            level="error",
                            stage_name=operation.target_stage,
                            payload=prepare_result,
                        )
                        raise ValidationError("失败项重试准备校验失败")
                    self._record_operation_event(
                        db,
                        task,
                        operation,
                        "retry_prepare_validation_succeeded",
                        "失败项重试准备校验通过",
                        stage_name=operation.target_stage,
                        payload=prepare_result,
                    )

                requeue_required = operation.operation_type not in {TASK_ACTION_RETRY_ARCHIVE_FAILED_ITEMS, TASK_ACTION_RETRY_ARCHIVE_FULL}
                next_step = TASK_OPERATION_STEP_REQUEUE_TASK if requeue_required else TASK_OPERATION_STEP_SUCCEEDED
                self._record_operation_step_finished(
                    db,
                    task,
                    operation,
                    step_name=prepare_step,
                    message=f"后台操作准备步骤已完成: {operation.operation_type}",
                    stage_name=operation.target_stage,
                    payload=self._operation_result_data(operation) if operation.operation_type in {TASK_ACTION_RETRY_FAILED_ITEMS, TASK_ACTION_RETRY_STAGE_FAILED_ITEMS} else None,
                    next_step=next_step,
                )
                if not requeue_required:
                    db.commit()
                    return
                resume_step = TASK_OPERATION_STEP_REQUEUE_TASK

        if resume_step != TASK_OPERATION_STEP_REQUEUE_TASK:
            return

        if self._is_operation_requeue_state_applied(task, operation):
            self._record_operation_step_finished(
                db,
                task,
                operation,
                step_name=TASK_OPERATION_STEP_REQUEUE_TASK,
                message=f"后台操作重新排队步骤已确认完成，无需重复执行: {operation.operation_type}",
                stage_name=operation.target_stage,
                payload={"idempotent_recovery": True},
                next_step=TASK_OPERATION_STEP_SUCCEEDED,
            )
            db.commit()
            return

        self._record_operation_step_started(
            db,
            task,
            operation,
            step_name=TASK_OPERATION_STEP_REQUEUE_TASK,
            message=f"后台操作进入重新排队步骤: {operation.operation_type}",
            stage_name=operation.target_stage,
        )
        task.status = "pending"
        task.current_stage = operation.target_stage or task.current_stage
        task.last_error = None
        task.finished_at = None
        self._invalidate_task_execution(task)
        self._enqueue_task(task.id)
        self._update_operation_result_payload(
            operation,
            {
                "requeue": {
                    "task_status_before": "requeue_pending",
                    "task_status_after": task.status,
                    "requeue_requested": True,
                },
            },
            workspace_root=task.workspace_root,
        )
        self._record_operation_event(
            db,
            task,
            operation,
            "task_requeued",
            f"后台操作完成，任务已重新排队: {operation.operation_type}",
            stage_name=operation.target_stage,
        )
        self._record_operation_step_finished(
            db,
            task,
            operation,
            step_name=TASK_OPERATION_STEP_REQUEUE_TASK,
            message=f"后台操作重新排队步骤已完成: {operation.operation_type}",
            stage_name=operation.target_stage,
            next_step=TASK_OPERATION_STEP_SUCCEEDED,
        )
        db.commit()

    async def _run_retry_failed_items_operation_steps(
        self,
        db: Session,
        task: BinarySecurityTask,
        operation: BinarySecurityTaskOperation,
        resume_step: str,
    ) -> None:
        step_flow = (
            (
                TASK_OPERATION_STEP_COLLECT_CLEANUP_PLAN,
                "开始收集失败项重试计划",
                "失败项重试计划已收集",
                self._operation_collect_retry_failed_items_plan,
                TASK_OPERATION_STEP_SYNC_TARGET_STAGE_STATE,
            ),
            (
                TASK_OPERATION_STEP_SYNC_TARGET_STAGE_STATE,
                "开始同步目标阶段下游状态",
                "目标阶段下游状态同步完成",
                self._operation_sync_retry_target_stage_state,
                TASK_OPERATION_STEP_PREPARE_RETRY_ITEMS,
            ),
            (
                TASK_OPERATION_STEP_PREPARE_RETRY_ITEMS,
                "开始准备失败项重试上下文",
                "失败项重试上下文准备完成",
                self._operation_prepare_retry_items,
                TASK_OPERATION_STEP_CLEANUP_ABNORMAL_CHILDREN,
            ),
            (
                TASK_OPERATION_STEP_CLEANUP_ABNORMAL_CHILDREN,
                "开始清理异常子任务",
                "异常子任务清理完成",
                self._operation_cleanup_retry_abnormal_children,
                TASK_OPERATION_STEP_CREATE_REPLACEMENT_CHILDREN,
            ),
            (
                TASK_OPERATION_STEP_CREATE_REPLACEMENT_CHILDREN,
                "开始创建替换子任务",
                "替换子任务创建完成",
                self._operation_create_retry_children,
                TASK_OPERATION_STEP_VERIFY_RETRY_BINDINGS,
            ),
            (
                TASK_OPERATION_STEP_VERIFY_RETRY_BINDINGS,
                "开始校验失败项重试绑定",
                "失败项重试绑定校验完成",
                self._operation_verify_retry_bindings,
                TASK_OPERATION_STEP_FINALIZE_RETRY_OPERATION,
            ),
            (
                TASK_OPERATION_STEP_FINALIZE_RETRY_OPERATION,
                "开始完成失败项重试操作",
                "失败项重试操作已完成",
                self._operation_finalize_retry_failed_items,
                TASK_OPERATION_STEP_REQUEUE_TASK,
            ),
        )
        current_step = resume_step if resume_step in {row[0] for row in step_flow} else TASK_OPERATION_STEP_COLLECT_CLEANUP_PLAN
        for step_name, start_message, finish_message, handler, next_step in step_flow:
            if current_step != step_name:
                continue
            self._record_operation_step_started(
                db,
                task,
                operation,
                step_name=step_name,
                message=f"{start_message}: {operation.operation_type}",
                stage_name=operation.target_stage,
                payload={"operation_type": operation.operation_type},
            )
            db.commit()
            try:
                payload = await handler(db, task, operation)
            except Exception as exc:
                self._record_operation_step_failed(
                    db,
                    task,
                    operation,
                    step_name=step_name,
                    error=exc,
                    stage_name=operation.target_stage,
                )
                db.commit()
                raise
            self._record_operation_step_finished(
                db,
                task,
                operation,
                step_name=step_name,
                message=f"{finish_message}: {operation.operation_type}",
                stage_name=operation.target_stage,
                payload=dict(payload or {}),
                next_step=next_step,
            )
            db.commit()
            current_step = next_step

        if current_step != TASK_OPERATION_STEP_REQUEUE_TASK:
            return
        if self._is_operation_requeue_state_applied(task, operation):
            self._record_operation_step_finished(
                db,
                task,
                operation,
                step_name=TASK_OPERATION_STEP_REQUEUE_TASK,
                message=f"后台操作重新排队步骤已确认完成，无需重复执行: {operation.operation_type}",
                stage_name=operation.target_stage,
                payload={"idempotent_recovery": True},
                next_step=TASK_OPERATION_STEP_SUCCEEDED,
            )
            db.commit()
            return
        self._record_operation_step_started(
            db,
            task,
            operation,
            step_name=TASK_OPERATION_STEP_REQUEUE_TASK,
            message=f"后台操作进入重新排队步骤: {operation.operation_type}",
            stage_name=operation.target_stage,
        )
        task.status = "pending"
        task.current_stage = operation.target_stage or task.current_stage
        task.last_error = None
        task.finished_at = None
        self._invalidate_task_execution(task)
        self._enqueue_task(task.id)
        self._update_operation_result_payload(
            operation,
            {
                "requeue": {
                    "requested": True,
                    "task_status_before": "retry_operation_succeeded",
                    "task_status_after": task.status,
                },
            },
            workspace_root=task.workspace_root,
        )
        self._record_operation_event(
            db,
            task,
            operation,
            "task_requeued",
            f"失败项重试完成，任务已重新排队: {operation.operation_type}",
            stage_name=operation.target_stage,
        )
        self._record_operation_step_finished(
            db,
            task,
            operation,
            step_name=TASK_OPERATION_STEP_REQUEUE_TASK,
            message=f"后台操作重新排队步骤已完成: {operation.operation_type}",
            stage_name=operation.target_stage,
            next_step=TASK_OPERATION_STEP_SUCCEEDED,
        )
        db.commit()

    async def _run_retry_stage_full_operation_steps(
        self,
        db: Session,
        task: BinarySecurityTask,
        operation: BinarySecurityTaskOperation,
        resume_step: str,
    ) -> str:
        step_flow = (
            (
                TASK_OPERATION_STEP_COLLECT_CLEANUP_PLAN,
                "后台操作开始收集清理计划",
                "后台操作清理计划收集完成",
                self._operation_collect_retry_stage_full_plan,
                TASK_OPERATION_STEP_CANCEL_DOWNSTREAM,
            ),
            (
                TASK_OPERATION_STEP_CANCEL_DOWNSTREAM,
                "后台操作开始清理下游子任务",
                "后台操作下游子任务清理完成",
                self._operation_execute_retry_stage_full_cleanup,
                TASK_OPERATION_STEP_REQUEUE_TASK,
            ),
        )
        for step_name, start_message, finish_message, handler, next_step in step_flow:
            if resume_step != step_name:
                continue
            self._record_operation_step_started(
                db,
                task,
                operation,
                step_name=step_name,
                message=f"{start_message}: {operation.operation_type}",
                stage_name=operation.target_stage,
                payload={"operation_type": operation.operation_type},
            )
            db.commit()
            try:
                payload = await handler(db, task, operation)
            except Exception as exc:
                self._record_operation_step_failed(
                    db,
                    task,
                    operation,
                    step_name=step_name,
                    error=exc,
                    stage_name=operation.target_stage,
                )
                db.commit()
                raise
            self._record_operation_step_finished(
                db,
                task,
                operation,
                step_name=step_name,
                message=f"{finish_message}: {operation.operation_type}",
                stage_name=operation.target_stage,
                payload=payload,
                next_step=next_step,
            )
            db.commit()
            resume_step = next_step
        return resume_step

    async def _operation_collect_retry_failed_items_plan(
        self,
        db: Session,
        task: BinarySecurityTask,
        operation: BinarySecurityTaskOperation,
    ) -> dict[str, Any]:
        target_stage = str(operation.target_stage or "").strip()
        await self._collect_retry_item_actions(db, task, target_stage=target_stage, token=self._service_token())
        return self._sync_retry_operation_result_payload(
            db,
            task,
            operation,
            target_stage=target_stage,
            phase="prepare",
        )

    async def _operation_sync_retry_target_stage_state(
        self,
        db: Session,
        task: BinarySecurityTask,
        operation: BinarySecurityTaskOperation,
    ) -> dict[str, Any]:
        target_stage = str(operation.target_stage or "").strip()
        item_ids = [
            str(action.get("item_id") or "").strip()
            for action in self._retry_item_actions(task)
            if str(action.get("item_id") or "").strip()
        ]
        batch_size = self._operation_step_batch_size()
        cursor = dict(operation.resume_cursor or {})
        step_cursor = dict(cursor.get(TASK_OPERATION_STEP_SYNC_TARGET_STAGE_STATE) or {})
        offset = max(0, int(step_cursor.get("offset") or 0))
        synced_count = 0
        for batch_start in range(offset, len(item_ids), batch_size):
            batch_item_ids = item_ids[batch_start:batch_start + batch_size]
            await self.sync_downstream_status(
                db,
                project_id=task.project_id,
                task_id=task.id,
                stage_name=target_stage,
                item_ids=batch_item_ids,
                force=True,
                token=self._service_token(),
                record_request_event=False,
                record_noop_events=False,
                apply_state=(target_stage != "entry_analysis"),
            )
            synced_count += len(batch_item_ids)
            next_offset = batch_start + len(batch_item_ids)
            await self._operation_progress_heartbeat(
                db,
                task,
                operation,
                step_name=TASK_OPERATION_STEP_SYNC_TARGET_STAGE_STATE,
                resume_cursor={
                    "current_step": TASK_OPERATION_STEP_SYNC_TARGET_STAGE_STATE,
                    TASK_OPERATION_STEP_SYNC_TARGET_STAGE_STATE: {
                        "offset": next_offset,
                        "processed_count": next_offset,
                        "total_count": len(item_ids),
                    },
                },
                payload={
                    "batch_size": len(batch_item_ids),
                    "processed_count": next_offset,
                    "remaining_count": max(0, len(item_ids) - next_offset),
                    "total_count": len(item_ids),
                },
            )
        payload = {"target_stage": target_stage, "synced": True, "synced_items": synced_count, "total_items": len(item_ids)}
        self._update_operation_result_payload(
            operation,
            {"sync_target_stage_state": payload},
            workspace_root=task.workspace_root,
        )
        return payload

    async def _operation_prepare_retry_items(
        self,
        db: Session,
        task: BinarySecurityTask,
        operation: BinarySecurityTaskOperation,
    ) -> dict[str, Any]:
        target_stage = str(operation.target_stage or "").strip()
        affected_stages = await self._prepare_retry_failed_items(db, task, target_stage)
        prepare_result = self._build_retry_prepare_result(db, task, target_stage=target_stage)
        prepare_result["affected_stages"] = affected_stages
        self._sync_retry_operation_result_payload(
            db,
            task,
            operation,
            target_stage=target_stage,
            phase="prepare",
            extra_updates=prepare_result,
        )
        validation = dict(prepare_result.get("validation") or {})
        if not bool(validation.get("validated")):
            self._record_operation_event(
                db,
                task,
                operation,
                "retry_prepare_validation_failed",
                "失败项重试准备校验失败",
                level="error",
                stage_name=operation.target_stage,
                payload=prepare_result,
            )
            raise ValidationError("失败项重试准备校验失败")
        self._record_operation_event(
            db,
            task,
            operation,
            "retry_prepare_validation_succeeded",
            "失败项重试准备校验通过",
            stage_name=operation.target_stage,
            payload=prepare_result,
        )
        return prepare_result

    async def _operation_cleanup_retry_abnormal_children(
        self,
        db: Session,
        task: BinarySecurityTask,
        operation: BinarySecurityTaskOperation,
    ) -> dict[str, Any]:
        cleaned = 0
        batch_size = self._operation_step_batch_size()
        for action in self._retry_item_actions(task):
            if str(action.get("strategy") or "").strip() != RETRY_CHILD_STRATEGY_RECREATE_FROM_ABNORMAL:
                continue
            item = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.id == str(action.get("item_id") or "")).first()
            if item is None:
                raise ValidationError(f"失败项重试目标缺失: {action.get('item_id')}")
            old_task_id = str(action.get("old_downstream_task_id") or "").strip()
            self._record_operation_event(
                db,
                task,
                operation,
                "retry_item_cleanup_started",
                f"开始清理旧下游子任务: {item.downstream_service}:{old_task_id or '-'}",
                stage_name=item.stage_name,
                payload={"item_id": item.id, "item_key": item.item_key, "old_downstream_task_id": old_task_id},
            )
            if old_task_id:
                refs = [{
                    "service": item.downstream_service,
                    "task_id": old_task_id,
                    "project_id": task.project_id,
                    "stage_name": item.stage_name,
                    "item_id": item.id,
                    "item_key": item.item_key,
                }]
                try:
                    await self._downstream_cancel_refs(db, task, refs, self._service_token())
                except Exception:
                    db.rollback()
                try:
                    await self._delete_downstream_refs(db, task, refs, self._service_token())
                except Exception as exc:
                    self._update_retry_item_action(
                        task,
                        item_id=item.id,
                        updates={
                            "cleanup_status": "failed",
                            "error": str(exc),
                        },
                    )
                    self._record_operation_event(
                        db,
                        task,
                        operation,
                        "retry_item_cleanup_failed",
                        f"旧下游子任务清理失败: {item.downstream_service}:{old_task_id}",
                        level="error",
                        stage_name=item.stage_name,
                        payload={
                            "item_id": item.id,
                            "item_key": item.item_key,
                            "old_downstream_task_id": old_task_id,
                            "error": str(exc),
                        },
                    )
                    raise
            self._clear_item_downstream_runtime_state(item)
            item.status = "pending"
            item.finished_at = None
            self._update_retry_item_action(
                task,
                item_id=item.id,
                updates={
                    "cleanup_performed": True,
                    "binding_cleared": True,
                    "cleanup_status": "succeeded",
                    "current_downstream_task_id": None,
                    "new_downstream_task_id": None,
                },
            )
            self._record_operation_event(
                db,
                task,
                operation,
                "retry_item_cleanup_succeeded",
                f"旧下游子任务已清理: {item.downstream_service}:{old_task_id or '-'}",
                stage_name=item.stage_name,
                payload={"item_id": item.id, "item_key": item.item_key, "old_downstream_task_id": old_task_id},
            )
            cleaned += 1
            if cleaned % batch_size == 0:
                await self._operation_progress_heartbeat(
                    db,
                    task,
                    operation,
                    step_name=TASK_OPERATION_STEP_CLEANUP_ABNORMAL_CHILDREN,
                    payload={"processed_count": cleaned},
                )
        self._sync_retry_operation_result_payload(
            db,
            task,
            operation,
            target_stage=str(operation.target_stage or "").strip(),
            phase="prepare",
            extra_updates={"cleanup": {"cleaned_items": cleaned}},
        )
        return {"cleaned_items": cleaned}

    async def _operation_create_retry_children(
        self,
        db: Session,
        task: BinarySecurityTask,
        operation: BinarySecurityTaskOperation,
    ) -> dict[str, Any]:
        created_count = 0
        batch_size = self._operation_step_batch_size()
        for action in self._retry_item_actions(task):
            strategy = str(action.get("strategy") or "").strip()
            if strategy != RETRY_CHILD_STRATEGY_RECREATE_FROM_ABNORMAL:
                continue
            item = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.id == str(action.get("item_id") or "")).first()
            if item is None:
                raise ValidationError(f"失败项重试目标缺失: {action.get('item_id')}")
            if str(item.downstream_task_id or "").strip():
                self._update_retry_item_action(
                    task,
                    item_id=item.id,
                    updates={
                        "new_downstream_task_id": str(item.downstream_task_id or "").strip(),
                        "create_status": "succeeded",
                    },
                )
                continue
            recovered_payload = await self._find_retry_created_child_payload(task, item)
            if isinstance(recovered_payload, dict):
                recovered_task_id = str(recovered_payload.get("task_id") or recovered_payload.get("id") or "").strip()
                if recovered_task_id:
                    item.downstream_task_id = recovered_task_id
                    item.status = self._map_downstream_status(str(recovered_payload.get("status") or "")) or "pending"
                    item.started_at = item.started_at or _now()
                    item.error_message = None
                    self._update_retry_item_action(
                        task,
                        item_id=item.id,
                        updates={
                            "current_downstream_task_id": recovered_task_id,
                            "new_downstream_task_id": recovered_task_id,
                            "create_status": "succeeded",
                            "error": None,
                        },
                    )
                    self._record_operation_event(
                        db,
                        task,
                        operation,
                        "retry_item_create_succeeded",
                        f"重试恢复已创建的替换子任务: {item.downstream_service}:{recovered_task_id}",
                        stage_name=item.stage_name,
                        payload={
                            "item_id": item.id,
                            "item_key": item.item_key,
                            "service": item.downstream_service,
                            "new_downstream_task_id": recovered_task_id,
                            "idempotent_recovery": True,
                        },
                    )
                    created_count += 1
                    if created_count % batch_size == 0:
                        await self._operation_progress_heartbeat(
                            db,
                            task,
                            operation,
                            step_name=TASK_OPERATION_STEP_CREATE_REPLACEMENT_CHILDREN,
                            payload={"processed_count": created_count},
                        )
                    continue
            service, token, payload = self._retry_recreate_payload_for_item(task, item)
            self._record_operation_event(
                db,
                task,
                operation,
                "retry_item_create_started",
                f"开始创建替换子任务: {service}",
                stage_name=item.stage_name,
                payload={"item_id": item.id, "item_key": item.item_key, "service": service},
            )
            try:
                created = await self._downstream_create_task(db, task, item, service=service, token=token, payload=payload)
            except Exception as exc:
                self._update_retry_item_action(
                    task,
                    item_id=item.id,
                    updates={
                        "create_status": "failed",
                        "error": str(exc),
                    },
                )
                self._record_operation_event(
                    db,
                    task,
                    operation,
                    "retry_item_create_failed",
                    f"替换子任务创建失败: {service}",
                    level="error",
                    stage_name=item.stage_name,
                    payload={
                        "item_id": item.id,
                        "item_key": item.item_key,
                        "service": service,
                        "error": str(exc),
                    },
                )
                raise
            new_task_id = str(created.get("task_id") or created.get("id") or "").strip()
            if not new_task_id:
                self._update_retry_item_action(
                    task,
                    item_id=item.id,
                    updates={
                        "create_status": "failed",
                        "error": f"missing task id for {service}:{item.item_key}",
                    },
                )
                raise ValidationError(f"重试创建新子任务失败，缺少任务ID: {service}:{item.item_key}")
            item.downstream_task_id = new_task_id
            item.status = self._map_downstream_status(str(created.get("status") or "")) or "pending"
            item.started_at = item.started_at or _now()
            item.error_message = None
            self._update_retry_item_action(
                task,
                item_id=item.id,
                updates={
                    "current_downstream_task_id": new_task_id,
                    "new_downstream_task_id": new_task_id,
                    "create_status": "succeeded",
                },
            )
            self._record_operation_event(
                db,
                task,
                operation,
                "retry_item_create_succeeded",
                f"替换子任务已创建: {service}:{new_task_id}",
                stage_name=item.stage_name,
                payload={"item_id": item.id, "item_key": item.item_key, "service": service, "new_downstream_task_id": new_task_id},
            )
            created_count += 1
            if created_count % batch_size == 0:
                await self._operation_progress_heartbeat(
                    db,
                    task,
                    operation,
                    step_name=TASK_OPERATION_STEP_CREATE_REPLACEMENT_CHILDREN,
                    payload={"processed_count": created_count},
                )
        self._sync_retry_operation_result_payload(
            db,
            task,
            operation,
            target_stage=str(operation.target_stage or "").strip(),
            phase="prepare",
            extra_updates={"create": {"created_items": created_count}},
        )
        return {"created_items": created_count}

    async def _operation_verify_retry_bindings(
        self,
        db: Session,
        task: BinarySecurityTask,
        operation: BinarySecurityTaskOperation,
    ) -> dict[str, Any]:
        target_stage = str(operation.target_stage or "").strip()
        await self._operation_reconcile_retry_non_abnormal_children(db, task, operation)
        if any(
            str(action.get("strategy") or "").strip() == RETRY_CHILD_STRATEGY_RECREATE_FROM_ABNORMAL
            and str(action.get("cleanup_status") or "").strip() == "pending"
            for action in self._retry_item_actions(task)
        ):
            cleanup_payload = await self._operation_cleanup_retry_abnormal_children(db, task, operation)
            create_payload = await self._operation_create_retry_children(db, task, operation)
            self._sync_retry_operation_result_payload(
                db,
                task,
                operation,
                target_stage=target_stage,
                phase="verify",
                extra_updates={
                    "cleanup": dict(cleanup_payload or {}),
                    "create": dict(create_payload or {}),
                },
            )
        processed_count = 0
        batch_size = self._operation_step_batch_size()
        for action in self._retry_item_actions(task):
            item_id = str(action.get("item_id") or "").strip()
            item = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.id == item_id).first()
            if item is None:
                self._update_retry_item_action(
                    task,
                    item_id=item_id,
                    updates={
                        "verification_status": "skipped_missing",
                    },
                )
                continue
            strategy = str(action.get("strategy") or "").strip()
            if strategy == RETRY_CHILD_STRATEGY_RECREATE_FROM_ABNORMAL:
                old_task_id = str(action.get("old_downstream_task_id") or "").strip()
                new_task_id = str(item.downstream_task_id or "").strip()
                if not new_task_id:
                    self._record_operation_event(
                        db,
                        task,
                        operation,
                        "retry_item_binding_verification_failed",
                        f"失败项重试未生成新的下游任务: {item.item_key}",
                        level="error",
                        stage_name=item.stage_name,
                        payload={
                            "item_id": item.id,
                            "item_key": item.item_key,
                            "strategy": strategy,
                            "old_downstream_task_id": old_task_id,
                        },
                    )
                    raise ValidationError(f"失败项重试未生成新的下游任务: {item.item_key}")
                if old_task_id and old_task_id == new_task_id:
                    self._record_operation_event(
                        db,
                        task,
                        operation,
                        "retry_item_binding_verification_failed",
                        f"失败项重试仍绑定旧下游任务: {item.item_key}",
                        level="error",
                        stage_name=item.stage_name,
                        payload={
                            "item_id": item.id,
                            "item_key": item.item_key,
                            "strategy": strategy,
                            "old_downstream_task_id": old_task_id,
                            "new_downstream_task_id": new_task_id,
                        },
                    )
                    raise ValidationError(f"失败项重试仍绑定旧下游任务: {item.item_key}")
            self._update_retry_item_action(
                task,
                item_id=item_id,
                updates={
                    "current_downstream_task_id": str(item.downstream_task_id or "").strip() or None,
                    "new_downstream_task_id": str(item.downstream_task_id or "").strip() or None,
                    "verification_status": "succeeded",
                },
            )
            self._record_operation_event(
                db,
                task,
                operation,
                "retry_item_binding_verified",
                "失败项重试绑定已校验通过",
                stage_name=item.stage_name,
                payload={
                    "item_id": item.id,
                    "item_key": item.item_key,
                    "strategy": strategy,
                    "old_downstream_task_id": action.get("old_downstream_task_id"),
                    "new_downstream_task_id": item.downstream_task_id,
                },
            )
            processed_count += 1
            if processed_count % batch_size == 0:
                await self._operation_progress_heartbeat(
                    db,
                    task,
                    operation,
                    step_name=TASK_OPERATION_STEP_VERIFY_RETRY_BINDINGS,
                    payload={"processed_count": processed_count},
                )
        db.flush()
        refreshed_actions = self._retry_item_actions(task)
        result = self._build_retry_prepare_result(db, task, target_stage=target_stage, phase="verify")
        validation = dict(result.get("validation") or {})
        if not bool(validation.get("validated")):
            result = {
                **result,
                "item_actions": refreshed_actions,
            }
            self._record_operation_event(
                db,
                task,
                operation,
                "retry_item_binding_verification_failed",
                "失败项重试绑定校验失败",
                level="error",
                stage_name=operation.target_stage,
                payload=result,
            )
            raise ValidationError("失败项重试绑定校验失败")
        self._sync_retry_operation_result_payload(
            db,
            task,
            operation,
            target_stage=target_stage,
            phase="verify",
            extra_updates={
                **result,
                "item_actions": refreshed_actions,
            },
        )
        return result

    async def _find_retry_created_child_payload(
        self,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
    ) -> dict[str, Any] | None:
        service = str(item.downstream_service or "").strip()
        token = self._resolve_downstream_token()
        if service == "firmware_unpacker":
            return await self._find_reusable_firmware_unpack_payload(task, item, token)
        if service == "system_analyse":
            return await self._find_reusable_system_analysis_payload(task, item, token)
        if service == "binary_to_source":
            return await self._find_reusable_b2s_payload(task, item, token)
        if service == "entry_analyse":
            return await self._find_reusable_entry_payload(task, item, token)
        if service == "dataflow_analyse":
            return None
        if service == "dataflow_vuln_scan":
            return await self._find_reusable_vuln_payload(task, item, token)
        return None

    async def _operation_reconcile_retry_non_abnormal_children(
        self,
        db: Session,
        task: BinarySecurityTask,
        operation: BinarySecurityTaskOperation,
    ) -> dict[str, Any]:
        reused = 0
        adopted = 0
        for action in self._retry_item_actions(task):
            item_id = str(action.get("item_id") or "").strip()
            item = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.id == item_id).first()
            if item is None:
                self._update_retry_item_action(
                    task,
                    item_id=item_id,
                    updates={
                        "verification_status": "skipped_missing",
                    },
                )
                continue
            strategy = str(action.get("strategy") or "").strip()
            if strategy == RETRY_CHILD_STRATEGY_REUSE_SUCCESS:
                item.status = "success"
                self._update_retry_item_action(
                    task,
                    item_id=item_id,
                    updates={
                        "cleanup_status": "not_required",
                        "create_status": "not_required",
                        "verification_status": "succeeded",
                        "current_downstream_task_id": str(item.downstream_task_id or "").strip() or None,
                        "new_downstream_task_id": str(item.downstream_task_id or "").strip() or None,
                    },
                )
                reused += 1
                continue
            if strategy != RETRY_CHILD_STRATEGY_ADOPT_ACTIVE:
                continue
            control = await self._downstream_control_existing_task(
                db,
                stage_name=item.stage_name,
                task=task,
                item=item,
                token=self._resolve_downstream_token(),
            )
            payload = dict(control.get("payload") or {})
            outcome = str(control.get("outcome") or "").strip()
            if outcome in {"accepted", "already_running", "already_terminal"}:
                rebound_task_id = str(payload.get("task_id") or payload.get("id") or "").strip()
                if rebound_task_id:
                    item.downstream_task_id = rebound_task_id
                payload_status = self._map_downstream_status(str(payload.get("status") or "")) or ""
                if outcome == "already_terminal" or payload_status not in {"pending", "queued", "dispatching", "running", ""}:
                    normalized_terminal = payload_status or self._normalize_item_status(item.status)
                    self._update_retry_item_action(
                        task,
                        item_id=item_id,
                        updates={
                            "strategy": RETRY_CHILD_STRATEGY_RECREATE_FROM_ABNORMAL,
                            "observed_status": normalized_terminal,
                            "cleanup_required": True,
                            "create_required": True,
                            "cleanup_status": "pending",
                            "create_status": "pending",
                            "verification_status": "pending",
                            "old_downstream_task_id": str(item.downstream_task_id or "").strip() or None,
                            "error": None,
                        },
                    )
                    continue
            elif outcome == "not_found":
                self._update_retry_item_action(
                    task,
                    item_id=item_id,
                    updates={
                        "strategy": RETRY_CHILD_STRATEGY_RECREATE_FROM_ABNORMAL,
                        "observed_status": "downstream_missing",
                        "cleanup_required": True,
                        "create_required": True,
                        "cleanup_status": "pending",
                        "create_status": "pending",
                        "verification_status": "pending",
                        "old_downstream_task_id": str(item.downstream_task_id or "").strip() or None,
                        "error": None,
                    },
                )
                continue
            normalized_status = self._normalize_item_status(item.status)
            if normalized_status not in {"pending", "queued", "dispatching", "running"}:
                self._update_retry_item_action(
                    task,
                    item_id=item_id,
                    updates={
                        "strategy": RETRY_CHILD_STRATEGY_RECREATE_FROM_ABNORMAL,
                        "observed_status": normalized_status,
                        "cleanup_required": True,
                        "create_required": True,
                        "cleanup_status": "pending",
                        "create_status": "pending",
                        "verification_status": "pending",
                        "old_downstream_task_id": str(item.downstream_task_id or "").strip() or None,
                        "error": None,
                    },
                )
                continue
            self._update_retry_item_action(
                task,
                item_id=item_id,
                updates={
                    "cleanup_status": "not_required",
                    "create_status": "not_required",
                    "verification_status": "succeeded",
                    "current_downstream_task_id": str(item.downstream_task_id or "").strip() or None,
                    "new_downstream_task_id": str(item.downstream_task_id or "").strip() or None,
                },
            )
            adopted += 1
        self._sync_retry_operation_result_payload(
            db,
            task,
            operation,
            target_stage=str(operation.target_stage or "").strip(),
            phase="prepare",
            extra_updates={
                "non_abnormal": {"reused_items": reused, "adopted_items": adopted},
            },
        )
        return {"reused_items": reused, "adopted_items": adopted}

    async def _operation_finalize_retry_failed_items(
        self,
        db: Session,
        task: BinarySecurityTask,
        operation: BinarySecurityTaskOperation,
    ) -> dict[str, Any]:
        payload = {"finalized": True, "target_stage": operation.target_stage}
        self._sync_retry_operation_result_payload(
            db,
            task,
            operation,
            target_stage=str(operation.target_stage or "").strip(),
            phase="verify",
            extra_updates={"finalize": payload},
        )
        self._record_operation_event(
            db,
            task,
            operation,
            "retry_operation_succeeded",
            "失败项重试控制面已收敛",
            stage_name=operation.target_stage,
            payload=payload,
        )
        return payload

    async def _dispatch_loop(self) -> None:
        session_factory = get_session_factory()
        while self._running:
            task_id = None
            db = session_factory()
            try:
                with observe_scheduler_loop("task_dispatch"):
                    self._mark_loop_heartbeat("task_dispatch")
                    task_id = await get_task_queue().pop_task(self.cfg.queue.block_timeout_seconds)
                    if task_id:
                        claimed_id = self._dispatch_task_by_id(db, task_id)
                        if claimed_id:
                            async with self._worker_lock:
                                if claimed_id not in self._workers or self._workers[claimed_id].done():
                                    self._workers[claimed_id] = asyncio.create_task(
                                        self._run_task(claimed_id),
                                        name=f"binary-security-{claimed_id}",
                                    )
                    await self._reconcile_work_queues(db)
                    await self._observe_runtime_metrics(db)
                    self._mark_loop_heartbeat("task_dispatch")
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                self._recover_loop_db_error("task_dispatch", db, exc)
                logger.exception("binary-security task dispatch loop crashed and recovered")
                await asyncio.sleep(1)
            finally:
                with suppress(Exception):
                    db.close()

    async def _stage_item_dispatch_loop(self) -> None:
        session_factory = get_session_factory()
        while self._running:
            db = session_factory()
            try:
                with observe_scheduler_loop("stage_item_dispatch"):
                    self._mark_loop_heartbeat("stage_item_dispatch")
                    claimed_ids = self._claim_streaming_stage_items(db)
                    if claimed_ids:
                        async with self._stage_item_worker_lock:
                            for item_id in claimed_ids:
                                existing = self._stage_item_workers.get(item_id)
                                if existing is not None and not existing.done():
                                    continue
                                self._stage_item_workers[item_id] = asyncio.create_task(
                                    self._run_stage_item_by_id(item_id),
                                    name=f"binary-security-stage-item-{item_id}",
                                )
                    await self._observe_runtime_metrics(db)
                    self._mark_loop_heartbeat("stage_item_dispatch")
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                self._recover_loop_db_error("stage_item_dispatch", db, exc)
                logger.exception("binary-security stage item dispatch loop crashed and recovered")
                await asyncio.sleep(1)
            finally:
                with suppress(Exception):
                    db.close()
            await asyncio.sleep(max(1, int(self.cfg.scheduler.stage_poll_interval_seconds or 5)))

    def _claim_streaming_stage_items(self, db: Session) -> list[str]:
        claimed_ids: list[str] = []
        claimed_counts_by_stage: dict[tuple[str, str], int] = {}
        pending_items = (
            db.query(BinarySecurityStageItem)
            .filter(BinarySecurityStageItem.status.in_(["pending", "queued"]))
            .order_by(BinarySecurityStageItem.created_at.asc(), BinarySecurityStageItem.id.asc())
            .all()
        )
        for item in pending_items:
            if item.stage_name not in STREAMING_TAIL_STAGES:
                continue
            try:
                task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == item.task_id).first()
            except OperationalError as exc:
                if not self._is_retryable_lock_error(exc):
                    raise
                db.rollback()
                logger.warning(
                    "binary-security streaming stage item claim skipped by retryable lock conflict while loading task: item_id=%s task_id=%s",
                    item.id,
                    item.task_id,
                )
                continue
            if task is None or not self._streaming_mode_enabled(task):
                continue
            if task.status in TASK_TERMINAL_STATUSES or task.status == "cancelled":
                continue
            if not self._is_streaming_tail_stage(task, item.stage_name):
                continue
            if self._stage_item_orchestration_in_retry_backoff(item):
                continue
            dispatch_throttle = self._effective_runtime_policy(task).get("dispatch_throttle") or {}
            throttle_entry = dict(dispatch_throttle.get(item.stage_name) or {}) if isinstance(dispatch_throttle, dict) else {}
            max_new_items_per_tick = int(throttle_entry.get("max_new_items_per_tick") or 0)
            throttle_key = (str(task.id), str(item.stage_name))
            if max_new_items_per_tick > 0 and claimed_counts_by_stage.get(throttle_key, 0) >= max_new_items_per_tick:
                continue
            try:
                active_count = int(
                    db.query(func.count(BinarySecurityStageItem.id))
                    .filter(
                        BinarySecurityStageItem.task_id == task.id,
                        BinarySecurityStageItem.stage_name == item.stage_name,
                        BinarySecurityStageItem.status.in_(["dispatching", "queued", "running"]),
                    )
                    .scalar()
                    or 0
                )
            except OperationalError as exc:
                if not self._is_retryable_lock_error(exc):
                    raise
                db.rollback()
                logger.warning(
                    "binary-security streaming stage item claim skipped by retryable lock conflict while counting active items: item_id=%s stage=%s",
                    item.id,
                    item.stage_name,
                )
                continue
            if active_count >= self._stage_parallelism(task, item.stage_name):
                continue
            try:
                updated = (
                    db.query(BinarySecurityStageItem)
                    .filter(
                        BinarySecurityStageItem.id == item.id,
                        BinarySecurityStageItem.status.in_(["pending", "queued"]),
                    )
                    .update(
                        {
                            BinarySecurityStageItem.status: "dispatching",
                            BinarySecurityStageItem.started_at: _now(),
                            BinarySecurityStageItem.updated_at: _now(),
                        },
                        synchronize_session=False,
                    )
                )
            except OperationalError as exc:
                if not self._is_retryable_lock_error(exc):
                    raise
                db.rollback()
                logger.warning(
                    "binary-security streaming stage item claim skipped by retryable lock conflict while updating item: item_id=%s stage=%s",
                    item.id,
                    item.stage_name,
                )
                continue
            if updated:
                claimed_ids.append(item.id)
                claimed_counts_by_stage[throttle_key] = claimed_counts_by_stage.get(throttle_key, 0) + 1
        if claimed_ids:
            try:
                db.commit()
            except OperationalError as exc:
                if not self._is_retryable_lock_error(exc):
                    raise
                db.rollback()
                logger.warning(
                    "binary-security streaming stage item claim commit skipped by retryable lock conflict: item_ids=%s",
                    claimed_ids,
                )
                return []
        return claimed_ids

    async def _run_stage_item_by_id(self, item_id: str) -> None:
        db = get_session_factory()()
        owner_task_id: str | None = None
        owner_kind = f"streaming_stage_item:{item_id}"
        try:
            item = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.id == item_id).first()
            if item is None:
                return
            task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == item.task_id).first()
            if task is None or not self._streaming_mode_enabled(task):
                return
            if task.status in TASK_TERMINAL_STATUSES or task.status == "cancelled":
                return
            owner_task_id = task.id
            self._register_task_execution_owner(owner_task_id, owner_kind)
            stage_run = self._ensure_stage_run(db, task, item.stage_name)
            db.commit()
            payload = dict(item.input_ref or {})
            token = self._service_token()
            if item.stage_name == "entry_analysis":
                await self._run_entry_item(task, stage_run, payload, token, False)
            elif normalize_stage_name(item.stage_name) == "dataflow_vuln_scan":
                await self._run_dataflow_item(task, stage_run, payload, token, False)
            elif normalize_stage_name(item.stage_name) == "dataflow_vuln_scan":
                await self._run_dataflow_item(task, stage_run, payload, token, False)
            await self._sync_streaming_task_tail_state(task.id)
        except StaleTaskExecution as exc:
            item = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.id == item_id).first()
            task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == item.task_id).first() if item is not None else None
            if item is not None and str(item.status or "").strip().lower() == "dispatching":
                item.status = "pending"
                item.error_message = str(exc)
                item.finished_at = None
                if task is not None and self._should_hold_task_on_stage_after_requeue(db, task, item.stage_name):
                    task.status = "running"
                    task.current_stage = item.stage_name
                    task.finished_at = None
                    task.last_error = None
                    task.dispatcher_instance_id = None
                    task.dispatch_started_at = None
                    task.lease_expires_at = None
                db.commit()
                if task is not None:
                    self._record_event(
                        db,
                        task,
                        "streaming_stage_item_requeued_after_stale_execution",
                        f"流式阶段子任务执行 token 失效，已重新排队: {item.stage_name}:{item.item_key}",
                        level="warning",
                        stage_name=item.stage_name,
                        item=item,
                        payload={
                            "error": str(exc),
                            "requeued_status": item.status,
                        },
                    )
                    db.commit()
            logger.warning("binary-security streaming stage item stale execution: item_id=%s error=%s", item_id, exc)
        except Exception as exc:
            item = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.id == item_id).first()
            task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == item.task_id).first() if item is not None else None
            if item is not None and str(item.status or "").strip().lower() == "dispatching":
                retryable_transport = self._is_retryable_downstream_transport_error(exc)
                recoverable = retryable_transport or self._is_recoverable_orchestration_error(exc)
                item.status = "queued" if recoverable else "pending"
                item.error_message = str(exc)
                item.finished_at = None
                if recoverable:
                    state = self._build_next_stage_item_orchestration_failure_state(item)
                    self._mark_stage_item_orchestration_observation(
                        item,
                        source="streaming_stage_worker",
                        observed_at=_now(),
                        error_message=str(exc),
                        error_type=self._classify_orchestration_error(exc),
                        last_result="error",
                        consecutive_error_count=state.consecutive_error_count,
                        budget_exhausted=state.budget_exhausted,
                        next_retry_at=state.next_retry_at,
                    )
                db.commit()
                if task is not None:
                    self._record_event(
                        db,
                        task,
                        "streaming_stage_item_requeued_after_worker_error",
                        f"流式阶段子任务执行异常，已重新排队: {item.stage_name}:{item.item_key}",
                        level="warning",
                        stage_name=item.stage_name,
                        item=item,
                        payload={
                            "error": str(exc),
                            "retryable_transport": retryable_transport,
                            "recoverable_orchestration": recoverable,
                            "error_type": self._classify_orchestration_error(exc),
                            "next_retry_at": _isoformat_or_none(self._stage_item_next_orchestration_retry_at_value(item)),
                            "budget_exhausted": self._stage_item_orchestration_error_budget_exhausted(item),
                            "requeued_status": item.status,
                        },
                    )
                    db.commit()
            logger.exception("binary-security streaming stage item worker failed: item_id=%s", item_id)
        finally:
            if owner_task_id:
                self._release_task_execution_owner(owner_task_id, owner_kind)
            db.close()
            async with self._stage_item_worker_lock:
                self._stage_item_workers.pop(item_id, None)

    async def _sync_streaming_task_tail_state(self, task_id: str) -> None:
        db = get_session_factory()()
        try:
            task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == task_id).first()
            if task is None or not self._streaming_mode_enabled(task):
                return
            tail_stages = self._streaming_tail_stage_names(task)
            if not tail_stages:
                return
            prior_tail_statuses = {
                stage_name: str(
                    (
                        db.query(BinarySecurityStageRun)
                        .filter(
                            BinarySecurityStageRun.task_id == task.id,
                            BinarySecurityStageRun.stage_name == stage_name,
                        )
                        .first()
                        or BinarySecurityStageRun(stage_name=stage_name, task_id=task.id, project_id=task.project_id, sequence_no=0, status="pending")
                    ).status
                    or ""
                ).strip()
                for stage_name in tail_stages
            }
            for stage_name in tail_stages:
                self._refresh_streaming_tail_stage_state(db, task, stage_name)
            active_count = int(
                db.query(func.count(BinarySecurityStageItem.id))
                .filter(
                    BinarySecurityStageItem.task_id == task.id,
                    BinarySecurityStageItem.stage_name.in_(list(tail_stages)),
                    BinarySecurityStageItem.status.in_(list(STREAMING_ACTIVE_ITEM_STATUSES)),
                )
                .scalar()
                or 0
            )
            if active_count > 0:
                next_active_stage = next(
                    (
                        stage_name
                        for stage_name in tail_stages
                        if any(
                            self._is_streaming_active_item_status(item.status)
                            for item in self._stage_items(db, task.id, stage_name)
                        )
                    ),
                    tail_stages[0],
                )
                task.status = "running"
                task.current_stage = next_active_stage
                task.finished_at = None
                db.commit()
                return
            tail_runs = {
                stage_name: db.query(BinarySecurityStageRun)
                .filter(
                    BinarySecurityStageRun.task_id == task.id,
                    BinarySecurityStageRun.stage_name == stage_name,
                )
                .first()
                for stage_name in tail_stages
            }
            next_incomplete_tail = next(
                (
                    stage_name
                    for stage_name in tail_stages
                    if (
                        str((tail_runs.get(stage_name).status if tail_runs.get(stage_name) else "pending") or "").strip()
                        not in {"success", "partial_success", "cancelled"}
                        or prior_tail_statuses.get(stage_name) in {"failed", "downstream_missing"}
                    )
                ),
                None,
            )
            if next_incomplete_tail:
                task.current_stage = next_incomplete_tail
                next_status = str((tail_runs.get(next_incomplete_tail).status if tail_runs.get(next_incomplete_tail) else "pending") or "").strip()
                prior_status = prior_tail_statuses.get(next_incomplete_tail) or next_status
                next_stage_items = self._stage_items(db, task.id, next_incomplete_tail)
                has_tail_work = bool(next_stage_items)
                if prior_status in {"failed", "downstream_missing"}:
                    task.status = "failed"
                    task.finished_at = _now()
                elif next_status in {"pending", "queued"} and not has_tail_work:
                    task.status = "pending"
                    task.finished_at = None
                elif next_status not in {"success", "partial_success", "cancelled"}:
                    task.status = "running"
                    task.finished_at = None
                else:
                    task.status = "running"
                    task.finished_at = None
                db.commit()
                return
            self._finalize_task(db, task)
            await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
            db.commit()
        finally:
            db.close()

    async def _archive_dispatch_loop(self) -> None:
        while self._running:
            try:
                with observe_scheduler_loop("archive_dispatch"):
                    self._mark_loop_heartbeat("archive_dispatch")
                    await asyncio.to_thread(self._reclaim_stale_archive_jobs)
                    await self._schedule_archive_workers()
                    self._mark_loop_heartbeat("archive_dispatch")
            except asyncio.CancelledError:
                raise
            except Exception:
                logger.exception("binary-security archive dispatch loop crashed and recovered")
                await asyncio.sleep(1)
            await asyncio.sleep(max(1, self.cfg.scheduler.poll_interval_seconds))

    async def _schedule_archive_workers(self) -> None:
        max_workers = max(1, int(getattr(self.cfg.scheduler, "archive_job_concurrency", 0) or 1))
        async with self._archive_worker_lock:
            self._archive_workers = {task for task in self._archive_workers if not task.done()}
            slots = max_workers - len(self._archive_workers)
            if slots <= 0:
                return
            assignments: list[tuple[str, str]] = []
            for _ in range(slots):
                archived_job_id = await asyncio.to_thread(self._next_archived_job)
                if archived_job_id:
                    observe_archive_action("claim", "apply")
                    assignments.append(("apply", archived_job_id))
                    continue
                job_id = await asyncio.to_thread(self._claim_archive_job)
                if job_id:
                    observe_archive_action("claim", "copy")
                    assignments.append(("copy", job_id))
                    continue
                break
            for work_type, job_id in assignments:
                worker = asyncio.create_task(
                    self._archive_worker(work_type, job_id),
                    name=f"binary-security-archive-{work_type}-{job_id}",
                )
                self._archive_workers.add(worker)
            self._observe_worker_counts()

    async def _archive_worker(self, work_type: str, job_id: str) -> None:
        try:
            if work_type == "apply":
                await asyncio.to_thread(
                    self._enqueue_archive_state_event_by_job_id,
                    job_id,
                    event_type="archive_job_copied",
                    payload={"source": "archive_apply_claim"},
                )
            else:
                await self._process_archive_job(job_id)
        except asyncio.CancelledError:
            if work_type == "copy":
                await asyncio.to_thread(self._requeue_running_archive_job_if_owned, job_id, "archive worker cancelled")
            raise
        finally:
            async with self._archive_worker_lock:
                self._archive_workers.discard(asyncio.current_task())
            self._observe_worker_counts()

    def _archive_reclaim_timeout_seconds(self) -> int:
        return max(30, int(getattr(self.cfg.scheduler, "archive_reclaim_timeout_seconds", 300) or 300))

    def _archive_reclaim_max_attempts(self) -> int:
        return max(1, int(getattr(self.cfg.scheduler, "archive_reclaim_max_attempts", 3) or 3))

    def _archive_copy_missing_source_retry_schedule_seconds(self) -> list[int]:
        raw_schedule = getattr(self.cfg.scheduler, "archive_copy_missing_source_retry_schedule_seconds", None)
        values = raw_schedule if isinstance(raw_schedule, list) else [60, 120, 180]
        schedule = [max(1, int(value)) for value in values if str(value).strip()]
        return schedule or [60, 120, 180]

    def _archive_job_retry_attempt(self, job: BinarySecurityArchiveJob) -> int:
        return max(0, int((job.payload or {}).get("copy_retry_attempt") or 0))

    def _archive_job_retry_next_at(self, job: BinarySecurityArchiveJob) -> datetime | None:
        raw = (job.payload or {}).get("copy_retry_next_at")
        if not raw:
            return None
        try:
            return datetime.fromisoformat(str(raw))
        except Exception:
            return None

    def _archive_job_ready_for_retry(self, job: BinarySecurityArchiveJob, *, now: datetime | None = None) -> bool:
        next_retry_at = self._archive_job_retry_next_at(job)
        if next_retry_at is None:
            return True
        return _seconds_until(next_retry_at) is None or _seconds_until(next_retry_at) <= 0

    def _clear_archive_job_retry_metadata(self, job: BinarySecurityArchiveJob) -> dict[str, Any]:
        payload = dict(job.payload or {})
        for key in (
            "copy_retry_reason",
            "copy_retry_attempt",
            "copy_retry_next_at",
            "copy_retry_schedule_seconds",
            "last_missing_source_observed_at",
            "last_source_candidates",
            "last_source_candidate_count",
            "last_source_candidates_preview",
        ):
            payload.pop(key, None)
        return payload

    def _schedule_archive_job_missing_source_retry(
        self,
        db: Session,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem | None,
        job: BinarySecurityArchiveJob,
        *,
        source_candidates: list[str],
    ) -> tuple[bool, int | None, datetime | None]:
        schedule = self._archive_copy_missing_source_retry_schedule_seconds()
        retry_attempt = self._archive_job_retry_attempt(job)
        if retry_attempt >= len(schedule):
            return False, None, None
        retry_delay_seconds = int(schedule[retry_attempt])
        next_retry_at = _now() + timedelta(seconds=retry_delay_seconds)
        payload = self._clear_archive_job_retry_metadata(job)
        payload.update(
            {
                "copy_retry_reason": ARCHIVE_COPY_MISSING_SOURCE_RETRY_REASON,
                "copy_retry_attempt": retry_attempt + 1,
                "copy_retry_next_at": next_retry_at.isoformat(),
                "copy_retry_schedule_seconds": schedule,
                "last_missing_source_observed_at": _now().isoformat(),
                "last_source_candidate_count": len(source_candidates),
                "last_source_candidates_preview": list(source_candidates[:DB_ARTIFACT_PREVIEW_LIMIT]),
            }
        )
        job.payload = payload
        job.archive_status = "pending"
        job.owner_id = None
        job.error_message = None
        job.archive_root = None
        job.started_at = None
        job.completed_at = None
        job.updated_at = _now()
        self._record_event(
            db,
            task,
            "downstream_archive_job_delayed_retry_scheduled",
            f"下游产物暂未就绪，已安排 {retry_delay_seconds}s 后重试归档",
            stage_name=job.stage_name,
            item=item,
            level="warning",
            payload={
                "archive_job_id": job.id,
                "retry_attempt": retry_attempt + 1,
                "retry_delay_seconds": retry_delay_seconds,
                "next_retry_at": next_retry_at.isoformat(),
                "source_candidate_count": len(source_candidates),
                "source_candidates_preview": list(source_candidates[:DB_ARTIFACT_PREVIEW_LIMIT]),
                "downstream_task_id": job.downstream_task_id,
                "resolution_reason": ARCHIVE_COPY_MISSING_SOURCE_RETRY_REASON,
            },
        )
        return True, retry_delay_seconds, next_retry_at

    def _active_archive_job_ids(self) -> set[str]:
        active_job_ids: set[str] = set()
        for worker in self._archive_workers:
            if worker.done():
                continue
            name = str(worker.get_name() or "")
            prefix = "binary-security-archive-"
            if not name.startswith(prefix):
                continue
            job_id = name.split("-")[-1]
            if job_id:
                active_job_ids.add(job_id)
        return active_job_ids

    def _requeue_running_archive_job_if_owned(self, job_id: str, reason: str) -> bool:
        db = get_session_factory()()
        try:
            job = db.query(BinarySecurityArchiveJob).filter(BinarySecurityArchiveJob.id == job_id).first()
            if job is None or str(job.archive_status or "").strip() != "running":
                return False
            if str(job.owner_id or "").strip() != str(self.instance_id or "").strip():
                return False
            task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == job.task_id).first()
            if task is None:
                return False
            item = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.id == job.item_id).first()
            self._requeue_archive_jobs(
                db,
                task,
                [job],
                stage_name=job.stage_name,
                event_type="downstream_archive_job_owner_lost",
                event_message="归档 worker 中断，归档任务已自动回退重排队",
            )
            self._record_event(
                db,
                task,
                "downstream_archive_job_owner_lost",
                "归档 worker 中断，运行中的归档任务已自动回退重排队",
                stage_name=job.stage_name,
                item=item,
                level="warning",
                payload={
                    "archive_job_id": job.id,
                    "owner_id_before": self.instance_id,
                    "resolution_reason": reason,
                },
            )
            observe_archive_reclaim("owner_cleanup")
            db.commit()
            return True
        except Exception:
            db.rollback()
            return False
        finally:
            db.close()

    def _requeue_owned_running_archive_jobs(self) -> int:
        db = get_session_factory()()
        try:
            jobs = (
                db.query(BinarySecurityArchiveJob)
                .filter(
                    BinarySecurityArchiveJob.archive_status == "running",
                    BinarySecurityArchiveJob.owner_id == self.instance_id,
                )
                .order_by(BinarySecurityArchiveJob.updated_at.asc(), BinarySecurityArchiveJob.id.asc())
                .all()
            )
            if not jobs:
                return 0
            tasks_by_id = {
                str(task.id): task
                for task in db.query(BinarySecurityTask).filter(
                    BinarySecurityTask.id.in_([str(job.task_id) for job in jobs if job.task_id])
                ).all()
            }
            reclaimed = 0
            for job in jobs:
                task = tasks_by_id.get(str(job.task_id))
                if task is None:
                    continue
                item = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.id == job.item_id).first()
                self._requeue_archive_jobs(
                    db,
                    task,
                    [job],
                    stage_name=job.stage_name,
                    event_type="downstream_archive_job_owner_lost",
                    event_message="归档实例停止，运行中的归档任务已自动回退重排队",
                )
                self._record_event(
                    db,
                    task,
                    "downstream_archive_job_owner_lost",
                    "归档实例停止，运行中的归档任务已自动回退重排队",
                    stage_name=job.stage_name,
                    item=item,
                    level="warning",
                    payload={
                        "archive_job_id": job.id,
                        "owner_id_before": self.instance_id,
                        "resolution_reason": "stop_cleanup",
                    },
                )
                reclaimed += 1
            if reclaimed:
                observe_archive_reclaim("stop_cleanup")
                db.commit()
            else:
                db.rollback()
            return reclaimed
        except Exception:
            db.rollback()
            return 0
        finally:
            db.close()

    def _reclaim_stale_archive_jobs(self) -> int:
        db = get_session_factory()()
        try:
            active_job_ids = self._active_archive_job_ids()
            timeout_seconds = self._archive_reclaim_timeout_seconds()
            max_attempts = self._archive_reclaim_max_attempts()
            now = _now()
            jobs = (
                db.query(BinarySecurityArchiveJob)
                .filter(BinarySecurityArchiveJob.archive_status == "running")
                .order_by(BinarySecurityArchiveJob.updated_at.asc(), BinarySecurityArchiveJob.id.asc())
                .all()
            )
            reclaimed = 0
            for job in jobs:
                if str(job.id or "") in active_job_ids:
                    continue
                if job.archive_root or job.completed_at:
                    continue
                last_progress_at = job.updated_at or job.started_at or job.created_at
                if last_progress_at is None:
                    continue
                if (now - last_progress_at).total_seconds() < timeout_seconds:
                    continue
                task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == job.task_id).first()
                if task is None:
                    continue
                item = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.id == job.item_id).first()
                attempts = int(job.attempts or 0)
                owner_before = str(job.owner_id or "").strip() or None
                if attempts > max_attempts:
                    job.archive_status = "failed"
                    job.error_message = "archive worker lost after claim; reclaim exhausted"
                    job.completed_at = now
                    job.updated_at = now
                    self._record_event(
                        db,
                        task,
                        "downstream_archive_job_reclaim_failed",
                        "归档任务在运行态丢失且已超过自动回收预算，需人工处理",
                        stage_name=job.stage_name,
                        item=item,
                        level="warning",
                        payload={
                            "archive_job_id": job.id,
                            "attempts": attempts,
                            "owner_id_before": owner_before,
                            "resolution_reason": "archive_reclaim_exhausted",
                            "timeout_seconds": timeout_seconds,
                        },
                    )
                    observe_archive_reclaim("failed")
                    reclaimed += 1
                    continue
                self._requeue_archive_jobs(
                    db,
                    task,
                    [job],
                    stage_name=job.stage_name,
                    event_type="downstream_archive_job_requeued_after_reclaim",
                    event_message="归档任务在运行态丢失，已自动回退重排队",
                )
                self._record_event(
                    db,
                    task,
                    "downstream_archive_job_owner_lost",
                    "归档任务长时间无进展且无本地 worker 持有，判定为运行态丢失",
                    stage_name=job.stage_name,
                    item=item,
                    level="warning",
                    payload={
                        "archive_job_id": job.id,
                        "attempts": attempts,
                        "owner_id_before": owner_before,
                        "resolution_reason": "stale_running_archive_job",
                        "timeout_seconds": timeout_seconds,
                    },
                )
                observe_archive_reclaim("requeued")
                reclaimed += 1
            if reclaimed:
                db.commit()
            else:
                db.rollback()
            return reclaimed
        except Exception:
            db.rollback()
            return 0
        finally:
            db.close()

    async def _state_reducer_loop(self) -> None:
        interval_seconds = max(1, int(self.cfg.scheduler.poll_interval_seconds or 5))
        while self._running:
            db = get_session_factory()()
            try:
                with observe_scheduler_loop("state_reducer"):
                    self._mark_loop_heartbeat("state_reducer")
                    await asyncio.to_thread(self._observe_state_runtime_metrics, db)
                    processed = 0
                    for _ in range(max(1, int(self.cfg.scheduler.downstream_action_concurrency or 1))):
                        event_id = self._claim_state_event(db)
                        if not event_id:
                            break
                        processed += 1
                        await self._reduce_state_event(event_id)
                    await self._observe_runtime_metrics(db)
                    self._state_reducer_consecutive_crash_count = 0
                    observe_state_reducer_health(
                        pod=self.instance_id,
                        loop_ok_at=time.time(),
                        consecutive_crash_count=0,
                    )
                    self._mark_loop_heartbeat("state_reducer")
                    if processed:
                        continue
            except asyncio.CancelledError:
                raise
            except Exception:
                self._state_reducer_consecutive_crash_count += 1
                observe_state_reducer_health(
                    pod=self.instance_id,
                    crash_at=time.time(),
                    consecutive_crash_count=self._state_reducer_consecutive_crash_count,
                )
                logger.exception("binary-security state reducer loop crashed and recovered")
                await asyncio.sleep(1)
            finally:
                db.close()
            await asyncio.sleep(interval_seconds)

    async def _reducer_metrics_snapshot_loop(self) -> None:
        interval_seconds = max(5, int(self.cfg.scheduler.poll_interval_seconds or 5))
        # Publish one snapshot immediately on startup so the dashboard has a
        # current baseline even before the reducer processes the first event.
        self._mark_loop_heartbeat("reducer_metrics_snapshot")
        await self._publish_reducer_metrics_snapshot()
        self._mark_loop_heartbeat("reducer_metrics_snapshot")
        while self._running:
            await asyncio.sleep(interval_seconds)
            await self._publish_reducer_metrics_snapshot()
            self._mark_loop_heartbeat("reducer_metrics_snapshot")

    async def _publish_reducer_metrics_snapshot(self) -> None:
        try:
            payload, _ = await asyncio.to_thread(render_metrics)
            await get_reducer_metrics_snapshot_store().write_snapshot(
                metrics_payload=payload.decode("utf-8", errors="ignore"),
                source_pod=self.instance_id,
            )
        except Exception:
            logger.exception("binary-security failed to publish reducer metrics snapshot")

    def _observe_state_runtime_metrics(self, db: Session) -> None:
        rows = (
            db.query(BinarySecurityStateEvent.status, func.count(BinarySecurityStateEvent.id))
            .group_by(BinarySecurityStateEvent.status)
            .all()
        )
        status_counts = {str(status or "unknown"): int(count or 0) for status, count in rows}
        oldest_ages: dict[str, float] = {}
        for status in {"pending", "processing", "retryable", "dead_letter"}:
            oldest = (
                db.query(func.min(BinarySecurityStateEvent.created_at))
                .filter(BinarySecurityStateEvent.status == status)
                .scalar()
            )
            oldest_ages[status] = max(0.0, (_now() - oldest).total_seconds()) if oldest else 0.0
        observe_state_event_queues(status_counts=status_counts, oldest_ages=oldest_ages)
        archive_rows = (
            db.query(BinarySecurityArchiveJob.stage_name, BinarySecurityArchiveJob.archive_status, func.count(BinarySecurityArchiveJob.id))
            .group_by(BinarySecurityArchiveJob.stage_name, BinarySecurityArchiveJob.archive_status)
            .all()
        )
        observe_archive_job_statuses({
            (str(stage or "unknown"), str(status or "unknown")): int(count or 0)
            for stage, status, count in archive_rows
        })

    def _claim_state_event(self, db: Session) -> str | None:
        now_value = _now()
        try:
            event = (
                db.query(BinarySecurityStateEvent)
                .filter(
                    BinarySecurityStateEvent.status.in_(["pending", "retryable", "processing"]),
                    BinarySecurityStateEvent.available_at <= now_value,
                    or_(
                        BinarySecurityStateEvent.status != "processing",
                        BinarySecurityStateEvent.lease_expires_at.is_(None),
                        BinarySecurityStateEvent.lease_expires_at < now_value,
                    ),
                )
                .order_by(BinarySecurityStateEvent.available_at.asc(), BinarySecurityStateEvent.created_at.asc(), BinarySecurityStateEvent.id.asc())
                .first()
            )
        except OperationalError as exc:
            if not self._is_retryable_lock_error(exc):
                raise
            db.rollback()
            logger.warning("binary-security state reducer skipped event claim after retryable lock conflict during lookup")
            return None
        if event is None:
            return None
        try:
            updated = (
                db.query(BinarySecurityStateEvent)
                .filter(
                    BinarySecurityStateEvent.id == event.id,
                    BinarySecurityStateEvent.status.in_(["pending", "retryable", "processing"]),
                    or_(
                        BinarySecurityStateEvent.status != "processing",
                        BinarySecurityStateEvent.lease_expires_at.is_(None),
                        BinarySecurityStateEvent.lease_expires_at < now_value,
                    ),
                )
                .update(
                    {
                        BinarySecurityStateEvent.status: "processing",
                        BinarySecurityStateEvent.leased_by: self.instance_id,
                        BinarySecurityStateEvent.processed_by: self.instance_id,
                        BinarySecurityStateEvent.lease_expires_at: now_value + timedelta(seconds=STATE_EVENT_LEASE_SECONDS),
                        BinarySecurityStateEvent.processing_started_at: now_value,
                        BinarySecurityStateEvent.processing_finished_at: None,
                        BinarySecurityStateEvent.processing_result: "processing",
                        BinarySecurityStateEvent.attempts: int(event.attempts or 0) + 1,
                        BinarySecurityStateEvent.last_error_message: None,
                        BinarySecurityStateEvent.updated_at: now_value,
                    },
                    synchronize_session=False,
                )
            )
            db.commit()
        except OperationalError as exc:
            if not self._is_retryable_lock_error(exc):
                raise
            db.rollback()
            logger.warning(
                "binary-security state reducer skipped event claim after retryable lock conflict: event_id=%s",
                getattr(event, "id", None),
            )
            return None
        return event.id if updated else None

    def _acquire_task_state_lease(self, db: Session, task_id: str, *, operation: str = "state_reduce") -> str | None:
        started = time.perf_counter()
        now_value = _now()
        token = uuid.uuid4().hex
        expires_at = now_value + timedelta(seconds=TASK_STATE_LEASE_SECONDS)
        values = {
            BinarySecurityTaskStateLease.owner_id: self.instance_id,
            BinarySecurityTaskStateLease.lease_token: token,
            BinarySecurityTaskStateLease.lease_expires_at: expires_at,
            BinarySecurityTaskStateLease.heartbeat_at: now_value,
            BinarySecurityTaskStateLease.operation: operation,
            BinarySecurityTaskStateLease.updated_at: now_value,
        }
        max_attempts = self._retryable_write_attempts()
        for attempt in range(max_attempts):
            updated = (
                db.query(BinarySecurityTaskStateLease)
                .filter(
                    BinarySecurityTaskStateLease.task_id == task_id,
                    or_(
                        BinarySecurityTaskStateLease.lease_expires_at.is_(None),
                        BinarySecurityTaskStateLease.lease_expires_at <= now_value,
                        BinarySecurityTaskStateLease.owner_id == self.instance_id,
                    ),
                )
                .update(values, synchronize_session=False)
            )
            if updated:
                try:
                    db.flush()
                    observe_task_state_lock(operation=operation, wait_seconds=time.perf_counter() - started, active=1)
                    return token
                except OperationalError as exc:
                    if not self._is_retryable_lock_error(exc) or attempt >= max_attempts - 1:
                        raise
                    db.rollback()
                    self._sleep_after_retryable_lock_error(attempt + 1)
                    continue
            try:
                lease = BinarySecurityTaskStateLease(
                    task_id=task_id,
                    owner_id=self.instance_id,
                    lease_token=token,
                    lease_expires_at=expires_at,
                    heartbeat_at=now_value,
                    operation=operation,
                    updated_at=now_value,
                )
                with self._savepoint(db):
                    db.add(lease)
                    db.flush()
                observe_task_state_lock(operation=operation, wait_seconds=time.perf_counter() - started, active=1)
                return token
            except IntegrityError:
                updated = (
                    db.query(BinarySecurityTaskStateLease)
                    .filter(
                        BinarySecurityTaskStateLease.task_id == task_id,
                        or_(
                            BinarySecurityTaskStateLease.lease_expires_at.is_(None),
                            BinarySecurityTaskStateLease.lease_expires_at <= now_value,
                            BinarySecurityTaskStateLease.owner_id == self.instance_id,
                        ),
                    )
                    .update(values, synchronize_session=False)
                )
                if updated:
                    try:
                        db.flush()
                        observe_task_state_lock(operation=operation, wait_seconds=time.perf_counter() - started, active=1)
                        return token
                    except OperationalError as exc:
                        if not self._is_retryable_lock_error(exc) or attempt >= max_attempts - 1:
                            raise
                        db.rollback()
                        self._sleep_after_retryable_lock_error(attempt + 1)
                        continue
                observe_task_state_lock(operation=operation, wait_seconds=time.perf_counter() - started, active=0)
                return None
            except OperationalError as exc:
                if not self._is_retryable_lock_error(exc) or attempt >= max_attempts - 1:
                    raise
                db.rollback()
                self._sleep_after_retryable_lock_error(attempt + 1)
        observe_task_state_lock(operation=operation, wait_seconds=time.perf_counter() - started, active=0)
        return None

    def _release_task_state_lease(self, db: Session, task_id: str, *, token: str, operation: str = "state_reduce", held_started: float | None = None) -> None:
        lease = db.query(BinarySecurityTaskStateLease).filter(BinarySecurityTaskStateLease.task_id == task_id).first()
        if lease is not None and lease.lease_token == token:
            db.delete(lease)
            db.flush()
        observe_task_state_lock(
            operation=operation,
            held_seconds=(time.perf_counter() - held_started) if held_started is not None else None,
            active=0,
        )

    async def _reduce_state_event(self, event_id: str) -> None:
        started = time.perf_counter()
        db = get_session_factory()()
        event: BinarySecurityStateEvent | None = None
        lease_token: str | None = None
        held_started: float | None = None
        result = "unknown"
        try:
            event = db.query(BinarySecurityStateEvent).filter(BinarySecurityStateEvent.id == event_id).first()
            if event is None or event.status != "processing" or event.leased_by != self.instance_id:
                result = "skipped"
                return
            lease_token = self._acquire_task_state_lease(db, event.task_id)
            if not lease_token:
                event.status = "retryable"
                event.available_at = _now() + timedelta(seconds=5)
                event.leased_by = None
                event.lease_expires_at = None
                event.processing_finished_at = _now()
                event.processing_result = "retryable"
                event.last_error_message = "task state lease busy"
                event.updated_at = _now()
                db.commit()
                result = "lock_busy"
                return
            held_started = time.perf_counter()
            # Publish the task-state lease before doing potentially slow file
            # and summary work; the apply itself stays in this reducer session.
            db.commit()
            await self._apply_state_event_locked(db, event)
            event = db.query(BinarySecurityStateEvent).filter(BinarySecurityStateEvent.id == event_id).first()
            if event is None:
                result = "missing_after_apply"
                return
            event_type = event.event_type
            task_id = event.task_id
            event_created_at = event.created_at
            event.status = "processed"
            finished_at = _now()
            event.processed_at = finished_at
            event.processing_finished_at = finished_at
            event.processing_result = "success"
            event.leased_by = None
            event.lease_expires_at = None
            event.error_message = None
            event.last_error_message = None
            event.updated_at = finished_at
            observe_state_event_lag(event_type, (_now() - event.created_at).total_seconds() if event.created_at else None)
            observe_state_reducer_event(event_type, "processed")
            observe_state_reducer_health(
                pod=self.instance_id,
                event_processed_at=time.time(),
            )
            result = "success"
            db.commit()
        except Exception as exc:
            db.rollback()
            result = "failed"
            if event is not None:
                try:
                    event = db.query(BinarySecurityStateEvent).filter(BinarySecurityStateEvent.id == event_id).first()
                    if event is not None:
                        event.error_message = str(exc)
                        event.leased_by = None
                        event.lease_expires_at = None
                        finished_at = _now()
                        event.processing_finished_at = finished_at
                        event.last_error_message = str(exc)
                        event.updated_at = finished_at
                        if int(event.attempts or 0) >= STATE_EVENT_MAX_ATTEMPTS:
                            event.status = "dead_letter"
                            event.processed_at = finished_at
                            event.processing_result = "dead_letter"
                            observe_state_dead_letter(event.event_type, "max_attempts")
                        else:
                            event.status = "retryable"
                            event.processing_result = "retryable"
                            event.available_at = _now() + timedelta(seconds=min(300, 2 ** max(1, int(event.attempts or 1))))
                        db.commit()
                except Exception:
                    db.rollback()
            logger.exception("binary-security state reducer failed: event=%s", event_id)
        finally:
            if lease_token and event is not None:
                try:
                    self._release_task_state_lease(db, event.task_id, token=lease_token, held_started=held_started)
                    db.commit()
                except Exception:
                    db.rollback()
            db.close()
            observe_state_reducer_run(result=result, pod=self.instance_id, duration_seconds=time.perf_counter() - started)

    async def _apply_state_event_locked(self, db: Session, event: BinarySecurityStateEvent) -> None:
        payload = dict(event.payload or {})
        if event.event_type == "archive_job_copied":
            await self._apply_archive_job_status_locked(db, event.archive_job_id or "", payload.get("archive_root"), state_event_id=event.id)
            return
        if event.event_type == "archive_job_copy_failed":
            self._apply_archive_job_copy_failed_locked(db, event)
            return
        if event.event_type in {"downstream_status_observed", "downstream_terminal_observed"}:
            await self._apply_downstream_status_event_locked(db, event)
            return
        if event.event_type == "stage_worker_terminal_observed":
            await self._apply_stage_worker_terminal_event_locked(db, event)
            return
        if event.event_type == "task_execution_failed":
            await self._apply_task_execution_failed_locked(db, event)
            return
        if event.event_type == "stage_worker_start_requested":
            self._apply_stage_worker_start_requested_locked(db, event)
            return
        if event.event_type == "manual_policy_update_requested":
            self._apply_manual_policy_update_requested_locked(db, event)
            return
        logger.info("binary-security state reducer ignored event type: %s", event.event_type)

    async def _apply_downstream_status_event_locked(self, db: Session, event: BinarySecurityStateEvent) -> None:
        task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == event.task_id).first()
        item = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.id == event.item_id).first()
        if task is None or item is None:
            return
        payload = dict(event.payload or {})
        if task.status == "cancelled":
            self._record_event(
                db,
                task,
                "downstream_status_event_ignored",
                "下游状态事件晚于取消事件到达，已忽略以避免恢复已取消任务",
                level="warning",
                stage_name=item.stage_name,
                item=item,
                payload={
                    "state_event_id": event.id,
                    "downstream_service": item.downstream_service,
                    "downstream_task_id": item.downstream_task_id,
                    "ignored_status": payload.get("mapped_status") or payload.get("downstream_status"),
                },
            )
            await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
            return
        mapped_status = str(payload.get("mapped_status") or "").strip()
        if not mapped_status:
            return
        mapped_status = self._map_downstream_status(mapped_status) or mapped_status
        downstream_payload = dict(payload.get("downstream_payload") or {})
        payload_downstream_task_id = self._payload_downstream_task_id(downstream_payload) or self._payload_downstream_task_id(payload)
        current_downstream_task_id = self._current_downstream_task_id(item)
        if (
            payload_downstream_task_id
            and current_downstream_task_id
            and payload_downstream_task_id != current_downstream_task_id
        ):
            self._mark_stage_item_sync_observation(
                item,
                sync_status="binding_mismatch",
                synced_at=_now(),
                error_message="旧 child 的下游状态事件已被忽略",
                error_type="binding_mismatch",
                status_raw=self._string_or_none(payload.get("downstream_status") or downstream_payload.get("status")),
                mapped_status=mapped_status,
                downstream_status=self._string_or_none(payload.get("downstream_status") or downstream_payload.get("status")),
                state_applied=False,
                last_sync_result="error",
            )
            self._record_binding_mismatch_event(
                db,
                task,
                item,
                event_type="downstream_binding_mismatch_detected",
                message="旧 child 的下游状态事件已被忽略，未回写当前阶段项",
                payload=self._binding_mismatch_payload(
                    source="downstream_status_event",
                    expected_downstream_task_id=current_downstream_task_id,
                    actual_downstream_task_id=payload_downstream_task_id,
                    payload_downstream_task_id=payload_downstream_task_id,
                ),
            )
            await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
            return
        if not self._payload_matches_current_child(item, downstream_payload or payload):
            self._mark_stage_item_sync_observation(
                item,
                sync_status="binding_mismatch",
                synced_at=_now(),
                error_message="旧 child 的下游状态事件已被忽略",
                error_type="binding_mismatch",
                status_raw=self._string_or_none(payload.get("downstream_status") or downstream_payload.get("status")),
                mapped_status=mapped_status,
                downstream_status=self._string_or_none(payload.get("downstream_status") or downstream_payload.get("status")),
                state_applied=False,
                last_sync_result="error",
            )
            self._record_binding_mismatch_event(
                db,
                task,
                item,
                event_type="downstream_binding_mismatch_detected",
                message="旧 child 的下游状态事件已被忽略，未回写当前阶段项",
                payload=self._binding_mismatch_payload(
                    source="downstream_status_event",
                    expected_downstream_task_id=current_downstream_task_id,
                    actual_downstream_task_id=payload_downstream_task_id,
                    payload_downstream_task_id=payload_downstream_task_id,
                ),
            )
            await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
            return
        self._apply_child_task_status_change(
            db,
            task=task,
            item=item,
            change_source="state_reducer",
            after_status=mapped_status,
            downstream_payload=downstream_payload,
            sync_status="synced",
            downstream_status_raw=self._string_or_none(payload.get("status_raw") or payload.get("downstream_status")),
            downstream_status_mapped=mapped_status,
            downstream_status=self._string_or_none(payload.get("downstream_status") or downstream_payload.get("status")),
            state_applied=True,
            error_message=(
                payload.get("error_message")
                or downstream_payload.get("error")
                or downstream_payload.get("error_message")
                or downstream_payload.get("message")
                or item.error_message
            ),
            error_type=self._string_or_none(payload.get("error_type")),
            http_status=self._int_or_none(payload.get("http_status")),
            state_event_id=event.id,
            extra_payload={"downstream_payload": self._lightweight_downstream_payload(downstream_payload)},
        )
        self._reconcile_stage_and_task_state_after_item_update(db, task, item.stage_name)
        self._record_event(
            db,
            task,
            "downstream_status_event_applied",
            "下游状态事件已由 reducer 串行应用",
            level="warning" if mapped_status in {"failed", "cancelled", "downstream_missing"} else "info",
            stage_name=item.stage_name,
            item=item,
            payload={
                "state_event_id": event.id,
                "before_status": payload.get("before_status"),
                "after_status": mapped_status,
                "http_status": payload.get("http_status"),
                "error_type": payload.get("error_type"),
                "status_raw": payload.get("status_raw") or payload.get("downstream_status"),
                "mapped_status": mapped_status,
                "state_applied": True,
                "downstream_status": payload.get("downstream_status"),
                "downstream_service": item.downstream_service,
                "downstream_task_id": item.downstream_task_id,
            },
        )
        await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)

    def _apply_downstream_status_inline(
        self,
        item: BinarySecurityStageItem,
        *,
        mapped_status: str,
        downstream_payload: dict[str, Any] | None,
        error_message: str | None,
        synced_at: datetime | None = None,
    ) -> None:
        self._apply_child_task_status_change(
            None,
            task=None,
            item=item,
            change_source="downstream_sync",
            after_status=mapped_status,
            downstream_payload=downstream_payload,
            sync_status="synced",
            downstream_status_raw=self._string_or_none((downstream_payload or {}).get("status")),
            downstream_status_mapped=self._map_downstream_status(mapped_status) or mapped_status,
            downstream_status=self._string_or_none((downstream_payload or {}).get("status")),
            state_applied=True,
            error_message=error_message,
            synced_at=synced_at,
        )

    def _should_apply_downstream_intermediate_status(
        self,
        item: BinarySecurityStageItem,
        *,
        mapped_status: str,
        payload: dict[str, Any] | None,
    ) -> bool:
        before_status = str(item.status or "").strip().lower()
        normalized_stage_name = normalize_stage_name(item.stage_name)
        if mapped_status == "running":
            if normalized_stage_name == "dataflow_vuln_scan":
                return before_status in {"pending", "queued", "running", "dispatching", "success", "failed"}
            return before_status in {"pending", "queued", "running", "dispatching", "success", "failed"}
        if mapped_status == "queued":
            return before_status in {"running", "queued"}
        if mapped_status == "pending":
            if before_status != "running":
                return False
            if str(item.downstream_service or "").strip() == "entry_analyse":
                return self._entry_payload_matches_stage_item(item, payload)
            return True
        return False

    def _mark_stage_item_sync_observation(
        self,
        item: BinarySecurityStageItem,
        *,
        sync_status: str,
        synced_at: datetime | None = None,
        error_message: str | None = None,
        http_status: int | None = None,
        error_type: str | None = None,
        status_raw: str | None = None,
        mapped_status: str | None = None,
        downstream_status: str | None = None,
        state_applied: bool | None = None,
        consecutive_error_count: int | None = None,
        budget_exhausted: bool | None = None,
        next_retry_at: datetime | None = None,
        last_sync_result: str | None = None,
    ) -> None:
        self._apply_child_task_sync_observation(
            item,
            sync_status=sync_status,
            synced_at=synced_at,
            error_message=error_message,
            http_status=http_status,
            error_type=error_type,
            downstream_status_raw=status_raw,
            downstream_status_mapped=mapped_status,
            downstream_status=downstream_status,
            state_applied=state_applied,
            consecutive_error_count=consecutive_error_count,
            budget_exhausted=budget_exhausted,
            next_retry_at=next_retry_at,
            last_sync_result=last_sync_result,
        )

    def _refresh_polled_child_sync_snapshot(
        self,
        *,
        task_id: str,
        item_id: str,
        payload: dict[str, Any],
    ) -> None:
        mapped_status = self._map_downstream_status(str(payload.get("status") or "").lower())
        if mapped_status not in {"pending", "queued", "running"}:
            return
        session = get_session_factory()()
        try:
            task = session.query(BinarySecurityTask).filter(BinarySecurityTask.id == task_id).first()
            item = session.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.id == item_id).first()
            if task is None or item is None:
                return
            current_downstream_task_id = str(item.downstream_task_id or "").strip()
            payload_task_id = str(payload.get("task_id") or payload.get("id") or "").strip()
            if payload_task_id and current_downstream_task_id and payload_task_id != current_downstream_task_id:
                return
            should_apply = self._should_apply_downstream_intermediate_status(
                item,
                mapped_status=mapped_status,
                payload=payload,
            )
            if should_apply:
                item.status = mapped_status
                if mapped_status in {"queued", "running"}:
                    item.started_at = item.started_at or _now()
                item.finished_at = None
                item.error_message = None
            self._mark_stage_item_sync_observation(
                item,
                sync_status="synced",
                error_message=None,
                status_raw=self._string_or_none(payload.get("status")),
                mapped_status=mapped_status,
                downstream_status=self._string_or_none(payload.get("status")),
                state_applied=should_apply,
            )
            session.commit()
        except Exception:
            session.rollback()
            raise
        finally:
            session.close()

    def _record_polled_child_sync_failure(
        self,
        *,
        task_id: str,
        item_id: str,
        error_message: str,
        error_type: str,
        http_status: int | None = None,
    ) -> None:
        session = get_session_factory()()
        try:
            task = session.query(BinarySecurityTask).filter(BinarySecurityTask.id == task_id).first()
            item = session.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.id == item_id).first()
            if task is None or item is None:
                return
            if self._is_tail_control_plane_stale_error(error_message=error_message, error_type=error_type):
                if str(task.status or "").strip() in {TASK_STATUS_PENDING_MODULE_CONFIRMATION, TASK_STATUS_PENDING_ENTRY_CONFIRMATION, "waiting_confirmation"}:
                    session.commit()
                    return
                event_message = f"tail 收口 owner 已丢失，等待新的 reducer 接管: {error_message}"
                event_payload = {
                    "error_type": error_type,
                    "error_message": error_message,
                    "http_status": http_status,
                }
                if self._has_recent_matching_task_event(
                    session,
                    task,
                    event_type="tail_reconcile_owner_lost",
                    stage_name=item.stage_name,
                    message=event_message,
                    payload_keys={
                        "error_type": error_type,
                        "error_message": error_message,
                    },
                    within_seconds=max(60, self._stage_item_sync_reconcile_interval_seconds() * 2),
                ):
                    session.commit()
                    return
                self._record_event(
                    session,
                    task,
                    "tail_reconcile_owner_lost",
                    event_message,
                    level="warning",
                    stage_name=item.stage_name,
                    item=item,
                    payload=event_payload,
                )
                session.commit()
                return
            if self._is_owned_execution_stale_error(error_message=error_message, error_type=error_type):
                event_message = f"当前执行 owner 已丢失，等待 worker 重新接管: {error_message}"
                event_payload = {
                    "error_type": error_type,
                    "error_message": error_message,
                    "http_status": http_status,
                }
                if self._has_recent_matching_task_event(
                    session,
                    task,
                    event_type="owned_execution_owner_lost",
                    stage_name=item.stage_name,
                    message=event_message,
                    payload_keys={
                        "error_type": error_type,
                        "error_message": error_message,
                    },
                    within_seconds=max(60, self._stage_item_sync_reconcile_interval_seconds() * 2),
                ):
                    session.commit()
                    return
                self._record_event(
                    session,
                    task,
                    "owned_execution_owner_lost",
                    event_message,
                    level="warning",
                    stage_name=item.stage_name,
                    item=item,
                    payload=event_payload,
                )
                item.retry_count = int(item.retry_count or 0) + 1
                self._record_event(
                    session,
                    task,
                    "child_owner_lost_detected",
                    "检测到下游 owner 丢失，已转入自动恢复",
                    level="warning",
                    stage_name=item.stage_name,
                    item=item,
                    payload={
                        **event_payload,
                        "service": item.downstream_service,
                        "stage_name": item.stage_name,
                        "item_id": item.id,
                        "item_key": item.item_key,
                        "downstream_task_id": item.downstream_task_id,
                        "auto_retry_count": int(item.retry_count or 0),
                        "max_retries_per_item": self._max_retries_per_item(task),
                        "recovery_action": "reconcile",
                    },
                )
                if int(item.retry_count or 0) > self._max_retries_per_item(task):
                    item.status = "failed"
                    item.finished_at = _now()
                    item.error_message = "owner_lost_retry_exhausted"
                    self._record_event(
                        session,
                        task,
                        "child_owner_lost_retry_exhausted",
                        "下游 owner 丢失自动恢复次数耗尽，子任务收口为失败",
                        level="warning",
                        stage_name=item.stage_name,
                        item=item,
                        payload={
                            **event_payload,
                            "service": item.downstream_service,
                            "stage_name": item.stage_name,
                            "item_id": item.id,
                            "item_key": item.item_key,
                            "downstream_task_id": item.downstream_task_id,
                            "auto_retry_count": int(item.retry_count or 0),
                            "max_retries_per_item": self._max_retries_per_item(task),
                            "recovery_action": "terminal_failed",
                        },
                    )
            state = self._build_next_downstream_sync_failure_state(item)
            self._persist_child_sync_observation(
                session,
                task=task,
                item=item,
                change_source="poll_supervisor",
                sync_status="transport_error",
                synced_at=_now(),
                error_message=error_message,
                http_status=http_status,
                error_type=error_type,
                state_applied=False,
                extra_payload={
                    "operation": "poll_until_terminal",
                    **self._downstream_sync_failure_payload(item, error_type=error_type, error_message=error_message, state=state),
                },
                consecutive_error_count=state.consecutive_error_count,
                budget_exhausted=state.budget_exhausted,
                next_retry_at=state.next_retry_at,
                last_sync_result="error",
            )
            self._record_event(
                session,
                task,
                "child_owner_lost_requeue_scheduled" if self._is_owned_execution_stale_error(error_message=error_message, error_type=error_type) else "downstream_poll_attempt_failed",
                "下游 owner 丢失，已安排自动恢复重试" if self._is_owned_execution_stale_error(error_message=error_message, error_type=error_type) else f"下游轮询失败，将在退避后重试: {error_message}",
                level="warning",
                stage_name=item.stage_name,
                item=item,
                payload={
                    "error_type": error_type,
                    "error_message": error_message,
                    "http_status": http_status,
                    "auto_retry_count": int(item.retry_count or 0),
                    "max_retries_per_item": self._max_retries_per_item(task),
                    "recovery_action": "reconcile" if self._is_owned_execution_stale_error(error_message=error_message, error_type=error_type) else "backoff",
                    **self._downstream_sync_failure_payload(item, error_type=error_type, error_message=error_message, state=state),
                },
            )
            session.commit()
        except Exception:
            session.rollback()
            raise
        finally:
            session.close()

    def _apply_stage_worker_start_requested_locked(self, db: Session, event: BinarySecurityStateEvent) -> None:
        payload = dict(event.payload or {})
        if payload.get("stage_start_applied"):
            return
        stage_name = str(event.stage_name or payload.get("stage_name") or "").strip()
        task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == event.task_id).first()
        if task is None or not stage_name:
            return
        stage_run = self._ensure_stage_run(db, task, stage_name)
        task.current_stage = stage_name
        stage_run.status = "running"
        stage_run.started_at = stage_run.started_at or _now()
        stage_run.finished_at = None
        stage_run.last_error = None
        existing_stage_items = self._stage_items(db, task.id, stage_name) if bool(payload.get("task_retry_mode")) else []
        target_stage_name = str(payload.get("target_stage_name") or "").strip()
        if bool(payload.get("stage_retry_mode")) and stage_name == target_stage_name:
            self._record_event(db, task, "stage_retry_started", f"阶段开始重试: {stage_name}", stage_name=stage_name, payload={"state_event_id": event.id})
        elif bool(payload.get("task_retry_mode")) and existing_stage_items:
            self._record_event(db, task, "stage_retry_started", f"阶段开始安全续跑: {stage_name}", stage_name=stage_name, payload={"state_event_id": event.id})
        self._record_event(db, task, "stage_started", f"阶段开始: {stage_name}", stage_name=stage_name, payload={"state_event_id": event.id})
        event.payload = {
            **payload,
            "stage_start_applied": True,
            "stage_start_applied_at": _now().isoformat(),
            "stage_start_applied_by": self.instance_id,
        }

    async def _apply_stage_worker_terminal_event_locked(self, db: Session, event: BinarySecurityStateEvent) -> None:
        payload = dict(event.payload or {})
        stage_name = str(event.stage_name or payload.get("stage_name") or "").strip()
        status = str(payload.get("status") or "").strip()
        task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == event.task_id).first()
        if task is None or not stage_name or not status:
            return
        payload = self._load_externalized_event_payload(task, payload)
        stage_name = str(event.stage_name or payload.get("stage_name") or stage_name).strip()
        status = str(payload.get("status") or status).strip()
        observed_terminal_status = status
        terminal_failure_statuses = {"failed", "downstream_missing", "cancelled"}
        summary = dict(payload.get("summary") or {})
        if task.status == "cancelled":
            self._record_event(
                db,
                task,
                "stage_worker_terminal_ignored",
                "阶段终态事件晚于取消事件到达，已忽略以避免恢复已取消任务",
                level="warning",
                stage_name=stage_name,
                payload={"state_event_id": event.id, "ignored_status": status},
            )
            await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
            return
        active_stage_status = status in {"pending", "queued", "running", "dispatching"}
        stage_run = db.query(BinarySecurityStageRun).filter(
            BinarySecurityStageRun.task_id == task.id,
            BinarySecurityStageRun.stage_name == stage_name,
        ).first()
        if stage_run is None:
            stage_run = self._ensure_stage_run(db, task, stage_name)
        if stage_name == "system_analysis":
            stage_run = self._refresh_stage_from_authoritative_items(db, task, stage_name) or stage_run
            summary = dict(stage_run.output_summary or summary)
            status = str(stage_run.status or status).strip() or status
            active_stage_status = status in {"pending", "queued", "running", "dispatching"}
        elif self._is_streaming_tail_stage(task, stage_name):
            existing_items = self._stage_items(db, task.id, stage_name)
            if existing_items:
                stage_run = self._refresh_stage_from_authoritative_items(db, task, stage_name) or stage_run
                summary = dict(stage_run.output_summary or summary)
                status = str(stage_run.status or status).strip() or status
                active_stage_status = status in {"pending", "queued", "running", "dispatching"}
                has_live_downstream_child = self._stage_has_live_downstream_children(existing_items)
                if observed_terminal_status in terminal_failure_statuses and active_stage_status and has_live_downstream_child:
                    self._record_event(
                        db,
                        task,
                        "stage_worker_terminal_deferred",
                        "阶段终态事件与活跃子项冲突，已按权威子项状态延后收敛",
                        level="warning",
                        stage_name=stage_name,
                        payload={
                            "state_event_id": event.id,
                            "observed_status": observed_terminal_status,
                            "authoritative_stage_status": status,
                        },
                    )
                    observed_terminal_status = status
            else:
                if (
                    observed_terminal_status in terminal_failure_statuses
                    and self._is_streaming_tail_stage(task, stage_name)
                    and not bool(payload.get("stage_retry_mode"))
                    and not bool(payload.get("task_retry_mode"))
                ):
                    stage_run.status = "pending"
                    stage_run.finished_at = None
                    stage_run.last_error = None
                    self._merge_stage_run_output_summary(task, stage_run, {"status_synced": True, "sync_status": "pending"})
                    self._update_task_stage_summary_entry(task, stage_run)
                    self._record_event(
                        db,
                        task,
                        "stage_worker_terminal_ignored_for_empty_streaming_tail",
                        "空流式尾段的历史终态事件已忽略，等待真实子项状态收敛",
                        level="warning",
                        stage_name=stage_name,
                        payload={
                            "state_event_id": event.id,
                            "observed_status": observed_terminal_status,
                        },
                    )
                    active_stage_status = True
                    status = "pending"
                    observed_terminal_status = "pending"
                else:
                    stage_run.status = "waiting_confirmation" if task.status == TASK_STATUS_PENDING_MODULE_CONFIRMATION else ("running" if active_stage_status else status)
                    stage_run.finished_at = None if active_stage_status else _now()
                    if not active_stage_status:
                        observe_stage_duration(
                            stage=stage_name,
                            result=stage_run.status,
                            duration_seconds=_elapsed_seconds_since(stage_run.started_at),
                        )
                    await self._persist_stage_run_output_summary_async(task, stage_run, summary)
                    stage_run.counts = self._stage_counts(db, stage_run)
                    if status in {"failed", "partial_success", "downstream_missing"}:
                        stage_run.last_error = summary.get("error")
                    self._merge_task_stage_summary_entry(
                        task,
                        stage_run,
                        {
                            **(
                                {
                                    "failure_code": summary.get("failure_code"),
                                    "failure_category": summary.get("failure_category"),
                                    "failure_message": summary.get("failure_message"),
                                }
                                if summary.get("failure_code")
                                else {}
                            ),
                        },
                    )
        else:
            existing_items = self._stage_items(db, task.id, stage_name)
            if existing_items:
                stage_run = self._refresh_stage_from_authoritative_items(db, task, stage_name) or stage_run
                summary = dict(stage_run.output_summary or summary)
                status = str(stage_run.status or status).strip() or status
                active_stage_status = status in {"pending", "queued", "running", "dispatching"}
                has_live_downstream_child = self._stage_has_live_downstream_children(existing_items)
                if observed_terminal_status in terminal_failure_statuses and active_stage_status and has_live_downstream_child:
                    self._record_event(
                        db,
                        task,
                        "stage_worker_terminal_deferred",
                        "阶段终态事件与活跃下游子任务冲突，已按权威子项状态延后收敛",
                        level="warning",
                        stage_name=stage_name,
                        payload={
                            "state_event_id": event.id,
                            "observed_status": observed_terminal_status,
                            "authoritative_stage_status": status,
                        },
                    )
                    observed_terminal_status = status
            else:
                stage_run.status = "waiting_confirmation" if task.status == TASK_STATUS_PENDING_MODULE_CONFIRMATION else ("running" if active_stage_status else status)
                stage_run.finished_at = None if active_stage_status else _now()
                if not active_stage_status:
                    observe_stage_duration(
                        stage=stage_name,
                        result=stage_run.status,
                        duration_seconds=_elapsed_seconds_since(stage_run.started_at),
                    )
                await self._persist_stage_run_output_summary_async(task, stage_run, summary)
                stage_run.counts = self._stage_counts(db, stage_run)
                if status in {"failed", "partial_success", "downstream_missing"}:
                    stage_run.last_error = summary.get("error")
                self._merge_task_stage_summary_entry(
                    task,
                    stage_run,
                    {
                        **(
                            {
                                "failure_code": summary.get("failure_code"),
                                "failure_category": summary.get("failure_category"),
                                "failure_message": summary.get("failure_message"),
                            }
                            if summary.get("failure_code")
                            else {}
                        ),
                    },
                )
        task.current_stage = stage_name
        if stage_name == "firmware_unpack":
            task.metrics = {
                **task.metrics,
                "unpacked_firmware_count": int(summary.get("success_count", 0)),
                "failed_firmware_count": int(summary.get("failed_count", 0)),
            }
        elif stage_name == "system_analysis":
            stage_summary = dict(stage_run.output_summary or {})
            task.metrics = {
                **task.metrics,
                "high_risk_module_count": int(stage_summary.get("high_risk_module_count", summary.get("high_risk_module_count", 0)) or 0),
                "medium_risk_module_count": int(stage_summary.get("medium_risk_module_count", summary.get("medium_risk_module_count", 0)) or 0),
                "low_risk_module_count": int(stage_summary.get("low_risk_module_count", summary.get("low_risk_module_count", 0)) or 0),
                "candidate_module_count": int(stage_summary.get("candidate_module_count", summary.get("candidate_module_count", 0)) or 0),
                "selected_module_count": int(stage_summary.get("selected_module_count", summary.get("selected_module_count", 0)) or 0),
            }
            task_summary = dict(task.summary or {})
            if self._normalize_downstream_status(stage_run.status) == "success" and not task_summary.get("selected_modules"):
                self._refresh_system_analysis_stage_from_synced_items(db, task)
                task_summary = dict(task.summary or {})
                if task_summary.get("selected_modules"):
                    stage_run = db.query(BinarySecurityStageRun).filter(
                        BinarySecurityStageRun.task_id == task.id,
                        BinarySecurityStageRun.stage_name == stage_name,
                    ).first() or stage_run
                    stage_summary = dict(stage_run.output_summary or stage_summary)
                    task.metrics = {
                        **task.metrics,
                        "high_risk_module_count": int(stage_summary.get("high_risk_module_count", summary.get("high_risk_module_count", 0)) or 0),
                        "medium_risk_module_count": int(stage_summary.get("medium_risk_module_count", summary.get("medium_risk_module_count", 0)) or 0),
                        "low_risk_module_count": int(stage_summary.get("low_risk_module_count", summary.get("low_risk_module_count", 0)) or 0),
                        "candidate_module_count": int(stage_summary.get("candidate_module_count", summary.get("candidate_module_count", 0)) or 0),
                        "selected_module_count": int(stage_summary.get("selected_module_count", summary.get("selected_module_count", 0)) or 0),
                    }
        elif stage_name == "entry_analysis":
            task.metrics = {**task.metrics, "entry_count": int(summary.get("entry_count", 0))}
        elif normalize_stage_name(stage_name) == "dataflow_vuln_scan":
            task.metrics = {**task.metrics, "vuln_result_count": int(summary.get("vuln_result_count", summary.get("success_count", 0)) or 0)}

        if observed_terminal_status in terminal_failure_statuses:
            status = observed_terminal_status
            active_stage_status = False
            for item in self._stage_items(db, task.id, stage_name):
                if str(item.status or "").strip() not in {"pending", "queued", "running", "dispatching"}:
                    continue
                item.status = status
                item.finished_at = item.finished_at or _now()
                item.error_message = (
                    summary.get("failure_message")
                    or summary.get("error")
                    or item.error_message
                )
            stage_run.status = status
            stage_run.finished_at = stage_run.finished_at or _now()
            stage_run.last_error = (
                summary.get("failure_message")
                or summary.get("error")
                or stage_run.last_error
            )

        if active_stage_status:
            # Keep the parent task in the active execution context while the
            # current stage still has live downstream work. A stage-level
            # "pending" here means individual items need redispatch/reclaim,
            # not that the whole task should be re-queued and start the same
            # stage a second time.
            task.status = "running"
            task.current_stage = stage_name
            task.last_error = None
            task.finished_at = None
            self._record_event(
                db,
                task,
                "stage_waiting_downstream_progress",
                "阶段仍在等待下游明确状态，已保留在当前阶段继续跟进",
                stage_name=stage_name,
                payload={
                    "state_event_id": event.id,
                    "stage_status": status,
                    "deferred_mode": "redispatch" if status == "pending" else "reconcile",
                },
            )
            await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
            return
        if task.status == TASK_STATUS_PENDING_MODULE_CONFIRMATION:
            self._invalidate_task_execution(task)
            await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
            return
        if summary.get("archive_blocked"):
            task.status = "failed"
            task.last_error = summary.get("error") or "总任务产物归档失败"
            self._invalidate_task_execution(task)
            task.finished_at = _now()
            blocked_item_ids = self._suppress_later_stage_items_after_archive_blocked(
                db,
                task,
                stage_name=stage_name,
                error_message=task.last_error,
            )
            observe_task_error("downstream_error", stage=stage_name, result="archive_blocked")
            observe_task_lifecycle("finished", status=task.status, task_type=self._task_type(task))
            observe_task_duration(
                phase="execution",
                duration_seconds=_elapsed_seconds_since(task.started_at),
                status=task.status,
                task_type=self._task_type(task),
            )
            observe_task_duration(
                phase="total",
                duration_seconds=_elapsed_seconds_since(task.created_at),
                status=task.status,
                task_type=self._task_type(task),
            )
            self._record_event(
                db,
                task,
                "stage_archive_blocked",
                f"阶段业务执行已完成，但总任务产物归档失败，停止后续推进: {stage_name}",
                level="error",
                stage_name=stage_name,
                payload={
                    "stage_status": status,
                    "error": task.last_error,
                    "state_event_id": event.id,
                    "blocked_item_ids": blocked_item_ids,
                },
            )
            await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
            return
        if bool(payload.get("stage_retry_mode")) and stage_name == str(payload.get("target_stage_name") or ""):
            self._record_event(
                db,
                task,
                "stage_retry_finished",
                f"阶段重试完成: {stage_name}",
                stage_name=stage_name,
                payload={"status": status, "state_event_id": event.id},
            )
        if status == "failed":
            if bool(payload.get("stage_retry_mode")) or bool(payload.get("task_retry_mode")):
                self._clear_retry_execution_context(
                    db,
                    task,
                    stage_name=stage_name,
                    payload={"status": status, "state_event_id": event.id},
                )
            self._record_event(
                db,
                task,
                "stage_failed",
                f"阶段失败，停止后续推进: {stage_name}",
                level="error",
                stage_name=stage_name,
                payload={
                    "error": task.last_error,
                    "state_event_id": event.id,
                    **(
                        {
                            "failure_code": summary.get("failure_code"),
                            "failure_category": summary.get("failure_category"),
                            "failure_message": summary.get("failure_message"),
                        }
                        if summary.get("failure_code")
                        else {}
                    ),
                },
            )
            self._finalize_task(db, task)
            await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
            return
        if bool(payload.get("stage_retry_mode")) or bool(payload.get("task_retry_mode")):
            self._clear_retry_execution_context(
                db,
                task,
                stage_name=stage_name,
                payload={"status": status, "state_event_id": event.id},
            )
        if self._ensure_task_remains_cancelling(db, task) is not None:
            await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
            return
        next_stage = self._next_incomplete_stage(db, task)
        if (
            task.status in {"running", "dispatching"}
            and next_stage
            and self._streaming_mode_enabled(task)
            and self._is_streaming_tail_stage(task, next_stage)
        ):
            task.status = "running"
            task.current_stage = next_stage
            task.finished_at = None
            task.last_error = None
            self._record_event(
                db,
                task,
                "streaming_tail_activated",
                f"阶段完成后切换为流式尾段推进: {next_stage}",
                stage_name=next_stage,
                payload={"state_event_id": event.id, "completed_stage": stage_name},
            )
            await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
            return
        if task.status in {"running", "dispatching"} and next_stage:
            task.status = "pending"
            task.current_stage = next_stage
            self._invalidate_task_execution(task)
            task.finished_at = None
            task.last_error = None
            self._record_event(
                db,
                task,
                "task_requeued_after_stage_completion",
                f"阶段完成后任务继续进入下一阶段: {next_stage}",
                stage_name=next_stage,
                payload={"state_event_id": event.id, "completed_stage": stage_name},
            )
            await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
            self._enqueue_task(task.id)
            return
        self._finalize_task(db, task)
        await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)

    async def _apply_task_execution_failed_locked(self, db: Session, event: BinarySecurityStateEvent) -> None:
        payload = dict(event.payload or {})
        task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == event.task_id).first()
        if task is None:
            return
        expected_dispatcher = str(payload.get("dispatcher_instance_id") or "").strip()
        expected_execution_token = str(payload.get("execution_token") or "").strip()
        current_execution_token = task.dispatch_started_at.isoformat() if task.dispatch_started_at else ""
        if expected_dispatcher and task.dispatcher_instance_id not in {None, expected_dispatcher}:
            self._record_event(
                db,
                task,
                "task_execution_failed_ignored",
                "执行失败事件已过期，当前 dispatcher 已变化",
                level="warning",
                stage_name=task.current_stage,
                payload={"state_event_id": event.id, "dispatcher_instance_id": expected_dispatcher},
            )
            return
        if expected_execution_token and current_execution_token and expected_execution_token != current_execution_token:
            self._record_event(
                db,
                task,
                "task_execution_failed_ignored",
                "执行失败事件已过期，当前执行 token 已变化",
                level="warning",
                stage_name=task.current_stage,
                payload={"state_event_id": event.id, "execution_token": expected_execution_token},
            )
            return
        if task.status not in {"dispatching", "running"}:
            self._record_event(
                db,
                task,
                "task_execution_failed_ignored",
                "执行失败事件已过期，当前任务不在运行态",
                level="warning",
                stage_name=task.current_stage,
                payload={"state_event_id": event.id, "status": task.status},
            )
            return
        error_message = str(payload.get("error") or "任务执行失败")
        task.status = "failed"
        task.last_error = error_message
        self._invalidate_task_execution(task)
        task.finished_at = _now()
        observe_task_error("execution_error", stage=str(task.current_stage or "unknown"), result="failed")
        observe_task_lifecycle("finished", status=task.status, task_type=self._task_type(task))
        observe_task_duration(
            phase="execution",
            duration_seconds=_elapsed_seconds_since(task.started_at),
            status=task.status,
            task_type=self._task_type(task),
        )
        observe_task_duration(
            phase="total",
            duration_seconds=_elapsed_seconds_since(task.created_at),
            status=task.status,
            task_type=self._task_type(task),
        )
        self._record_event(
            db,
            task,
            "task_failed",
            f"任务执行失败: {error_message}",
            level="error",
            stage_name=task.current_stage,
            payload={"state_event_id": event.id},
        )
        await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)

    def _apply_manual_policy_update_requested_locked(self, db: Session, event: BinarySecurityStateEvent) -> None:
        payload = dict(event.payload or {})
        task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == event.task_id).first()
        if task is None:
            return
        mode = str(payload.get("mode") or "policy").strip()
        before = dict(payload.get("before") or {})
        after = dict(payload.get("after") or {})
        if not after:
            raise ValidationError("策略更新事件缺少目标策略")
        if mode == "runtime_override":
            task.runtime_override = after
            task.runtime_override_version = int(getattr(task, "runtime_override_version", 0) or 0) + 1
            task.runtime_override_updated_at = _now()
            task.runtime_override_updated_by = str(payload.get("updated_by") or "").strip() or None
            self._record_event(
                db,
                task,
                "task_runtime_policy_updated",
                "任务运行时策略已由 reducer 更新",
                payload={
                    "before": before,
                    "after": after,
                    "effective_scope": payload.get("effective_scope") or "tail_claim_immediate",
                    "state_event_id": event.id,
                },
            )
            return
        task.policy = after
        if mode == "concurrency":
            self._record_event(
                db,
                task,
                "task_concurrency_updated",
                "任务阶段并发配置已由 reducer 更新",
                payload={
                    "before": payload.get("concurrency_before") or before.get("stage_parallelism") or {},
                    "after": payload.get("concurrency_after") or after.get("stage_parallelism") or {},
                    "state_event_id": event.id,
                },
            )
        else:
            self._record_event(
                db,
                task,
                "task_policy_updated",
                "任务策略已由 reducer 更新",
                payload={
                    "before": before,
                    "after": after,
                    "effective_scope": payload.get("effective_scope") or "future_stages_only",
                    "state_event_id": event.id,
                },
            )

    def _apply_archive_job_copy_failed_locked(self, db: Session, event: BinarySecurityStateEvent) -> None:
        job = db.query(BinarySecurityArchiveJob).filter(BinarySecurityArchiveJob.id == event.archive_job_id).first()
        if job is None:
            return
        task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == job.task_id).first()
        item = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.id == job.item_id).first()
        if task is None:
            return
        payload = dict(event.payload or {})
        job.archive_status = "failed"
        job.error_message = payload.get("error") or job.error_message or "下游产物归档失败"
        job.completed_at = job.completed_at or _now()
        job.updated_at = _now()
        if task.status not in TASK_TERMINAL_STATUSES:
            task.status = "failed"
            task.current_stage = job.stage_name
            task.last_error = job.error_message
            task.finished_at = _now()
            task.dispatcher_instance_id = None
            task.dispatch_started_at = None
            task.lease_expires_at = None
        self._record_event(
            db,
            task,
            "downstream_archive_job_copy_failed",
            "下游产物归档复制失败，已由 reducer 记录失败事实",
            level="warning",
            stage_name=job.stage_name,
            item=item,
            payload={
                "state_event_id": event.id,
                "archive_job_id": job.id,
                "archive_status": job.archive_status,
                "error": job.error_message,
            },
        )
        self._write_task_metadata(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)

    async def _downstream_reconcile_loop(self) -> None:
        interval_seconds = max(
            5,
            int(
                getattr(self.cfg.scheduler, "downstream_reconcile_interval_seconds", 30)
                or self.cfg.scheduler.stage_poll_interval_seconds
                or self.cfg.scheduler.poll_interval_seconds
                or 30
            ),
        )
        while self._running:
            db = get_session_factory()()
            try:
                with observe_scheduler_loop("downstream_reconcile"):
                    self._mark_loop_heartbeat("downstream_reconcile")
                    task_refs = await asyncio.to_thread(self._list_tasks_needing_downstream_sync, db)
                    token = self._service_token()
                    results = await self._run_with_limits(
                        task_refs,
                        lambda ref: self._reconcile_downstream_task_ref(ref, token),
                        concurrency=max(1, min(int(self.cfg.scheduler.downstream_sync_concurrency or 1), 8)),
                        timeout_seconds=self.cfg.scheduler.downstream_request_timeout_seconds,
                    )
                    for ref, _, exc in results:
                        if exc is None:
                            continue
                        try:
                            task = self._task_or_404(db, ref["project_id"], ref["task_id"])
                            self._record_event(
                                db,
                                task,
                                "downstream_status_reconcile_failed",
                                f"后台同步下游状态失败: {exc}",
                                level="warning",
                                payload={
                                    "task_id": ref["task_id"],
                                    "project_id": ref["project_id"],
                                    "error": str(exc),
                                    "error_type": exc.__class__.__name__,
                                    "downstream_sync_batch_size": int(
                                        getattr(self.cfg.scheduler, "downstream_sync_batch_size", 50) or 50
                                    ),
                                },
                            )
                            db.commit()
                        except Exception:
                            db.rollback()
                    deferred_cleanup_refs = await asyncio.to_thread(self._list_tasks_with_deferred_cleanup, db)
                    deferred_results = await self._run_with_limits(
                        deferred_cleanup_refs,
                        lambda ref: self._reconcile_deferred_cleanup_task_ref(ref, token),
                        concurrency=max(1, min(int(self.cfg.scheduler.downstream_sync_concurrency or 1), 8)),
                        timeout_seconds=self.cfg.scheduler.downstream_request_timeout_seconds,
                    )
                    for ref, _, exc in deferred_results:
                        if exc is None:
                            continue
                        try:
                            task = self._task_or_404(db, ref["project_id"], ref["task_id"])
                            self._record_event(
                                db,
                                task,
                                "task_delete_cleanup_reconcile_failed",
                                f"后台补偿下游删除失败: {exc}",
                                level="warning",
                                payload={
                                    "task_id": ref["task_id"],
                                    "project_id": ref["project_id"],
                                    "error": str(exc),
                                    "error_type": exc.__class__.__name__,
                                },
                            )
                            db.commit()
                        except Exception:
                            db.rollback()
                    await self._observe_runtime_metrics(db, reconcile_candidates=len(task_refs))
                    self._mark_loop_heartbeat("downstream_reconcile")
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                self._recover_loop_db_error("downstream_reconcile", db, exc)
                logger.exception("binary-security downstream reconcile loop crashed and recovered")
                await asyncio.sleep(1)
            finally:
                db.close()
            await asyncio.sleep(interval_seconds)

    async def _reconcile_downstream_task_ref(self, ref: dict[str, str], token: str | None) -> None:
        db = get_session_factory()()
        try:
            await self.sync_downstream_status(
                db,
                project_id=ref["project_id"],
                task_id=ref["task_id"],
                force=False,
                token=token,
                record_request_event=False,
                record_noop_events=False,
                apply_state=True,
            )
        finally:
            db.close()

    async def _stage_item_sync_reconcile_loop(self) -> None:
        interval_seconds = self._stage_item_sync_reconcile_interval_seconds()
        while self._running:
            db = get_session_factory()()
            try:
                with observe_scheduler_loop("stage_item_sync_reconcile"):
                    self._mark_loop_heartbeat("stage_item_sync_reconcile")
                    refs = await asyncio.to_thread(self._list_tasks_with_stale_stage_item_syncs, db)
                    token = self._service_token()
                    results = await self._run_with_limits(
                        refs,
                        lambda ref: self._reconcile_stale_stage_item_sync_ref(ref, token),
                        concurrency=max(1, min(int(self.cfg.scheduler.downstream_sync_concurrency or 1), 8)),
                        timeout_seconds=self.cfg.scheduler.downstream_request_timeout_seconds,
                    )
                    for ref, _, exc in results:
                        if exc is None:
                            continue
                        with suppress(Exception):
                            task = self._task_or_404(db, ref["project_id"], ref["task_id"])
                            self._record_event(
                                db,
                                task,
                                "downstream_sync_reconcile_failed",
                                f"后台 stale sync 收敛失败: {exc}",
                                level="warning",
                                stage_name=ref.get("stage_name"),
                                payload={
                                    "task_id": ref["task_id"],
                                    "project_id": ref["project_id"],
                                    "stage_name": ref.get("stage_name"),
                                    "item_ids": list(ref.get("item_ids") or []),
                                    "error": str(exc),
                                    "error_type": exc.__class__.__name__,
                                },
                            )
                            db.commit()
                    self._mark_loop_heartbeat("stage_item_sync_reconcile")
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                self._recover_loop_db_error("stage_item_sync_reconcile", db, exc)
                logger.exception("binary-security stage item sync reconcile loop crashed and recovered")
                await asyncio.sleep(1)
            finally:
                db.close()
            await asyncio.sleep(interval_seconds)

    async def _archive_runtime_reconcile_loop(self) -> None:
        interval_seconds = self._archive_runtime_reconcile_interval_seconds()
        while self._running:
            try:
                self._mark_loop_heartbeat("archive_runtime_reconcile")
                await asyncio.to_thread(self._reclaim_stale_archive_jobs)
                self._mark_loop_heartbeat("archive_runtime_reconcile")
            except asyncio.CancelledError:
                raise
            except Exception:
                logger.exception("binary-security archive runtime reconcile loop crashed and recovered")
                await asyncio.sleep(1)
            await asyncio.sleep(interval_seconds)

    async def _state_repair_reconcile_loop(self) -> None:
        interval_seconds = self._state_repair_reconcile_interval_seconds()
        while self._running:
            db = get_session_factory()()
            try:
                self._mark_loop_heartbeat("state_repair_reconcile")
                await asyncio.to_thread(self._repair_retryable_state_events, db)
                self._mark_loop_heartbeat("state_repair_reconcile")
            except asyncio.CancelledError:
                raise
            except Exception:
                logger.exception("binary-security state repair reconcile loop crashed and recovered")
                await asyncio.sleep(1)
            finally:
                db.close()
            await asyncio.sleep(interval_seconds)

    def _repair_retryable_state_events(self, db: Session) -> int:
        batch_size = self._state_repair_reconcile_batch_size()
        events = (
            db.query(BinarySecurityStateEvent)
            .filter(BinarySecurityStateEvent.status.in_(["retryable", "dead_letter"]))
            .order_by(BinarySecurityStateEvent.updated_at.asc(), BinarySecurityStateEvent.id.asc())
            .limit(batch_size)
            .all()
        )
        repaired = 0
        for event in events:
            task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == event.task_id).first()
            if task is None:
                continue
            event.status = "pending"
            event.available_at = _now()
            event.leased_by = None
            event.lease_expires_at = None
            event.processing_result = "requeued_for_repair"
            event.updated_at = _now()
            self._record_event(
                db,
                task,
                "task_state_repair_reconcile_triggered",
                "检测到 retryable/dead-letter reducer 事件，已重新排队修复",
                stage_name=event.stage_name,
                payload={
                    "state_event_id": event.id,
                    "event_type": event.event_type,
                    "resolution_reason": "retryable_or_dead_letter_state_event",
                },
            )
            repaired += 1
        if repaired:
            db.commit()
        else:
            db.rollback()
        return repaired

    def _list_tasks_with_stale_stage_item_syncs(self, db: Session) -> list[dict[str, Any]]:
        batch_size = self._stage_item_sync_reconcile_batch_size()
        rows = (
            db.query(BinarySecurityStageItem)
            .join(BinarySecurityTask, BinarySecurityTask.id == BinarySecurityStageItem.task_id)
            .filter(
                BinarySecurityTask.status.in_(["pending", "dispatching", "running", "failed"]),
                BinarySecurityStageItem.downstream_service.isnot(None),
                BinarySecurityStageItem.downstream_task_id.isnot(None),
                BinarySecurityStageItem.status.in_(["pending", "queued", "dispatching", "running"]),
            )
            .order_by(BinarySecurityStageItem.updated_at.asc(), BinarySecurityStageItem.created_at.asc(), BinarySecurityStageItem.id.asc())
            .limit(batch_size * 4)
            .all()
        )
        grouped: dict[tuple[str, str, str], dict[str, Any]] = {}
        for item in rows:
            item_task = getattr(item, "task", None)
            if item_task is not None and self._task_runtime_phase(item_task) == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION and not self._is_reducer_role():
                continue
            if not self._item_downstream_sync_stale(item):
                continue
            key = (str(item.project_id or ""), str(item.task_id or ""), str(item.stage_name or ""))
            entry = grouped.setdefault(
                key,
                {
                    "project_id": str(item.project_id or ""),
                    "task_id": str(item.task_id or ""),
                    "stage_name": str(item.stage_name or ""),
                    "item_ids": [],
                },
            )
            entry["item_ids"].append(str(item.id or ""))
            if sum(len(current["item_ids"]) for current in grouped.values()) >= batch_size:
                break
        return list(grouped.values())

    async def _reconcile_stale_stage_item_sync_ref(self, ref: dict[str, Any], token: str | None) -> None:
        db = get_session_factory()()
        try:
            task = self._task_or_404(db, ref["project_id"], ref["task_id"])
            self._record_event(
                db,
                task,
                "downstream_sync_reconcile_triggered",
                "检测到阶段下游同步陈旧，触发安全重同步",
                stage_name=ref.get("stage_name"),
                payload={
                    "task_id": ref["task_id"],
                    "stage_name": ref.get("stage_name"),
                    "item_ids": list(ref.get("item_ids") or []),
                    "resolution_reason": "stale_sync_attempt",
                },
            )
            db.commit()
            await self.sync_downstream_status(
                db,
                project_id=ref["project_id"],
                task_id=ref["task_id"],
                stage_name=ref.get("stage_name"),
                item_ids=list(ref.get("item_ids") or []),
                force=True,
                token=token,
                record_request_event=False,
                record_noop_events=False,
                apply_state=True,
            )
        finally:
            db.close()

    def _next_archived_job(self) -> str | None:
        session_factory = get_session_factory()
        db = session_factory()
        try:
            job = (
                db.query(BinarySecurityArchiveJob)
                .filter(BinarySecurityArchiveJob.archive_status == "archived")
                .order_by(BinarySecurityArchiveJob.updated_at.asc(), BinarySecurityArchiveJob.id.asc())
                .first()
            )
            if job is None:
                return None
            updated = (
                db.query(BinarySecurityArchiveJob)
                .filter(
                    BinarySecurityArchiveJob.id == job.id,
                    BinarySecurityArchiveJob.archive_status == "archived",
                )
                .update(
                    {
                        BinarySecurityArchiveJob.archive_status: "applying",
                        BinarySecurityArchiveJob.owner_id: self.instance_id,
                        BinarySecurityArchiveJob.updated_at: _now(),
                    },
                    synchronize_session=False,
                )
            )
            db.commit()
            return job.id if updated else None
        finally:
            db.close()

    def _list_tasks_needing_downstream_sync(self, db: Session) -> list[dict[str, str]]:
        rows = (
            db.query(BinarySecurityTask)
            .join(BinarySecurityStageItem, BinarySecurityStageItem.task_id == BinarySecurityTask.id)
            .filter(
                BinarySecurityTask.status.in_(["pending", "dispatching", "running", "failed"]),
                BinarySecurityStageItem.downstream_service.isnot(None),
                BinarySecurityStageItem.downstream_task_id.isnot(None),
                BinarySecurityStageItem.status.in_(
                    ["pending", "queued", "running", "dispatching", "failed", "success", "cancelled", "downstream_missing", "partial_success"]
                ),
            )
            .distinct()
            .all()
        )
        refs: list[dict[str, str]] = []
        seen: set[str] = set()
        for task in rows:
            if task.id in seen:
                continue
            if self._task_runtime_phase(task) == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION and not self._is_reducer_role():
                continue
            candidate_items = self._task_reconcile_candidate_items(db, task)
            if not candidate_items:
                continue
            if not self._task_needs_downstream_reconcile(db, task):
                continue
            if not self._task_sync_cooldown_elapsed_for_items(task, candidate_items):
                continue
            seen.add(task.id)
            refs.append({"project_id": str(task.project_id), "task_id": str(task.id)})
        return refs

    def _task_sync_cooldown_elapsed(self, db: Session, task: BinarySecurityTask) -> bool:
        return self._task_sync_cooldown_elapsed_for_items(
            task,
            self._task_reconcile_candidate_items(db, task),
        )

    def _claim_archive_job(self) -> str | None:
        session_factory = get_session_factory()
        db = session_factory()
        try:
            while True:
                job = (
                    db.query(BinarySecurityArchiveJob)
                    .filter(BinarySecurityArchiveJob.archive_status == "pending")
                    .order_by(BinarySecurityArchiveJob.created_at.asc(), BinarySecurityArchiveJob.id.asc())
                    .first()
                )
                if job is None:
                    return None
                if not self._archive_job_ready_for_retry(job):
                    db.rollback()
                    delayed_job_exists = (
                        db.query(BinarySecurityArchiveJob)
                        .filter(BinarySecurityArchiveJob.archive_status == "pending")
                        .order_by(BinarySecurityArchiveJob.created_at.asc(), BinarySecurityArchiveJob.id.asc())
                        .all()
                    )
                    next_ready = next((candidate for candidate in delayed_job_exists if self._archive_job_ready_for_retry(candidate)), None)
                    if next_ready is None:
                        return None
                    job = next_ready
                duplicate_active = (
                    db.query(BinarySecurityArchiveJob)
                    .filter(
                        BinarySecurityArchiveJob.id != job.id,
                        BinarySecurityArchiveJob.item_id == job.item_id,
                        BinarySecurityArchiveJob.downstream_task_id == job.downstream_task_id,
                        BinarySecurityArchiveJob.archive_status.in_(["running", "archived", "applying", "success"]),
                    )
                    .first()
                )
                if duplicate_active is not None:
                    job.archive_status = "skipped"
                    job.error_message = f"duplicate archive job skipped; canonical job={duplicate_active.id}"
                    job.completed_at = _now()
                    job.updated_at = _now()
                    db.commit()
                    continue
                updated = (
                    db.query(BinarySecurityArchiveJob)
                    .filter(
                        BinarySecurityArchiveJob.id == job.id,
                        BinarySecurityArchiveJob.archive_status == "pending",
                    )
                    .update(
                        {
                            BinarySecurityArchiveJob.archive_status: "running",
                            BinarySecurityArchiveJob.owner_id: self.instance_id,
                            BinarySecurityArchiveJob.started_at: _now(),
                            BinarySecurityArchiveJob.updated_at: _now(),
                            BinarySecurityArchiveJob.attempts: int(job.attempts or 0) + 1,
                        },
                        synchronize_session=False,
                    )
                )
                db.commit()
                if updated:
                    return job.id
        finally:
            db.close()

    async def _process_archive_job(self, job_id: str) -> None:
        archived_root, error, retry_scheduled = await asyncio.to_thread(self._run_archive_copy_job, job_id)
        if retry_scheduled:
            return
        if error:
            observe_archive_action("copy", "failed")
            await asyncio.to_thread(
                self._enqueue_archive_state_event_by_job_id,
                job_id,
                event_type="archive_job_copy_failed",
                payload={"error": error},
            )
            return
        observe_archive_action("copy", "archived")
        await asyncio.to_thread(
            self._enqueue_archive_state_event_by_job_id,
            job_id,
            event_type="archive_job_copied",
            payload={"archive_root": archived_root},
        )

    async def _wait_archive_job_completion(self, job_id: str, task_id: str) -> BinarySecurityArchiveJob | None:
        session_factory = get_session_factory()
        while True:
            self._touch_task_heartbeat(task_id)
            db = session_factory()
            try:
                job = db.query(BinarySecurityArchiveJob).filter(BinarySecurityArchiveJob.id == job_id).first()
                if job is None:
                    return None
                if job.archive_status in {"success", "failed"}:
                    return job
            finally:
                db.close()
            await asyncio.sleep(max(1, self.cfg.scheduler.stage_poll_interval_seconds))

    def _run_archive_copy_job(self, job_id: str) -> tuple[str | None, str | None, bool]:
        session_factory = get_session_factory()
        db = session_factory()
        try:
            job = db.query(BinarySecurityArchiveJob).filter(BinarySecurityArchiveJob.id == job_id).first()
            if job is None or job.archive_status != "running":
                return None, "archive job is not running", False
            task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == job.task_id).first()
            item = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.id == job.item_id).first()
            if task is None or item is None:
                job.archive_status = "failed"
                job.error_message = "任务或阶段子任务不存在"
                job.completed_at = _now()
                db.commit()
                return None, job.error_message, False
            if task.status == "cancelled":
                job.archive_status = "failed"
                job.error_message = "任务已取消，跳过归档复制"
                job.completed_at = _now()
                job.updated_at = _now()
                db.commit()
                return None, job.error_message, False
            payload = dict(job.payload or {})
            bound_downstream_task_id = self._archive_job_bound_downstream_task_id(job)
            archive_result = self._archive_downstream_output(
                db,
                task,
                item,
                semantic_key=item.item_key,
                bound_downstream_task_id=bound_downstream_task_id,
                payload=payload.get("downstream_payload") or {},
                extra_paths=payload.get("extra_paths") or None,
            )
            if archive_result.status == "source_not_ready":
                scheduled, retry_delay_seconds, next_retry_at = self._schedule_archive_job_missing_source_retry(
                    db,
                    task,
                    item,
                    job,
                    source_candidates=archive_result.source_candidates,
                )
                if scheduled:
                    db.commit()
                    return None, None, True
                exhausted_attempt = self._archive_job_retry_attempt(job)
                job.archive_status = "failed"
                job.error_message = "下游产物归档未完成"
                job.completed_at = _now()
                job.updated_at = _now()
                job.payload = {
                    **self._clear_archive_job_retry_metadata(job),
                    "archive_copy_stats": dict((item.output_ref or {}).get("archive_copy_stats") or {}),
                    "copy_retry_reason": ARCHIVE_COPY_MISSING_SOURCE_RETRY_REASON,
                    "copy_retry_attempt": exhausted_attempt,
                    "copy_retry_schedule_seconds": self._archive_copy_missing_source_retry_schedule_seconds(),
                    "last_missing_source_observed_at": _now().isoformat(),
                    "last_source_candidate_count": len(archive_result.source_candidates),
                    "last_source_candidates_preview": list(archive_result.source_candidates[:DB_ARTIFACT_PREVIEW_LIMIT]),
                }
                self._record_event(
                    db,
                    task,
                    "downstream_archive_job_retry_exhausted",
                    "下游产物长时间未就绪，归档延迟重试已耗尽",
                    stage_name=job.stage_name,
                    item=item,
                    level="warning",
                    payload={
                        "archive_job_id": job.id,
                        "retry_attempt": exhausted_attempt,
                        "retry_delay_seconds": retry_delay_seconds,
                        "next_retry_at": next_retry_at.isoformat() if next_retry_at else None,
                        "source_candidate_count": len(archive_result.source_candidates),
                        "source_candidates_preview": list(archive_result.source_candidates[:DB_ARTIFACT_PREVIEW_LIMIT]),
                        "downstream_task_id": job.downstream_task_id,
                        "resolution_reason": "archive_source_retry_exhausted",
                    },
                )
                db.commit()
                return None, job.error_message, False
            archived_dir = archive_result.target_dir
            if not archived_dir:
                job.archive_status = "failed"
                job.error_message = "下游产物归档未完成"
                job.completed_at = _now()
                job.updated_at = _now()
                db.commit()
                return None, job.error_message, False
            copy_stats = dict((item.output_ref or {}).get("archive_copy_stats") or {})
            job.payload = {
                **self._clear_archive_job_retry_metadata(job),
                "bound_downstream_task_id": bound_downstream_task_id,
                "downstream_payload": payload.get("downstream_payload") or {},
                "extra_paths": payload.get("extra_paths") or None,
                "mapped_status": payload.get("mapped_status"),
                "archive_copy_stats": copy_stats,
            }
            observe_archive_duration(
                action="copy",
                result="archived",
                duration_seconds=_elapsed_seconds_since(job.started_at),
            )
            job.archive_status = "archived"
            job.archive_root = str(archived_dir)
            job.error_message = None
            job.updated_at = _now()
            db.commit()
            return str(archived_dir), None, False
        except Exception as exc:
            db.rollback()
            try:
                job = db.query(BinarySecurityArchiveJob).filter(BinarySecurityArchiveJob.id == job_id).first()
                if job is not None:
                    job.archive_status = "failed"
                    job.error_message = str(exc)
                    job.completed_at = _now()
                    job.updated_at = _now()
                    observe_archive_duration(
                        action="copy",
                        result="failed",
                        duration_seconds=_elapsed_seconds_since(job.started_at),
                    )
                    db.commit()
            except Exception:
                db.rollback()
            return None, str(exc), False
        finally:
            db.close()

    async def _apply_archive_job_status(self, job_id: str, archived_root: str | None) -> None:
        await asyncio.to_thread(
            self._enqueue_archive_state_event_by_job_id,
            job_id,
            event_type="archive_job_copied",
            payload={"archive_root": archived_root, "source": "compat_apply_request"},
        )

    async def _apply_archive_job_status_locked(
        self,
        db: Session,
        job_id: str,
        archived_root: str | None,
        *,
        state_event_id: str | None = None,
    ) -> None:
        job = db.query(BinarySecurityArchiveJob).filter(BinarySecurityArchiveJob.id == job_id).first()
        if job is None or job.archive_status not in {"archived", "running", "applying", "success"}:
            return
        task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == job.task_id).first()
        item = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.id == job.item_id).first()
        if task is None or item is None:
            return
        job_bound_downstream_task_id = self._archive_job_bound_downstream_task_id(job)
        current_downstream_task_id = self._current_downstream_task_id(item)
        if (
            job_bound_downstream_task_id
            and current_downstream_task_id
            and job_bound_downstream_task_id != current_downstream_task_id
        ):
            mismatch_payload = self._binding_mismatch_payload(
                source="archive_apply",
                expected_downstream_task_id=current_downstream_task_id,
                actual_downstream_task_id=job_bound_downstream_task_id,
                archive_job_id=job.id,
            )
            self._record_binding_mismatch_event(
                db,
                task,
                item,
                event_type="archive_job_superseded_late_result",
                message="旧 child 归档结果晚到，已忽略并废弃旧归档作业",
                payload=mismatch_payload,
            )
            job.archive_status = "superseded"
            job.error_message = None
            job.completed_at = _now()
            job.updated_at = _now()
            payload = dict(job.payload or {})
            payload["superseded"] = True
            payload["superseded_reason"] = "late_archive_apply_binding_mismatch"
            payload["superseded_downstream_task_id"] = job_bound_downstream_task_id or None
            job.payload = payload
            observe_archive_action("apply", "superseded")
            observe_archive_duration(
                action="apply",
                result="superseded",
                duration_seconds=_elapsed_seconds_since(job.started_at),
            )
            return
        if str(task.status or "").strip() in {TASK_STATUS_CANCELLING, "cancelled"}:
            job.archive_status = "ignored"
            job.error_message = None
            job.completed_at = job.completed_at or _now()
            job.updated_at = _now()
            self._record_event(
                db,
                task,
                "downstream_archive_job_ignored",
                "归档完成事件到达时任务已进入取消链路，已忽略以避免恢复已取消阶段状态",
                level="warning",
                stage_name=item.stage_name,
                item=item,
                payload={
                    "archive_job_id": job.id,
                    "state_event_id": state_event_id,
                    "archive_root": archived_root or job.archive_root,
                    "task_status": task.status,
                    "archive_bound_downstream_task_id": job_bound_downstream_task_id or None,
                },
            )
            await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
            return
        failure_ctx = self._current_stage_authoritative_failure_context(db, task)
        if (
            failure_ctx is not None
            and str(failure_ctx.get("failure_category") or "").strip() == "archive_blocked"
            and str(failure_ctx.get("stage_name") or "").strip() == str(item.stage_name or "").strip()
        ):
            job.archive_status = "ignored"
            job.error_message = None
            job.completed_at = job.completed_at or _now()
            job.updated_at = _now()
            self._record_event(
                db,
                task,
                "downstream_archive_apply_blocked_by_authoritative_failure",
                "归档结果到达时当前阶段已被归档失败阻断，已拒绝晚到回写推进",
                level="warning",
                stage_name=item.stage_name,
                item=item,
                payload={
                    "archive_job_id": job.id,
                    "state_event_id": state_event_id,
                    "archive_root": archived_root or job.archive_root,
                    "failure_code": self._string_or_none(failure_ctx.get("failure_code")),
                    "failure_message": self._string_or_none(failure_ctx.get("failure_message")),
                    "archive_bound_downstream_task_id": job_bound_downstream_task_id or None,
                },
            )
            await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
            return
        try:
            payload = dict(job.payload or {})
            mapped_status = str(payload.get("mapped_status") or "").strip()
            downstream_payload = dict(payload.get("downstream_payload") or {})
            effective_archive_root = archived_root or job.archive_root
            archive_copy_stats = dict(payload.get("archive_copy_stats") or {})
            if not mapped_status:
                job.archive_status = "failed"
                job.error_message = "归档 job 缺少目标状态"
                job.completed_at = _now()
                return
            normalized_mapped_status = self._map_downstream_status(mapped_status) or mapped_status
            downstream_error_text = json.dumps(downstream_payload, ensure_ascii=False) if downstream_payload else ""
            if normalized_mapped_status == "failed" and any(
                marker in downstream_error_text.lower()
                for marker in ("task not found", "not found", "不存在", "downstream_missing")
            ):
                normalized_mapped_status = "downstream_missing"
            if str(item.status or "").strip().lower() == "downstream_missing" and normalized_mapped_status == "failed":
                normalized_mapped_status = "downstream_missing"
            self._apply_child_task_status_change(
                db,
                task=task,
                item=item,
                change_source="archive_apply",
                after_status=normalized_mapped_status,
                downstream_payload=downstream_payload,
                sync_status="synced",
                downstream_status_raw=self._string_or_none(downstream_payload.get("status")),
                downstream_status_mapped=normalized_mapped_status,
                downstream_status=self._string_or_none(downstream_payload.get("status")) or normalized_mapped_status,
                state_applied=True,
                error_message=(
                    downstream_payload.get("error")
                    or downstream_payload.get("error_message")
                    or downstream_payload.get("message")
                    or item.error_message
                ),
                archive_job_id=job.id,
                state_event_id=state_event_id,
                event_type="child_archive_status_changed",
                extra_payload={
                    "archive_root": effective_archive_root,
                    "downstream_payload": self._lightweight_downstream_payload(downstream_payload),
                },
            )
            self._merge_stage_item_output_ref(
                item,
                archive_root=effective_archive_root,
                **({"archive_copy_stats": archive_copy_stats} if archive_copy_stats else {}),
            )
            if item.stage_name == "firmware_unpack" and normalized_mapped_status == "success":
                self._refresh_firmware_unpack_item_result(
                    task,
                    item,
                    archived_dir=Path(effective_archive_root) if effective_archive_root else None,
                    bound_downstream_task_id=job_bound_downstream_task_id or None,
                    downstream_payload=downstream_payload,
                )
            if normalized_mapped_status in {"success", "partial_success"}:
                await self._refresh_terminal_item_result_from_downstream(
                    task,
                    item,
                    downstream_payload,
                    mapped_status=normalized_mapped_status,
                    archived_dir=Path(effective_archive_root) if effective_archive_root else None,
                )
            self._reconcile_stage_and_task_state_after_item_update(db, task, item.stage_name)
            if effective_archive_root:
                job.archive_root = effective_archive_root
            job.archive_status = "success"
            job.error_message = None
            job.completed_at = _now()
            job.updated_at = _now()
            self._record_event(
                db,
                task,
                "downstream_archive_job_completed",
                "下游产物归档完成，状态已同步",
                stage_name=item.stage_name,
                item=item,
                payload={
                    "archive_job_id": job.id,
                    "archive_root": effective_archive_root,
                    "mapped_status": mapped_status,
                    "downstream_service": item.downstream_service,
                    "downstream_task_id": item.downstream_task_id,
                    "archive_bound_downstream_task_id": job_bound_downstream_task_id or None,
                },
            )
            await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
            observe_archive_action("apply", "success")
            observe_archive_duration(
                action="apply",
                result="success",
                duration_seconds=_elapsed_seconds_since(job.started_at),
            )
        except Exception as exc:
            if job is not None:
                job.archive_status = "failed"
                job.error_message = str(exc)
                job.completed_at = _now()
                job.updated_at = _now()
            observe_archive_action("apply", "failed")
            observe_archive_duration(
                action="apply",
                result="failed",
                duration_seconds=_elapsed_seconds_since(job.started_at) if job is not None else None,
            )
            raise

    def _dispatch_once(self, db: Session) -> list[str]:
        (
            stale_reclaimed,
            orphaned_owned_execution_requeued,
            stale_stage_item_reclaimed,
            stale_running_reclaimed,
            released_running_requeued,
            recovered_missing_terminal_events,
        ) = self._run_parent_reclaim_pass(db)
        service_config = self._load_service_config(db)
        active_count = self._active_dispatch_count(db)
        slots = max(0, service_config.max_concurrent_tasks - active_count)
        claimed_ids = self._claim_pending_tasks(db, slots)
        if stale_reclaimed or orphaned_owned_execution_requeued or stale_stage_item_reclaimed or stale_running_reclaimed or released_running_requeued or recovered_missing_terminal_events or claimed_ids:
            db.commit()
        return claimed_ids

    def _dispatch_task_by_id(self, db: Session, task_id: str) -> str | None:
        self._run_parent_reclaim_pass(db)
        service_config = self._load_service_config(db)
        active_count = self._active_dispatch_count(db)
        if active_count >= service_config.max_concurrent_tasks:
            return None
        task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == task_id).first()
        if task is None:
            return None
        if (
            self._task_runtime_phase(task) == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION
            and self._tail_requires_execution_takeover(db, task)
        ):
            self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
            task.tail_reconcile_state = "idle"
            task.dispatcher_instance_id = None
            task.dispatch_started_at = None
            task.lease_expires_at = None
            self._release_tail_reconcile_owner(task.id)
            db.flush()
        if self._task_runtime_phase(task) == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION and not self._is_reducer_role():
            return None
        started_at = _now()
        lease_expires_at = self._next_lease_expiry(db, now_value=started_at)
        updated = (
            db.query(BinarySecurityTask)
            .filter(
                BinarySecurityTask.id == task_id,
                BinarySecurityTask.status == "pending",
                self._lease_filter_available(),
            )
            .update(
                {
                    BinarySecurityTask.status: "dispatching",
                    BinarySecurityTask.dispatcher_instance_id: self.instance_id,
                    BinarySecurityTask.dispatch_started_at: started_at,
                    BinarySecurityTask.lease_expires_at: lease_expires_at,
                    BinarySecurityTask.updated_at: started_at,
                },
                synchronize_session=False,
            )
        )
        if updated:
            db.commit()
            return task_id
        return None

    async def _run_task(self, task_id: str) -> None:
        session_factory = get_session_factory()
        db = session_factory()
        execution_token: str | None = None
        owner_registered = False
        try:
            task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == task_id).first()
            if (
                task is None
                or task.status != "dispatching"
                or task.dispatcher_instance_id != self.instance_id
                or not self._lease_is_active(task, db=db)
            ):
                return
            if task.started_at is None:
                task.started_at = _now()
            started_at = task.dispatch_started_at or _now()
            task.dispatch_started_at = started_at
            task.lease_expires_at = self._next_lease_expiry(db, now_value=started_at)
            execution_token = task.dispatch_started_at.isoformat() if task.dispatch_started_at else None
            task.status = "running"
            self._upsert_runtime_lease(db, task, now_value=started_at, owner_instance_id=self.instance_id)
            self._clear_task_abnormal_reason_snapshot(db, task)
            self._bind_execution_token(task)
            self._register_task_execution_owner(task.id, "primary_task_worker")
            owner_registered = True
            observe_task_lifecycle("started", status=task.status, task_type=self._task_type(task))
            self._record_event(
                db,
                task,
                "task_dispatched",
                f"任务由实例 {self.instance_id} 启动执行",
                payload={"dispatcher_instance_id": self.instance_id},
            )
            active_stage_name, active_item_count, has_downstream_refs = self._streaming_tail_active_context(db, task)
            if active_item_count > 0:
                self._record_event(
                    db,
                    task,
                    "downstream_reconcile_resumed_after_takeover",
                    "新的 worker 已接管流式尾段父任务，继续执行下游状态对账与阶段收口",
                    stage_name=active_stage_name or task.current_stage,
                    payload={
                        "dispatcher_instance_id": self.instance_id,
                        "active_stage_name": active_stage_name or task.current_stage,
                        "active_item_count": active_item_count,
                        "has_downstream_refs": has_downstream_refs,
                    },
                )
            db.commit()
            await self._execute_task(task_id)
        except StaleTaskExecution:
            return
        except Exception as exc:
            task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == task_id).first()
            if task:
                current_token = task.dispatch_started_at.isoformat() if task.dispatch_started_at else None
                same_execution = (
                    task.dispatcher_instance_id == self.instance_id
                    and execution_token is not None
                    and execution_token == current_token
                    and task.status in {"dispatching", "running"}
                )
                if not same_execution:
                    return
                self._enqueue_state_event(
                    db,
                    task_id=task.id,
                    project_id=task.project_id,
                    stage_name=task.current_stage,
                    event_type="task_execution_failed",
                    idempotency_key=(
                        f"task_execution_failed:{task.id}:"
                        f"{execution_token or current_token or ''}:{hashlib.sha1(str(exc).encode('utf-8')).hexdigest()}"
                    ),
                    payload={
                        "error": str(exc),
                        "dispatcher_instance_id": self.instance_id,
                        "execution_token": execution_token or current_token,
                    },
                )
                db.commit()
        finally:
            if owner_registered:
                self._release_task_execution_owner(task_id, "primary_task_worker")
            cleanup_db = session_factory()
            try:
                task = cleanup_db.query(BinarySecurityTask).filter(BinarySecurityTask.id == task_id).first()
                if (
                    task is None
                    or str(task.status or "").strip().lower() in TASK_TERMINAL_STATUSES
                    or (
                        not self._has_local_task_execution_owner(task_id)
                        and not self._task_has_active_streaming_stage_workers(task_id)
                        and not self._should_preserve_tail_runtime_lease(cleanup_db, task)
                    )
                ):
                    self._clear_runtime_lease(cleanup_db, task_id, owner_instance_id=self.instance_id)
                    self._release_tail_reconcile_owner(task_id)
                    cleanup_db.commit()
                elif self._should_preserve_tail_runtime_lease(cleanup_db, task):
                    observe_tail_reconcile_heartbeat("preserved_on_worker_exit")
            except Exception:
                cleanup_db.rollback()
                logger.exception("binary-security runtime lease cleanup failed: task_id=%s", task_id)
            finally:
                cleanup_db.close()
            async with self._worker_lock:
                self._workers.pop(task_id, None)
            db.close()

    async def _execute_task(self, task_id: str) -> None:
        session_factory = get_session_factory()
        db = session_factory()
        try:
            task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == task_id).first()
            if not task:
                return
            self._bind_execution_token(task)
            token = self._service_token()
            stage_sequence = self._stage_sequence_for_task(task)
            start_index = stage_sequence.index(task.current_stage) if task.current_stage in stage_sequence else 0
            stage_retry_mode = task.execution_mode in {"stage_retry", "stage_retry_failed_items", "stage_retry_full"} and bool(task.target_stage_name)
            task_retry_mode = task.execution_mode in {"task_retry", "task_retry_failed_items"} and bool(task.target_stage_name)
            target_stage_name = task.target_stage_name if (stage_retry_mode or task_retry_mode) else None
            target_stage_index = stage_sequence.index(target_stage_name) if target_stage_name in stage_sequence else start_index
            if stage_retry_mode:
                start_index = min(start_index, target_stage_index)
            archive_blocked = False
            for stage_name in stage_sequence[start_index:]:
                if stage_retry_mode and stage_sequence.index(stage_name) < target_stage_index:
                    continue
                db.refresh(task)
                if task.status == "cancelled":
                    return
                if not self._stage_enabled(task, stage_name):
                    stage_run = self._ensure_stage_run(db, task, stage_name)
                    stage_run.status = "success"
                    stage_run.started_at = stage_run.started_at or _now()
                    stage_run.finished_at = _now()
                    await self._persist_stage_run_output_summary_async(task, stage_run, {"reason": "disabled_by_stage_options"})
                    stage_run.counts = self._stage_counts(db, stage_run)
                    task.stage_summary = {
                        **task.stage_summary,
                        stage_name: {
                            "status": "success",
                            "counts": stage_run.counts,
                            "finished_at": stage_run.finished_at.isoformat(),
                            "reason": "disabled_by_stage_options",
                        },
                    }
                    self._record_event(db, task, "stage_completed", f"阶段未启用，按配置完成: {stage_name}", stage_name=stage_name)
                    observe_stage_duration(stage=stage_name, result="success", duration_seconds=_elapsed_seconds_since(stage_run.started_at))
                    db.commit()
                    continue
                start_event = self._enqueue_state_event(
                    db,
                    task=task,
                    task_id=task.id,
                    project_id=task.project_id,
                    stage_name=stage_name,
                    event_type="stage_worker_start_requested",
                    idempotency_key=(
                        f"stage_worker_start_requested:{task.id}:{stage_name}:"
                        f"{task.dispatch_started_at.isoformat() if task.dispatch_started_at else ''}"
                    ),
                    payload={
                        "stage_name": stage_name,
                        "stage_retry_mode": bool(stage_retry_mode),
                        "task_retry_mode": bool(task_retry_mode),
                        "target_stage_name": target_stage_name,
                    },
                )
                if start_event is not None:
                    self._apply_stage_worker_start_requested_locked(db, start_event)
                handler = getattr(self, f"_stage_{normalize_stage_name(stage_name)}")
                stage_run = self._ensure_stage_run(db, task, stage_name)
                existing_stage_items = self._stage_items(db, task.id, stage_name) if task_retry_mode else []
                db.commit()
                retry_existing = False
                if task.execution_mode in {"stage_retry_failed_items", "task_retry_failed_items"} and stage_name == target_stage_name:
                    retry_existing = True
                elif task_retry_mode and existing_stage_items:
                    retry_existing = True
                status, summary = await handler(db, task, stage_run, token, retry_existing)
                execution_token = task.dispatch_started_at.isoformat() if task.dispatch_started_at else None
                self._emit_stage_terminal_event_safely(
                    db,
                    task=task,
                    stage_name=stage_name,
                    status=status,
                    summary=summary,
                    stage_retry_mode=bool(stage_retry_mode),
                    task_retry_mode=bool(task_retry_mode),
                    target_stage_name=target_stage_name,
                    execution_token=execution_token,
                )
                self._record_event(
                    db,
                    task,
                    "stage_worker_terminal_observed",
                    f"阶段 worker 已完成，等待 reducer 串行收口: {stage_name}",
                    stage_name=stage_name,
                    payload={"status": status},
                )
                try:
                    db.commit()
                except Exception:
                    db.rollback()
                    task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == task_id).first()
                    if task is not None:
                        self._emit_stage_terminal_event_safely(
                            db,
                            task=task,
                            stage_name=stage_name,
                            status=status,
                            summary=summary,
                            stage_retry_mode=bool(stage_retry_mode),
                            task_retry_mode=bool(task_retry_mode),
                            target_stage_name=target_stage_name,
                            execution_token=execution_token,
                        )
                        self._record_missing_stage_terminal_event(
                            db,
                            task,
                            stage_name=stage_name,
                            status=status,
                            reason="worker_commit_retry_after_failure",
                            summary=summary,
                            execution_token=execution_token,
                        )
                        db.commit()
                return
                stage_run.status = "waiting_confirmation" if task.status == TASK_STATUS_PENDING_MODULE_CONFIRMATION else status
                stage_run.finished_at = _now()
                observe_stage_duration(
                    stage=stage_name,
                    result=stage_run.status,
                    duration_seconds=_elapsed_seconds_since(stage_run.started_at),
                )
                await self._persist_stage_run_output_summary_async(task, stage_run, summary)
                stage_run.counts = self._stage_counts(db, stage_run)
                if status in {"failed", "partial_success", "downstream_missing"}:
                    stage_run.last_error = summary.get("error")
                self._merge_task_stage_summary_entry(
                    task,
                    stage_run,
                    {
                        **(
                            {
                                "failure_code": summary.get("failure_code"),
                                "failure_category": summary.get("failure_category"),
                                "failure_message": summary.get("failure_message"),
                            }
                            if summary.get("failure_code")
                            else {}
                        ),
                    },
                )
                task.current_stage = stage_name
                if stage_name == "firmware_unpack":
                    task.metrics = {
                        **task.metrics,
                        "unpacked_firmware_count": int(summary.get("success_count", 0)),
                        "failed_firmware_count": int(summary.get("failed_count", 0)),
                    }
                elif stage_name == "system_analysis":
                    task.metrics = {
                        **task.metrics,
                        "high_risk_module_count": int(summary.get("high_risk_module_count", 0)),
                        "medium_risk_module_count": int(summary.get("medium_risk_module_count", 0)),
                        "low_risk_module_count": int(summary.get("low_risk_module_count", 0)),
                        "candidate_module_count": int(summary.get("candidate_module_count", 0)),
                        "selected_module_count": int(summary.get("selected_module_count", 0)),
                    }
                elif stage_name == "entry_analysis":
                    task.metrics = {**task.metrics, "entry_count": int(summary.get("entry_count", 0))}
                elif normalize_stage_name(stage_name) == "dataflow_vuln_scan":
                    task.metrics = {**task.metrics, "vuln_result_count": int(summary.get("vuln_result_count", 0))}
                db.commit()
                if task.status == TASK_STATUS_PENDING_MODULE_CONFIRMATION:
                    await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
                    db.commit()
                    return
                if summary.get("archive_blocked"):
                    archive_blocked = True
                    task.status = "failed"
                    task.last_error = summary.get("error") or "总任务产物归档失败"
                    task.dispatcher_instance_id = None
                    task.dispatch_started_at = None
                    task.lease_expires_at = None
                    task.finished_at = _now()
                    blocked_item_ids = self._suppress_later_stage_items_after_archive_blocked(
                        db,
                        task,
                        stage_name=stage_name,
                        error_message=task.last_error,
                    )
                    observe_task_error("downstream_error", stage=stage_name, result="archive_blocked")
                    observe_task_lifecycle("finished", status=task.status, task_type=self._task_type(task))
                    observe_task_duration(
                        phase="execution",
                        duration_seconds=_elapsed_seconds_since(task.started_at),
                        status=task.status,
                        task_type=self._task_type(task),
                    )
                    observe_task_duration(
                        phase="total",
                        duration_seconds=_elapsed_seconds_since(task.created_at),
                        status=task.status,
                        task_type=self._task_type(task),
                    )
                    self._record_event(
                        db,
                        task,
                        "stage_archive_blocked",
                        f"阶段业务执行已完成，但总任务产物归档失败，停止后续推进: {stage_name}",
                        level="error",
                        stage_name=stage_name,
                        payload={
                            "stage_status": status,
                            "error": task.last_error,
                            "blocked_item_ids": blocked_item_ids,
                        },
                    )
                    db.commit()
                    break
                if stage_retry_mode and stage_name == target_stage_name:
                    self._record_event(
                        db,
                        task,
                        "stage_retry_finished",
                        f"阶段重试完成: {stage_name}",
                        stage_name=stage_name,
                        payload={"status": status},
                    )
                if status == "failed":
                    task.status = "failed"
                    task.last_error = summary.get("failure_message") or summary.get("error")
                    self._record_event(
                        db,
                        task,
                        "stage_failed",
                        f"阶段失败，停止后续推进: {stage_name}",
                        level="error",
                        stage_name=stage_name,
                        payload={
                            "error": task.last_error,
                            **(
                                {
                                    "failure_code": summary.get("failure_code"),
                                    "failure_category": summary.get("failure_category"),
                                    "failure_message": summary.get("failure_message"),
                                }
                                if summary.get("failure_code")
                                else {}
                            ),
                        },
                    )
                    db.commit()
                    break
            if archive_blocked:
                await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
                db.commit()
                return
            if stage_retry_mode or task_retry_mode:
                self._clear_retry_execution_context(
                    db,
                    task,
                    stage_name=target_stage_name or task.current_stage,
                    payload={
                        "status": task.status,
                        "stage_retry_mode": bool(stage_retry_mode),
                        "task_retry_mode": bool(task_retry_mode),
                    },
                )
            if self._ensure_task_remains_cancelling(db, task) is not None:
                await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
                db.commit()
                return
            next_stage = self._next_incomplete_stage(db, task)
            if task.status in {"running", "dispatching"} and next_stage:
                task.status = "pending"
                task.current_stage = next_stage
                task.dispatcher_instance_id = None
                task.dispatch_started_at = None
                task.lease_expires_at = None
                task.finished_at = None
                task.last_error = None
                self._record_event(
                    db,
                    task,
                    "task_requeued_after_stage_completion",
                    f"阶段完成后任务继续进入下一阶段: {next_stage}",
                    stage_name=next_stage,
                )
                db.commit()
                self._enqueue_task(task.id)
                return
            self._finalize_task(db, task)
            await self._write_task_metadata_async(task, Path(task.workspace_root) / "input" / "task-metadata.json", status=task.status)
            db.commit()
        finally:
            db.close()

    def _load_service_config(self, db: Session) -> BinarySecurityServiceConfigPayload:
        row = db.query(BinarySecurityServiceConfig).filter(BinarySecurityServiceConfig.config_key == "global").first()
        raw = row.config if row else {}
        return BinarySecurityServiceConfigPayload(**raw)

    def _lease_timeout_seconds(self, db: Session | None = None) -> int:
        if db is not None:
            try:
                return max(15, int(self._load_service_config(db).lease_timeout_seconds))
            except Exception:
                pass
        return 90

    def _next_lease_expiry(self, db: Session | None = None, *, now_value: datetime | None = None) -> datetime:
        return (now_value or _now()) + timedelta(seconds=self._lease_timeout_seconds(db))

    def runtime_status(self) -> dict[str, object]:
        loop_details = {
            "task_dispatch": self._loop_runtime_detail("task_dispatch", self._loop_task),
            "operation_dispatch": self._loop_runtime_detail("operation_dispatch", getattr(self, "_operation_loop_task", None)),
            "archive_dispatch": self._loop_runtime_detail("archive_dispatch", self._archive_loop_task),
            "stage_item_dispatch": self._loop_runtime_detail("stage_item_dispatch", self._stage_item_loop_task),
            "downstream_reconcile": self._loop_runtime_detail("downstream_reconcile", self._downstream_reconcile_task),
            "stage_item_sync_reconcile": self._loop_runtime_detail("stage_item_sync_reconcile", self._stage_item_sync_reconcile_task),
            "archive_runtime_reconcile": self._loop_runtime_detail("archive_runtime_reconcile", self._archive_runtime_reconcile_task),
            "state_repair_reconcile": self._loop_runtime_detail("state_repair_reconcile", self._state_repair_reconcile_task),
            "readless_reconcile": self._loop_runtime_detail("readless_reconcile", self._readless_reconcile_task),
            "state_reducer": self._loop_runtime_detail("state_reducer", self._state_reducer_loop_task),
            "reducer_metrics_snapshot": self._loop_runtime_detail("reducer_metrics_snapshot", self._reducer_metrics_snapshot_loop_task),
            "task_heartbeat": self._loop_runtime_detail("task_heartbeat", self._task_heartbeat_loop_task),
        }
        return {
            "running": self._running,
            "loops": {loop_name: bool(detail.get("alive")) for loop_name, detail in loop_details.items() if loop_name != "task_heartbeat"},
            "loop_details": loop_details,
            "workers": {
                "task_workers": len([task for task in self._workers.values() if not task.done()]),
                "operation_workers": len([task for task in self._operation_workers.values() if not task.done()]),
                "stage_item_workers": len([task for task in self._stage_item_workers.values() if not task.done()]),
                "archive_workers": len([task for task in self._archive_workers if not task.done()]),
            },
            "tail_reconcile_active": bool(self._is_reducer_role() and self._runtime_lease_capable()),
        }

    def _runtime_lease_capable(self) -> bool:
        if not self._is_reducer_role():
            return False
        return bool(
            self._state_reducer_loop_task
            and not self._state_reducer_loop_task.done()
            and self._reducer_metrics_snapshot_loop_task
            and not self._reducer_metrics_snapshot_loop_task.done()
        )

    def _lease_is_active(self, task: BinarySecurityTask, db: Session | None = None) -> bool:
        lease: BinarySecurityTaskRuntimeLease | None = None
        if db is not None:
            lease = self._runtime_lease_for_task(db, task.id)
        elif task.lease_expires_at is None:
            session = get_session_factory()()
            try:
                lease = self._runtime_lease_for_task(session, task.id)
            finally:
                session.close()
        if lease is not None:
            return self._runtime_lease_is_active(lease)
        remaining = _seconds_until(task.lease_expires_at)
        return remaining is not None and remaining > 0

    def _lease_filter_available(self):
        return or_(
            BinarySecurityTask.lease_expires_at.is_(None),
            BinarySecurityTask.lease_expires_at < _now(),
        )

    def _task_needs_downstream_reconcile(self, db: Session, task: BinarySecurityTask) -> bool:
        status = str(task.status or "").strip().lower()
        if status == "pending":
            return True
        if status == "failed":
            return self._failed_task_needs_downstream_reconcile(db, task)
        if status not in {"dispatching", "running"}:
            return False
        if self._streaming_mode_enabled(task) and self._is_streaming_tail_stage(task, task.current_stage):
            return False
        if self._task_has_active_streaming_stage_workers(task.id):
            return False
        if self._has_local_task_execution_owner(task.id):
            return self._task_has_stale_active_reconcile_items(db, task)
        if not str(task.dispatcher_instance_id or "").strip():
            return True
        if not self._lease_is_active(task, db=db):
            return True
        lease = self._runtime_lease_for_task(db, task.id)
        heartbeat_at = (lease.heartbeat_at if lease is not None else None) or task.updated_at or task.dispatch_started_at
        elapsed_seconds = _elapsed_seconds_since(heartbeat_at)
        if elapsed_seconds is None:
            return False
        grace_seconds = max(
            int(getattr(self.cfg.scheduler, "downstream_reconcile_grace_seconds", 0) or 0),
            int(getattr(self.cfg.scheduler, "heartbeat_update_interval_seconds", 0) or 15) * 2,
            30,
        )
        return elapsed_seconds >= grace_seconds

    def _failed_task_needs_downstream_reconcile(self, db: Session, task: BinarySecurityTask) -> bool:
        return bool(self._task_reconcile_candidate_items(db, task, include_failed_terminal_items=False))

    def _active_reconcile_stage_name(self, task: BinarySecurityTask) -> str | None:
        if (
            str(task.execution_mode or "").strip() in ACTIVE_RECONCILE_TARGET_STAGE_MODES
            and str(task.target_stage_name or "").strip()
        ):
            return str(task.target_stage_name).strip()
        if str(task.current_stage or "").strip():
            return str(task.current_stage).strip()
        return None

    def _stage_item_in_active_reconcile_scope(
        self,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
    ) -> bool:
        active_stage_name = self._active_reconcile_stage_name(task)
        if not active_stage_name or str(item.stage_name or "").strip() != active_stage_name:
            return False
        if not str(item.downstream_service or "").strip():
            return False
        if self._item_needs_downstream_binding_reconcile(item):
            return True
        if not str(item.downstream_task_id or "").strip():
            return False
        return self._item_needs_downstream_sync(item, for_task_status=str(task.status or "").strip().lower() or None)

    def _task_has_active_reconcile_items(self, db: Session, task: BinarySecurityTask) -> bool:
        active_stage_name = self._active_reconcile_stage_name(task)
        if not active_stage_name:
            return False
        return any(
            self._stage_item_in_active_reconcile_scope(task, item)
            for item in self._stage_items(db, task.id, active_stage_name)
        )

    def _task_has_stale_active_reconcile_items(self, db: Session, task: BinarySecurityTask) -> bool:
        active_stage_name = self._active_reconcile_stage_name(task)
        if not active_stage_name:
            return False
        return any(
            self._stage_item_in_active_reconcile_scope(task, item)
            and self._item_downstream_sync_stale(item)
            for item in self._stage_items(db, task.id, active_stage_name)
        )

    def _task_stage_items_with_downstream_refs(
        self,
        db: Session,
        task: BinarySecurityTask,
        *,
        stage_name: str | None = None,
    ) -> list[BinarySecurityStageItem]:
        query = db.query(BinarySecurityStageItem).filter(
            BinarySecurityStageItem.task_id == task.id,
            BinarySecurityStageItem.downstream_service.isnot(None),
            BinarySecurityStageItem.downstream_task_id.isnot(None),
        )
        if stage_name:
            query = query.filter(BinarySecurityStageItem.stage_name == stage_name)
        return query.order_by(
            BinarySecurityStageItem.updated_at.asc(),
            BinarySecurityStageItem.created_at.asc(),
            BinarySecurityStageItem.id.asc(),
        ).all()

    def _item_missing_recorded_downstream_status(self, item: BinarySecurityStageItem) -> bool:
        result = self._load_stage_item_result_payload(item)
        if self._string_or_none(result.get("downstream_status")):
            return False
        downstream_payload = dict(result.get("downstream") or {})
        return not self._string_or_none(downstream_payload.get("status"))

    def _task_reconcile_candidate_items(
        self,
        db: Session,
        task: BinarySecurityTask,
        *,
        stage_name: str | None = None,
        item_id: str | None = None,
        force: bool = False,
        include_failed_terminal_items: bool = True,
    ) -> list[BinarySecurityStageItem]:
        query = db.query(BinarySecurityStageItem).filter(
            BinarySecurityStageItem.task_id == task.id,
            BinarySecurityStageItem.downstream_service.isnot(None),
        )
        if stage_name:
            query = query.filter(BinarySecurityStageItem.stage_name == stage_name)
        items = query.order_by(
            BinarySecurityStageItem.updated_at.asc(),
            BinarySecurityStageItem.created_at.asc(),
            BinarySecurityStageItem.id.asc(),
        ).all()
        if item_id:
            items = [item for item in items if str(item.id or "").strip() == str(item_id or "").strip()]
        if force:
            return items
        candidates: list[BinarySecurityStageItem] = []
        task_status = str(task.status or "").strip().lower() or None
        for item in items:
            item_status = self._normalize_downstream_status(item.status) or str(item.status or "").strip().lower()
            if (
                not include_failed_terminal_items
                and task_status == "failed"
                and item_status in {"failed", "cancelled", "downstream_missing", "partial_success", "success"}
                and not self._item_missing_recorded_downstream_status(item)
            ):
                continue
            if (
                normalize_stage_name(item.stage_name) == "dataflow_vuln_scan"
                and not str(item.downstream_task_id or "").strip()
                and self._item_needs_downstream_binding_reconcile(item)
            ):
                candidates.append(item)
                continue
            if self._item_needs_downstream_sync(
                item,
                for_task_status=task_status,
            ):
                candidates.append(item)
                continue
            if self._item_missing_recorded_downstream_status(item):
                candidates.append(item)
        return candidates

    def _task_sync_cooldown_elapsed_for_items(
        self,
        task: BinarySecurityTask,
        items: list[BinarySecurityStageItem],
    ) -> bool:
        del task
        interval_seconds = max(
            5,
            int(getattr(self.cfg.scheduler, "downstream_reconcile_interval_seconds", 30) or 30),
        )
        latest_synced_at: datetime | None = None
        for item in items:
            sync_status = self._stage_item_sync_status_value(item)
            if sync_status in {None, "", "pending", "transport_error"}:
                return True
            if self._stage_item_sync_in_retry_backoff(item):
                continue
            if self._item_missing_recorded_downstream_status(item):
                return True
            parsed = self._stage_item_sync_attempt_at_value(item)
            if parsed is None:
                return True
            if latest_synced_at is None or parsed > latest_synced_at:
                latest_synced_at = parsed
        if latest_synced_at is None:
            return True
        return (_now() - latest_synced_at).total_seconds() >= interval_seconds

    def _stage_item_sync_priority(self, item: BinarySecurityStageItem, now_value: datetime | None = None) -> tuple[int, datetime, str]:
        item_status = str(item.status or "").strip().lower()
        sync_status = self._stage_item_sync_status_value(item)
        last_synced_at = self._stage_item_last_synced_at_value(item) or datetime.min
        stale = self._item_downstream_sync_stale(item, now_value)
        missing_recorded_downstream_status = self._item_missing_recorded_downstream_status(item)
        if sync_status == "transport_error":
            priority = 0
        elif item_status in {"running", "dispatching", "queued", "pending"} and sync_status in {None, "", "pending"}:
            priority = 1
        elif item_status in {"running", "dispatching", "queued", "pending"} and stale:
            priority = 2
        elif item_status in {"success", "cancelled", "downstream_missing", "partial_success", "failed"} and (
            sync_status in {None, "", "pending"} or missing_recorded_downstream_status
        ):
            priority = 3
        elif missing_recorded_downstream_status:
            priority = 4
        else:
            priority = 9
        return priority, last_synced_at, str(item.id or "")

    def _stage_item_sync_status_value(self, item: BinarySecurityStageItem) -> str | None:
        result = self._load_stage_item_result_payload(item)
        sync_status = result.get("sync_status")
        if sync_status is None:
            sync_status = dict(result.get("sync_observation") or {}).get("sync_status")
        value = str(sync_status or "").strip().lower()
        return value or None

    def _stage_item_sync_observation(self, item: BinarySecurityStageItem) -> dict[str, Any]:
        result = self._load_stage_item_result_payload(item)
        observation = result.get("sync_observation") or {}
        return dict(observation) if isinstance(observation, dict) else {}

    def _stage_item_sync_attempt_at_value(self, item: BinarySecurityStageItem) -> datetime | None:
        result = self._load_stage_item_result_payload(item)
        sync_observation = self._stage_item_sync_observation(item)
        raw = (
            sync_observation.get("last_attempt_at")
            or result.get("last_sync_attempt_at")
            or sync_observation.get("last_synced_at")
            or result.get("downstream_status_synced_at")
        )
        if not isinstance(raw, str) or not raw.strip():
            return None
        try:
            return datetime.fromisoformat(raw)
        except ValueError:
            return None

    def _stage_item_sync_error_at_value(self, item: BinarySecurityStageItem) -> datetime | None:
        result = self._load_stage_item_result_payload(item)
        sync_observation = self._stage_item_sync_observation(item)
        raw = sync_observation.get("last_error_at") or result.get("last_sync_error_at")
        if not isinstance(raw, str) or not raw.strip():
            return None
        try:
            return datetime.fromisoformat(raw)
        except ValueError:
            return None

    def _stage_item_sync_consecutive_error_count(self, item: BinarySecurityStageItem) -> int:
        result = self._load_stage_item_result_payload(item)
        sync_observation = self._stage_item_sync_observation(item)
        raw = sync_observation.get("consecutive_error_count")
        if raw is None:
            raw = result.get("consecutive_sync_error_count")
        try:
            return max(0, int(raw or 0))
        except Exception:
            return 0

    def _stage_item_sync_error_budget_exhausted(self, item: BinarySecurityStageItem) -> bool:
        result = self._load_stage_item_result_payload(item)
        sync_observation = self._stage_item_sync_observation(item)
        raw = sync_observation.get("budget_exhausted")
        if raw is None:
            raw = result.get("sync_error_budget_exhausted")
        return bool(raw)

    def _stage_item_sync_error_type_value(self, item: BinarySecurityStageItem) -> str | None:
        result = self._load_stage_item_result_payload(item)
        sync_observation = self._stage_item_sync_observation(item)
        return self._string_or_none(sync_observation.get("error_type")) or self._string_or_none(result.get("last_sync_error_type"))

    def _stage_item_sync_error_message_value(self, item: BinarySecurityStageItem) -> str | None:
        result = self._load_stage_item_result_payload(item)
        sync_observation = self._stage_item_sync_observation(item)
        return self._string_or_none(sync_observation.get("error_message")) or self._string_or_none(result.get("last_sync_error_message"))

    def _stage_item_next_sync_retry_at_value(self, item: BinarySecurityStageItem) -> datetime | None:
        result = self._load_stage_item_result_payload(item)
        sync_observation = self._stage_item_sync_observation(item)
        raw = sync_observation.get("next_retry_at") or result.get("next_sync_retry_at")
        if not isinstance(raw, str) or not raw.strip():
            return None
        try:
            return datetime.fromisoformat(raw)
        except ValueError:
            return None

    def _stage_item_sync_in_retry_backoff(self, item: BinarySecurityStageItem, now_value: datetime | None = None) -> bool:
        next_retry_at = self._stage_item_next_sync_retry_at_value(item)
        if next_retry_at is None:
            return False
        return next_retry_at > (now_value or _now())

    def _stage_item_orchestration_observation(self, item: BinarySecurityStageItem) -> dict[str, Any]:
        result = self._load_stage_item_result_payload(item)
        observation = result.get("orchestration_observation") or {}
        return dict(observation) if isinstance(observation, dict) else {}

    def _stage_item_orchestration_attempt_at_value(self, item: BinarySecurityStageItem) -> datetime | None:
        result = self._load_stage_item_result_payload(item)
        observation = self._stage_item_orchestration_observation(item)
        raw = observation.get("last_attempt_at") or result.get("last_orchestration_attempt_at")
        if not isinstance(raw, str) or not raw.strip():
            return None
        try:
            return datetime.fromisoformat(raw)
        except ValueError:
            return None

    def _stage_item_next_orchestration_retry_at_value(self, item: BinarySecurityStageItem) -> datetime | None:
        result = self._load_stage_item_result_payload(item)
        observation = self._stage_item_orchestration_observation(item)
        raw = observation.get("next_retry_at") or result.get("next_orchestration_retry_at")
        if not isinstance(raw, str) or not raw.strip():
            return None
        try:
            return datetime.fromisoformat(raw)
        except ValueError:
            return None

    def _stage_item_orchestration_in_retry_backoff(self, item: BinarySecurityStageItem, now_value: datetime | None = None) -> bool:
        next_retry_at = self._stage_item_next_orchestration_retry_at_value(item)
        if next_retry_at is None:
            return False
        return next_retry_at > (now_value or _now())

    def _stage_item_orchestration_error_budget_exhausted(self, item: BinarySecurityStageItem) -> bool:
        result = self._load_stage_item_result_payload(item)
        observation = self._stage_item_orchestration_observation(item)
        raw = observation.get("budget_exhausted")
        if raw is None:
            raw = result.get("orchestration_error_budget_exhausted")
        return bool(raw)

    def _stage_item_orchestration_consecutive_error_count(self, item: BinarySecurityStageItem) -> int:
        result = self._load_stage_item_result_payload(item)
        observation = self._stage_item_orchestration_observation(item)
        raw = observation.get("consecutive_error_count")
        if raw is None:
            raw = result.get("consecutive_orchestration_error_count")
        try:
            return max(0, int(raw or 0))
        except Exception:
            return 0

    def _next_stage_orchestration_retry_backoff_seconds(self, consecutive_error_count: int) -> int:
        exponent = max(0, int(consecutive_error_count) - 1)
        backoff = self._stage_orchestration_backoff_base_seconds() * (2 ** exponent)
        return min(self._stage_orchestration_backoff_max_seconds(), max(1, int(backoff)))

    def _read_stage_item_orchestration_state(self, item: BinarySecurityStageItem) -> OrchestrationSupervisorState:
        result = self._load_stage_item_result_payload(item)
        observation = self._stage_item_orchestration_observation(item)
        consecutive = observation.get("consecutive_error_count")
        if consecutive is None:
            consecutive = result.get("consecutive_orchestration_error_count")
        exhausted = observation.get("budget_exhausted")
        if exhausted is None:
            exhausted = result.get("orchestration_error_budget_exhausted")
        last_result = self._string_or_none(observation.get("last_result")) or self._string_or_none(result.get("last_orchestration_result"))
        return OrchestrationSupervisorState(
            consecutive_error_count=max(0, int(consecutive or 0)),
            budget_exhausted=bool(exhausted),
            next_retry_at=self._stage_item_next_orchestration_retry_at_value(item),
            last_result=last_result,
        )

    def _build_next_stage_item_orchestration_failure_state(
        self,
        item: BinarySecurityStageItem,
        *,
        observed_at: datetime | None = None,
    ) -> OrchestrationSupervisorState:
        previous = self._read_stage_item_orchestration_state(item)
        consecutive = previous.consecutive_error_count + 1
        budget_exhausted = consecutive >= self._stage_orchestration_max_consecutive_errors()
        retry_at = (observed_at or _now()) + timedelta(seconds=self._next_stage_orchestration_retry_backoff_seconds(consecutive))
        return OrchestrationSupervisorState(
            consecutive_error_count=consecutive,
            budget_exhausted=budget_exhausted,
            next_retry_at=retry_at,
            last_result="error",
        )

    def _mark_stage_item_orchestration_observation(
        self,
        item: BinarySecurityStageItem,
        *,
        source: str,
        observed_at: datetime | None = None,
        error_message: str | None = None,
        error_type: str | None = None,
        last_result: str | None = None,
        consecutive_error_count: int | None = None,
        budget_exhausted: bool | None = None,
        next_retry_at: datetime | None = None,
    ) -> None:
        # Keep runtime observation updates lightweight in DB. If the stage item
        # already externalized its full result, preserve only the compact row
        # envelope plus result_path instead of writing the full payload back.
        result = dict(item.result or {})
        observation = dict(result.get("orchestration_observation") or {})
        now_value = observed_at or _now()
        observed_at_iso = now_value.isoformat()
        if last_result is None:
            last_result = "error" if error_message or error_type else "success"
        observation.update(
            {
                "source": source,
                "last_attempt_at": observed_at_iso,
                "last_result": last_result,
                "error_message": error_message,
                "error_type": error_type,
            }
        )
        if consecutive_error_count is not None:
            observation["consecutive_error_count"] = max(0, int(consecutive_error_count))
        if budget_exhausted is not None:
            observation["budget_exhausted"] = bool(budget_exhausted)
        if next_retry_at is not None:
            observation["next_retry_at"] = next_retry_at.isoformat()
        elif last_result == "success":
            observation["next_retry_at"] = None
        if last_result == "success":
            observation["last_success_at"] = observed_at_iso
            observation["last_error_at"] = None
            observation["error_message"] = None
            observation["error_type"] = None
            observation["consecutive_error_count"] = 0
            observation["budget_exhausted"] = False
            observation["next_retry_at"] = None
        else:
            observation["last_error_at"] = observed_at_iso
        result.update(
            {
                "orchestration_observation": observation,
                "last_orchestration_attempt_at": observed_at_iso,
                "last_orchestration_success_at": observation.get("last_success_at"),
                "last_orchestration_error_at": observation.get("last_error_at"),
                "last_orchestration_error_type": observation.get("error_type"),
                "last_orchestration_error_message": observation.get("error_message"),
                "consecutive_orchestration_error_count": observation.get("consecutive_error_count"),
                "orchestration_error_budget_exhausted": observation.get("budget_exhausted"),
                "next_orchestration_retry_at": observation.get("next_retry_at"),
                "last_orchestration_result": observation.get("last_result"),
            }
        )
        item.result = result

    def _stage_item_last_synced_at_value(self, item: BinarySecurityStageItem) -> datetime | None:
        result = self._load_stage_item_result_payload(item)
        raw = result.get("downstream_status_synced_at")
        if not isinstance(raw, str) or not raw.strip():
            raw = dict(result.get("sync_observation") or {}).get("last_synced_at")
        if not isinstance(raw, str) or not raw.strip():
            return None
        try:
            return datetime.fromisoformat(raw)
        except ValueError:
            return None

    def _item_downstream_sync_stale(self, item: BinarySecurityStageItem, now_value: datetime | None = None) -> bool:
        item_status = str(item.status or "").strip().lower()
        if item_status not in {"pending", "queued", "running", "dispatching"}:
            return False
        current_now = now_value or _now()
        last_attempt_at = self._stage_item_sync_attempt_at_value(item)
        if last_attempt_at is None:
            return True
        return (current_now - last_attempt_at).total_seconds() >= self._stage_item_sync_stale_seconds()

    def _item_needs_initial_downstream_sync(self, item: BinarySecurityStageItem) -> bool:
        sync_status = self._stage_item_sync_status_value(item)
        if sync_status in {None, "", "pending", "transport_error"}:
            return True
        return self._stage_item_sync_attempt_at_value(item) is None

    def _item_needs_downstream_sync(
        self,
        item: BinarySecurityStageItem,
        *,
        for_task_status: str | None = None,
        now_value: datetime | None = None,
    ) -> bool:
        if not str(item.downstream_service or "").strip() or not str(item.downstream_task_id or "").strip():
            return False
        if self._stage_item_sync_in_retry_backoff(item, now_value):
            return False
        item_status = str(item.status or "").strip().lower()
        if item_status in {"pending", "queued", "running", "dispatching"}:
            return self._item_needs_initial_downstream_sync(item) or self._item_downstream_sync_stale(item, now_value)
        if item_status == "failed":
            return (for_task_status or "") in {"dispatching", "running", "failed"} or self._item_needs_initial_downstream_sync(item)
        if item_status in {"success", "cancelled", "downstream_missing", "partial_success"}:
            return self._item_needs_initial_downstream_sync(item)
        return False

    def _downstream_binding_ready_for_retry(self, item: BinarySecurityStageItem, now_value: datetime | None = None) -> bool:
        current_now = now_value or _now()
        next_retry_at = self._downstream_binding_time(item, "next_retry_at")
        if next_retry_at is None:
            return True
        return next_retry_at <= current_now

    def _downstream_binding_retry_window_exhausted(self, item: BinarySecurityStageItem, now_value: datetime | None = None) -> bool:
        current_now = now_value or _now()
        attempts = self._downstream_binding_attempts(item)
        if attempts >= DOWNSTREAM_CREATE_RETRY_MAX_ATTEMPTS:
            return True
        first_attempt_at = self._downstream_binding_time(item, "first_attempt_at")
        if first_attempt_at is None:
            return False
        return (current_now - first_attempt_at).total_seconds() >= DOWNSTREAM_CREATE_RETRY_MAX_WINDOW_SECONDS

    def _mark_downstream_binding_creating(
        self,
        item: BinarySecurityStageItem,
        *,
        message: str | None = None,
    ) -> None:
        current_now = _now()
        first_attempt_at = self._downstream_binding_time(item, "first_attempt_at") or current_now
        attempts = max(1, self._downstream_binding_attempts(item))
        self._set_downstream_binding_snapshot(
            item,
            state="creating",
            attempts=attempts,
            first_attempt_at=first_attempt_at,
            last_attempt_at=current_now,
            next_retry_at=None,
            last_error=None,
            last_error_type=None,
            recoverable=True,
            message=message or "下游任务创建中",
        )

    def _mark_downstream_binding_created(
        self,
        item: BinarySecurityStageItem,
        *,
        message: str | None = None,
    ) -> None:
        self._set_downstream_binding_snapshot(
            item,
            state="created_pending_sync",
            next_retry_at=None,
            last_error=None,
            last_error_type=None,
            recoverable=None,
            message=message or "下游任务已创建，状态待同步",
        )

    def _mark_downstream_binding_retry(
        self,
        item: BinarySecurityStageItem,
        *,
        error_message: str,
        error_type: str | None,
        recoverable: bool,
    ) -> None:
        current_now = _now()
        previous_attempts = self._downstream_binding_attempts(item)
        attempts = previous_attempts + 1
        next_retry_at = None if not recoverable else current_now + timedelta(seconds=self._downstream_binding_retry_after(attempts))
        state = "create_retrying" if recoverable and not self._downstream_binding_retry_window_exhausted(item, now_value=current_now) and attempts < DOWNSTREAM_CREATE_RETRY_MAX_ATTEMPTS else "create_failed"
        if state == "create_failed":
            next_retry_at = None
        self._set_downstream_binding_snapshot(
            item,
            state=state,
            attempts=attempts,
            first_attempt_at=self._downstream_binding_time(item, "first_attempt_at") or current_now,
            last_attempt_at=current_now,
            next_retry_at=next_retry_at,
            last_error=error_message,
            last_error_type=error_type,
            recoverable=recoverable,
            message=(
                "下游任务创建重试中" if state == "create_retrying"
                else "下游任务创建失败"
            ),
        )

    def _downstream_binding_status_message(self, item: BinarySecurityStageItem) -> str | None:
        state = self._downstream_binding_state(item)
        if state == "creating":
            return "创建中，尚未拿到下游任务ID"
        if state == "create_retrying":
            return "正在自动重试创建，成功后可跳转"
        if state == "create_failed":
            return "创建失败，当前无下游任务可查看"
        if state == "created_pending_sync":
            return "下游已创建，状态待同步"
        return None

    async def _attempt_vuln_downstream_binding_recovery(
        self,
        db: Session,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        *,
        token: str | None,
        force: bool = False,
    ) -> tuple[bool, str]:
        if normalize_stage_name(item.stage_name) != "dataflow_vuln_scan" or str(item.downstream_service or "").strip() != "dataflow_vuln_scan":
            return False, "not_vuln_scan"
        if str(item.downstream_task_id or "").strip():
            return False, "already_bound"
        if not force and not self._downstream_binding_ready_for_retry(item):
            return False, "retry_not_due"

        reusable = await self._find_reusable_vuln_payload(task, item, token)
        if reusable is not None:
            item.downstream_task_id = reusable.get("task_id") or reusable.get("id") or item.downstream_task_id
            mapped = self._map_downstream_status(str(reusable.get("status") or "")) or "pending"
            if mapped in {"pending", "queued", "dispatching", "running"}:
                item.status = mapped
                item.finished_at = None
            self._mark_downstream_binding_created(item, message="下游任务已恢复绑定，状态待同步")
            self._record_downstream_item_disposition(
                db,
                task,
                item,
                event_type="downstream_child_recovered",
                message=f"已恢复下游子任务绑定: {item.downstream_service}:{item.downstream_task_id or '-'}",
                payload={
                    "downstream_service": item.downstream_service,
                    "downstream_task_id": item.downstream_task_id,
                    "binding_state": self._downstream_binding_state(item),
                    "status_raw": reusable.get("status"),
                },
            )
            db.commit()
            return True, "recovered"

        if self._downstream_binding_retry_window_exhausted(item):
            self._set_downstream_binding_snapshot(
                item,
                state="create_failed",
                next_retry_at=None,
                recoverable=False,
                message="下游任务创建失败",
            )
            self._record_downstream_item_disposition(
                db,
                task,
                item,
                event_type="downstream_create_failed_final",
                message="下游任务创建重试窗口已耗尽",
                level="warning",
                payload={
                    "attempts": self._downstream_binding_attempts(item),
                    "binding_state": "create_failed",
                },
            )
            db.commit()
            return False, "failed_final"

        dataflow_result = self._validate_dataflow_output_contract(dict(item.input_ref or {}))
        dataflow_input_dir = self._resolve_vuln_scan_dataflow_input_dir(dataflow_result)
        source_dir = str(dataflow_result.get("source_root_path") or dataflow_result.get("source_dir") or "").strip()
        if not dataflow_input_dir or not source_dir:
            self._mark_downstream_binding_retry(
                item,
                error_message="数据流漏洞挖掘输入缺失，无法创建下游任务",
                error_type="invalid_input",
                recoverable=False,
            )
            db.commit()
            return False, "invalid_input"

        self._mark_downstream_binding_creating(item)
        db.commit()
        try:
            created = await self._downstream_create_task(
                db,
                task,
                item,
                service="dataflow_vuln_scan",
                token=token,
                payload={
                    "title": f"{task.name}-{dataflow_result['function_name']}-scan",
                    "data_flow_path": dataflow_input_dir,
                    "source_dir": source_dir,
                    "origin": _downstream_origin_payload(task, item),
                },
                event_payload={"binding_recovery": True},
            )
        except Exception as exc:
            recoverable = self._is_retryable_downstream_transport_error(exc)
            self._mark_downstream_binding_retry(
                item,
                error_message=self._extract_downstream_error_text(exc) or str(exc),
                error_type=self._classify_downstream_sync_error(exc),
                recoverable=recoverable,
            )
            self._record_downstream_item_disposition(
                db,
                task,
                item,
                event_type="downstream_create_retry_scheduled" if recoverable and self._downstream_binding_state(item) == "create_retrying" else "downstream_create_failed_final",
                message="下游任务创建重试已排队" if recoverable and self._downstream_binding_state(item) == "create_retrying" else "下游任务创建失败",
                level="warning",
                payload={
                    "binding_state": self._downstream_binding_state(item),
                    "attempts": self._downstream_binding_attempts(item),
                    "next_retry_at": _isoformat_or_none(self._downstream_binding_time(item, "next_retry_at")),
                    "error": self._extract_downstream_error_text(exc) or str(exc),
                    "error_type": self._classify_downstream_sync_error(exc),
                },
            )
            db.commit()
            return False, "create_failed"

        old_downstream_task_id = await self._replace_active_child_binding(
            db,
            task,
            item,
            new_downstream_task_id=created.get("task_id") or created.get("id"),
            token=token,
            reason="binding_recovery_create",
        )
        item.status = self._map_downstream_status(str(created.get("status") or "")) or "pending"
        item.started_at = item.started_at or _now()
        item.finished_at = None
        item.error_message = None
        self._mark_downstream_binding_created(item)
        self._record_downstream_item_disposition(
            db,
            task,
            item,
            event_type="downstream_create_retry_attempted",
            message="已重新创建下游任务并完成绑定",
            payload={
                "binding_state": self._downstream_binding_state(item),
                "downstream_task_id": item.downstream_task_id,
                "attempts": self._downstream_binding_attempts(item),
                "old_downstream_task_id": old_downstream_task_id,
            },
        )
        db.commit()
        return True, "created"

    def _extract_http_status_from_exception(self, exc: Exception) -> int | None:
        message = str(exc or "")
        if not message:
            return None
        leading = re.match(r"^\s*(?:http\s+)?(\d{3})\b", message, re.IGNORECASE)
        if leading:
            try:
                return int(leading.group(1))
            except Exception:
                return None
        match = re.search(r"(?:状态码|status(?:_code)?)[:= ]+(\d{3})", message, re.IGNORECASE)
        if match:
            try:
                return int(match.group(1))
            except Exception:
                return None
        return None

    def _is_http_429_exception(self, exc: Exception) -> bool:
        return self._extract_http_status_from_exception(exc) == 429

    def _classify_downstream_sync_error(self, exc: Exception) -> str:
        if isinstance(exc, SATimeoutError):
            return "db_connection_lost"
        if isinstance(exc, OperationalError):
            lowered_operational = str(exc or "").strip().lower()
            if "connection refused" in lowered_operational or "[errno 111]" in lowered_operational:
                return "db_connection_refused"
            if any(token in lowered_operational for token in {"lost connection", "server has gone away", "closed the connection"}):
                return "db_connection_lost"
            return "db_session_invalid"
        http_status = self._extract_http_status_from_exception(exc)
        lowered = str(exc or "").strip().lower()
        detail = str(getattr(exc, "error_type_detail", "") or getattr(exc, "transport_error_kind", "")).strip().lower()
        if detail == "connection_reused_stale":
            return "connection_reused_stale"
        if http_status == 429:
            return "http_429_rate_limited"
        if http_status is not None and http_status >= 500:
            return "http_5xx"
        if "timeout" in lowered or "超时" in lowered:
            return "timeout"
        if "server disconnected without sending a response" in lowered:
            return "connection_reused_stale"
        if any(token in lowered for token in {"connect", "connection", "连接", "refused"}):
            return "connection_error"
        if any(token in lowered for token in {"auth", "unauthorized", "forbidden", "认证"}):
            return "auth_error"
        if isinstance(exc, (TypeError, ValueError, KeyError, AssertionError)):
            return "downstream_payload_invalid"
        return exc.__class__.__name__

    def _classify_orchestration_error(self, exc: Exception) -> str:
        sync_error = self._classify_downstream_sync_error(exc)
        if sync_error in {
            "db_connection_refused",
            "db_connection_lost",
            "db_session_invalid",
            "downstream_http_timeout",
            "downstream_http_error",
            "downstream_payload_invalid",
        }:
            return sync_error
        lowered = str(exc or "").strip().lower()
        if isinstance(exc, FileNotFoundError):
            return "workspace_transient_missing"
        if isinstance(exc, OSError):
            return "archive_copy_io_error"
        if any(token in lowered for token in {"metadata", "task-metadata.json"}):
            return "task_metadata_write_failed"
        if any(token in lowered for token in {"state event", "state reducer"}):
            return "state_event_persist_failed"
        if self._is_retryable_lock_error(exc):
            return "retryable_lock_conflict"
        return sync_error

    def _is_recoverable_orchestration_error(self, exc: Exception) -> bool:
        if isinstance(exc, (OperationalError, SATimeoutError, UpstreamError, httpx.RequestError, FileNotFoundError, OSError)):
            return True
        return self._classify_orchestration_error(exc) in {
            "db_connection_refused",
            "db_connection_lost",
            "db_session_invalid",
            "retryable_lock_conflict",
            "downstream_http_timeout",
            "downstream_http_error",
            "downstream_payload_invalid",
            "task_metadata_write_failed",
            "state_event_persist_failed",
            "archive_copy_io_error",
            "archive_apply_io_error",
            "workspace_transient_missing",
            "fileserver_transient_error",
            "connection_error",
            "timeout",
            "http_5xx",
        }

    def _is_retryable_downstream_transport_error(self, exc: Exception) -> bool:
        if self._is_http_429_exception(exc):
            return True
        if isinstance(exc, UpstreamError):
            return True
        if isinstance(exc, (NotFoundError, ValidationError, ConflictError)):
            return False
        if isinstance(exc, httpx.RequestError):
            return True
        return self._classify_downstream_sync_error(exc) in {"timeout", "connection_error", "http_5xx", "http_429_rate_limited"}

    def _active_dispatch_count(self, db: Session) -> int:
        now_value = _now()
        return int(
            db.query(func.count(BinarySecurityTask.id))
            .filter(BinarySecurityTask.status.in_(["dispatching", "running"]))
            .filter(
                or_(
                    BinarySecurityTask.lease_expires_at.is_(None),
                    BinarySecurityTask.lease_expires_at > now_value,
                )
            )
            .scalar()
            or 0
        )

    def _claim_pending_tasks(self, db: Session, slots: int) -> list[str]:
        if slots <= 0:
            return []
        phase_repaired = False
        pending_rows = (
            db.query(BinarySecurityTask)
            .filter(
                BinarySecurityTask.status == "pending",
                BinarySecurityTask.runtime_phase == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION,
            )
            .order_by(BinarySecurityTask.created_at.asc(), BinarySecurityTask.id.asc())
            .limit(max(slots * 4, 16))
            .all()
        )
        for task in pending_rows:
            if not self._tail_requires_execution_takeover(db, task):
                continue
            self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
            task.tail_reconcile_state = "idle"
            task.dispatcher_instance_id = None
            task.dispatch_started_at = None
            task.lease_expires_at = None
            self._release_tail_reconcile_owner(task.id)
            phase_repaired = True
        if phase_repaired:
            db.flush()
        lease_expires_at = self._next_lease_expiry(db)
        candidate_rows = (
            db.query(BinarySecurityTask)
            .filter(
                BinarySecurityTask.status == "pending",
                self._lease_filter_available(),
            )
            .order_by(BinarySecurityTask.created_at.asc(), BinarySecurityTask.id.asc())
            .limit(slots)
            .all()
        )
        candidates: list[str] = []
        for task in candidate_rows:
            if self._task_runtime_phase(task) == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION and not self._is_reducer_role():
                continue
            candidates.append(str(task.id))
        claimed: list[str] = []
        dispatch_started_at = _now()
        for task_id in candidates:
            updated = (
                db.query(BinarySecurityTask)
                .filter(
                    BinarySecurityTask.id == task_id,
                    BinarySecurityTask.status == "pending",
                    self._lease_filter_available(),
                )
                .update(
                    {
                        BinarySecurityTask.status: "dispatching",
                        BinarySecurityTask.dispatcher_instance_id: self.instance_id,
                        BinarySecurityTask.dispatch_started_at: dispatch_started_at,
                        BinarySecurityTask.lease_expires_at: lease_expires_at,
                        BinarySecurityTask.updated_at: dispatch_started_at,
                    },
                    synchronize_session=False,
                )
            )
            if updated:
                claimed.append(task_id)
        if claimed:
            db.flush()
        return claimed

    def _reclaim_stale_dispatching_locked(self, db: Session) -> bool:
        service_config = self._load_service_config(db)
        stale_rows = (
            db.query(BinarySecurityTask)
            .filter(
                BinarySecurityTask.status == "dispatching",
                BinarySecurityTask.dispatch_started_at.isnot(None),
                BinarySecurityTask.lease_expires_at.isnot(None),
            )
            .all()
        )
        if not stale_rows:
            return False
        local_workers = {
            task_id for task_id, worker in self._workers.items()
            if not worker.done()
        }
        reclaimed = False
        for task in stale_rows:
            if self._task_has_active_cancel_operation(db, task) or str(task.status or "").strip() == TASK_STATUS_CANCELLING:
                continue
            if task.id in local_workers and str(task.dispatcher_instance_id or "").strip() == self.instance_id:
                continue
            if not self._can_preserve_dispatching_state(db, task):
                authoritative_failure_ctx = self._current_stage_authoritative_failure_context(db, task)
                if authoritative_failure_ctx is not None:
                    self._finalize_task_after_authoritative_failure(
                        db,
                        task,
                        failure_ctx=authoritative_failure_ctx,
                        previous_status="dispatching",
                    )
                else:
                    task.status = "pending"
                    task.dispatcher_instance_id = None
                    task.dispatch_started_at = None
                    task.lease_expires_at = None
                reclaimed = True
                continue
            lease, runtime_lease_owner, runtime_lease_expires_at = self._runtime_lease_context(db, task)
            if self._runtime_lease_is_active(lease):
                if (
                    self._task_runtime_phase(task) == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION
                    and str(lease.owner_instance_id or "").strip() == str(self.instance_id or "").strip()
                    and self._has_tail_reconcile_owner(task.id)
                ):
                    observe_tail_reconcile_requeue_blocked("active_local_tail_lease")
                    continue
                continue
            active_stage_name, active_item_count, has_downstream_refs = self._streaming_tail_active_context(db, task)
            if active_item_count > 0:
                continue
            lease_remaining = _seconds_until(task.lease_expires_at)
            if lease_remaining is None:
                elapsed_seconds = _elapsed_seconds_since(task.dispatch_started_at)
                if elapsed_seconds is None or elapsed_seconds < service_config.dispatch_timeout_seconds:
                    continue
            elif lease_remaining > 0:
                continue
            dispatcher_instance_id = str(task.dispatcher_instance_id or "").strip() or None
            dispatch_started_at = task.dispatch_started_at
            task_lease_expires_at = task.lease_expires_at
            task.status = "pending"
            task.dispatcher_instance_id = None
            task.dispatch_started_at = None
            task.lease_expires_at = None
            task.last_error = None
            observe_dispatch_reclaim("dispatch_timeout")
            self._record_event(
                db,
                task,
                "dispatch_reclaimed",
                "调度超时，任务已回收并重新进入队列",
                level="warning",
                stage_name=task.current_stage,
                payload={
                    "dispatcher_instance_id": dispatcher_instance_id,
                    "dispatch_started_at": _isoformat_or_none(dispatch_started_at),
                    "task_lease_expires_at": _isoformat_or_none(task_lease_expires_at),
                    "runtime_lease_owner": runtime_lease_owner,
                    "runtime_lease_expires_at": _isoformat_or_none(runtime_lease_expires_at),
                    "active_stage_name": active_stage_name or task.current_stage,
                    "active_item_count": active_item_count,
                    "reclaim_reason": "dispatch_timeout",
                    "has_downstream_refs": has_downstream_refs,
                },
            )
            if has_downstream_refs:
                self._record_event(
                    db,
                    task,
                    "dispatch_backoff_scheduled",
                    "检测到下游仍存活，回收后进入退让等待",
                    level="warning",
                    stage_name=task.current_stage,
                    payload={
                        "reclaim_reason": "dispatch_timeout",
                        "backoff_seconds": max(int(service_config.dispatch_timeout_seconds or 0), 60),
                        "has_downstream_refs": has_downstream_refs,
                        "active_stage_name": active_stage_name or task.current_stage,
                    },
                )
            reclaimed = True
        if reclaimed:
            db.flush()
        return reclaimed

    def _requeue_orphaned_owned_execution_locked(self, db: Session) -> bool:
        candidate_rows = (
            db.query(BinarySecurityTask)
            .filter(
                BinarySecurityTask.status.in_(["running", "dispatching"]),
                BinarySecurityTask.runtime_phase == TASK_RUNTIME_PHASE_OWNED_EXECUTION,
            )
            .all()
        )
        if not candidate_rows:
            return False
        reclaimed = False
        for task in candidate_rows:
            if self._task_has_active_cancel_operation(db, task) or str(task.status or "").strip() == TASK_STATUS_CANCELLING:
                continue
            if self._should_skip_readless_reconcile_for_active_task(task):
                continue
            if not self._should_requeue_for_owned_execution(
                db,
                task,
                next_stage=str(task.current_stage or "").strip() or None,
            ):
                continue
            self._requeue_owned_execution_takeover(
                db,
                task,
                stage_name=str(task.current_stage or "").strip() or None,
                reason="readless_owned_execution_orphan",
                event_type="owned_execution_takeover_requeued",
                message="检测到执行接管悬空，已重新排队等待 worker 接管",
                event_payload={"previous_status": str(task.status or "").strip() or None},
            )
            reclaimed = True
        if reclaimed:
            db.flush()
        return reclaimed

    def _reclaim_stale_streaming_stage_items_locked(self, db: Session) -> bool:
        service_config = self._load_service_config(db)
        stale_rows = (
            db.query(BinarySecurityStageItem)
            .filter(
                BinarySecurityStageItem.stage_name.in_(list(STREAMING_TAIL_STAGES)),
                BinarySecurityStageItem.status == "dispatching",
            )
            .all()
        )
        if not stale_rows:
            return False
        local_workers = {
            task_id for task_id, worker in self._stage_item_workers.items()
            if not worker.done()
        }
        reclaimed = False
        timeout_seconds = max(int(service_config.dispatch_timeout_seconds or 0), 60)
        for item in stale_rows:
            if item.id in local_workers:
                continue
            if str(item.downstream_task_id or "").strip():
                # Streaming tail items that already own a downstream task must
                # be reconciled against the child service instead of being
                # locally re-queued by an elapsed-time heuristic. Otherwise a
                # still-pending child can be recreated repeatedly while the
                # downstream task remains valid.
                continue
            reference_time = item.updated_at or item.started_at or item.created_at
            elapsed_seconds = _elapsed_seconds_since(reference_time)
            if elapsed_seconds is None or elapsed_seconds < timeout_seconds:
                continue
            previous_status = str(item.status or "").strip()
            item.status = "pending"
            item.error_message = None
            item.finished_at = None
            task = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == item.task_id).first()
            if task is not None:
                self._merge_stage_item_result_fields(
                    task,
                    item,
                    stage_name=str(item.stage_name or "").strip(),
                    updates={"dispatch_reclaimed_at": _now().isoformat()},
                )
            else:
                item.result = {
                    **(item.result or {}),
                    "dispatch_reclaimed_at": _now().isoformat(),
                }
            if task is not None:
                self._record_event(
                    db,
                    task,
                    "streaming_stage_item_dispatch_reclaimed",
                    f"流式阶段子任务调度超时，已回收重试: {item.stage_name}:{item.item_key}",
                    level="warning",
                    stage_name=item.stage_name,
                    item=item,
                    payload={
                        "previous_status": previous_status,
                        "requeued_status": item.status,
                        "downstream_task_id": item.downstream_task_id,
                        "elapsed_seconds": elapsed_seconds,
                    },
                )
            reclaimed = True
        if reclaimed:
            db.flush()
        return reclaimed

    def _reclaim_stale_running_locked(self, db: Session) -> bool:
        service_config = self._load_service_config(db)
        timeout_seconds = max(int(service_config.dispatch_timeout_seconds) * 3, 300)
        stale_rows = (
            db.query(BinarySecurityTask)
            .filter(
                BinarySecurityTask.status == "running",
                BinarySecurityTask.dispatch_started_at.isnot(None),
            )
            .all()
        )
        if not stale_rows:
            return False
        local_workers = {
            task_id for task_id, worker in self._workers.items()
            if not worker.done()
        }
        reclaimed = False
        for task in stale_rows:
            if self._task_has_active_cancel_operation(db, task) or str(task.status or "").strip() == TASK_STATUS_CANCELLING:
                continue
            if task.id in local_workers and str(task.dispatcher_instance_id or "").strip() == self.instance_id:
                continue
            lease, runtime_lease_owner, runtime_lease_expires_at = self._runtime_lease_context(db, task)
            heartbeat_at = (lease.heartbeat_at if lease is not None else None) or task.updated_at or task.dispatch_started_at
            elapsed_seconds = _elapsed_seconds_since(heartbeat_at)
            lease_remaining = _seconds_until(runtime_lease_expires_at)
            if lease_remaining is not None and lease_remaining > 0:
                continue
            if elapsed_seconds is None or elapsed_seconds < max(timeout_seconds, self._task_reclaim_grace_seconds()):
                continue
            if self._has_local_task_execution_owner(task.id) or self._task_has_active_streaming_stage_workers(task.id):
                continue
            stage_name = task.current_stage or self._stage_sequence_for_task(task)[0]
            if self._release_streaming_parent_for_takeover_locked(
                db,
                task,
                runtime_lease_owner=runtime_lease_owner,
                runtime_lease_expires_at=runtime_lease_expires_at,
                reason="expired_runtime_lease_with_active_tail",
            ):
                observe_runtime_lease_owner_mismatch("expired_runtime_lease_with_active_tail")
                reclaimed = True
                continue
            stage_run = db.query(BinarySecurityStageRun).filter(
                BinarySecurityStageRun.task_id == task.id,
                BinarySecurityStageRun.stage_name == stage_name,
            ).first()
            active_items = db.query(BinarySecurityStageItem).filter(
                BinarySecurityStageItem.task_id == task.id,
                BinarySecurityStageItem.stage_name == stage_name,
                BinarySecurityStageItem.status.in_(["pending", "queued", "running"]),
            ).all()
            has_downstream_refs = any(str(item.downstream_task_id or "").strip() for item in active_items)
            queued_only = bool(active_items) and all(
                str(item.status or "").strip().lower() in {"pending", "queued"}
                for item in active_items
            )
            if queued_only or has_downstream_refs:
                task.status = "pending"
                task.dispatcher_instance_id = None
                task.dispatch_started_at = None
                task.lease_expires_at = None
                task.last_error = None
                self._clear_runtime_lease(db, task.id)
                self._record_event(
                    db,
                    task,
                    "running_execution_released",
                    "运行实例心跳超时，已释放过期执行实例并保留阶段状态等待安全接管",
                    level="warning",
                    stage_name=stage_name,
                    payload={
                        "stage_name": stage_name,
                        "queued_only": queued_only,
                        "has_downstream_refs": has_downstream_refs,
                        "active_item_count": len(active_items),
                        "runtime_lease_owner": runtime_lease_owner,
                        "runtime_lease_expires_at": _isoformat_or_none(runtime_lease_expires_at),
                    },
                )
                reclaimed = True
                continue
            if self._is_streaming_tail_stage(task, stage_name) and not active_items:
                fallback_stage = self._next_incomplete_stage(db, task)
                if fallback_stage and fallback_stage != stage_name:
                    task.status = "pending"
                    task.current_stage = fallback_stage
                    task.dispatcher_instance_id = None
                    task.dispatch_started_at = None
                    task.lease_expires_at = None
                    task.last_error = None
                    task.finished_at = None
                    self._clear_runtime_lease(db, task.id)
                    self._record_event(
                        db,
                        task,
                        "running_execution_released",
                        "运行实例心跳超时，空尾阶段已释放并回退到最近仍有真实工作的阶段",
                        level="warning",
                        stage_name=stage_name,
                        payload={
                            "stage_name": stage_name,
                            "fallback_stage": fallback_stage,
                            "active_item_count": 0,
                            "empty_tail_stage": True,
                        },
                    )
                    reclaimed = True
                    continue
            if stage_run:
                stage_run.status = "failed"
                stage_run.finished_at = _now()
                stage_run.last_error = "任务执行实例心跳超时，运行状态已回收"
                self._merge_stage_run_output_summary(
                    task,
                    stage_run,
                    {
                        "error": stage_run.last_error,
                        "reclaimed": True,
                    },
                )
                running_items = db.query(BinarySecurityStageItem).filter(
                    BinarySecurityStageItem.task_id == task.id,
                    BinarySecurityStageItem.stage_name == stage_name,
                    BinarySecurityStageItem.status.in_(["pending", "queued", "running"]),
                ).all()
                for item in running_items:
                    item.status = "failed"
                    item.finished_at = _now()
                    item.error_message = item.error_message or stage_run.last_error
                stage_run.counts = self._stage_counts(db, stage_run)
            task.status = "failed"
            task.last_error = "任务执行实例心跳超时，运行状态已回收"
            task.dispatcher_instance_id = None
            task.dispatch_started_at = None
            task.lease_expires_at = None
            task.finished_at = _now()
            self._clear_runtime_lease(db, task.id)
            self._record_event(
                db,
                task,
                "running_reclaimed",
                "运行实例心跳超时，任务已回收并标记失败",
                level="error",
                stage_name=stage_name,
                payload={"stage_name": stage_name},
            )
            reclaimed = True
        if reclaimed:
            db.flush()
        return reclaimed

    def _requeue_released_running_locked(self, db: Session) -> bool:
        released_rows = (
            db.query(BinarySecurityTask)
            .filter(
                BinarySecurityTask.status == "running",
                or_(
                    BinarySecurityTask.dispatcher_instance_id.is_(None),
                    BinarySecurityTask.dispatcher_instance_id == "",
                ),
                BinarySecurityTask.dispatch_started_at.is_(None),
                BinarySecurityTask.lease_expires_at.is_(None),
            )
            .all()
        )
        if not released_rows:
            return False
        requeued = False
        for task in released_rows:
            if self._task_has_active_cancel_operation(db, task) or str(task.status or "").strip() == TASK_STATUS_CANCELLING:
                continue
            lease = self._runtime_lease_for_task(db, task.id)
            if self._runtime_lease_is_active(lease):
                continue
            if self._has_local_task_execution_owner(task.id) or self._task_has_active_streaming_stage_workers(task.id):
                continue
            lease = self._runtime_lease_for_task(db, task.id)
            runtime_lease_owner = str(lease.owner_instance_id or "").strip() or None if lease is not None else None
            runtime_lease_expires_at = lease.lease_expires_at if lease is not None else None
            if self._release_streaming_parent_for_takeover_locked(
                db,
                task,
                runtime_lease_owner=runtime_lease_owner,
                runtime_lease_expires_at=runtime_lease_expires_at,
                reason="released_running_without_owner_with_active_tail",
            ):
                observe_runtime_lease_owner_mismatch("released_running_with_active_tail")
                requeued = True
                continue
            stage_name = task.current_stage or self._stage_sequence_for_task(task)[0]
            active_items = db.query(BinarySecurityStageItem).filter(
                BinarySecurityStageItem.task_id == task.id,
                BinarySecurityStageItem.stage_name == stage_name,
                BinarySecurityStageItem.status.in_(["pending", "queued", "running"]),
            ).all()
            has_downstream_refs = any(str(item.downstream_task_id or "").strip() for item in active_items)
            if active_items or has_downstream_refs:
                continue
            task.status = "pending"
            task.updated_at = _now()
            task.last_error = None
            observe_running_requeue("released_without_owner")
            self._record_event(
                db,
                task,
                "running_execution_requeued",
                "已将释放后的运行任务重新纳入待调度队列，等待新的 worker 安全接管",
                level="warning",
                stage_name=stage_name,
                payload={
                    "stage_name": stage_name,
                    "active_item_count": len(active_items),
                    "runtime_lease_owner": None,
                    "runtime_lease_stale": True,
                },
            )
            requeued = True
        if requeued:
            db.flush()
        return requeued

    def _build_queue_info(self, db: Session, *, project_id: str) -> dict[str, Any]:
        running_count = int(
            db.query(func.count(BinarySecurityTask.id))
            .filter(
                BinarySecurityTask.project_id == project_id,
                BinarySecurityTask.status.in_(["dispatching", "running"]),
            )
            .scalar()
            or 0
        )
        queued_rows = (
            db.query(BinarySecurityTask.id)
            .filter(
                BinarySecurityTask.project_id == project_id,
                BinarySecurityTask.status == "pending",
            )
            .order_by(BinarySecurityTask.created_at.asc(), BinarySecurityTask.id.asc())
            .all()
        )
        pending_positions = {row[0]: index + 1 for index, row in enumerate(queued_rows)}
        return {
            "running_count": running_count,
            "queued_count": len(queued_rows),
            "pending_positions": pending_positions,
            "last_reconcile_at": self._last_queue_reconcile_at,
        }

    def _task_queue_state(
        self,
        task: BinarySecurityTask,
        queue_info: dict[str, Any] | None = None,
        *,
        db: Session | None = None,
    ) -> tuple[str, str | None]:
        queue_info = queue_info or {}
        pending_positions = queue_info.get("pending_positions", {}) or {}
        status = str(task.status or "").strip().lower()
        runtime_phase = self._task_runtime_phase(task)
        tail_takeover_required = False
        if runtime_phase == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION:
            if db is not None:
                row = db.query(BinarySecurityTask).filter(BinarySecurityTask.id == task.id).first()
                if row is not None:
                    tail_takeover_required = self._tail_requires_execution_takeover(db, row)
            else:
                session = get_session_factory()()
                try:
                    row = session.query(BinarySecurityTask).filter(BinarySecurityTask.id == task.id).first()
                    if row is not None:
                        tail_takeover_required = self._tail_requires_execution_takeover(session, row)
                finally:
                    session.close()
        if tail_takeover_required:
            if status == "pending":
                if task.id in pending_positions:
                    return "queued", None
                return "db_pending_not_enqueued", "pending_task_not_present_in_redis_queue"
            if status in {"dispatching", "running"}:
                return "leased", "tail_execution_takeover_required"
        if runtime_phase == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION:
            return "tail_reconciling", "tail_reconciliation_active"
        if status in {"dispatching", "running"}:
            if task.dispatcher_instance_id or task.lease_expires_at:
                return "dispatching", None
            return "leased", "execution_owner_missing"
        if status == "pending":
            if task.id in pending_positions:
                return "queued", None
            return "db_pending_not_enqueued", "pending_task_not_present_in_redis_queue"
        return "idle", None

    def _observe_worker_counts(self) -> None:
        observe_worker_counts(
            task_workers=len([task for task in self._workers.values() if not task.done()]),
            operation_workers=len([task for task in self._operation_workers.values() if not task.done()]),
            archive_workers=len([task for task in self._archive_workers if not task.done()]),
        )

    def _collect_runtime_metrics_snapshot_sync(self) -> dict[str, int]:
        db = get_session_factory()()
        try:
            pending_tasks = int(
                db.query(func.count(BinarySecurityTask.id))
                .filter(BinarySecurityTask.status == "pending")
                .scalar()
                or 0
            )
            running_tasks = int(
                db.query(func.count(BinarySecurityTask.id))
                .filter(BinarySecurityTask.status.in_(["dispatching", "running"]))
                .scalar()
                or 0
            )
            archive_pending_jobs = int(
                db.query(func.count(BinarySecurityArchiveJob.id))
                .filter(BinarySecurityArchiveJob.archive_status == "pending")
                .scalar()
                or 0
            )
            archive_running_jobs = int(
                db.query(func.count(BinarySecurityArchiveJob.id))
                .filter(BinarySecurityArchiveJob.archive_status == "running")
                .scalar()
                or 0
            )
            archive_applying_jobs = int(
                db.query(func.count(BinarySecurityArchiveJob.id))
                .filter(BinarySecurityArchiveJob.archive_status.in_(["archived", "applying"]))
                .scalar()
                or 0
            )
            leased_tasks = int(
                db.query(func.count(BinarySecurityTask.id))
                .filter(
                    BinarySecurityTask.dispatch_started_at.isnot(None),
                    BinarySecurityTask.lease_expires_at.isnot(None),
                )
                .scalar()
                or 0
            )
            service_config = self._load_service_config(db)
            return {
                "pending_tasks": pending_tasks,
                "running_tasks": running_tasks,
                "archive_pending_jobs": archive_pending_jobs,
                "archive_running_jobs": archive_running_jobs,
                "archive_applying_jobs": archive_applying_jobs,
                "leased_tasks": leased_tasks,
                "task_capacity": int(service_config.max_concurrent_tasks),
            }
        finally:
            db.close()

    async def _observe_runtime_metrics(self, db: Session, *, reconcile_candidates: int | None = None) -> None:
        del db
        queue_snapshot = await get_task_queue().snapshot()
        metrics_snapshot = await asyncio.to_thread(self._collect_runtime_metrics_snapshot_sync)
        pending_tasks = int(metrics_snapshot.get("pending_tasks", 0) or 0)
        running_tasks = int(metrics_snapshot.get("running_tasks", 0) or 0)
        archive_pending_jobs = int(metrics_snapshot.get("archive_pending_jobs", 0) or 0)
        archive_running_jobs = int(metrics_snapshot.get("archive_running_jobs", 0) or 0)
        archive_applying_jobs = int(metrics_snapshot.get("archive_applying_jobs", 0) or 0)
        leased_tasks = int(metrics_snapshot.get("leased_tasks", 0) or 0)
        task_capacity = int(metrics_snapshot.get("task_capacity", 0) or 0)
        if task_capacity <= 0:
            task_capacity = 1
        pending_tasks = int(
            pending_tasks
        )
        running_tasks = int(
            running_tasks
        )
        archive_pending_jobs = int(
            archive_pending_jobs
        )
        archive_running_jobs = int(
            archive_running_jobs
        )
        archive_applying_jobs = int(
            archive_applying_jobs
        )
        leased_tasks = int(
            leased_tasks
        )
        task_workers = len([task for task in self._workers.values() if not task.done()])
        operation_workers = len([task for task in self._operation_workers.values() if not task.done()])
        observe_queue_depths(
            pending_tasks=pending_tasks,
            running_tasks=running_tasks,
            archive_pending_jobs=archive_pending_jobs,
            archive_running_jobs=archive_running_jobs,
            archive_applying_jobs=archive_applying_jobs,
            reconcile_candidates=max(0, int(reconcile_candidates or 0)),
            redis_task_queue=int((queue_snapshot.get("task_queue") or {}).get("length", 0)),
            redis_operation_queue=int((queue_snapshot.get("operation_queue") or {}).get("length", 0)),
            leased_tasks=leased_tasks,
            task_queue_oldest_age_seconds=float((queue_snapshot.get("task_queue") or {}).get("oldest_age_seconds", 0.0) or 0.0),
            operation_queue_oldest_age_seconds=float((queue_snapshot.get("operation_queue") or {}).get("oldest_age_seconds", 0.0) or 0.0),
        )
        observe_slot_usage(
            task_active=task_workers,
            task_capacity=task_capacity,
            action_active=operation_workers,
            action_capacity=max(1, int(self.cfg.scheduler.downstream_action_concurrency)),
        )
        self._observe_worker_counts()

    def _finalize_task(self, db: Session, task: BinarySecurityTask) -> None:
        with self._task_execution_owner_lock:
            self._task_execution_owners.pop(task.id, None)
        if self._ensure_task_remains_cancelling(db, task) is not None:
            self._last_task_heartbeat_at.pop(task.id, None)
            self._sync_task_abnormal_reason_snapshot(db, task, None)
            return
        if task.status == TASK_STATUS_PENDING_MODULE_CONFIRMATION:
            self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
            self._sync_task_abnormal_reason_snapshot(db, task, None)
            task.dispatcher_instance_id = None
            task.dispatch_started_at = None
            task.lease_expires_at = None
            self._last_task_heartbeat_at.pop(task.id, None)
            return
        if task.status == "cancelled":
            self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_TERMINAL)
            stage_sequence = self._stage_sequence_for_task(task)
            stage_summaries = self._build_stage_summaries(db, task, stage_sequence, db.query(BinarySecurityStageRun).filter(BinarySecurityStageRun.task_id == task.id).all(), db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.task_id == task.id).all())
            items = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.task_id == task.id).all()
            archive_jobs = db.query(BinarySecurityArchiveJob).filter(BinarySecurityArchiveJob.task_id == task.id).all()
            self._sync_task_abnormal_reason_snapshot(db, task, self._task_abnormal_reason(task, stage_summaries, items, archive_jobs))
            task.dispatcher_instance_id = None
            task.dispatch_started_at = None
            task.lease_expires_at = None
            task.finished_at = _now()
            self._last_task_heartbeat_at.pop(task.id, None)
            return
        if task.status == TASK_STATUS_CANCEL_FAILED:
            self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_TERMINAL)
            stage_sequence = self._stage_sequence_for_task(task)
            stage_summaries = self._build_stage_summaries(db, task, stage_sequence, db.query(BinarySecurityStageRun).filter(BinarySecurityStageRun.task_id == task.id).all(), db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.task_id == task.id).all())
            items = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.task_id == task.id).all()
            archive_jobs = db.query(BinarySecurityArchiveJob).filter(BinarySecurityArchiveJob.task_id == task.id).all()
            self._sync_task_abnormal_reason_snapshot(db, task, self._task_abnormal_reason(task, stage_summaries, items, archive_jobs))
            self._invalidate_task_execution(task)
            task.finished_at = task.finished_at or _now()
            self._last_task_heartbeat_at.pop(task.id, None)
            return
        stage_runs = db.query(BinarySecurityStageRun).filter(BinarySecurityStageRun.task_id == task.id).all()
        vuln_run = next((run for run in stage_runs if normalize_stage_name(run.stage_name) == "dataflow_vuln_scan"), None)
        has_active_streaming_upstream, active_streaming_stage, active_streaming_status = self._streaming_has_active_upstream_stage(task, stage_runs)
        if has_active_streaming_upstream:
            task.status = "running" if active_streaming_status in {"running", "dispatching", "applying"} else "pending"
            self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
            task.tail_reconcile_state = "idle"
            task.current_stage = active_streaming_stage
            task.dispatcher_instance_id = None
            task.dispatch_started_at = None
            task.lease_expires_at = None
            task.finished_at = None
            task.last_error = None
            self._release_tail_reconcile_owner(task.id)
            self._last_task_heartbeat_at.pop(task.id, None)
            self._record_event(
                db,
                task,
                "task_finalize_deferred_for_streaming_upstream",
                f"深度模式下仍有上游阶段活跃，转回 worker 接管继续执行: {active_streaming_stage}",
                level="info",
                stage_name=active_streaming_stage,
                payload={"stage_status": active_streaming_status},
            )
            self._sync_task_abnormal_reason_snapshot(db, task, None)
            if self._should_requeue_for_owned_execution(
                db,
                task,
                next_stage=active_streaming_stage,
                next_stage_status=str(active_streaming_status or "").strip(),
            ):
                self._requeue_owned_execution_takeover(
                    db,
                    task,
                    stage_name=active_streaming_stage,
                    reason="finalize_streaming_upstream_no_active_owner",
                    event_type="owned_execution_takeover_requeued",
                    message=f"检测到执行接管悬空，已重新排队等待 worker 接管: {active_streaming_stage}",
                    event_payload={"stage_status": active_streaming_status, "source": "finalize_streaming_upstream"},
                )
            return
        has_active_incomplete_stage, active_stage_name, active_stage_status = self._has_any_active_incomplete_stage(task, stage_runs)
        if has_active_incomplete_stage:
            task.status = "running" if active_stage_status in {"running", "dispatching", "applying"} else "pending"
            task.current_stage = active_stage_name or task.current_stage
            task.dispatcher_instance_id = None
            task.dispatch_started_at = None
            task.lease_expires_at = None
            task.finished_at = None
            task.last_error = None
            if (
                self._is_streaming_tail_stage(task, active_stage_name)
                and self._tail_requires_execution_takeover(db, task)
                and str(active_stage_status or "").strip() in {"running", "dispatching", "applying"}
            ):
                task.status = "running"
                self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
                task.tail_reconcile_state = None
                self._release_tail_reconcile_owner(task.id)
                self._last_task_heartbeat_at.pop(task.id, None)
                self._record_event(
                    db,
                    task,
                    "task_finalize_deferred_for_active_stage",
                    f"仍有活跃未完成阶段，转回 worker 接管继续执行: {active_stage_name}",
                    level="info",
                    stage_name=active_stage_name,
                    payload={"stage_status": active_stage_status},
                )
                self._sync_task_abnormal_reason_snapshot(db, task, None)
                return
            if self._is_streaming_tail_stage(task, active_stage_name) and self._should_enter_tail_reconciliation(db, task):
                task.status = "running"
                self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_TAIL_RECONCILIATION)
                task.tail_reconcile_state = "idle"
            else:
                self._release_tail_reconcile_owner(task.id)
                self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
            self._last_task_heartbeat_at.pop(task.id, None)
            self._record_event(
                db,
                task,
                "task_finalize_deferred_for_active_stage",
                f"仍有活跃未完成阶段，延迟任务收口: {active_stage_name}",
                level="info",
                stage_name=active_stage_name,
                payload={"stage_status": active_stage_status},
            )
            self._sync_task_abnormal_reason_snapshot(db, task, None)
            if self._should_requeue_for_owned_execution(
                db,
                task,
                next_stage=active_stage_name,
                next_stage_status=str(active_stage_status or "").strip(),
            ):
                self._requeue_owned_execution_takeover(
                    db,
                    task,
                    stage_name=active_stage_name,
                    reason="finalize_active_stage_no_active_owner",
                    event_type="owned_execution_takeover_requeued",
                    message=f"检测到执行接管悬空，已重新排队等待 worker 接管: {active_stage_name}",
                    event_payload={"stage_status": active_stage_status, "source": "finalize_active_stage"},
                )
            return
        next_stage = self._next_incomplete_stage(db, task)
        if next_stage:
            if vuln_run and vuln_run.status in {"success", "partial_success"}:
                next_stage = None
            else:
                next_stage_run = next((run for run in stage_runs if run.stage_name == next_stage), None)
                next_stage_items = self._stage_items(db, task.id, next_stage)
                next_stage_status = (
                    self._normalize_downstream_status(next_stage_run.status) or str(next_stage_run.status or "").strip()
                    if next_stage_run is not None
                    else "pending"
                )
                if next_stage_items:
                    item_status = self._aggregate_item_statuses([item.status for item in next_stage_items])
                    if item_status in {"pending", "queued", "running", "dispatching"}:
                        next_stage_status = item_status
                if next_stage_status in {"failed", "downstream_missing", "cancelled"} and next_stage_items and not self._stage_has_nonterminal_items(next_stage_items):
                    task.status = "failed"
                    self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_TERMINAL)
                    task.current_stage = next_stage
                    task.dispatcher_instance_id = None
                    task.dispatch_started_at = None
                    task.lease_expires_at = None
                    task.finished_at = _now()
                    task.last_error = next_stage_run.last_error if next_stage_run is not None else task.last_error
                    self._last_task_heartbeat_at.pop(task.id, None)
                    stage_summaries = self._build_stage_summaries(db, task, self._stage_sequence_for_task(task), stage_runs, db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.task_id == task.id).all())
                    items = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.task_id == task.id).all()
                    archive_jobs = db.query(BinarySecurityArchiveJob).filter(BinarySecurityArchiveJob.task_id == task.id).all()
                    self._sync_task_abnormal_reason_snapshot(db, task, self._task_abnormal_reason(task, stage_summaries, items, archive_jobs))
                    return
                task.status = "running" if next_stage_status in {"running", "dispatching", "applying"} else "pending"
                task.current_stage = next_stage
                task.dispatcher_instance_id = None
                task.dispatch_started_at = None
                task.lease_expires_at = None
                task.finished_at = None
                task.last_error = None
                self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
                task.tail_reconcile_state = "idle"
                self._release_tail_reconcile_owner(task.id)
                self._last_task_heartbeat_at.pop(task.id, None)
                if self._should_requeue_for_owned_execution(
                    db,
                    task,
                    next_stage=next_stage,
                    next_stage_status=str(next_stage_status or "").strip(),
                ):
                    self._requeue_owned_execution_takeover(
                        db,
                        task,
                        stage_name=next_stage,
                        reason="finalize_deferred_no_active_owner",
                        event_type="owned_execution_takeover_requeued",
                        message=f"检测到执行接管悬空，已重新排队等待 worker 接管: {next_stage}",
                        event_payload={"stage_status": next_stage_status},
                    )
                else:
                    self._record_event(
                        db,
                        task,
                        "task_finalize_deferred_for_incomplete_stage",
                        f"任务仍有未完成阶段，保持活跃状态等待继续推进: {next_stage}",
                        level="warning",
                        stage_name=next_stage,
                        payload={"stage_status": next_stage_status},
                    )
                    self._sync_task_abnormal_reason_snapshot(db, task, None)
                    if next_stage_status in {"pending", "queued"} or next_stage_run is None:
                        self._enqueue_task(task.id)
                return
        else:
            runs_by_stage = {str(run.stage_name or "").strip(): run for run in stage_runs}
            missing_enabled_stage = next(
                (
                    stage_name
                    for stage_name in self._stage_sequence_for_task(task)
                    if (
                        self._stage_enabled(task, stage_name)
                        and runs_by_stage.get(stage_name) is None
                        and not self._should_finalize_without_entries(db, task, stage_name)
                    )
                ),
                None,
            )
            if missing_enabled_stage and not (vuln_run and vuln_run.status in {"success", "partial_success"}):
                task.status = "pending"
                self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
                task.current_stage = missing_enabled_stage
                task.dispatcher_instance_id = None
                task.dispatch_started_at = None
                task.lease_expires_at = None
                task.finished_at = None
                task.last_error = None
                self._last_task_heartbeat_at.pop(task.id, None)
                self._record_event(
                    db,
                    task,
                    "task_finalize_deferred_for_missing_stage",
                    f"任务缺少已启用阶段的执行记录，保持活跃状态等待补跑: {missing_enabled_stage}",
                    level="warning",
                    stage_name=missing_enabled_stage,
                )
                self._sync_task_abnormal_reason_snapshot(db, task, None)
                self._enqueue_task(task.id)
                return
        statuses = [run.status for run in stage_runs]
        if statuses and all(status == "success" for status in statuses):
            task.status = "success"
        elif vuln_run and vuln_run.status in {"success", "partial_success"}:
            task.status = "partial_success" if any(status in {"failed", "partial_success", "downstream_missing"} for status in statuses) else "success"
        elif any(status in {"failed", "partial_success", "downstream_missing"} for status in statuses):
            task.status = "failed"
        else:
            task.status = "success"
        stale_stages = list((task.summary or {}).get("stale_stages") or [])
        if stale_stages and task.status == "success":
            task.status = "partial_success"
        self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_TERMINAL)
        task.dispatcher_instance_id = None
        task.dispatch_started_at = None
        task.finished_at = _now()
        self._last_task_heartbeat_at.pop(task.id, None)
        items = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.task_id == task.id).all()
        archive_jobs = db.query(BinarySecurityArchiveJob).filter(BinarySecurityArchiveJob.task_id == task.id).all()
        stage_summaries = self._build_stage_summaries(db, task, self._stage_sequence_for_task(task), stage_runs, items)
        self._sync_task_abnormal_reason_snapshot(
            db,
            task,
            None if task.status == "success" else self._task_abnormal_reason(task, stage_summaries, items, archive_jobs),
        )
        observe_task_lifecycle("finished", status=task.status, task_type=self._task_type(task))
        observe_task_duration(
            phase="execution",
            duration_seconds=_elapsed_seconds_since(task.started_at),
            status=task.status,
            task_type=self._task_type(task),
        )
        observe_task_duration(
            phase="total",
            duration_seconds=_elapsed_seconds_since(task.created_at),
            status=task.status,
            task_type=self._task_type(task),
        )
        self._record_event(db, task, "task_finished", f"任务结束: {task.status}")

    def _resolve_output_root(self, workspace_root: Path, custom_output_root: str | None) -> Path:
        if custom_output_root:
            candidate = Path(custom_output_root).resolve()
            return ensure_dir(candidate)
        return ensure_dir(workspace_root / "output")

    def _init_workspace(self, root: Path) -> None:
        for rel in ["input", "output", "run", "logs"]:
            ensure_dir(root / rel)

    async def _init_workspace_async(self, root: Path) -> None:
        await asyncio.to_thread(self._init_workspace, root)

    async def _ensure_task_directories(self, project_id: str, task_id: str, authorization_token: str) -> None:
        client = get_fileserver_client()
        task_root = client.project_files_root(project_id) / "app" / "secflow-app-binary-security" / task_id
        await client.ensure_project_directory(project_id, task_root.parent.parent, authorization_token)
        await client.ensure_project_directory(project_id, task_root.parent, authorization_token)
        await client.ensure_project_directory(project_id, task_root, authorization_token)
        for name in ("input", "output", "run"):
            await client.ensure_project_directory(project_id, task_root / name, authorization_token)
        await client.ensure_project_directory(project_id, task_root / "run" / "upload-tmp", authorization_token)

    def _write_task_metadata(self, task: BinarySecurityTask, metadata_path: Path, *, status: str) -> None:
        _write_json(
            metadata_path,
            {
                "task_id": task.id,
                "project_id": task.project_id,
                "task_type": self._task_type(task),
                "name": task.name,
                "description": task.description,
                "created_by": task.created_by,
                "created_at": task.created_at.isoformat() if task.created_at else None,
                "status": status,
                "input_files": task.summary.get("input_files", []),
                "input_kind": task.summary.get("input_kind"),
                "policy": task.policy,
                "stage_options": task.policy.get("stage_options", {}),
                "paths": {
                    "task_root": task.summary.get("task_root_path"),
                    "input_dir": task.summary.get("input_dir"),
                    "output_dir": task.summary.get("output_dir"),
                    "run_dir": task.summary.get("run_dir"),
                    "temp_upload_dir": task.summary.get("temp_upload_dir"),
                },
            },
        )

    async def _write_task_metadata_async(self, task: BinarySecurityTask, metadata_path: Path, *, status: str) -> None:
        await asyncio.to_thread(self._write_task_metadata, task, metadata_path, status=status)

    def _normalize_input_files(self, files: list[BinarySecurityInputFile | dict[str, Any]], *, task_type: str) -> list[dict[str, Any]]:
        rows = []
        seen_names: set[str] = set()
        seen_paths: set[str] = set()
        seen_keys: set[str] = set()
        for index, raw in enumerate(files):
            item = raw.model_dump(mode="json") if isinstance(raw, BinarySecurityInputFile) else dict(raw)
            filename = str(item.get("filename") or "").strip()
            if not filename:
                raise ValidationError("上传文件名不能为空")
            if "/" in filename or "\\" in filename:
                raise ValidationError(f"文件名不合法: {filename}")
            relative_path_raw = str(item.get("relative_path") or "").strip().replace("\\", "/").strip("/")
            if relative_path_raw:
                path_parts = [part for part in relative_path_raw.split("/") if part]
                if any(part in {".", ".."} for part in path_parts):
                    raise ValidationError(f"相对路径不合法: {relative_path_raw}")
                effective_path = "/".join(path_parts)
                if Path(effective_path).name != filename:
                    effective_path = "/".join([part for part in path_parts[:-1]] + [filename]) if path_parts else filename
            else:
                effective_path = filename
            if task_type == TASK_TYPE_SOURCE:
                effective_path = filename
                if filename in seen_names:
                    raise ValidationError(f"存在重复文件名: {filename}")
                seen_names.add(filename)
                if not self._is_supported_source_archive(filename):
                    raise ValidationError(f"源码扫描仅支持常见压缩文件: {filename}")
            else:
                dedupe_key = effective_path if task_type == TASK_TYPE_BINARY_MODULE else filename
                if dedupe_key in seen_paths:
                    raise ValidationError(f"存在重复{'路径' if task_type == TASK_TYPE_BINARY_MODULE else '文件名'}: {dedupe_key}")
                seen_paths.add(dedupe_key)
                if filename in seen_names and task_type != TASK_TYPE_BINARY_MODULE:
                    raise ValidationError(f"存在重复文件名: {filename}")
                seen_names.add(filename)
            firmware_key = _slug(filename)
            if firmware_key in seen_keys:
                firmware_key = _slug(f"{index + 1}-{filename}")
            seen_keys.add(firmware_key)
            rows.append(
                {
                    "filename": filename,
                    "size": int(item.get("size") or 0),
                    "content_type": item.get("content_type"),
                    "relative_path": effective_path,
                    "metadata": item.get("metadata") or {},
                    "firmware_key": firmware_key,
                    "firmware_name": Path(filename).stem or filename,
                }
            )
        if not rows:
            raise ValidationError("至少需要上传一个输入文件")
        return rows

    def _build_binary_module_summary(self, task: BinarySecurityTask, input_files: list[dict[str, Any]]) -> dict[str, Any]:
        input_dir = Path(str(task.summary.get("input_dir") or Path(task.workspace_root) / "input"))
        module_input = dict(task.summary.get("module_input") or {})
        module_name = str(module_input.get("module_name") or task.name or "module").strip() or "module"
        module_key = _slug(module_name)
        firmware_key = MODULE_TASK_INPUT_KEY
        files_list_path = input_dir / "module-files.list"
        rel_paths = [str(item.get("relative_path") or item.get("filename") or "").strip().replace("\\", "/") for item in input_files]
        files_list_path.write_text("\n".join(path for path in rel_paths if path) + ("\n" if rel_paths else ""), encoding="utf-8")
        selected_at = _now().isoformat()
        module = {
            "module_key": module_key,
            "module_name": module_name,
            "task_type": TASK_TYPE_BINARY_MODULE,
            "firmware_key": firmware_key,
            "firmware_name": module_name,
            "source_dir": str(input_dir),
            "module_dir": str(input_dir),
            "files_list": str(files_list_path),
            "unpacked_root": str(input_dir),
            "source_root": str(input_dir),
            "file_count": len(input_files),
            "risk_level": "高",
            "risk_source": "manual_input",
            "selected_by": "manual_input",
            "selected_at": selected_at,
        }
        return {
            "module_input": {
                **module_input,
                "module_name": module_name,
                "module_key": module_key,
                "file_count": len(input_files),
            },
            "selected_modules": [module],
            "candidate_modules": [module],
            "system_analysis_modules": [module],
            "high_risk_modules": [module],
            "system_analysis_bypassed": True,
        }

    def _build_binary_module_restart_summary(self, task: BinarySecurityTask, input_files: list[dict[str, Any]]) -> dict[str, Any]:
        # A binary-module task skips system-analysis and starts from a fixed module input.
        # Hard restart must preserve that single-module execution context.
        return {
            "downstream_task_ids": {},
            **self._build_binary_module_summary(task, input_files),
        }

    def _is_supported_source_archive(self, filename: str) -> bool:
        lowered = str(filename or "").strip().lower()
        return any(lowered.endswith(ext) for ext in SOURCE_ARCHIVE_FORMATS)

    def _source_temp_upload_root(self, task: BinarySecurityTask) -> Path:
        return ensure_dir(Path(task.workspace_root) / "run" / "upload-tmp")

    def _check_storage_free_space(self, *, required_bytes: int = 0) -> None:
        root = Path(self.cfg.services.fileserver.data_mount_path)
        usage = shutil.disk_usage(root)
        min_required = max(
            int(getattr(self.cfg.storage, "min_free_disk_bytes", 0) or 0),
            int(required_bytes or 0),
        )
        if usage.free < min_required:
            raise ValidationError(f"存储空间不足，当前剩余 {usage.free} 字节，小于要求 {min_required} 字节")

    def _validate_uploaded_archive_size(self, filename: str, size_bytes: int, *, source_task: bool) -> None:
        max_upload = max(1, int(getattr(self.cfg.storage, "max_upload_file_bytes", 0) or 1))
        if size_bytes > max_upload:
            raise ValidationError(f"上传文件过大: {filename}，大小 {size_bytes} 超过限制 {max_upload} 字节")
        if source_task:
            max_archive = max(1, int(getattr(self.cfg.storage, "max_source_archive_bytes", 0) or 1))
            if size_bytes > max_archive:
                raise ValidationError(f"源码压缩包过大: {filename}，大小 {size_bytes} 超过限制 {max_archive} 字节")

    def _safe_extract_archive(self, archive_path: Path, target_dir: Path) -> int:
        if target_dir.exists() or target_dir.is_symlink():
            if target_dir.is_dir() and not target_dir.is_symlink():
                shutil.rmtree(target_dir, ignore_errors=True)
            else:
                target_dir.unlink(missing_ok=True)
        ensure_dir(target_dir)
        extracted = 0
        extracted_bytes = 0
        max_files = max(1, int(getattr(self.cfg.storage, "max_source_extract_files", 0) or 1))
        max_bytes = max(1, int(getattr(self.cfg.storage, "max_source_extract_bytes", 0) or 1))

        def ensure_limits(member_name: str, size_bytes: int) -> None:
            nonlocal extracted, extracted_bytes
            extracted += 1
            extracted_bytes += max(0, int(size_bytes or 0))
            if extracted > max_files:
                raise ValidationError(f"压缩包解压文件数超限: {member_name}")
            if extracted_bytes > max_bytes:
                raise ValidationError(f"压缩包解压总大小超限: {member_name}")

        if zipfile.is_zipfile(archive_path):
            with zipfile.ZipFile(archive_path) as archive:
                for member in archive.infolist():
                    member_name = member.filename.replace("\\", "/").strip("/")
                    if not member_name:
                        continue
                    target_path = target_dir / member_name
                    if not _is_within_path(target_dir, target_path):
                        raise ValidationError(f"压缩包包含非法路径: {member.filename}")
                    if member.is_dir():
                        ensure_dir(target_path)
                        continue
                    ensure_limits(member_name, member.file_size)
                    ensure_dir(target_path.parent)
                    with archive.open(member, "r") as source, open(target_path, "wb") as dest:
                        shutil.copyfileobj(source, dest, length=1024 * 1024)
            return extracted
        if tarfile.is_tarfile(archive_path):
            with tarfile.open(archive_path, "r:*") as archive:
                for member in archive.getmembers():
                    member_name = member.name.replace("\\", "/").strip("/")
                    if not member_name:
                        continue
                    target_path = target_dir / member_name
                    if not _is_within_path(target_dir, target_path):
                        raise ValidationError(f"压缩包包含非法路径: {member.name}")
                    if member.isdir():
                        ensure_dir(target_path)
                        continue
                    if member.issym() or member.islnk() or not member.isfile():
                        raise ValidationError(f"压缩包包含不安全条目: {member.name}")
                    ensure_limits(member_name, member.size)
                    ensure_dir(target_path.parent)
                    source = archive.extractfile(member)
                    if source is None:
                        raise ValidationError(f"压缩包成员无法读取: {member.name}")
                    with source, open(target_path, "wb") as dest:
                        shutil.copyfileobj(source, dest, length=1024 * 1024)
            return extracted
        raise ValidationError(f"不支持的源码压缩文件格式: {archive_path.name}")

    async def _wait_for_uploaded_file(self, path: Path, *, timeout_seconds: int = 10, interval_seconds: int = 1) -> bool:
        attempts = max(1, timeout_seconds // max(1, interval_seconds)) + 1
        for attempt in range(attempts):
            if await asyncio.to_thread(path.is_file):
                return True
            if attempt < attempts - 1:
                await asyncio.sleep(interval_seconds)
        return await asyncio.to_thread(path.is_file)

    async def _materialize_source_archives(self, task: BinarySecurityTask, declared: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], int, int]:
        input_dir = ensure_dir(Path(task.workspace_root) / "input")
        temp_dir = self._source_temp_upload_root(task)
        actual_files: list[dict[str, Any]] = []
        total_bytes = 0
        extracted_count = 0
        for file_info in declared:
            filename = str(file_info["filename"])
            temp_path = temp_dir / filename
            if not await self._wait_for_uploaded_file(temp_path, timeout_seconds=10, interval_seconds=1):
                raise ValidationError(f"上传文件缺失: {filename}")
            stat = await asyncio.to_thread(temp_path.stat)
            self._validate_uploaded_archive_size(filename, stat.st_size, source_task=True)
            self._check_storage_free_space(
                required_bytes=min(
                    int(getattr(self.cfg.storage, "max_source_extract_bytes", 0) or 0),
                    stat.st_size * 4 if stat.st_size > 0 else 0,
                )
            )
            total_bytes += stat.st_size
            extracted_count += await asyncio.to_thread(self._safe_extract_archive, temp_path, input_dir)
            await asyncio.to_thread(temp_path.unlink, missing_ok=True)
            actual_files.append(
                {
                    **file_info,
                    "size": stat.st_size,
                    "uploaded": True,
                    "path": str(task.summary.get("input_dir") or self._fileserver_task_path(task.project_id, task.id, "input")),
                    "temp_path": f"{task.summary.get('temp_upload_dir')}/{filename}" if task.summary.get("temp_upload_dir") else None,
                    "extracted": True,
                }
            )
        if extracted_count <= 0:
            raise ValidationError("源码压缩包解压后没有得到任何文件")
        await asyncio.to_thread(shutil.rmtree, temp_dir, True)
        await asyncio.to_thread(ensure_dir, temp_dir)
        return actual_files, total_bytes, extracted_count

    def _merge_policy(self, db: Session, project_id: str, overrides: dict[str, Any], stage_options: dict[str, Any]) -> dict[str, Any]:
        stage_parallelism = {stage: self.cfg.runtime_policy.max_stage_parallelism for stage in STAGE_SEQUENCE}
        base = BinarySecurityProjectConfigPayload(
            pipeline_mode=_normalize_pipeline_mode(self.cfg.runtime_policy.pipeline_mode),
            max_stage_parallelism=self.cfg.runtime_policy.max_stage_parallelism,
            max_retries_per_item=self.cfg.runtime_policy.max_retries_per_item,
            continue_on_item_failure=self.cfg.runtime_policy.continue_on_item_failure,
            partial_success_stage_advancement=DEFAULT_PARTIAL_SUCCESS_STAGE_ADVANCEMENT,
            stage_parallelism=stage_parallelism,
        ).model_dump(mode="json")
        row = db.query(BinarySecurityProjectConfig).filter(BinarySecurityProjectConfig.project_id == project_id).first()
        if row:
            base.update(row.config)
        base["pipeline_mode"] = _normalize_pipeline_mode(base.get("pipeline_mode"))
        base["partial_success_stage_advancement"] = self._normalized_partial_success_stage_advancement_map(
            base.get("partial_success_stage_advancement"),
            allowed_stages=PARTIAL_SUCCESS_ADVANCEMENT_STAGES,
            default_map=DEFAULT_PARTIAL_SUCCESS_STAGE_ADVANCEMENT,
        )
        if stage_options:
            base["stage_options"] = {
                **base.get("stage_options", {}),
                **{key: value.model_dump(mode="json") for key, value in stage_options.items()},
            }
        if overrides.get("max_stage_parallelism") is not None:
            stage_value = int(overrides["max_stage_parallelism"])
            base["max_stage_parallelism"] = stage_value
            base["stage_parallelism"] = {stage: stage_value for stage in STAGE_SEQUENCE}
        if overrides.get("pipeline_mode") is not None:
            base["pipeline_mode"] = _normalize_pipeline_mode(overrides["pipeline_mode"])
        if overrides.get("stage_parallelism"):
            merged = {**base.get("stage_parallelism", {})}
            for stage_name, value in (overrides.get("stage_parallelism") or {}).items():
                if stage_name in STAGE_SEQUENCE and value is not None:
                    merged[stage_name] = int(value)
            base["stage_parallelism"] = merged
        if overrides.get("max_retries_per_item") is not None:
            base["max_retries_per_item"] = int(overrides["max_retries_per_item"])
        if overrides.get("continue_on_item_failure") is not None:
            base["continue_on_item_failure"] = bool(overrides["continue_on_item_failure"])
        if overrides.get("partial_success_stage_advancement"):
            base["partial_success_stage_advancement"] = {
                **base.get("partial_success_stage_advancement", {}),
                **self._validate_and_normalize_partial_success_stage_advancement_overrides(
                    overrides.get("partial_success_stage_advancement"),
                    task_type=overrides.get("task_type"),
                ),
            }
        if overrides.get("task_type") is not None:
            base["partial_success_stage_advancement"] = self._normalized_partial_success_stage_advancement_map(
                base.get("partial_success_stage_advancement"),
                allowed_stages=self._partial_success_advancement_stages_for_task(overrides.get("task_type")),
                default_map=self._default_partial_success_stage_advancement_for_task(overrides.get("task_type")),
                strict=False,
            )
        selection_mode = str(overrides.get("module_selection_mode") or base.get("module_selection_mode") or MODULE_SELECTION_MODE_AUTO).strip()
        if selection_mode not in {MODULE_SELECTION_MODE_AUTO, MODULE_SELECTION_MODE_MANUAL_CONFIRM}:
            selection_mode = MODULE_SELECTION_MODE_AUTO
        base["module_selection_mode"] = selection_mode
        entry_selection_mode = str(overrides.get("entry_selection_mode") or base.get("entry_selection_mode") or ENTRY_SELECTION_MODE_AUTO).strip()
        if entry_selection_mode not in {ENTRY_SELECTION_MODE_AUTO, ENTRY_SELECTION_MODE_MANUAL_CONFIRM}:
            entry_selection_mode = ENTRY_SELECTION_MODE_AUTO
        base["entry_selection_mode"] = entry_selection_mode
        base["module_risk_levels"] = _normalize_module_risk_levels(overrides.get("module_risk_levels") or base.get("module_risk_levels"))
        return base

    def _max_retries_per_item(self, task: BinarySecurityTask) -> int:
        policy = dict(task.policy or {})
        if policy.get("max_retries_per_item") is not None:
            return max(0, int(policy.get("max_retries_per_item") or 0))
        return max(0, int(getattr(self.cfg.runtime_policy, "max_retries_per_item", 0) or 0))

    def _partial_success_advancement_stages_for_task(self, task: BinarySecurityTask | str | None) -> list[str]:
        stage_sequence = set(self._stage_sequence_for_task(task))
        return [stage_name for stage_name in PARTIAL_SUCCESS_ADVANCEMENT_STAGES if stage_name in stage_sequence]

    def _default_partial_success_stage_advancement_for_task(self, task: BinarySecurityTask | str | None) -> dict[str, bool]:
        return {
            stage_name: DEFAULT_PARTIAL_SUCCESS_STAGE_ADVANCEMENT[stage_name]
            for stage_name in self._partial_success_advancement_stages_for_task(task)
        }

    def _normalize_partial_success_stage_advancement_payload(
        self,
        raw: Any,
        *,
        allowed_stages: list[str] | tuple[str, ...],
    ) -> tuple[dict[str, bool], list[str]]:
        payload = dict(raw or {}) if isinstance(raw, dict) else {}
        allowed = set(allowed_stages)
        normalized: dict[str, bool] = {}
        invalid_stages: list[str] = []
        for stage_name, value in payload.items():
            canonical_stage = normalize_stage_name(stage_name)
            if canonical_stage not in allowed:
                invalid_stages.append(str(stage_name))
                continue
            normalized[canonical_stage] = bool(value)
        return normalized, invalid_stages

    def _normalized_partial_success_stage_advancement_map(
        self,
        raw: Any,
        *,
        allowed_stages: list[str] | tuple[str, ...],
        default_map: dict[str, bool],
        strict: bool = True,
    ) -> dict[str, bool]:
        allowed = list(allowed_stages)
        payload, invalid_stages = self._normalize_partial_success_stage_advancement_payload(
            raw,
            allowed_stages=allowed,
        )
        if invalid_stages and strict:
            raise ValidationError(f"阶段不支持配置部分成功推进: {invalid_stages[0]}")
        normalized = {stage_name: bool(default_map.get(stage_name, True)) for stage_name in allowed}
        for stage_name, value in payload.items():
            normalized[stage_name] = bool(value)
        return normalized

    def _validate_and_normalize_partial_success_stage_advancement_overrides(
        self,
        raw: Any,
        *,
        task_type: BinarySecurityTask | str | None,
    ) -> dict[str, bool]:
        allowed_stages = self._partial_success_advancement_stages_for_task(task_type)
        if not raw:
            return {}
        payload, invalid_stages = self._normalize_partial_success_stage_advancement_payload(
            raw,
            allowed_stages=allowed_stages,
        )
        if invalid_stages:
            raise ValidationError(f"阶段不属于当前任务流程: {invalid_stages[0]}")
        return payload

    def _partial_success_advancement_enabled(self, task: BinarySecurityTask, stage_name: str) -> bool:
        if stage_name not in PARTIAL_SUCCESS_ADVANCEMENT_STAGES:
            return True
        stage_map = self._normalized_partial_success_stage_advancement_map(
            self._effective_runtime_policy(task).get("partial_success_stage_advancement"),
            allowed_stages=self._partial_success_advancement_stages_for_task(task),
            default_map=self._default_partial_success_stage_advancement_for_task(task),
            strict=False,
        )
        return bool(stage_map.get(stage_name, True))

    def _task_base_policy(self, task: BinarySecurityTask) -> dict[str, Any]:
        return dict(task.policy or {})

    def _task_runtime_override(self, task: BinarySecurityTask) -> dict[str, Any]:
        return dict(getattr(task, "runtime_override", {}) or {})

    def _effective_runtime_policy(self, task: BinarySecurityTask) -> dict[str, Any]:
        base = json.loads(json.dumps(self._task_base_policy(task)))
        override = self._task_runtime_override(task)

        if override.get("stage_parallelism"):
            merged = dict(base.get("stage_parallelism") or {})
            for stage_name, value in dict(override.get("stage_parallelism") or {}).items():
                if stage_name in self._stage_sequence_for_task(task) and value is not None:
                    merged[stage_name] = max(1, int(value))
            base["stage_parallelism"] = merged
            if merged:
                base["max_stage_parallelism"] = max(int(v) for v in merged.values())

        if override.get("dispatch_throttle"):
            base["dispatch_throttle"] = {
                **dict(base.get("dispatch_throttle") or {}),
                **dict(override.get("dispatch_throttle") or {}),
            }
        if override.get("max_retries_per_item") is not None:
            base["max_retries_per_item"] = int(override["max_retries_per_item"])
        if override.get("continue_on_item_failure") is not None:
            base["continue_on_item_failure"] = bool(override["continue_on_item_failure"])
        if override.get("tail_reconcile_poll_interval_seconds") is not None:
            base["tail_reconcile_poll_interval_seconds"] = int(override["tail_reconcile_poll_interval_seconds"])
        return base

    def _runtime_policy_effect_scope(self, task: BinarySecurityTask) -> dict[str, str]:
        effective = self._effective_runtime_policy(task)
        stage_scope: dict[str, str] = {}
        for stage_name in self._stage_sequence_for_task(task):
            if stage_name in STREAMING_TAIL_STAGES:
                stage_scope[stage_name] = "tail_claim_immediate"
            elif stage_name == str(task.current_stage or "").strip():
                stage_scope[stage_name] = "next_dispatch_batch"
            else:
                stage_scope[stage_name] = "future_stage_only"
        if effective.get("tail_reconcile_poll_interval_seconds") is not None:
            stage_scope["_tail_reconcile_poll_interval_seconds"] = "tail_claim_immediate"
        if effective.get("dispatch_throttle"):
            stage_scope["_dispatch_throttle"] = "tail_claim_immediate"
        return stage_scope

    def _service_token(self) -> str | None:
        return self.cfg.auth_service.service_machine_token

    def _resolve_downstream_token(self, preferred_token: str | None = None) -> str | None:
        token = str(preferred_token or "").strip()
        if token:
            return token
        service_token = str(self._service_token() or "").strip()
        return service_token or None

    def _root_task_key_secret(self, task: BinarySecurityTask) -> str | None:
        summary = task.summary if isinstance(task.summary, dict) else {}
        runtime_keys = summary.get("runtime_task_keys") if isinstance(summary.get("runtime_task_keys"), dict) else {}
        secret = str(runtime_keys.get("root_task_key_secret") or "").strip()
        return secret or None

    async def _derive_downstream_work_key(
        self,
        *,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        service: str,
    ) -> dict[str, str] | None:
        root_secret = self._root_task_key_secret(task)
        if not root_secret:
            return None
        aigw_base = os.environ.get("SECFLOW_AIGW_BASE_URL") or os.environ.get("AIGW_BASE_URL") or "http://gaiasec-llm-gateway"
        client = await get_shared_async_client("binary-security-aigw-work-key", timeout=30)
        child_correlation_id = str(getattr(item, "downstream_task_id", "") or getattr(item, "id", "") or getattr(item, "item_key", "") or "").strip()
        payload = {
            "key_name": f"{str(service or '').strip()}-{child_correlation_id}",
            "sub_task_id": child_correlation_id,
            "max_concurrency": 0,
            "enabled": True,
            "description": f"work key for {task.id}/{str(service or '').strip()}/{str(getattr(item, 'stage_name', '') or '').strip()}",
        }
        try:
            response = await client.post(
                f"{aigw_base.rstrip('/')}/api/aigw/work-keys",
                json=payload,
                headers={
                    "Authorization": f"Bearer {root_secret}",
                    "Content-Type": "application/json",
                },
            )
        except httpx.TimeoutException as exc:
            raise UpstreamError("向 AI Gateway 派生 work key 超时") from exc
        except httpx.RequestError as exc:
            raise UpstreamError(f"向 AI Gateway 派生 work key 失败: {exc}") from exc
        if response.status_code not in (200, 201):
            raise UpstreamError(f"向 AI Gateway 派生 work key 失败: {response.status_code}")
        data = response.json() if response.content else {}
        if not isinstance(data, dict):
            raise UpstreamError("AI Gateway work key 响应格式错误")
        key_payload = data.get("key") if isinstance(data.get("key"), dict) else {}
        secret = str(data.get("secret") or "").strip()
        if not secret:
            raise UpstreamError("AI Gateway work key 响应缺少 secret")
        return {
            "agent_task_key_id": str(key_payload.get("id") or "").strip(),
            "agent_task_key_name": str(key_payload.get("key_name") or "").strip(),
            "agent_task_key_prefix": str(key_payload.get("key_prefix") or "").strip(),
            "agent_task_key_secret": secret,
            "agent_task_key_source": "schedule_dispatch",
        }

    def _task_runtime_phase(self, task: BinarySecurityTask) -> str:
        value = str(getattr(task, "runtime_phase", "") or "").strip()
        if value in {
            TASK_RUNTIME_PHASE_OWNED_EXECUTION,
            TASK_RUNTIME_PHASE_TAIL_RECONCILIATION,
            TASK_RUNTIME_PHASE_TERMINAL,
        }:
            return value
        status = str(getattr(task, "status", "") or "").strip().lower()
        if status in TASK_TERMINAL_STATUSES:
            return TASK_RUNTIME_PHASE_TERMINAL
        return TASK_RUNTIME_PHASE_OWNED_EXECUTION

    def _set_task_runtime_phase(self, task: BinarySecurityTask, phase: str) -> None:
        task.runtime_phase = str(phase or "").strip() or TASK_RUNTIME_PHASE_OWNED_EXECUTION

    def _task_control_mode(self, task: BinarySecurityTask) -> str:
        phase = self._task_runtime_phase(task)
        if phase == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION:
            return TASK_RUNTIME_PHASE_TAIL_RECONCILIATION
        if phase == TASK_RUNTIME_PHASE_TERMINAL:
            return TASK_RUNTIME_PHASE_TERMINAL
        return TASK_RUNTIME_PHASE_OWNED_EXECUTION

    def _dispatch_token(self, task: BinarySecurityTask) -> str | None:
        return task.dispatch_started_at.isoformat() if task.dispatch_started_at else None

    def _bind_execution_token(self, task: BinarySecurityTask) -> None:
        setattr(task, "_execution_dispatcher_id", task.dispatcher_instance_id)
        setattr(task, "_execution_token", self._dispatch_token(task))

    def _ensure_owned_execution_current(self, task: BinarySecurityTask) -> None:
        expected_dispatcher_id = getattr(task, "_execution_dispatcher_id", None)
        expected_token = getattr(task, "_execution_token", None)
        if expected_dispatcher_id is None and expected_token is None and not task.dispatcher_instance_id and not task.dispatch_started_at:
            return
        expected_dispatcher_id = expected_dispatcher_id or task.dispatcher_instance_id
        expected_token = expected_token or self._dispatch_token(task)
        if not expected_dispatcher_id or not expected_token:
            raise StaleTaskExecution(f"任务 {task.id} 缺少当前执行 token")
        session = get_session_factory()()
        try:
            row = session.query(BinarySecurityTask).filter(BinarySecurityTask.id == task.id).first()
            current_token = row.dispatch_started_at.isoformat() if row and row.dispatch_started_at else None
            if (
                row is None
                or row.status not in {"dispatching", "running"}
                or row.dispatcher_instance_id != expected_dispatcher_id
                or current_token != expected_token
                or not self._lease_is_active(row)
            ):
                raise StaleTaskExecution(f"任务 {task.id} 当前执行 token 已失效")
        finally:
            session.close()

    def _ensure_tail_reconciliation_current(self, task: BinarySecurityTask) -> None:
        session = get_session_factory()()
        try:
            row = session.query(BinarySecurityTask).filter(BinarySecurityTask.id == task.id).first()
            if row is None:
                raise StaleTaskExecution(f"任务 {task.id} 不存在")
            if self._task_runtime_phase(row) != TASK_RUNTIME_PHASE_TAIL_RECONCILIATION:
                raise StaleTaskExecution(f"任务 {task.id} 当前 tail 收敛上下文已失效")
            if str(row.status or "").strip().lower() in TASK_TERMINAL_STATUSES:
                raise StaleTaskExecution(f"任务 {task.id} 已进入终态")
            lease = self._runtime_lease_for_task(session, task.id)
            if not self._runtime_lease_is_active(lease):
                raise StaleTaskExecution(f"任务 {task.id} 当前 tail 收敛 lease 已失效")
            if str(lease.owner_instance_id or "").strip() != str(self.instance_id or "").strip():
                self._release_tail_reconcile_owner(task.id)
                raise StaleTaskExecution(f"任务 {task.id} 当前 tail 收敛 owner 已变更")
            active_stage_name, active_item_count, has_downstream_refs = self._streaming_tail_active_context(session, row)
            if active_item_count <= 0 and not has_downstream_refs:
                raise StaleTaskExecution(f"任务 {task.id} 当前 tail 收敛上下文已结束")
        finally:
            session.close()

    def _ensure_task_execution_current(self, task: BinarySecurityTask) -> None:
        phase = self._task_runtime_phase(task)
        if phase == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION:
            self._ensure_tail_reconciliation_current(task)
            return
        self._ensure_owned_execution_current(task)

    async def _ensure_task_execution_current_async(self, task: BinarySecurityTask) -> None:
        await asyncio.to_thread(self._ensure_task_execution_current, task)

    def _invalidate_task_execution(self, task: BinarySecurityTask) -> None:
        task.dispatcher_instance_id = None
        task.dispatch_started_at = None
        task.lease_expires_at = None
        self._last_task_heartbeat_at.pop(task.id, None)

    def _task_has_active_streaming_stage_workers(self, task_id: str) -> bool:
        if self._task_execution_owner_count(task_id) > 0:
            with self._task_execution_owner_lock:
                owners = set(self._task_execution_owners.get(task_id) or ())
            if any(owner.startswith("streaming_stage_item:") for owner in owners):
                return True
        active_worker_item_ids = {
            str(item_id or "")
            for item_id, worker in self._stage_item_workers.items()
            if not worker.done() and str(item_id or "").strip()
        }
        if not active_worker_item_ids:
            return False
        session = get_session_factory()()
        try:
            active_item_ids = {
                str(row.id)
                for row in session.query(BinarySecurityStageItem).filter(
                    BinarySecurityStageItem.task_id == task_id,
                    BinarySecurityStageItem.stage_name.in_(list(STREAMING_TAIL_STAGES)),
                    BinarySecurityStageItem.status.in_(list(STREAMING_ACTIVE_ITEM_STATUSES)),
                ).all()
            }
        finally:
            session.close()
        if not active_item_ids:
            return False
        return bool(active_worker_item_ids.intersection(active_item_ids))

    def _streaming_tail_active_context(
        self,
        db: Session,
        task: BinarySecurityTask,
    ) -> tuple[str | None, int, bool]:
        summary = self._tail_stage_work_summary(db, task)
        return (
            summary.get("active_stage_name"),
            int(summary.get("unbound_runnable_item_count", 0) or 0) + int(summary.get("bound_active_item_count", 0) or 0),
            bool(summary.get("has_downstream_refs")),
        )

    def _task_has_active_streaming_tail_state(self, db: Session, task: BinarySecurityTask) -> bool:
        _, active_item_count, _ = self._streaming_tail_active_context(db, task)
        return active_item_count > 0

    def _recover_streaming_parent_running_state_locked(
        self,
        db: Session,
        task: BinarySecurityTask,
        *,
        record_event: bool = False,
        reason: str | None = None,
    ) -> bool:
        summary = self._tail_stage_work_summary(db, task)
        active_stage_name = summary.get("active_stage_name")
        active_item_count = int(summary.get("unbound_runnable_item_count", 0) or 0) + int(summary.get("bound_active_item_count", 0) or 0)
        has_downstream_refs = bool(summary.get("has_downstream_refs"))
        if active_item_count <= 0:
            return False
        previous_status = str(task.status or "").strip()
        previous_dispatcher = str(task.dispatcher_instance_id or "").strip() or None
        task.status = "running"
        task.current_stage = active_stage_name or task.current_stage
        task.finished_at = None
        task.last_error = None
        if self._tail_requires_execution_takeover(db, task):
            self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
            task.tail_reconcile_state = "idle"
            if not self._should_preserve_task_dispatch_ownership(task, previous_status=previous_status):
                task.dispatcher_instance_id = None
                task.dispatch_started_at = None
                task.lease_expires_at = None
        else:
            self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_TAIL_RECONCILIATION)
            task.dispatcher_instance_id = None
            task.dispatch_started_at = None
            task.lease_expires_at = None
            lease = self._activate_tail_reconciliation(
                db,
                task,
                now_value=_now(),
                fallback_status="pending",
                takeover_result="recovered",
            )
            if not self._runtime_lease_is_active(lease):
                task.status = "running"
        self._clear_task_abnormal_reason_snapshot(db, task)
        if record_event:
            self._record_event(
                db,
                task,
                "streaming_parent_state_recovered",
                f"流式尾段存在活跃子项，父任务状态已收敛为 running: {task.current_stage}",
                level="warning",
                stage_name=task.current_stage,
                payload={
                    "from_status": previous_status,
                    "to_status": task.status,
                    "active_stage_name": task.current_stage,
                    "active_item_count": active_item_count,
                    "had_downstream_refs": has_downstream_refs,
                    "previous_dispatcher_instance_id": previous_dispatcher,
                    "tail_control_mode": summary.get("tail_control_mode"),
                    "runtime_lease_established": self._task_runtime_phase(task) == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION,
                    "reason": reason,
                },
            )
            observe_streaming_parent_recovered(
                stage=str(task.current_stage or "unknown"),
                from_status=previous_status or "unknown",
            )
        return True

    def _release_streaming_parent_for_takeover_locked(
        self,
        db: Session,
        task: BinarySecurityTask,
        *,
        runtime_lease_owner: str | None,
        runtime_lease_expires_at: datetime | None,
        reason: str,
    ) -> bool:
        summary = self._tail_stage_work_summary(db, task)
        active_stage_name = summary.get("active_stage_name")
        active_item_count = int(summary.get("unbound_runnable_item_count", 0) or 0) + int(summary.get("bound_active_item_count", 0) or 0)
        has_downstream_refs = bool(summary.get("has_downstream_refs"))
        if active_item_count <= 0:
            return False
        previous_dispatcher = str(task.dispatcher_instance_id or "").strip() or None
        task.status = "pending"
        task.current_stage = active_stage_name or task.current_stage
        task.dispatcher_instance_id = None
        task.dispatch_started_at = None
        task.lease_expires_at = None
        task.finished_at = None
        task.last_error = None
        self._clear_runtime_lease(db, task.id)
        self._clear_task_abnormal_reason_snapshot(db, task)
        self._record_event(
            db,
            task,
            "running_execution_released_for_takeover",
            "运行实例租约已失效，父任务已释放并重新排队，等待新的 worker 继续推进尾段执行",
            level="warning",
            stage_name=task.current_stage,
            payload={
                "stage_name": task.current_stage,
                "previous_dispatcher_instance_id": previous_dispatcher,
                "runtime_lease_owner": runtime_lease_owner,
                "runtime_lease_expires_at": _isoformat_or_none(runtime_lease_expires_at),
                "active_item_count": active_item_count,
                "has_downstream_refs": has_downstream_refs,
                "tail_control_mode": summary.get("tail_control_mode"),
                "requeue_reason": reason,
            },
        )
        return True

    def _task_operation_token(self) -> str:
        return uuid.uuid4().hex

    def _task_operation_lock_expires_at(self, *, now_value: datetime | None = None, ttl_seconds: int = TASK_OPERATION_LOCK_TTL_SECONDS) -> datetime:
        base = now_value or _now()
        effective_ttl = self._operation_lease_ttl_seconds() if ttl_seconds == TASK_OPERATION_LOCK_TTL_SECONDS else max(30, int(ttl_seconds))
        return base + timedelta(seconds=effective_ttl)

    def _raise_task_operation_locked(self, task_id: str) -> None:
        connection = get_engine().connect()
        try:
            row = connection.execute(
                text(
                    f"SELECT operation_lock_type, operation_lock_owner, operation_lock_expires_at "
                    f"FROM {BinarySecurityTask.__tablename__} WHERE id = :task_id"
                ),
                {"task_id": task_id},
            ).first()
        finally:
            connection.close()
        if row:
            lock_type = str(row[0] or "unknown").strip() or "unknown"
            owner = str(row[1] or "").strip()
            expires_at = row[2]
            owner_suffix = f"，持有实例 {owner}" if owner else ""
            expires_suffix = f"，预计释放时间 {expires_at}" if expires_at else ""
            raise ValidationError(f"当前任务正在执行 {lock_type} 操作{owner_suffix}{expires_suffix}，请稍后重试")
        raise ValidationError("当前任务正被其他操作修改，请稍后重试")

    def _acquire_task_operation_lease(
        self,
        db: Session,
        task_id: str,
        *,
        operation: str,
        ttl_seconds: int = TASK_OPERATION_LOCK_TTL_SECONDS,
    ) -> str:
        if not isinstance(db, Session):
            connection_factory = getattr(db, "connection", None)
            if not callable(connection_factory):
                return "test-operation-token"
            connection = connection_factory()
            lock_name = f"secflow_binary_security_task_lock:{task_id}"
            acquired = bool(
                connection.execute(
                    text("SELECT GET_LOCK(:name, :timeout)"),
                    {"name": lock_name, "timeout": 1},
                ).scalar()
            )
            if not acquired:
                raise ValidationError("当前任务正被其他操作修改，请稍后重试")
            return lock_name

        now_value = _now()
        expires_at = self._task_operation_lock_expires_at(now_value=now_value, ttl_seconds=ttl_seconds)
        token = self._task_operation_token()
        with get_engine().begin() as connection:
            result = connection.execute(
                text(
                    f"""
                    UPDATE {BinarySecurityTask.__tablename__}
                       SET operation_lock_owner = :owner,
                           operation_lock_token = :token,
                           operation_lock_type = :operation,
                           operation_lock_acquired_at = :now_value,
                           operation_lock_heartbeat_at = :now_value,
                           operation_lock_expires_at = :expires_at,
                           updated_at = :now_value
                     WHERE id = :task_id
                       AND (
                            operation_lock_expires_at IS NULL
                            OR operation_lock_expires_at < :now_value
                       )
                    """
                ),
                {
                    "owner": self.instance_id,
                    "token": token,
                    "operation": operation,
                    "now_value": now_value,
                    "expires_at": expires_at,
                    "task_id": task_id,
                },
            )
        if int(getattr(result, "rowcount", 0) or 0) != 1:
            self._raise_task_operation_locked(task_id)
        return token

    def _renew_task_operation_lease(
        self,
        task_id: str,
        *,
        token: str,
        operation: str,
        ttl_seconds: int = TASK_OPERATION_LOCK_TTL_SECONDS,
    ) -> bool:
        now_value = _now()
        expires_at = self._task_operation_lock_expires_at(now_value=now_value, ttl_seconds=ttl_seconds)
        with get_engine().begin() as connection:
            result = connection.execute(
                text(
                    f"""
                    UPDATE {BinarySecurityTask.__tablename__}
                       SET operation_lock_owner = :owner,
                           operation_lock_type = :operation,
                           operation_lock_heartbeat_at = :now_value,
                           operation_lock_expires_at = :expires_at,
                           updated_at = :now_value
                     WHERE id = :task_id
                       AND operation_lock_token = :token
                    """
                ),
                {
                    "owner": self.instance_id,
                    "operation": operation,
                    "now_value": now_value,
                    "expires_at": expires_at,
                    "task_id": task_id,
                    "token": token,
                },
            )
        return int(getattr(result, "rowcount", 0) or 0) == 1

    def _release_task_operation_lease(self, db: Session, task_id: str, *, token: str) -> None:
        if not isinstance(db, Session):
            connection_factory = getattr(db, "connection", None)
            if not callable(connection_factory):
                return
            connection = connection_factory()
            try:
                connection.execute(
                    text("SELECT RELEASE_LOCK(:name)"),
                    {"name": token},
                )
            finally:
                close_fn = getattr(connection, "close", None)
                if callable(close_fn):
                    close_fn()
            return

        now_value = _now()
        with get_engine().begin() as connection:
            connection.execute(
                text(
                    f"""
                    UPDATE {BinarySecurityTask.__tablename__}
                       SET operation_lock_owner = NULL,
                           operation_lock_token = NULL,
                           operation_lock_type = NULL,
                           operation_lock_acquired_at = NULL,
                           operation_lock_heartbeat_at = NULL,
                           operation_lock_expires_at = NULL,
                           updated_at = :now_value
                     WHERE id = :task_id
                       AND operation_lock_token = :token
                    """
                ),
                {
                    "now_value": now_value,
                    "task_id": task_id,
                    "token": token,
                },
            )

    @contextmanager
    def _task_operation_lock(self, db: Session, task_id: str, *, operation: str, ttl_seconds: int = TASK_OPERATION_LOCK_TTL_SECONDS):
        token = self._acquire_task_operation_lease(db, task_id, operation=operation, ttl_seconds=ttl_seconds)
        try:
            yield token
        finally:
            self._release_task_operation_lease(db, task_id, token=token)

    @contextmanager
    def _savepoint(self, db: Session):
        begin_nested = getattr(db, "begin_nested", None)
        if not callable(begin_nested):
            yield None
            return
        nested = begin_nested()
        try:
            yield nested
        except Exception:
            nested.rollback()
            raise

    def _is_retryable_lock_error(self, exc: BaseException) -> bool:
        current: BaseException | None = exc
        while current is not None:
            if isinstance(current, OperationalError):
                args = getattr(getattr(current, "orig", None), "args", ()) or ()
                code = args[0] if args else None
                message = str(current).lower()
                if code in {1205, 1213}:
                    return True
                if "lock wait timeout" in message or "deadlock found" in message:
                    return True
            current = getattr(current, "__cause__", None) or getattr(current, "orig", None)
        return False

    def _retryable_write_attempts(self, max_retries: int | None = None) -> int:
        retries = 3 if max_retries is None else int(max_retries)
        return max(1, retries)

    def _next_stage_sync_retry_backoff_seconds(self, consecutive_error_count: int) -> int:
        exponent = max(0, int(consecutive_error_count) - 1)
        backoff = self._stage_downstream_sync_backoff_base_seconds() * (2 ** exponent)
        return min(self._stage_downstream_sync_backoff_max_seconds(), max(1, int(backoff)))

    def _next_http_429_retry_backoff_seconds(self, consecutive_error_count: int) -> int:
        sequence = (5, 10, 15, 20, 25, 30)
        index = max(0, int(consecutive_error_count) - 1)
        if index >= len(sequence):
            return sequence[-1]
        return sequence[index]

    def _read_stage_item_sync_supervisor_state(self, item: BinarySecurityStageItem) -> DownstreamSyncSupervisorState:
        result = self._load_stage_item_result_payload(item)
        sync_observation = self._stage_item_sync_observation(item)
        consecutive = sync_observation.get("consecutive_error_count")
        if consecutive is None:
            consecutive = result.get("consecutive_sync_error_count")
        exhausted = sync_observation.get("budget_exhausted")
        if exhausted is None:
            exhausted = result.get("sync_error_budget_exhausted")
        last_result = self._string_or_none(sync_observation.get("last_result")) or self._string_or_none(result.get("last_sync_result"))
        return DownstreamSyncSupervisorState(
            consecutive_error_count=max(0, int(consecutive or 0)),
            budget_exhausted=bool(exhausted),
            next_retry_at=self._stage_item_next_sync_retry_at_value(item),
            last_result=last_result,
        )

    def _downstream_sync_failure_payload(
        self,
        item: BinarySecurityStageItem,
        *,
        error_type: str,
        error_message: str,
        state: DownstreamSyncSupervisorState,
    ) -> dict[str, Any]:
        return {
            "item_id": str(item.id or ""),
            "stage_name": str(item.stage_name or ""),
            "downstream_task_id": str(item.downstream_task_id or ""),
            "consecutive_sync_error_count": state.consecutive_error_count,
            "last_sync_error_type": error_type,
            "last_sync_error_message": error_message,
            "next_sync_retry_at": _isoformat_or_none(state.next_retry_at),
            "sync_error_budget_exhausted": state.budget_exhausted,
        }

    def _build_next_downstream_sync_failure_state(
        self,
        item: BinarySecurityStageItem,
        *,
        observed_at: datetime | None = None,
    ) -> DownstreamSyncSupervisorState:
        previous = self._read_stage_item_sync_supervisor_state(item)
        consecutive = previous.consecutive_error_count + 1
        budget_exhausted = consecutive >= self._stage_downstream_sync_max_consecutive_errors()
        retry_at = (observed_at or _now()) + timedelta(seconds=self._next_stage_sync_retry_backoff_seconds(consecutive))
        return DownstreamSyncSupervisorState(
            consecutive_error_count=consecutive,
            budget_exhausted=budget_exhausted,
            next_retry_at=retry_at,
            last_result="error",
        )

    def _build_next_http_429_failure_state(
        self,
        item: BinarySecurityStageItem,
        *,
        observed_at: datetime | None = None,
    ) -> DownstreamSyncSupervisorState:
        previous = self._read_stage_item_sync_supervisor_state(item)
        consecutive = previous.consecutive_error_count + 1
        retry_at = (observed_at or _now()) + timedelta(seconds=self._next_http_429_retry_backoff_seconds(consecutive))
        return DownstreamSyncSupervisorState(
            consecutive_error_count=consecutive,
            budget_exhausted=False,
            next_retry_at=retry_at,
            last_result="error",
        )

    def _sleep_after_retryable_lock_error(self, attempt: int) -> None:
        attempt_no = max(1, int(attempt))
        backoff_seconds = {1: 1.0, 2: 3.0, 3: 5.0}.get(attempt_no, 5.0)
        time.sleep(backoff_seconds)

    def _delete_stage_items_for_stages(
        self,
        db: Session,
        task_id: str,
        stage_names: list[str],
        *,
        batch_size: int = 100,
        max_retries: int = 3,
    ) -> int:
        normalized = self._expand_stage_name_aliases(stage_names)
        if not normalized:
            return 0
        if hasattr(db, "stage_items") and isinstance(getattr(db, "stage_items"), list):
            allowed_stage_names = set(normalized)
            matching = [
                row
                for row in db.stage_items
                if str(getattr(row, "task_id", "") or "").strip() == task_id
                and str(getattr(row, "stage_name", "") or "").strip() in allowed_stage_names
            ]
            if matching:
                db.stage_items = [row for row in db.stage_items if row not in matching]
                return len(matching)
        deleted = 0
        while True:
            item_ids = [
                row[0]
                for row in db.query(BinarySecurityStageItem.id)
                .filter(
                    BinarySecurityStageItem.task_id == task_id,
                    BinarySecurityStageItem.stage_name.in_(normalized),
                )
                .order_by(BinarySecurityStageItem.created_at.asc(), BinarySecurityStageItem.id.asc())
                .limit(max(1, int(batch_size)))
                .all()
            ]
            if not item_ids:
                if hasattr(db, "stage_items") and isinstance(getattr(db, "stage_items"), list):
                    allowed_stage_names = set(normalized)
                    db.stage_items = [
                        row for row in db.stage_items
                        if not (
                            str(getattr(row, "task_id", "") or "").strip() == task_id
                            and str(getattr(row, "stage_name", "") or "").strip() in allowed_stage_names
                        )
                    ]
                return deleted
            for attempt in range(max(1, int(max_retries))):
                try:
                    with self._savepoint(db):
                        deleted += int(
                            db.query(BinarySecurityStageItem)
                            .filter(BinarySecurityStageItem.id.in_(item_ids))
                            .delete(synchronize_session=False)
                            or 0
                        )
                        db.flush()
                    break
                except OperationalError as exc:
                    if not self._is_retryable_lock_error(exc) or attempt >= max(1, int(max_retries)) - 1:
                        raise
                    time.sleep(0.2 * (attempt + 1))
    def _delete_stage_items_by_ids(self, db: Session, item_ids: list[str]) -> int:
        normalized = [str(item_id or "").strip() for item_id in item_ids if str(item_id or "").strip()]
        if not normalized:
            return 0
        return int(
            db.query(BinarySecurityStageItem)
            .filter(BinarySecurityStageItem.id.in_(normalized))
            .delete(synchronize_session=False)
            or 0
        )

    def _stage_enabled(self, task: BinarySecurityTask, stage_name: str) -> bool:
        stage_name = normalize_stage_name(stage_name)
        policy = task.policy or {}
        stage_options = policy.get("stage_options", {})
        option = stage_options.get(stage_name)
        if option is None:
            return True
        return bool(option.get("enabled", True))

    def _b2s_execution_mode(self, task: BinarySecurityTask) -> tuple[str | None, str | None]:
        policy = task.policy or {}
        stage_options = policy.get("stage_options", {}) if isinstance(policy.get("stage_options"), dict) else {}
        option = stage_options.get("binary_to_source") if isinstance(stage_options.get("binary_to_source"), dict) else {}
        raw_mode = option.get("mode") or policy.get("b2s_mode")
        mode = str(raw_mode or "").strip().lower()
        if not mode:
            return None, None
        if mode == "turbo":
            return "turbo", "turbo"
        if mode in {"deep", "agent"}:
            return "deep", "agent"
        if mode in {"fast", "hybrid"}:
            return "fast", "hybrid"
        return None, None

    def _pipeline_mode(self, task: BinarySecurityTask | dict[str, Any] | None) -> str:
        if isinstance(task, dict):
            policy = task
        else:
            policy = (getattr(task, "policy", None) if task is not None else {}) or {}
        value = policy.get("pipeline_mode")
        if value is None:
            value = getattr(self.cfg.runtime_policy, "pipeline_mode", PIPELINE_MODE_BARRIER)
        return _normalize_pipeline_mode(value)

    def _streaming_mode_enabled(self, task: BinarySecurityTask | dict[str, Any] | None) -> bool:
        return self._pipeline_mode(task) == PIPELINE_MODE_MIXED_STREAMING

    def _streaming_tail_stage_names(self, task: BinarySecurityTask) -> tuple[str, ...]:
        return tuple(
            stage_name
            for stage_name in STREAMING_TAIL_STAGES
            if stage_name in self._stage_sequence_for_task(task) and self._stage_enabled(task, stage_name)
        )

    def _is_streaming_tail_stage(self, task: BinarySecurityTask, stage_name: str | None) -> bool:
        normalized = str(stage_name or "").strip()
        return bool(normalized) and normalized in self._streaming_tail_stage_names(task)

    def _streaming_has_active_upstream_stage(
        self,
        task: BinarySecurityTask,
        stage_runs: list[BinarySecurityStageRun],
    ) -> tuple[bool, str | None, str | None]:
        if not self._streaming_mode_enabled(task):
            return False, None, None
        active_statuses = {"pending", "queued", "running", "dispatching", "applying"}
        runs_by_stage = {run.stage_name: run for run in stage_runs}
        active_candidates: list[tuple[str, str]] = []
        for stage_name in self._stage_sequence_for_task(task):
            if not self._stage_enabled(task, stage_name):
                continue
            if self._is_streaming_tail_stage(task, stage_name):
                continue
            run = runs_by_stage.get(stage_name)
            if run is None:
                active_candidates.append((stage_name, "pending"))
                continue
            normalized_status = self._normalize_downstream_status(run.status) or str(run.status or "").strip()
            if normalized_status in active_statuses:
                active_candidates.append((stage_name, normalized_status))
        if active_candidates:
            stage_name, normalized_status = active_candidates[-1]
            return True, stage_name, normalized_status
        return False, None, None

    def _has_any_active_incomplete_stage(
        self,
        task: BinarySecurityTask,
        stage_runs: list[BinarySecurityStageRun],
    ) -> tuple[bool, str | None, str | None]:
        active_statuses = {"pending", "queued", "running", "dispatching", "applying"}
        runs_by_stage = {run.stage_name: run for run in stage_runs}
        task_retry_target_stage = (
            str(task.target_stage_name or "").strip()
            if task.execution_mode in {"task_retry", "task_retry_failed_items"} and str(task.target_stage_name or "").strip()
            else None
        )
        active_candidates: list[tuple[str, str]] = []
        for stage_name in self._stage_sequence_for_task(task):
            if not self._stage_enabled(task, stage_name):
                continue
            run = runs_by_stage.get(stage_name)
            if run is None:
                continue
            normalized_status = self._normalize_downstream_status(run.status) or str(run.status or "").strip()
            if task_retry_target_stage and stage_name == task_retry_target_stage and normalized_status == "success":
                continue
            if normalized_status in active_statuses:
                active_candidates.append((stage_name, normalized_status))
        if active_candidates:
            stage_name, normalized_status = active_candidates[-1]
            return True, stage_name, normalized_status
        return False, None, None

    def _is_streaming_active_item_status(self, status: str | None) -> bool:
        normalized = self._normalize_downstream_status(status) or str(status or "").strip()
        return normalized in STREAMING_ACTIVE_ITEM_STATUSES

    def _stage_parallelism(self, task: BinarySecurityTask, stage_name: str) -> int:
        policy = self._effective_runtime_policy(task)
        stage_parallelism = policy.get("stage_parallelism") or {}
        if stage_name in stage_parallelism:
            return max(1, int(stage_parallelism[stage_name]))
        return max(1, int(policy.get("max_stage_parallelism") or 1))

    def _module_selection_mode(self, task: BinarySecurityTask) -> str:
        mode = str((task.policy or {}).get("module_selection_mode") or MODULE_SELECTION_MODE_AUTO).strip()
        if mode not in {MODULE_SELECTION_MODE_AUTO, MODULE_SELECTION_MODE_MANUAL_CONFIRM}:
            return MODULE_SELECTION_MODE_AUTO
        return mode

    def _entry_selection_mode(self, task: BinarySecurityTask) -> str:
        mode = str((task.policy or {}).get("entry_selection_mode") or ENTRY_SELECTION_MODE_AUTO).strip()
        if mode not in {ENTRY_SELECTION_MODE_AUTO, ENTRY_SELECTION_MODE_MANUAL_CONFIRM}:
            return ENTRY_SELECTION_MODE_AUTO
        return mode

    def _module_risk_levels(self, task: BinarySecurityTask) -> list[str]:
        return _normalize_module_risk_levels((task.policy or {}).get("module_risk_levels"))

    def _module_selection_candidate_levels(self, task: BinarySecurityTask) -> list[str]:
        if self._module_selection_mode(task) == MODULE_SELECTION_MODE_MANUAL_CONFIRM:
            return list(ALLOWED_MODULE_RISK_LEVELS)
        return self._module_risk_levels(task)

    def _mark_selected_modules(self, modules: list[dict[str, Any]], *, selected_by: str, selected_at: str | None = None) -> list[dict[str, Any]]:
        timestamp = selected_at or _now().isoformat()
        return [
            {
                **module,
                "selected_by": selected_by,
                "selected_at": timestamp,
            }
            for module in modules
        ]

    def _entry_selection_snapshot(self, task: BinarySecurityTask) -> dict[str, Any]:
        snapshot = (task.summary or {}).get("entry_selection")
        return dict(snapshot) if isinstance(snapshot, dict) else {}

    def _entry_results(self, task: BinarySecurityTask) -> list[dict[str, Any]]:
        return [dict(item) for item in (task.summary.get("entry_results") or []) if isinstance(item, dict)]

    def _entry_candidates(self, task: BinarySecurityTask) -> list[dict[str, Any]]:
        snapshot = self._entry_selection_snapshot(task)
        candidate_entries = snapshot.get("candidate_entries")
        if isinstance(candidate_entries, list) and candidate_entries:
            return [dict(item) for item in candidate_entries if isinstance(item, dict)]
        return self._entry_results(task)

    def _selected_entry_keys(self, task: BinarySecurityTask) -> list[str]:
        snapshot = self._entry_selection_snapshot(task)
        return [
            str(key).strip()
            for key in (snapshot.get("selected_entry_keys") or [])
            if str(key).strip()
        ]

    def _selected_entries(self, task: BinarySecurityTask) -> list[dict[str, Any]]:
        snapshot = self._entry_selection_snapshot(task)
        return [dict(item) for item in (snapshot.get("selected_entries") or []) if isinstance(item, dict)]

    def _mark_selected_entries(self, entries: list[dict[str, Any]], *, selected_by: str, selected_at: str | None = None) -> list[dict[str, Any]]:
        timestamp = selected_at or _now().isoformat()
        return [
            {
                **entry,
                "selected_by": selected_by,
                "selected_at": timestamp,
            }
            for entry in entries
        ]

    def _effective_entry_inputs(self, task: BinarySecurityTask) -> list[dict[str, Any]]:
        if self._entry_selection_mode(task) == ENTRY_SELECTION_MODE_AUTO:
            return self._entry_candidates(task)
        selected_entries = self._selected_entries(task)
        if selected_entries:
            return selected_entries
        selected_keys = set(self._selected_entry_keys(task))
        if not selected_keys:
            return []
        return [
            entry
            for entry in self._entry_candidates(task)
            if str(entry.get("entry_key") or "").strip() in selected_keys
        ]

    def _entry_selection_metrics(self, task: BinarySecurityTask) -> dict[str, int]:
        return {
            "candidate_entry_count": len(self._entry_candidates(task)),
            "selected_entry_count": len(self._effective_entry_inputs(task)) if self._entry_selection_mode(task) == ENTRY_SELECTION_MODE_MANUAL_CONFIRM else len(self._entry_candidates(task)),
        }

    def _filter_candidate_modules(self, modules: list[dict[str, Any]], risk_levels: list[str]) -> list[dict[str, Any]]:
        allowed = set(_normalize_module_risk_levels(risk_levels))
        return [dict(module) for module in modules if str(module.get("risk_level") or "").strip() in allowed]

    def _module_metrics(self, modules: list[dict[str, Any]], candidate_modules: list[dict[str, Any]], selected_modules: list[dict[str, Any]]) -> dict[str, int]:
        return {
            "high_risk_module_count": sum(1 for module in modules if str(module.get("risk_level") or "").strip() == "高"),
            "medium_risk_module_count": sum(1 for module in modules if str(module.get("risk_level") or "").strip() == "中"),
            "low_risk_module_count": sum(1 for module in modules if str(module.get("risk_level") or "").strip() == "低"),
            "candidate_module_count": len(candidate_modules),
            "selected_module_count": len(selected_modules),
        }

    def _task_or_404(self, db: Session, project_id: str, task_id: str) -> BinarySecurityTask:
        task = db.query(BinarySecurityTask).filter(
            BinarySecurityTask.project_id == project_id,
            BinarySecurityTask.id == task_id,
        ).first()
        if not task:
            raise NotFoundError("任务不存在")
        return task

    async def _readless_reconcile_loop(self) -> None:
        interval_seconds = max(300, int(getattr(self.cfg.scheduler, "readless_reconcile_interval_seconds", 300) or 300))
        await run_readless_sync_loop(
            should_stop=lambda: not self._running,
            interval_seconds=interval_seconds,
            before_tick=self._before_readless_reconcile_tick,
            candidate_ids_loader=self._load_readless_reconcile_candidate_ids,
            process_one=self._process_readless_reconcile_task,
            observe=self._observe_readless_reconcile_stats,
            loop_context=observe_scheduler_loop,
            loop_name="readless_reconcile",
        )

    async def _before_readless_reconcile_tick(self) -> bool:
        self._mark_loop_heartbeat("readless_reconcile")
        return True

    def _load_readless_reconcile_candidate_ids(self) -> list[str]:
        candidate_session = get_session_factory()()
        try:
            return [
                str(task_id)
                for (task_id,) in candidate_session.query(BinarySecurityTask.id)
                .filter(BinarySecurityTask.status.in_(["pending", "running", "dispatching"]))
                .order_by(BinarySecurityTask.updated_at.asc(), BinarySecurityTask.created_at.asc())
                .limit(64)
                .all()
            ]
        finally:
            candidate_session.close()

    def _process_readless_reconcile_task_sync(self, task_id: str) -> tuple[bool, bool]:
        session = get_session_factory()()
        try:
            task = session.query(BinarySecurityTask).filter(BinarySecurityTask.id == task_id).first()
            if task is None:
                return False, False
            if (
                self._task_runtime_phase(task) == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION
                and not self._is_reducer_role()
                and not self._tail_requires_execution_takeover(session, task)
            ):
                session.rollback()
                return True, False
            if self._should_skip_readless_reconcile_for_active_task(task):
                session.rollback()
                return True, False
            before_status = str(task.status or "").strip()
            before_stage = str(task.current_stage or "").strip()
            before_phase = self._task_runtime_phase(task)
            self._refresh_task_status_after_sync(session, task)
            changed = (
                str(task.status or "").strip() != before_status
                or str(task.current_stage or "").strip() != before_stage
                or self._task_runtime_phase(task) != before_phase
            )
            if self._tail_requires_execution_takeover(session, task):
                self._record_event(
                    session,
                    task,
                    "tail_execution_takeover_required",
                    "检测到流式尾段仍有未绑定子项，任务将回到 worker 接管继续执行",
                    level="warning",
                    stage_name=task.current_stage,
                    payload={
                        "tail_control_mode": "execution_takeover",
                        "reason": "runnable_unbound_tail_items",
                    },
                )
                self._enqueue_task(task.id)
            session.commit()
            return True, changed
        except Exception:
            session.rollback()
            raise
        finally:
            session.close()

    async def _process_readless_reconcile_task(self, task_id: str) -> tuple[bool, bool]:
        result = await asyncio.to_thread(self._process_readless_reconcile_task_sync, task_id)
        self._mark_loop_heartbeat("readless_reconcile")
        return result

    def _observe_readless_reconcile_stats(self, stats: ReadlessSyncStats) -> None:
        observe_task_readless_reconcile(
            attempted=stats.attempted,
            changed=stats.changed,
            failed=stats.failed,
            candidates=stats.candidates,
        )

    def _ensure_stage_run(self, db: Session, task: BinarySecurityTask, stage_name: str) -> BinarySecurityStageRun:
        stage_run = db.query(BinarySecurityStageRun).filter(
            BinarySecurityStageRun.task_id == task.id,
            BinarySecurityStageRun.stage_name == stage_name,
        ).first()
        if stage_run:
            return stage_run
        stage_run = BinarySecurityStageRun(
            id=f"sr_{uuid.uuid4().hex[:20]}",
            task_id=task.id,
            project_id=task.project_id,
            stage_name=stage_name,
            sequence_no=self._stage_sequence_for_task(task).index(stage_name) + 1,
            status="pending",
        )
        max_attempts = self._retryable_write_attempts()
        for attempt in range(max_attempts):
            try:
                with self._savepoint(db):
                    db.add(stage_run)
                    db.flush()
                return stage_run
            except IntegrityError:
                existing = db.query(BinarySecurityStageRun).filter(
                    BinarySecurityStageRun.task_id == task.id,
                    BinarySecurityStageRun.stage_name == stage_name,
                ).first()
                if existing is None:
                    raise
                return existing
            except OperationalError as exc:
                if not self._is_retryable_lock_error(exc) or attempt >= max_attempts - 1:
                    raise
                db.rollback()
                self._sleep_after_retryable_lock_error(attempt + 1)

    def _record_event(
        self,
        db: Session,
        task: BinarySecurityTask,
        event_type: str,
        message: str,
        *,
        level: str = "info",
        stage_name: str | None = None,
        item: BinarySecurityStageItem | None = None,
        payload: dict[str, Any] | None = None,
        operation_id: str | None = None,
    ) -> None:
        event = BinarySecurityEvent(
            id=f"evt_{uuid.uuid4().hex[:24]}",
            task_id=task.id,
            project_id=task.project_id,
            operation_id=operation_id,
            stage_name=stage_name,
            item_id=_stage_item_attr(item, "id"),
            item_key=_stage_item_attr(item, "item_key"),
            level=level,
            event_type=event_type,
            message=message,
        )
        event.payload = self._prepare_event_payload_for_db(
            db,
            task=task,
            event_id=event.id,
            event_type=event_type,
            stage_name=stage_name,
            payload=payload or {},
            state_event=False,
        )
        db.add(event)

    @staticmethod
    def _preserved_child_result_keys() -> tuple[str, ...]:
        return (
            "first_started_at",
            "sync_status",
            "downstream_status_synced_at",
            "downstream_status",
            "sync_observation",
            "downstream",
            "downstream_binding",
            "archive_copy_stats",
            "archive_root",
            "artifact_root",
            "orchestration_observation",
            "last_orchestration_attempt_at",
            "last_orchestration_success_at",
            "last_orchestration_error_at",
            "last_orchestration_error_type",
            "last_orchestration_error_message",
            "consecutive_orchestration_error_count",
            "orchestration_error_budget_exhausted",
            "next_orchestration_retry_at",
            "last_orchestration_result",
        )

    def _downstream_binding_snapshot(self, item: BinarySecurityStageItem) -> dict[str, Any]:
        result_payload = dict(item.result or {})
        return dict(result_payload.get("downstream_binding") or {})

    def _set_downstream_binding_snapshot(
        self,
        item: BinarySecurityStageItem,
        *,
        state: str | None = None,
        attempts: int | None = None,
        first_attempt_at: datetime | None | object = _UNSET,
        last_attempt_at: datetime | None | object = _UNSET,
        next_retry_at: datetime | None | object = _UNSET,
        last_error: str | None | object = _UNSET,
        last_error_type: str | None | object = _UNSET,
        recoverable: bool | None | object = _UNSET,
        message: str | None | object = _UNSET,
    ) -> dict[str, Any]:
        result_payload = dict(item.result or {})
        binding = dict(result_payload.get("downstream_binding") or {})
        if state is not None:
            binding["state"] = str(state).strip()
        if attempts is not None:
            binding["attempts"] = max(0, int(attempts))
        if first_attempt_at is not _UNSET:
            binding["first_attempt_at"] = _isoformat_or_none(first_attempt_at if isinstance(first_attempt_at, datetime) else None) if first_attempt_at is not None else None
        if last_attempt_at is not _UNSET:
            binding["last_attempt_at"] = _isoformat_or_none(last_attempt_at if isinstance(last_attempt_at, datetime) else None) if last_attempt_at is not None else None
        if next_retry_at is not _UNSET:
            binding["next_retry_at"] = _isoformat_or_none(next_retry_at if isinstance(next_retry_at, datetime) else None) if next_retry_at is not None else None
        if last_error is not _UNSET:
            binding["last_error"] = str(last_error).strip() or None if last_error is not None else None
        if last_error_type is not _UNSET:
            binding["last_error_type"] = str(last_error_type).strip() or None if last_error_type is not None else None
        if recoverable is not _UNSET:
            binding["recoverable"] = bool(recoverable) if recoverable is not None else None
        if message is not _UNSET:
            binding["message"] = str(message).strip() or None if message is not None else None
        result_payload["downstream_binding"] = binding
        item.result = result_payload
        return binding

    def _downstream_binding_state(self, item: BinarySecurityStageItem) -> str:
        binding = self._downstream_binding_snapshot(item)
        task_id = str(item.downstream_task_id or "").strip()
        item_result = self._load_stage_item_result_payload(item)
        downstream_status = self._string_or_none(binding.get("downstream_status")) or self._string_or_none(item_result.get("downstream_status"))
        explicit = self._string_or_none(binding.get("state"))
        if task_id:
            return "bound" if downstream_status else "created_pending_sync"
        if explicit:
            return explicit
        return "not_started"

    def _downstream_binding_attempts(self, item: BinarySecurityStageItem) -> int:
        binding = self._downstream_binding_snapshot(item)
        try:
            return max(0, int(binding.get("attempts") or 0))
        except Exception:
            return 0

    def _downstream_binding_time(self, item: BinarySecurityStageItem, key: str) -> datetime | None:
        binding = self._downstream_binding_snapshot(item)
        return self._parse_comparable_datetime(binding.get(key))

    def _downstream_binding_retry_after(self, attempts: int) -> int:
        index = max(0, attempts - 1)
        if index >= len(DOWNSTREAM_CREATE_RETRY_BACKOFF_SECONDS):
            return DOWNSTREAM_CREATE_RETRY_BACKOFF_SECONDS[-1]
        return DOWNSTREAM_CREATE_RETRY_BACKOFF_SECONDS[index]

    def _item_needs_downstream_binding_reconcile(self, item: BinarySecurityStageItem) -> bool:
        if str(item.downstream_service or "").strip() != "dataflow_vuln_scan":
            return False
        if str(item.downstream_task_id or "").strip():
            return False
        if normalize_stage_name(item.stage_name) != "dataflow_vuln_scan":
            return False
        item_status = str(item.status or "").strip().lower()
        if item_status not in {"pending", "queued", "running", "dispatching"}:
            return False
        binding_state = self._downstream_binding_state(item)
        if binding_state in {"creating", "create_retrying", "create_failed"}:
            return True
        sync_status = self._stage_item_sync_status_value(item)
        return sync_status == "transport_error"

    def _preserve_child_result_metadata(self, result: dict[str, Any] | None) -> dict[str, Any]:
        current_result = dict(result or {})
        preserved: dict[str, Any] = {}
        for key in self._preserved_child_result_keys():
            if key in current_result:
                preserved[key] = current_result.get(key)
        return preserved

    def _reset_child_runtime_payload(
        self,
        item: BinarySecurityStageItem,
        *,
        payload: dict[str, Any] | None = None,
        keep_error: bool = False,
        reset_started_at: bool = False,
        reset_finished_at: bool = True,
    ) -> list[str]:
        preserved_result = self._preserve_child_result_metadata(item.result)
        preserved_keys = list(preserved_result.keys())
        item.payload = dict(payload or {})
        item.result = preserved_result
        if not keep_error:
            item.error_message = None
        if reset_started_at:
            item.started_at = None
        if reset_finished_at:
            item.finished_at = None
        return preserved_keys

    @staticmethod
    def _stage_item_first_started_at(item: BinarySecurityStageItem) -> datetime | None:
        result_payload = dict(item.result or {})
        raw_value = result_payload.get("first_started_at")
        if isinstance(raw_value, datetime):
            return raw_value
        if isinstance(raw_value, str) and raw_value.strip():
            try:
                return datetime.fromisoformat(raw_value)
            except ValueError:
                return None
        return item.started_at

    def _ensure_stage_item_first_started_at(self, item: BinarySecurityStageItem) -> None:
        if item.started_at is None:
            return
        result_payload = dict(item.result or {})
        current = self._stage_item_first_started_at(item)
        if current is None:
            result_payload["first_started_at"] = item.started_at.isoformat()
            item.result = result_payload

    def _build_child_status_event_payload(
        self,
        *,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        change_source: str,
        before_status: str | None,
        after_status: str | None,
        sync_status: str | None = None,
        downstream_status_raw: str | None = None,
        downstream_status_mapped: str | None = None,
        downstream_status: str | None = None,
        state_applied: bool | None = None,
        error_message: str | None = None,
        error_type: str | None = None,
        http_status: int | None = None,
        archive_job_id: str | None = None,
        state_event_id: str | None = None,
        preserved_result_keys: list[str] | None = None,
        task_status_after_reconcile: str | None = None,
        stage_status_after_reconcile: str | None = None,
        extra_payload: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        payload = {
            "change_source": change_source,
            "before_status": before_status,
            "after_status": after_status,
            "downstream_service": item.downstream_service,
            "downstream_task_id": item.downstream_task_id,
            "downstream_status_raw": downstream_status_raw,
            "downstream_status_mapped": downstream_status_mapped,
            "downstream_status": downstream_status,
            "state_applied": state_applied,
            "sync_status": sync_status,
            "http_status": http_status,
            "error_type": error_type,
            "error_message": error_message,
            "archive_job_id": archive_job_id,
            "state_event_id": state_event_id,
            "preserved_result_keys": preserved_result_keys or [],
            "task_status_after_reconcile": task_status_after_reconcile or task.status,
            "stage_status_after_reconcile": stage_status_after_reconcile,
        }
        if extra_payload:
            payload.update(extra_payload)
        return payload

    def _child_status_event_message(
        self,
        item: BinarySecurityStageItem,
        *,
        event_type: str,
        before_status: str | None,
        after_status: str | None,
        change_source: str,
    ) -> str:
        item_label = str(item.item_key or item.item_name or item.id or "-")
        stage_label = str(item.stage_name or "unknown")
        if event_type == "child_sync_observed":
            return f"{stage_label} 子任务同步观测完成: {item_label}"
        if event_type == "child_sync_failed":
            return f"{stage_label} 子任务同步失败: {item_label}"
        if event_type == "child_transport_failed":
            return f"{stage_label} 子任务同步通信失败: {item_label}"
        if event_type == "child_observation_persist_failed":
            return f"{stage_label} 子任务观测快照写入失败: {item_label}"
        if event_type == "child_state_apply_failed":
            return f"{stage_label} 子任务状态推进失败: {item_label}"
        if event_type == "child_archive_status_changed":
            return f"{stage_label} 子任务归档状态推进: {item_label} {before_status or '-'} -> {after_status or '-'}"
        return f"{stage_label} 子任务状态变更: {item_label} {before_status or '-'} -> {after_status or '-'} ({change_source})"

    def _log_child_status_event(
        self,
        db: Session,
        *,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        event_type: str,
        change_source: str,
        before_status: str | None,
        after_status: str | None,
        sync_status: str | None = None,
        downstream_status_raw: str | None = None,
        downstream_status_mapped: str | None = None,
        downstream_status: str | None = None,
        state_applied: bool | None = None,
        error_message: str | None = None,
        error_type: str | None = None,
        http_status: int | None = None,
        archive_job_id: str | None = None,
        state_event_id: str | None = None,
        preserved_result_keys: list[str] | None = None,
        stage_status_after_reconcile: str | None = None,
        extra_payload: dict[str, Any] | None = None,
    ) -> None:
        level = "warning" if event_type in {"child_sync_failed", "child_transport_failed", "child_observation_persist_failed", "child_state_apply_failed", "child_archive_status_changed", "downstream_http_429_retry_scheduled"} or str(after_status or "") in {"failed", "cancelled", "downstream_missing"} else "info"
        self._record_event(
            db,
            task,
            event_type,
            self._child_status_event_message(
                item,
                event_type=event_type,
                before_status=before_status,
                after_status=after_status,
                change_source=change_source,
            ),
            level=level,
            stage_name=item.stage_name,
            item=item,
            payload=self._build_child_status_event_payload(
                task=task,
                item=item,
                change_source=change_source,
                before_status=before_status,
                after_status=after_status,
                sync_status=sync_status,
                downstream_status_raw=downstream_status_raw,
                downstream_status_mapped=downstream_status_mapped,
                downstream_status=downstream_status,
                state_applied=state_applied,
                error_message=error_message,
                error_type=error_type,
                http_status=http_status,
                archive_job_id=archive_job_id,
                state_event_id=state_event_id,
                preserved_result_keys=preserved_result_keys,
                stage_status_after_reconcile=stage_status_after_reconcile,
                extra_payload=extra_payload,
            ),
        )

    def _apply_child_task_sync_observation(
        self,
        item: BinarySecurityStageItem,
        *,
        sync_status: str,
        synced_at: datetime | None = None,
        error_message: str | None = None,
        http_status: int | None = None,
        error_type: str | None = None,
        downstream_status_raw: str | None = None,
        downstream_status_mapped: str | None = None,
        downstream_status: str | None = None,
        state_applied: bool | None = None,
        downstream_payload: dict[str, Any] | None = None,
        archive_root: str | None = None,
        archive_copy_stats: dict[str, Any] | None = None,
        consecutive_error_count: int | None = None,
        budget_exhausted: bool | None = None,
        next_retry_at: datetime | None = None,
        last_sync_result: str | None = None,
    ) -> list[str]:
        current_result = dict(item.result or {})
        preserved_keys = [key for key in self._preserved_child_result_keys() if key in current_result]
        sync_observation = dict(current_result.get("sync_observation") or {})
        control_plane_stale = self._is_tail_control_plane_stale_error(
            error_message=error_message,
            error_type=error_type,
        )
        if control_plane_stale:
            sync_status = "synced" if (downstream_status or downstream_status_mapped or downstream_status_raw or current_result.get("downstream_status")) else (sync_status or "observed")
            error_message = None
            error_type = None
            http_status = None
        observed_at = synced_at or _now()
        observed_at_iso = observed_at.isoformat()
        sync_observation["last_attempt_at"] = observed_at_iso
        if last_sync_result is None:
            last_sync_result = "error" if error_message or error_type else "success"
        sync_observation.update(
            {
                "sync_status": sync_status,
                "error_message": error_message,
                "http_status": http_status,
                "error_type": error_type,
                "status_raw": downstream_status_raw,
                "mapped_status": downstream_status_mapped,
                "downstream_status": downstream_status,
                "state_applied": state_applied,
                "last_result": last_sync_result,
            }
        )
        if consecutive_error_count is not None:
            sync_observation["consecutive_error_count"] = max(0, int(consecutive_error_count))
        if budget_exhausted is not None:
            sync_observation["budget_exhausted"] = bool(budget_exhausted)
        if next_retry_at is not None:
            sync_observation["next_retry_at"] = next_retry_at.isoformat()
        elif error_message or error_type:
            sync_observation["next_retry_at"] = sync_observation.get("next_retry_at")
        else:
            sync_observation["next_retry_at"] = None
        if error_message or error_type:
            sync_observation["last_error_at"] = observed_at_iso
        elif state_applied or downstream_status or downstream_status_mapped or downstream_status_raw:
            sync_observation["last_success_at"] = observed_at_iso
            sync_observation["last_synced_at"] = observed_at_iso
            sync_observation["last_error_at"] = None
            sync_observation["error_message"] = None
            sync_observation["error_type"] = None
            sync_observation["http_status"] = None
            sync_observation["consecutive_error_count"] = 0
            sync_observation["budget_exhausted"] = False
            sync_observation["next_retry_at"] = None
        merged_result = {
            **current_result,
            "sync_status": sync_status,
            "last_sync_attempt_at": observed_at_iso,
            "downstream_status_synced_at": (
                sync_observation.get("last_success_at")
                or sync_observation.get("last_synced_at")
                or observed_at_iso
            ),
            "last_sync_success_at": sync_observation.get("last_success_at") or sync_observation.get("last_synced_at"),
            "last_sync_error_at": sync_observation.get("last_error_at"),
            "last_sync_error_message": sync_observation.get("error_message"),
            "last_sync_error_type": sync_observation.get("error_type"),
            "last_sync_result": sync_observation.get("last_result"),
            "consecutive_sync_error_count": sync_observation.get("consecutive_error_count"),
            "sync_error_budget_exhausted": sync_observation.get("budget_exhausted"),
            "next_sync_retry_at": sync_observation.get("next_retry_at"),
            "downstream_status": downstream_status or current_result.get("downstream_status"),
            "sync_observation": sync_observation,
        }
        if downstream_payload is not None:
            merged_result["downstream"] = self._lightweight_downstream_payload(downstream_payload or {})
        if archive_root is not None:
            merged_result["archive_root"] = archive_root
        if archive_copy_stats is not None:
            merged_result["archive_copy_stats"] = dict(archive_copy_stats or {})
        item.result = merged_result
        return preserved_keys

    def _child_sync_observation_would_change(
        self,
        item: BinarySecurityStageItem,
        *,
        sync_status: str,
        synced_at: datetime | None = None,
        error_message: str | None = None,
        http_status: int | None = None,
        error_type: str | None = None,
        status_raw: str | None = None,
        mapped_status: str | None = None,
        downstream_status: str | None = None,
        state_applied: bool | None = None,
    ) -> bool:
        current_result = dict(item.result or {})
        current_observation = dict(current_result.get("sync_observation") or {})
        comparable_synced_at = self._comparable_datetime(synced_at)
        if comparable_synced_at is not None:
            current_synced_candidates = [
                self._parse_comparable_datetime(current_observation.get("last_synced_at")),
                self._parse_comparable_datetime(current_observation.get("last_success_at")),
                self._parse_comparable_datetime(current_result.get("last_sync_attempt_at")),
            ]
            if not any(candidate != comparable_synced_at for candidate in current_synced_candidates if candidate is not None):
                comparable_synced_at = None
        current_sync_status = self._string_or_none(current_result.get("sync_status"))
        current_downstream_status = self._string_or_none(current_result.get("downstream_status"))
        comparable_pairs = (
            (current_sync_status, self._string_or_none(sync_status)),
            (self._string_or_none(current_observation.get("sync_status")), self._string_or_none(sync_status)),
            (self._string_or_none(current_observation.get("error_message")), self._string_or_none(error_message)),
            (self._int_or_none(current_observation.get("http_status")), self._int_or_none(http_status)),
            (self._string_or_none(current_observation.get("error_type")), self._string_or_none(error_type)),
            (self._string_or_none(current_observation.get("status_raw")), self._string_or_none(status_raw)),
            (self._string_or_none(current_observation.get("mapped_status")), self._string_or_none(mapped_status)),
            (self._string_or_none(current_observation.get("downstream_status")), self._string_or_none(downstream_status)),
            (self._bool_or_none(current_observation.get("state_applied")), self._bool_or_none(state_applied)),
            (current_downstream_status, self._string_or_none(downstream_status) or current_downstream_status),
        )
        return comparable_synced_at is not None or any(before != after for before, after in comparable_pairs)

    def _merge_stage_item_output_ref(self, item: BinarySecurityStageItem, **updates: Any) -> list[str]:
        current_output_ref = dict(getattr(item, "output_ref", None) or {})
        preserved_keys = [key for key in updates.keys() if key in current_output_ref]
        merged_output_ref = dict(current_output_ref)
        changed = False
        for key, value in updates.items():
            if value is None:
                continue
            if merged_output_ref.get(key) == value:
                continue
            merged_output_ref[key] = value
            changed = True
        if changed:
            item.output_ref = merged_output_ref
        return preserved_keys

    def _apply_child_task_status_change(
        self,
        db: Session | None,
        *,
        task: BinarySecurityTask | None,
        item: BinarySecurityStageItem,
        change_source: str,
        after_status: str,
        downstream_payload: dict[str, Any] | None = None,
        sync_status: str | None = None,
        downstream_status_raw: str | None = None,
        downstream_status_mapped: str | None = None,
        downstream_status: str | None = None,
        state_applied: bool | None = None,
        error_message: str | None = None,
        error_type: str | None = None,
        http_status: int | None = None,
        archive_job_id: str | None = None,
        state_event_id: str | None = None,
        synced_at: datetime | None = None,
        extra_payload: dict[str, Any] | None = None,
        event_type: str = "child_status_changed",
    ) -> list[str]:
        normalized_status = self._map_downstream_status(after_status) or after_status
        before_status = str(item.status or "").strip().lower() or None
        item.status = normalized_status
        keep_active_error = (
            bool(error_message)
            and normalized_status in {"queued", "running"}
            and (change_source == "transport_error" or sync_status == "transport_error")
        )
        item.error_message = error_message if keep_active_error else (
            None if normalized_status in {"pending", "queued", "dispatching", "running", "success", "partial_success"} else error_message
        )
        if normalized_status in {"running", "success", "failed", "cancelled", "downstream_missing", "partial_success"}:
            item.started_at = item.started_at or _now()
        item.finished_at = None if normalized_status in {"pending", "queued", "dispatching", "running"} else (item.finished_at or _now())
        preserved_keys = self._apply_child_task_sync_observation(
            item,
            sync_status=sync_status or ("synced" if state_applied else "observed"),
            synced_at=synced_at,
            error_message=error_message,
            http_status=http_status,
            error_type=error_type,
            downstream_status_raw=downstream_status_raw,
            downstream_status_mapped=downstream_status_mapped or normalized_status,
            downstream_status=downstream_status,
            state_applied=state_applied,
            downstream_payload=downstream_payload,
        )
        if db is not None and task is not None:
            self._log_child_status_event(
                db,
                task=task,
                item=item,
                event_type=event_type,
                change_source=change_source,
                before_status=before_status,
                after_status=normalized_status,
                sync_status=sync_status or ("synced" if state_applied else "observed"),
                downstream_status_raw=downstream_status_raw,
                downstream_status_mapped=downstream_status_mapped or normalized_status,
                downstream_status=downstream_status,
                state_applied=state_applied,
                error_message=error_message,
                error_type=error_type,
                http_status=http_status,
                archive_job_id=archive_job_id,
                state_event_id=state_event_id,
                preserved_result_keys=preserved_keys,
                extra_payload=extra_payload,
            )
        return preserved_keys

    def _persist_child_sync_observation(
        self,
        db: Session,
        *,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        change_source: str,
        sync_status: str,
        synced_at: datetime | None = None,
        error_message: str | None = None,
        http_status: int | None = None,
        error_type: str | None = None,
        status_raw: str | None = None,
        mapped_status: str | None = None,
        downstream_status: str | None = None,
        state_applied: bool | None = None,
        extra_payload: dict[str, Any] | None = None,
        consecutive_error_count: int | None = None,
        budget_exhausted: bool | None = None,
        next_retry_at: datetime | None = None,
        last_sync_result: str | None = None,
    ) -> bool:
        before_status = str(item.status or "").strip().lower() or None
        after_status = str(item.status or "").strip().lower() or None
        if not self._child_sync_observation_would_change(
            item,
            sync_status=sync_status,
            synced_at=synced_at,
            error_message=error_message,
            http_status=http_status,
            error_type=error_type,
            status_raw=status_raw,
            mapped_status=mapped_status,
            downstream_status=downstream_status,
            state_applied=state_applied,
        ):
            return True
        max_attempts = self._retryable_write_attempts()
        for attempt in range(max_attempts):
            try:
                with self._savepoint(db):
                    self._mark_stage_item_sync_observation(
                        item,
                        sync_status=sync_status,
                        synced_at=synced_at,
                        error_message=error_message,
                        http_status=http_status,
                        error_type=error_type,
                        status_raw=status_raw,
                        mapped_status=mapped_status,
                        downstream_status=downstream_status,
                        state_applied=state_applied,
                        consecutive_error_count=consecutive_error_count,
                        budget_exhausted=budget_exhausted,
                        next_retry_at=next_retry_at,
                        last_sync_result=last_sync_result,
                    )
                    db.flush()
                return True
            except Exception as exc:
                if self._is_retryable_lock_error(exc) and attempt < max_attempts - 1:
                    self._sleep_after_retryable_lock_error(attempt + 1)
                    continue
                self._log_child_status_event(
                    db,
                    task=task,
                    item=item,
                    event_type="child_observation_persist_failed",
                    change_source=change_source,
                    before_status=before_status,
                    after_status=after_status,
                    sync_status=sync_status,
                    downstream_status_raw=status_raw,
                    downstream_status_mapped=mapped_status,
                    downstream_status=downstream_status,
                    state_applied=state_applied,
                    error_message=str(exc),
                    error_type=exc.__class__.__name__,
                    http_status=http_status,
                    extra_payload={
                        "persist_error": str(exc),
                        "persist_error_type": exc.__class__.__name__,
                        **(extra_payload or {}),
                    },
                )
                return False
        return False

    def _apply_child_state_with_savepoint(
        self,
        db: Session,
        *,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        change_source: str,
        target_status: str,
        sync_status: str,
        downstream_status_raw: str | None,
        downstream_status_mapped: str | None,
        downstream_status: str | None,
        error_message: str | None,
        http_status: int | None,
        error_type: str | None,
        apply_fn,
        extra_payload: dict[str, Any] | None = None,
    ) -> bool:
        before_status = str(item.status or "").strip().lower() or None
        max_attempts = self._retryable_write_attempts()
        for attempt in range(max_attempts):
            try:
                with self._savepoint(db):
                    apply_fn()
                    db.flush()
                return True
            except Exception as exc:
                if self._is_retryable_lock_error(exc) and attempt < max_attempts - 1:
                    self._sleep_after_retryable_lock_error(attempt + 1)
                    continue
                self._log_child_status_event(
                    db,
                    task=task,
                    item=item,
                    event_type="child_state_apply_failed",
                    change_source=change_source,
                    before_status=before_status,
                    after_status=target_status,
                    sync_status=sync_status,
                    downstream_status_raw=downstream_status_raw,
                    downstream_status_mapped=downstream_status_mapped,
                    downstream_status=downstream_status,
                    state_applied=False,
                    error_message=str(exc),
                    error_type=exc.__class__.__name__,
                    http_status=http_status,
                    extra_payload={
                        "apply_error": str(exc),
                        "apply_error_type": exc.__class__.__name__,
                        **(extra_payload or {}),
                    },
                )
                return False
        return False

    def _enqueue_state_event(
        self,
        db: Session,
        *,
        task_id: str,
        project_id: str,
        event_type: str,
        idempotency_key: str,
        stage_name: str | None = None,
        item_id: str | None = None,
        archive_job_id: str | None = None,
        payload: dict[str, Any] | None = None,
        task: BinarySecurityTask | None = None,
    ) -> BinarySecurityStateEvent | None:
        event = BinarySecurityStateEvent(
            id=f"sev_{uuid.uuid4().hex[:24]}",
            task_id=task_id,
            project_id=project_id,
            stage_name=stage_name,
            item_id=item_id,
            archive_job_id=archive_job_id,
            event_type=event_type,
            idempotency_key=idempotency_key,
            status="pending",
            available_at=_now(),
            updated_at=_now(),
        )
        event.payload = self._prepare_event_payload_for_db(
            db,
            task=task,
            event_id=event.id,
            event_type=event_type,
            stage_name=stage_name,
            payload=payload or {},
            state_event=True,
            task_id=task_id,
            project_id=project_id,
        )
        max_attempts = self._retryable_write_attempts()
        for attempt in range(max_attempts):
            try:
                with self._savepoint(db):
                    db.add(event)
                    db.flush()
                observe_state_event(event_type, "created")
                return event
            except IntegrityError:
                observe_state_event(event_type, "duplicate")
                return None
            except OperationalError as exc:
                if not self._is_retryable_lock_error(exc) or attempt >= max_attempts - 1:
                    raise
                db.rollback()
                self._sleep_after_retryable_lock_error(attempt + 1)

    def _record_missing_stage_terminal_event(
        self,
        db: Session,
        task: BinarySecurityTask,
        *,
        stage_name: str,
        status: str,
        reason: str,
        summary: dict[str, Any] | None = None,
        execution_token: str | None = None,
    ) -> None:
        self._record_event(
            db,
            task,
            "stage_worker_terminal_event_missing",
            f"检测到阶段终态事件漏信，已补投 reducer 事件: {stage_name}",
            level="warning",
            stage_name=stage_name,
            payload={
                "reason": reason,
                "status": status,
                "execution_token": execution_token,
                "summary": self._fit_event_payload_for_db(dict(summary or {})),
            },
        )

    def _emit_stage_terminal_event_safely(
        self,
        db: Session,
        *,
        task: BinarySecurityTask,
        stage_name: str,
        status: str,
        summary: dict[str, Any],
        stage_retry_mode: bool,
        task_retry_mode: bool,
        target_stage_name: str | None,
        execution_token: str | None,
    ) -> BinarySecurityStateEvent | None:
        return self._enqueue_state_event(
            db,
            task=task,
            task_id=task.id,
            project_id=task.project_id,
            stage_name=stage_name,
            event_type="stage_worker_terminal_observed",
            idempotency_key=(
                f"stage_worker_terminal_observed:{task.id}:{stage_name}:"
                f"{execution_token or ''}:{status}"
            ),
            payload={
                "stage_name": stage_name,
                "status": status,
                "summary": summary,
                "stage_retry_mode": bool(stage_retry_mode),
                "task_retry_mode": bool(task_retry_mode),
                "target_stage_name": target_stage_name,
                "execution_token": execution_token,
            },
        )

    def _enqueue_downstream_status_event(
        self,
        db: Session,
        *,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        mapped_status: str,
        before_status: str | None,
        downstream_status: str,
        payload: dict[str, Any],
        error_message: str | None = None,
        http_status: int | None = None,
        error_type: str | None = None,
        status_raw: str | None = None,
        force: bool = False,
        event_type: str = "downstream_status_observed",
    ) -> BinarySecurityStateEvent | None:
        downstream_payload = self._lightweight_downstream_payload(payload or {})
        fingerprint_payload = {
            "item_id": item.id,
            "downstream_task_id": item.downstream_task_id,
            "mapped_status": mapped_status,
            "downstream_status": downstream_status,
            "error_message": error_message,
            "downstream_payload": downstream_payload,
        }
        fingerprint = hashlib.sha1(json.dumps(fingerprint_payload, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()
        return self._enqueue_state_event(
            db,
            task_id=task.id,
            project_id=task.project_id,
            stage_name=item.stage_name,
            item_id=item.id,
            event_type=event_type,
            idempotency_key=f"{event_type}:{item.id}:{fingerprint}",
            payload={
                "mapped_status": mapped_status,
                "before_status": before_status,
                "downstream_status": downstream_status,
                "downstream_payload": downstream_payload,
                "error_message": error_message,
                "http_status": http_status,
                "error_type": error_type,
                "status_raw": status_raw or downstream_status,
                "force": bool(force),
            },
        )

    def _enqueue_downstream_terminal_event(
        self,
        db: Session,
        *,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        mapped_status: str,
        before_status: str | None,
        downstream_status: str,
        payload: dict[str, Any],
        error_message: str | None = None,
        http_status: int | None = None,
        error_type: str | None = None,
        status_raw: str | None = None,
        force: bool = False,
    ) -> BinarySecurityStateEvent | None:
        return self._enqueue_downstream_status_event(
            db,
            task=task,
            item=item,
            mapped_status=mapped_status,
            before_status=before_status,
            downstream_status=downstream_status,
            payload=payload,
            error_message=error_message,
            http_status=http_status,
            error_type=error_type,
            status_raw=status_raw,
            force=force,
            event_type="downstream_terminal_observed",
        )

    def _recover_missing_stage_terminal_events_locked(self, db: Session) -> bool:
        recovered = False
        running_tasks = db.query(BinarySecurityTask).filter(BinarySecurityTask.status == "running").all()
        for task in running_tasks:
            execution_token = task.dispatch_started_at.isoformat() if task.dispatch_started_at else ""
            stage_runs = db.query(BinarySecurityStageRun).filter(BinarySecurityStageRun.task_id == task.id).all()
            for stage_run in stage_runs:
                stage_name = str(stage_run.stage_name or "").strip()
                stage_status = str(stage_run.status or "").strip()
                if stage_status not in {"success", "partial_success", "failed", "cancelled", "downstream_missing"}:
                    continue
                expected_key = f"stage_worker_terminal_observed:{task.id}:{stage_name}:{execution_token}:{stage_status}"
                existing = db.query(BinarySecurityStateEvent).filter(
                    BinarySecurityStateEvent.idempotency_key == expected_key
                ).first()
                if existing is not None:
                    continue
                summary = dict(stage_run.output_summary or {})
                emitted = self._emit_stage_terminal_event_safely(
                    db,
                    task=task,
                    stage_name=stage_name,
                    status=stage_status,
                    summary=summary,
                    stage_retry_mode=False,
                    task_retry_mode=False,
                    target_stage_name=None,
                    execution_token=execution_token,
                )
                if emitted is None:
                    continue
                self._record_missing_stage_terminal_event(
                    db,
                    task,
                    stage_name=stage_name,
                    status=stage_status,
                    reason="dispatch_loop_recovery_missing_execution_token" if not execution_token else "dispatch_loop_recovery",
                    summary=summary,
                    execution_token=execution_token,
                )
                recovered = True
        if recovered:
            db.flush()
        return recovered

    def _enqueue_archive_state_event_by_job_id(self, job_id: str, *, event_type: str, payload: dict[str, Any] | None = None) -> None:
        db = get_session_factory()()
        try:
            job = db.query(BinarySecurityArchiveJob).filter(BinarySecurityArchiveJob.id == job_id).first()
            if job is None:
                observe_state_event(event_type, "missing_archive_job")
                return
            merged_payload = {**(payload or {})}
            if job.archive_root and "archive_root" not in merged_payload:
                merged_payload["archive_root"] = job.archive_root
            self._enqueue_state_event(
                db,
                task_id=job.task_id,
                project_id=job.project_id,
                stage_name=job.stage_name,
                item_id=job.item_id,
                archive_job_id=job.id,
                event_type=event_type,
                idempotency_key=f"{event_type}:{job.id}:{job.archive_status}:{job.updated_at.isoformat() if job.updated_at else ''}",
                payload=merged_payload,
            )
            db.commit()
        except Exception:
            db.rollback()
            observe_state_event(event_type, "error")
            logger.exception("binary-security failed to enqueue archive state event: job=%s type=%s", job_id, event_type)
        finally:
            db.close()

    def _stage_counts(self, db: Session, stage_run: BinarySecurityStageRun) -> dict[str, int]:
        raw_items = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.stage_run_id == stage_run.id).all()
        items: list[BinarySecurityStageItem] = []
        seen_item_ids: set[str] = set()
        seen_identity_keys: set[str] = set()
        for item in raw_items:
            item_id = str(item.id or "").strip()
            if item_id and item_id in seen_item_ids:
                continue
            identity_key = str(getattr(item, "item_identity_key", "") or "").strip()
            if not identity_key:
                identity_key = self._stage_item_identity(item.item_key, item.parent_key)
            if identity_key and identity_key in seen_identity_keys:
                continue
            if item_id:
                seen_item_ids.add(item_id)
            if identity_key:
                seen_identity_keys.add(identity_key)
            items.append(item)
        counts = {
            "total_items": len(items),
            "success_items": 0,
            "failed_items": 0,
            "downstream_missing_items": 0,
            "skipped_items": 0,
            "running_items": 0,
            "cancelled_items": 0,
        }
        for item in items:
            normalized_status = self._normalize_downstream_status(item.status) or item.status
            key = f"{normalized_status}_items"
            if key in counts:
                counts[key] += 1
            elif normalized_status in {"pending", "queued", "dispatching"}:
                counts["running_items"] += 1
        return counts

    def _normalize_downstream_status(self, status: str | None) -> str | None:
        return self._map_downstream_status(status or "")

    def _business_stage_status(
        self,
        task: BinarySecurityTask,
        stage_name: str,
        stage_run: BinarySecurityStageRun | None,
        items: list[BinarySecurityStageItem],
        *,
        db: Session | None = None,
    ) -> str:
        if stage_name == "system_analysis":
            if task.status == TASK_STATUS_PENDING_MODULE_CONFIRMATION:
                return "waiting_confirmation"
        if stage_run and stage_run.status == "waiting_confirmation":
            return "waiting_confirmation"
        statuses = [self._normalize_downstream_status(item.status) or item.status for item in items]
        aggregated_item_status = self._aggregate_item_statuses(statuses) if statuses else None
        archive_gated = self._stage_archive_success_blocked(task, stage_name, items, db=db)
        if (
            not items
            and stage_run is not None
            and self._stage_requires_materialized_inputs(task, stage_name)
            and not self._is_streaming_tail_stage(task, stage_name)
        ):
            normalized_run_status = self._normalize_downstream_status(stage_run.status) or str(stage_run.status or "")
            if normalized_run_status in {"failed", "downstream_missing", "cancelled", "partial_success"}:
                return "pending"
        if self._is_streaming_tail_stage(task, stage_name) and any(
            self._is_streaming_active_item_status(item.status)
            for item in items
        ):
            return "running"
        if archive_gated and aggregated_item_status in {"success", "partial_success"}:
            return "running"
        if stage_run:
            normalized_run_status = self._normalize_downstream_status(stage_run.status) or str(stage_run.status or "")
            if normalized_run_status in {"pending", "queued", "running", "dispatching"} and aggregated_item_status not in {None, "pending"}:
                return aggregated_item_status
            if normalized_run_status in {"running", "dispatching"} and aggregated_item_status == "pending":
                return "running"
            if archive_gated and normalized_run_status in {"success", "partial_success"}:
                return "running"
            if normalized_run_status in {
                "success",
                "partial_success",
                "failed",
                "downstream_missing",
                "cancelled",
                "waiting_confirmation",
                "running",
                "queued",
                "pending",
                "dispatching",
            }:
                return normalized_run_status
        if aggregated_item_status:
            return aggregated_item_status
        return "pending"

    def _status_label(self, status: str) -> str:
        return {
            "pending": "pending",
            "queued": "queued",
            "running": "running",
            "applying": "applying",
            "success": "success",
            "skipped": "skipped",
            "partial_success": "partial_success",
            "failed": "failed",
            "downstream_missing": "downstream_missing",
            "cancelled": "cancelled",
            "waiting_confirmation": "waiting_confirmation",
        }.get(status, status)

    @staticmethod
    def _abnormal_reason_evidence(key: str, label: str, value: Any) -> BinarySecurityAbnormalEvidence | None:
        text = str(value or "").strip()
        if not text:
            return None
        return BinarySecurityAbnormalEvidence(key=key, label=label, value=text)

    @staticmethod
    def _abnormal_reason_message(raw: Any, fallback: str) -> str:
        text = str(raw or "").strip()
        return text or fallback

    @staticmethod
    def _abnormal_reason_code_from_message(message: str, *, fallback: str) -> str:
        lowered = str(message or "").lower()
        if "lease lost" in lowered or "租约" in lowered:
            return "lease_lost"
        if "cancel" in lowered or "取消" in lowered:
            return "runtime_interrupted"
        if any(token in lowered for token in ("auth", "dependency", "upstream", "503", "502", "connection refused", "timeout")):
            return "dependency_unavailable"
        if "dispatch" in lowered or "调度" in lowered:
            return "dispatch_failed"
        return fallback

    def _build_abnormal_reason(
        self,
        *,
        category: str,
        code: str,
        title: str,
        message: str,
        source_layer: str,
        status: str,
        service: str,
        stage_name: str | None = None,
        item_key: str | None = None,
        downstream_task_id: str | None = None,
        downstream_service: str | None = None,
        first_seen_at: datetime | None = None,
        last_seen_at: datetime | None = None,
        evidence: list[BinarySecurityAbnormalEvidence | None] | None = None,
        recommended_action: str | None = None,
        related_event_ids: list[str] | None = None,
        terminal: bool = True,
    ) -> BinarySecurityAbnormalReason:
        return BinarySecurityAbnormalReason(
            is_abnormal=True,
            category=category,
            code=code,
            title=title,
            message=message,
            terminal=terminal,
            source_layer=source_layer,
            status=status,
            service=service,
            stage_name=stage_name,
            item_key=item_key,
            downstream_task_id=downstream_task_id,
            downstream_service=downstream_service,
            first_seen_at=first_seen_at,
            last_seen_at=last_seen_at,
            evidence=[item for item in (evidence or []) if item is not None],
            recommended_action=recommended_action,
            related_event_ids=list(related_event_ids or []),
        )

    def _stage_item_abnormal_reason(
        self,
        item: BinarySecurityStageItem,
        *,
        task: BinarySecurityTask | None = None,
    ) -> BinarySecurityAbnormalReason | None:
        status = self._normalize_downstream_status(item.status) or str(item.status or "")
        if status not in {"failed", "cancelled", "downstream_missing", "partial_success"}:
            return None
        error_message = self._abnormal_reason_message(item.error_message, "阶段子任务异常结束")
        if status == "downstream_missing":
            code = "downstream_missing"
            title = "下游任务不存在"
            category = "downstream"
            recommended_action = "检查下游任务是否被提前删除，必要时重新同步状态或重试当前阶段。"
        elif status == "cancelled":
            code = "downstream_cancelled"
            title = "下游任务已取消"
            category = "downstream"
            recommended_action = "检查是否有人为取消、父任务取消或下游运行时中断。"
        elif status == "partial_success":
            code = "result_inconsistent"
            title = "子任务部分成功"
            category = "orchestration"
            recommended_action = "结合时间线和下游详情检查未收敛的失败项。"
        else:
            if self._is_owner_lost_recoverable_failure(
                failure_message=error_message,
                error_type=self._stage_item_sync_error_type_value(item),
                item=item,
            ):
                exhausted = bool(task is not None and self._owner_lost_retry_exhausted(task, item))
                code = "owner_lost_retry_exhausted" if exhausted else "owner_lost_recoverable"
                title = "下游 owner 丢失自动恢复失败" if exhausted else "下游 owner 丢失，等待自动恢复"
                category = "infrastructure"
                recommended_action = "检查 rollout、worker 与 lease 变更，并手工重试或排查下游恢复能力。" if exhausted else "优先等待系统自动接管；若多次恢复后仍失败，再检查 rollout、worker 与 lease 变更。"
            else:
                code = "downstream_failed"
                title = "下游任务失败"
                category = "downstream"
                recommended_action = "优先查看下游任务详情与原始错误信息。"
        return self._build_abnormal_reason(
            category=category,
            code=code,
            title=title,
            message=error_message,
            source_layer="item",
            status=status,
            service=str(item.downstream_service or "binary-security"),
            stage_name=item.stage_name,
            item_key=item.item_key,
            downstream_task_id=item.downstream_task_id,
            downstream_service=item.downstream_service,
            first_seen_at=item.started_at,
            last_seen_at=item.finished_at or item.updated_at,
            evidence=[
                self._abnormal_reason_evidence("stage_name", "阶段", item.stage_name),
                self._abnormal_reason_evidence("item_key", "子任务 Key", item.item_key),
                self._abnormal_reason_evidence("downstream_task_id", "下游任务 ID", item.downstream_task_id),
                self._abnormal_reason_evidence("error_message", "原始错误", item.error_message),
            ],
            recommended_action=recommended_action,
        )

    def _archive_job_abnormal_reason(self, job: BinarySecurityArchiveJob) -> BinarySecurityAbnormalReason | None:
        normalized_status = str(job.archive_status or "").strip()
        if normalized_status == "running" and not job.archive_root and not job.completed_at:
            return self._build_abnormal_reason(
                category="archive",
                code="archive_stale_running",
                title="归档任务长时间运行未收敛",
                message="归档任务处于 running 且长时间未完成，可能发生了 worker 中断或回收延迟。",
                source_layer="archive",
                status=normalized_status,
                service="binary-security",
                stage_name=job.stage_name,
                item_key=job.item_key,
                downstream_task_id=job.downstream_task_id,
                downstream_service=job.downstream_service,
                first_seen_at=job.started_at or job.created_at,
                last_seen_at=job.updated_at,
                evidence=[
                    self._abnormal_reason_evidence("stage_name", "阶段", job.stage_name),
                    self._abnormal_reason_evidence("item_key", "条目", job.item_key),
                    self._abnormal_reason_evidence("downstream_task_id", "下游任务 ID", job.downstream_task_id),
                    self._abnormal_reason_evidence("owner_id", "归档 owner", job.owner_id),
                ],
                recommended_action="优先检查归档 worker 是否中断，以及是否触发了自动回收。",
                terminal=False,
            )
        if normalized_status != "failed":
            return None
        error_text = str(job.error_message or "").lower()
        if "reclaim exhausted" in error_text:
            code = "archive_reclaim_exhausted"
        elif "下游产物归档未完成" in str(job.error_message or "").strip() and int((job.payload or {}).get("copy_retry_attempt") or 0) >= len(self._archive_copy_missing_source_retry_schedule_seconds()):
            code = "archive_source_retry_exhausted"
        else:
            code = "archive_failed"
        return self._build_abnormal_reason(
            category="archive",
            code=code,
            title="归档任务失败",
            message=self._abnormal_reason_message(job.error_message, "阶段产物归档失败"),
            source_layer="archive",
            status=str(job.archive_status or "failed"),
            service="binary-security",
            stage_name=job.stage_name,
            item_key=job.item_key,
            downstream_task_id=job.downstream_task_id,
            downstream_service=job.downstream_service,
            first_seen_at=job.started_at or job.created_at,
            last_seen_at=job.completed_at or job.updated_at,
            evidence=[
                self._abnormal_reason_evidence("stage_name", "阶段", job.stage_name),
                self._abnormal_reason_evidence("item_key", "条目", job.item_key),
                self._abnormal_reason_evidence("downstream_task_id", "下游任务 ID", job.downstream_task_id),
                self._abnormal_reason_evidence("archive_root", "归档目录", job.archive_root),
                self._abnormal_reason_evidence("error_message", "归档错误", job.error_message),
            ],
            recommended_action="检查归档目录、文件系统权限和下游产物是否完整。",
        )

    def _string_or_none(self, value: Any) -> str | None:
        if value is None:
            return None
        text = str(value).strip()
        return text or None

    def _bool_or_none(self, value: Any) -> bool | None:
        if value is None:
            return None
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            normalized = value.strip().lower()
            if normalized in {"true", "1", "yes", "y", "on"}:
                return True
            if normalized in {"false", "0", "no", "n", "off"}:
                return False
            return None
        if isinstance(value, (int, float)):
            return bool(value)
        return None

    def _int_or_none(self, value: Any) -> int | None:
        if value is None or value == "":
            return None
        try:
            return int(value)
        except (TypeError, ValueError):
            return None

    def _stage_abnormal_reason(
        self,
        task: BinarySecurityTask,
        stage_name: str,
        summary: BinarySecurityStageSummary,
        stage_items: list[BinarySecurityStageItem],
    ) -> BinarySecurityAbnormalReason | None:
        if summary.status not in {"failed", "cancelled", "partial_success", "downstream_missing"}:
            return None
        item_reason = next(
            (
                self._stage_item_abnormal_reason(item, task=task)
                for item in reversed(stage_items)
                if self._stage_item_abnormal_reason(item, task=task)
            ),
            None,
        )
        if item_reason is not None:
            return item_reason.model_copy(update={"source_layer": "stage", "service": "binary-security", "stage_name": stage_name})
        message = self._abnormal_reason_message(summary.last_error, f"阶段 {stage_name} 异常结束")
        code = self._abnormal_reason_code_from_message(message, fallback="orchestration_failed")
        category = "runtime" if code in {"lease_lost", "runtime_interrupted", "dispatch_failed", "dependency_unavailable"} else "orchestration"
        return self._build_abnormal_reason(
            category=category,
            code=code if summary.status != "downstream_missing" else "downstream_missing",
            title="阶段异常结束" if summary.status != "partial_success" else "阶段部分成功",
            message=message,
            source_layer="stage",
            status=summary.status,
            service="binary-security",
            stage_name=stage_name,
            first_seen_at=summary.started_at,
            last_seen_at=summary.finished_at,
            evidence=[
                self._abnormal_reason_evidence("stage_name", "阶段", stage_name),
                self._abnormal_reason_evidence("stage_status", "阶段状态", summary.status),
                self._abnormal_reason_evidence("last_error", "原始错误", summary.last_error),
            ],
            recommended_action="查看阶段时间线、下游任务和归档节点，确认是哪一层先出现异常。",
        )

    def _task_abnormal_reason(
        self,
        task: BinarySecurityTask,
        stage_summaries: list[BinarySecurityStageSummary],
        items: list[BinarySecurityStageItem],
        archive_jobs: list[BinarySecurityArchiveJob],
    ) -> BinarySecurityAbnormalReason | None:
        status = str(task.status or "")
        if self._task_is_waiting_for_manual_confirmation(task, stage_summaries):
            return None
        if status in {"success", "pending", "queued", "running", "dispatching", "ready_to_start", "pending_upload", "uploading"}:
            return None
        if status == "cancelled":
            return self._build_abnormal_reason(
                category="cancel",
                code="user_cancelled",
                title="任务已取消",
                message=self._abnormal_reason_message(task.last_error, "用户或编排器已取消当前任务。"),
                source_layer="task",
                status=status,
                service="binary-security",
                stage_name=task.current_stage,
                first_seen_at=task.started_at,
                last_seen_at=task.finished_at,
                evidence=[
                    self._abnormal_reason_evidence("current_stage", "当前阶段", task.current_stage),
                    self._abnormal_reason_evidence("last_error", "原始错误", task.last_error),
                ],
                recommended_action="检查取消来源，必要时查看时间线中的取消与下游同步事件。",
            )
        failed_archive = next((job for job in reversed(archive_jobs) if str(job.archive_status or "") == "failed"), None)
        if failed_archive is not None:
            archive_reason = self._archive_job_abnormal_reason(failed_archive)
            if archive_reason is not None:
                return archive_reason.model_copy(update={"source_layer": "task", "status": status})
        failed_item = next((item for item in reversed(items) if (self._normalize_downstream_status(item.status) or item.status) in {"failed", "cancelled", "downstream_missing"}), None)
        if failed_item is not None:
            item_reason = self._stage_item_abnormal_reason(failed_item, task=task)
            if item_reason is not None:
                return item_reason.model_copy(update={"source_layer": "task", "status": status})
        failed_stage = next((summary for summary in reversed(stage_summaries) if summary.status in {"failed", "partial_success", "downstream_missing", "cancelled"}), None)
        if failed_stage is not None:
            stage_reason = self._stage_abnormal_reason(
                task,
                failed_stage.stage_name,
                failed_stage,
                [item for item in items if item.stage_name == failed_stage.stage_name],
            )
            if stage_reason is not None:
                return stage_reason.model_copy(update={"source_layer": "task", "status": status})
        next_stage = None
        if status == "failed":
            next_stage = next(
                (
                    summary.stage_name
                    for summary in stage_summaries
                    if summary.status not in {"success", "failed", "partial_success", "downstream_missing", "cancelled", "skipped"}
                ),
                None,
            )
        if next_stage:
            return self._build_abnormal_reason(
                category="orchestration",
                code="stage_incomplete_terminated",
                title="任务在最终阶段前终止",
                message=f"任务在 {next_stage} 前终止，未完成所有已启用阶段。",
                source_layer="task",
                status=status,
                service="binary-security",
                stage_name=next_stage,
                first_seen_at=task.started_at,
                last_seen_at=task.finished_at,
                evidence=[
                    self._abnormal_reason_evidence("current_stage", "当前阶段", task.current_stage),
                    self._abnormal_reason_evidence("next_stage", "未完成阶段", next_stage),
                    self._abnormal_reason_evidence("last_error", "原始错误", task.last_error),
                ],
                recommended_action="优先查看最后失败阶段、异常时间线和下游子任务详情。",
            )
        return self._build_abnormal_reason(
            category="orchestration",
            code="unknown_abnormal" if status != "partial_success" else "result_inconsistent",
            title="任务异常结束" if status != "partial_success" else "任务带异常完成",
            message=self._abnormal_reason_message(task.last_error, "任务以非正常状态结束，但未提取到更具体的根因。"),
            source_layer="task",
            status=status,
            service="binary-security",
            stage_name=task.current_stage,
            first_seen_at=task.started_at,
            last_seen_at=task.finished_at,
            evidence=[
                self._abnormal_reason_evidence("current_stage", "当前阶段", task.current_stage),
                self._abnormal_reason_evidence("last_error", "原始错误", task.last_error),
            ],
            recommended_action="查看时间线与编排观测，确认失败首先发生在哪个阶段或下游任务。",
        )

    def _abnormal_reason_history(self, db: Session, task: BinarySecurityTask) -> list[BinarySecurityAbnormalReasonEventSummary]:
        rows = (
            db.query(BinarySecurityEvent)
            .filter(
                BinarySecurityEvent.task_id == task.id,
                BinarySecurityEvent.event_type == "abnormal_reason_recorded",
            )
            .order_by(BinarySecurityEvent.created_at.desc())
            .limit(10)
            .all()
        )
        history: list[BinarySecurityAbnormalReasonEventSummary] = []
        for row in rows:
            payload = dict(row.payload or {})
            reason_payload = payload.get("reason") if isinstance(payload.get("reason"), dict) else payload
            if not isinstance(reason_payload, dict):
                continue
            try:
                history.append(
                    BinarySecurityAbnormalReasonEventSummary(
                        event_id=row.id,
                        created_at=row.created_at,
                        reason=BinarySecurityAbnormalReason(**reason_payload),
                    )
                )
            except Exception:
                continue
        return history

    def _sync_task_abnormal_reason_snapshot(
        self,
        db: Session,
        task: BinarySecurityTask,
        reason: BinarySecurityAbnormalReason | None,
    ) -> None:
        previous = task.latest_abnormal_reason or None
        next_payload = reason.model_dump(mode="json") if reason is not None else None
        if previous == next_payload:
            return
        task.latest_abnormal_reason = next_payload
        if reason is None:
            return
        self._record_event(
            db,
            task,
            "abnormal_reason_recorded",
            reason.title,
            level="warning" if reason.status in {"partial_success", "cancelled"} else "error",
            stage_name=reason.stage_name,
            payload={"reason": next_payload},
        )

    def _clear_task_abnormal_reason_snapshot(self, db: Session, task: BinarySecurityTask) -> None:
        self._sync_task_abnormal_reason_snapshot(db, task, None)

    def _build_stage_summaries(
        self,
        db: Session,
        task: BinarySecurityTask,
        stage_sequence: list[str],
        stage_runs: list[BinarySecurityStageRun],
        items: list[BinarySecurityStageItem],
        *,
        include_retry_support: bool = True,
    ) -> list[BinarySecurityStageSummary]:
        runs_by_stage = {run.stage_name: run for run in stage_runs if run.stage_name in stage_sequence}
        items_by_stage: dict[str, list[BinarySecurityStageItem]] = {stage_name: [] for stage_name in stage_sequence}
        for item in items:
            if item.stage_name in items_by_stage:
                items_by_stage[item.stage_name].append(item)
        stage_retry_support = (
            {
                stage_name: self._stage_retry_support(db, task, stage_name)
                for stage_name in stage_sequence
                if stage_name in runs_by_stage
            }
            if include_retry_support
            else {}
        )
        stage_retry_failed_support = (
            {
                stage_name: self._stage_retry_failed_items_support(db, task, stage_name)
                for stage_name in stage_sequence
                if stage_name in runs_by_stage
            }
            if include_retry_support
            else {}
        )
        summaries: list[BinarySecurityStageSummary] = []
        for index, stage_name in enumerate(stage_sequence, start=1):
            run = runs_by_stage.get(stage_name)
            stage_items = items_by_stage.get(stage_name, [])
            downstream_status_counts: dict[str, int] = {}
            for item in stage_items:
                item_result = self._load_stage_item_result_payload(item)
                sync_observation = dict(item_result.get("sync_observation") or {})
                downstream_status = (
                    self._string_or_none(sync_observation.get("downstream_status"))
                    or self._string_or_none(item_result.get("downstream_status"))
                )
                display_downstream_status = self._downstream_status_display_value(downstream_status)
                downstream_status_counts[display_downstream_status] = downstream_status_counts.get(display_downstream_status, 0) + 1
            counts = {
                "total_items": len(stage_items),
                "success_items": len([item for item in stage_items if (self._normalize_downstream_status(item.status) or item.status) == "success"]),
                "failed_items": len([item for item in stage_items if (self._normalize_downstream_status(item.status) or item.status) == "failed"]),
                "downstream_missing_items": len([item for item in stage_items if (self._normalize_downstream_status(item.status) or item.status) == "downstream_missing"]),
                "skipped_items": 0,
                "running_items": len(
                    [
                        item for item in stage_items
                        if (self._normalize_downstream_status(item.status) or item.status) in {"pending", "queued", "running", "dispatching"}
                    ]
                ),
            }
            stage_summary = BinarySecurityStageSummary(
                stage_name=stage_name,
                sequence_no=run.sequence_no if run else index,
                status=self._business_stage_status(task, stage_name, run, stage_items, db=db),
                retry_count=int(run.retry_count or 0) if run else 0,
                retry_supported=stage_retry_support.get(stage_name, (False, None))[0],
                retry_reason=stage_retry_support.get(stage_name, (False, None))[1],
                retry_failed_supported=stage_retry_failed_support.get(stage_name, (False, None, []))[0],
                retry_failed_reason=stage_retry_failed_support.get(stage_name, (False, None, []))[1],
                retry_full_supported=stage_retry_support.get(stage_name, (False, None))[0],
                retry_full_reason=stage_retry_support.get(stage_name, (False, None))[1],
                total_items=counts["total_items"],
                success_items=counts["success_items"],
                failed_items=counts["failed_items"],
                orchestration_failed_items=counts["failed_items"] + counts["downstream_missing_items"],
                downstream_missing_items=counts["downstream_missing_items"],
                skipped_items=counts["skipped_items"],
                running_items=counts["running_items"],
                cancelled_items=len([item for item in stage_items if (self._normalize_downstream_status(item.status) or item.status) == "cancelled"]),
                downstream_status_counts=downstream_status_counts,
                started_at=run.started_at if run else None,
                finished_at=run.finished_at if run else None,
                last_error=(
                    run.last_error
                    if run and run.last_error
                    else (
                        next((item.error_message for item in stage_items if item.error_message), None)
                        if self._business_stage_status(task, stage_name, run, stage_items, db=db) in {"failed", "partial_success", "downstream_missing", "cancelled"}
                        else None
                    )
                ),
            )
            stage_summary.abnormal_reason = self._stage_abnormal_reason(task, stage_name, stage_summary, stage_items)
            summaries.append(stage_summary)
        return summaries

    def _build_stage_summaries_readonly(
        self,
        db: Session,
        task: BinarySecurityTask,
        stage_sequence: list[str],
        stage_runs: list[BinarySecurityStageRun],
        items: list[BinarySecurityStageItem],
        *,
        include_retry_support: bool = True,
    ) -> list[BinarySecurityStageSummary]:
        return self._build_stage_summaries(
            db,
            task,
            stage_sequence,
            stage_runs,
            items,
            include_retry_support=include_retry_support,
        )

    def _aggregate_archive_stage_status(self, statuses: list[str]) -> str:
        if not statuses:
            return "pending"
        normalized = [str(status or "").strip().lower() for status in statuses]
        if any(status == "running" for status in normalized):
            return "running"
        if any(status in {"archived", "applying"} for status in normalized):
            return "applying"
        if any(status == "failed" for status in normalized):
            return "failed"
        terminal = [status for status in normalized if status != "skipped"]
        if terminal and all(status == "success" for status in terminal):
            return "success"
        return "pending"

    def _stage_requires_archive_success_gate(self, task: BinarySecurityTask, stage_name: str) -> bool:
        return self._is_streaming_tail_stage(task, stage_name) and normalize_stage_name(stage_name) == "dataflow_vuln_scan"

    def _stage_archive_jobs_by_item(self, db: Session, task_id: str, stage_name: str) -> dict[str, list[BinarySecurityArchiveJob]]:
        jobs = (
            db.query(BinarySecurityArchiveJob)
            .filter(
                BinarySecurityArchiveJob.task_id == task_id,
                BinarySecurityArchiveJob.stage_name == stage_name,
            )
            .order_by(BinarySecurityArchiveJob.created_at.asc(), BinarySecurityArchiveJob.id.asc())
            .all()
        )
        grouped: dict[str, list[BinarySecurityArchiveJob]] = {}
        for job in jobs:
            grouped.setdefault(str(job.item_id or ""), []).append(job)
        return grouped

    @staticmethod
    def _archive_jobs_by_item_id(archive_jobs: list[BinarySecurityArchiveJob]) -> dict[str, list[BinarySecurityArchiveJob]]:
        grouped: dict[str, list[BinarySecurityArchiveJob]] = {}
        for job in archive_jobs:
            grouped.setdefault(str(getattr(job, "item_id", "") or ""), []).append(job)
        return grouped

    def _resolved_stage_item_archive_refs(
        self,
        item: BinarySecurityStageItem,
        archive_jobs: list[BinarySecurityArchiveJob] | None = None,
    ) -> dict[str, Any]:
        current_output_ref = dict(item.output_ref or {})
        current_result = self._load_stage_item_result_payload(item)
        resolved: dict[str, Any] = {}
        for key in ("artifact_root", "archive_root", "archive_copy_stats"):
            current_value = current_output_ref.get(key)
            if current_value is None:
                current_value = current_result.get(key)
            if current_value is not None:
                resolved[key] = current_value
        if archive_jobs:
            ordered_jobs = sorted(
                archive_jobs,
                key=lambda job: (
                    getattr(job, "updated_at", None) or getattr(job, "completed_at", None) or getattr(job, "created_at", None) or datetime.min,
                    str(getattr(job, "id", "") or ""),
                ),
            )
            for job in reversed(ordered_jobs):
                if "archive_root" not in resolved and getattr(job, "archive_root", None):
                    resolved["archive_root"] = job.archive_root
                payload = dict(getattr(job, "payload", None) or {})
                if "artifact_root" not in resolved and payload.get("artifact_root"):
                    resolved["artifact_root"] = payload.get("artifact_root")
                if "archive_copy_stats" not in resolved and payload.get("archive_copy_stats") is not None:
                    resolved["archive_copy_stats"] = dict(payload.get("archive_copy_stats") or {})
                if "archive_job_id" not in resolved and getattr(job, "id", None):
                    resolved["archive_job_id"] = job.id
                if "archive_status" not in resolved and getattr(job, "archive_status", None):
                    resolved["archive_status"] = job.archive_status
                if all(
                    key in resolved
                    for key in ("archive_root", "artifact_root", "archive_copy_stats", "archive_job_id", "archive_status")
                ):
                    break
        if "artifact_root" not in resolved and resolved.get("archive_root"):
            resolved["artifact_root"] = resolved["archive_root"]
        return resolved

    def _stage_item_archive_root(
        self,
        item: BinarySecurityStageItem,
        archive_jobs: list[BinarySecurityArchiveJob] | None = None,
    ) -> str:
        resolved = self._resolved_stage_item_archive_refs(item, archive_jobs=archive_jobs)
        return str(
            resolved.get("archive_root")
            or resolved.get("artifact_root")
            or dict(item.output_ref or {}).get("unpacked_root")
            or self._load_stage_item_result_payload(item).get("unpacked_root")
            or ""
        ).strip()

    def _stage_item_artifact_root(
        self,
        item: BinarySecurityStageItem,
        archive_jobs: list[BinarySecurityArchiveJob] | None = None,
    ) -> str:
        resolved = self._resolved_stage_item_archive_refs(item, archive_jobs=archive_jobs)
        return str(
            resolved.get("artifact_root")
            or resolved.get("archive_root")
            or ""
        ).strip()

    def _stage_archive_success_blocked(
        self,
        task: BinarySecurityTask,
        stage_name: str,
        items: list[BinarySecurityStageItem],
        *,
        db: Session | None = None,
    ) -> bool:
        if not items or not self._stage_requires_archive_success_gate(task, stage_name):
            return False
        session = db
        owns_session = False
        if session is None:
            session = get_session_factory()()
            owns_session = True
        try:
            jobs_by_item = self._stage_archive_jobs_by_item(session, task.id, stage_name)
            for item in items:
                normalized_status = self._normalize_downstream_status(item.status) or str(item.status or "").strip()
                if normalized_status not in ARCHIVE_SUCCESS_MAPPED_STATUSES:
                    continue
                item_jobs = jobs_by_item.get(str(item.id or ""), [])
                if item_jobs and any(str(job.archive_status or "").strip() != "success" for job in item_jobs):
                    return True
            return False
        finally:
            if owns_session:
                session.close()

    def _build_stage_overview_nodes(
        self,
        db: Session,
        task: BinarySecurityTask,
        stage_summaries: list[BinarySecurityStageSummary],
        archive_jobs: list[BinarySecurityArchiveJobResponse],
        stage_items: list[BinarySecurityStageItem],
    ) -> list[BinarySecurityOverviewNode]:
        stage_sequence = self._stage_sequence_for_task(task)
        summaries_by_stage = {summary.stage_name: summary for summary in stage_summaries}
        jobs_by_stage: dict[str, list[BinarySecurityArchiveJobResponse]] = {}
        items_by_stage: dict[str, list[BinarySecurityStageItem]] = {}
        for job in archive_jobs:
            jobs_by_stage.setdefault(job.stage_name, []).append(job)
        for item in stage_items:
            items_by_stage.setdefault(item.stage_name, []).append(item)
        nodes: list[BinarySecurityOverviewNode] = []
        for index, stage_name in enumerate(stage_sequence, start=1):
            summary = summaries_by_stage.get(stage_name) or BinarySecurityStageSummary(stage_name=stage_name, sequence_no=index, status="pending")
            stage_jobs = jobs_by_stage.get(stage_name, [])
            current_stage_items = items_by_stage.get(stage_name, [])
            downstream_status_counts: dict[str, int] = {}
            for item in current_stage_items:
                item_result = self._load_stage_item_result_payload(item)
                sync_observation = dict(item_result.get("sync_observation") or {})
                raw_downstream_status = (
                    self._string_or_none(sync_observation.get("downstream_status"))
                    or self._string_or_none(item_result.get("downstream_status"))
                )
                display_status = self._downstream_status_display_value(raw_downstream_status)
                downstream_status_counts[display_status] = downstream_status_counts.get(display_status, 0) + 1
            business_detail = BinarySecurityOverviewBusinessDetail(
                total_items=summary.total_items,
                success_items=summary.success_items,
                failed_items=summary.failed_items,
                orchestration_failed_items=summary.orchestration_failed_items or summary.failed_items,
                downstream_missing_items=summary.downstream_missing_items,
                skipped_items=summary.skipped_items,
                running_items=summary.running_items,
                cancelled_items=summary.cancelled_items or downstream_status_counts.get("cancelled", 0),
                downstream_status_counts=downstream_status_counts,
                downstream_services=sorted({str(item.downstream_service) for item in current_stage_items if item.downstream_service}),
                representative_item_key=next((item.item_key for item in current_stage_items if item.item_key), None),
                representative_downstream_task_id=next((item.downstream_task_id for item in current_stage_items if item.downstream_task_id), None),
            )
            nodes.append(
                BinarySecurityOverviewNode(
                    node_id=f"business:{stage_name}",
                    node_type="business",
                    stage_name=stage_name,
                    sequence_no=summary.sequence_no or index,
                    title=STAGE_TITLES.get(stage_name, stage_name),
                    status=summary.status,
                    status_label=self._status_label(summary.status),
                    started_at=summary.started_at,
                    finished_at=summary.finished_at,
                    updated_at=summary.finished_at or summary.started_at,
                    last_error=summary.last_error,
                    abnormal_reason=summary.abnormal_reason or self._stage_abnormal_reason(stage_name, summary, current_stage_items),
                    retry_supported=summary.retry_supported,
                    retry_reason=summary.retry_reason,
                    retry_failed_supported=summary.retry_failed_supported,
                    retry_failed_reason=summary.retry_failed_reason,
                    retry_full_supported=summary.retry_full_supported,
                    retry_full_reason=summary.retry_full_reason,
                    detail=business_detail,
                )
            )
            first_created_at = min((job.created_at for job in stage_jobs if job.created_at), default=None)
            last_updated_at = max(
                (job.completed_at or job.updated_at or job.started_at or job.created_at for job in stage_jobs if (job.completed_at or job.updated_at or job.started_at or job.created_at)),
                default=None,
            )
            duration_seconds = None
            if first_created_at and last_updated_at:
                duration_seconds = max(0.0, (last_updated_at - first_created_at).total_seconds())
            archive_detail = BinarySecurityOverviewArchiveDetail(
                job_count=len(stage_jobs),
                success_count=len([job for job in stage_jobs if job.archive_status == "success"]),
                failed_count=len([job for job in stage_jobs if job.archive_status == "failed"]),
                running_count=len([job for job in stage_jobs if job.archive_status == "running"]),
                applying_count=len([job for job in stage_jobs if job.archive_status in {"archived", "applying"}]),
                pending_count=len([job for job in stage_jobs if job.archive_status == "pending"]),
                first_created_at=first_created_at,
                last_updated_at=last_updated_at,
                duration_seconds=duration_seconds,
                latest_error=next((job.error_message for job in reversed(stage_jobs) if job.archive_status == "failed" and job.error_message), None),
                jobs=stage_jobs,
            )
            archive_status = self._aggregate_archive_stage_status([job.archive_status for job in stage_jobs])
            terminal_item_count = sum(
                1
                for item in current_stage_items
                if (self._normalize_downstream_status(item.status) or item.status) in {"success", "failed", "partial_success", "cancelled"}
            )
            has_non_terminal_items = any(
                (self._normalize_downstream_status(item.status) or item.status) not in {"success", "failed", "partial_success", "cancelled"}
                for item in current_stage_items
            )
            # A stage may still be running while some completed items have already
            # been archived successfully. In that case the archive lane should stay
            # idle/pending until new terminal items produce new archive jobs,
            # instead of looking like an actively running archive worker.
            if archive_status == "success" and (has_non_terminal_items or len(stage_jobs) < terminal_item_count):
                archive_status = "pending"
            if stage_name == "system_analysis" and summary.status == "waiting_confirmation":
                archive_status = "pending"
            archive_retry_supported, archive_retry_reason, _ = self._archive_retry_support(db, task, stage_name)
            archive_retry_full_supported, archive_retry_full_reason, _, _ = self._archive_full_retry_support(db, task, stage_name)
            archive_abnormal_reason = next((job.abnormal_reason for job in reversed(stage_jobs) if job.abnormal_reason), None)
            nodes.append(
                BinarySecurityOverviewNode(
                    node_id=f"archive:{stage_name}",
                    node_type="archive",
                    stage_name=stage_name,
                    sequence_no=summary.sequence_no or index,
                    title="产物归档",
                    status=archive_status,
                    status_label=self._status_label(archive_status),
                    started_at=first_created_at,
                    finished_at=last_updated_at if archive_status == "success" else None,
                    updated_at=last_updated_at,
                    last_error=archive_detail.latest_error,
                    abnormal_reason=archive_abnormal_reason,
                    retry_supported=archive_retry_supported,
                    retry_reason=archive_retry_reason,
                    retry_failed_supported=archive_retry_supported,
                    retry_failed_reason=archive_retry_reason,
                    retry_full_supported=archive_retry_full_supported,
                    retry_full_reason=archive_retry_full_reason,
                    detail=archive_detail,
                )
            )
        return nodes

    def _downstream_status_display_value(self, raw_status: str | None) -> str:
        normalized = str(raw_status or "").strip().lower()
        if not normalized:
            return "unknown"
        return normalized

    def _build_project_stats(self, tasks: list[BinarySecurityTask]) -> BinarySecurityProjectStats:
        active_statuses = {
            "pending",
            "dispatching",
            "running",
            "pending_upload",
            "uploading",
            "ready_to_start",
            TASK_STATUS_PENDING_MODULE_CONFIRMATION,
        }
        stats = BinarySecurityProjectStats(total=len(tasks))
        for task in tasks:
            status = task.status or ""
            metrics = task.metrics or {}
            if status in active_statuses:
                stats.running += 1
            elif status == "success":
                stats.success += 1
            elif status == "partial_success":
                stats.partial_success += 1
            elif status == "failed":
                stats.failed += 1
            elif status == "cancelled":
                stats.cancelled += 1
            stats.selected_module_count += int(metrics.get("selected_module_count") or 0)
            stats.candidate_module_count += int(metrics.get("candidate_module_count") or 0)
            stats.high_risk_module_count += int(metrics.get("high_risk_module_count") or 0)
            stats.entry_count += int(metrics.get("entry_count") or 0)
            stats.vuln_result_count += int(metrics.get("vuln_result_count") or 0)
            stats.input_count += int(metrics.get("firmware_item_count") or 0)
            stats.unpacked_firmware_count += int(metrics.get("unpacked_firmware_count") or 0)
            stats.failed_firmware_count += int(metrics.get("failed_firmware_count") or 0)
        return stats

    def _build_project_stats_sql(
        self,
        db: Session,
        *,
        project_id: str,
        task_type: str | None = None,
    ) -> BinarySecurityProjectStats:
        base_query = db.query(BinarySecurityTask).filter(BinarySecurityTask.project_id == project_id)
        normalized_task_type = self._validate_task_type(task_type) if task_type else None
        if normalized_task_type:
            if normalized_task_type == TASK_TYPE_BINARY:
                base_query = base_query.filter(
                    or_(
                        BinarySecurityTask.task_type == TASK_TYPE_BINARY,
                        BinarySecurityTask.task_type.is_(None),
                    )
                )
            else:
                base_query = base_query.filter(BinarySecurityTask.task_type == normalized_task_type)
        active_statuses = (
            "pending",
            "dispatching",
            "running",
            "pending_upload",
            "uploading",
            "ready_to_start",
            TASK_STATUS_PENDING_MODULE_CONFIRMATION,
        )
        if not hasattr(base_query, "with_entities"):
            tasks = base_query.options(load_only(BinarySecurityTask.status, BinarySecurityTask.metrics_json)).all()
            return self._build_project_stats(tasks)

        def _json_metric_sum(metric_key: str):
            return func.sum(
                cast(
                    func.coalesce(
                        func.json_extract(BinarySecurityTask.metrics_json, f'$.{metric_key}'),
                        0,
                    ),
                    Integer,
                )
            )
        try:
            row = base_query.with_entities(
                func.count(BinarySecurityTask.id),
                func.sum(case((BinarySecurityTask.status.in_(active_statuses), 1), else_=0)),
                func.sum(case((BinarySecurityTask.status == "success", 1), else_=0)),
                func.sum(case((BinarySecurityTask.status == "partial_success", 1), else_=0)),
                func.sum(case((BinarySecurityTask.status == "failed", 1), else_=0)),
                func.sum(case((BinarySecurityTask.status == "cancelled", 1), else_=0)),
                _json_metric_sum("selected_module_count"),
                _json_metric_sum("candidate_module_count"),
                _json_metric_sum("high_risk_module_count"),
                _json_metric_sum("entry_count"),
                _json_metric_sum("vuln_result_count"),
                _json_metric_sum("firmware_item_count"),
                _json_metric_sum("unpacked_firmware_count"),
                _json_metric_sum("failed_firmware_count"),
            ).one()
        except Exception:
            logger.debug(
                "Falling back to in-memory project stats aggregation",
                exc_info=True,
            )
            tasks = base_query.options(load_only(BinarySecurityTask.status, BinarySecurityTask.metrics_json)).all()
            return self._build_project_stats(tasks)

        return BinarySecurityProjectStats(
            total=int(row[0] or 0),
            running=int(row[1] or 0),
            success=int(row[2] or 0),
            partial_success=int(row[3] or 0),
            failed=int(row[4] or 0),
            cancelled=int(row[5] or 0),
            selected_module_count=int(row[6] or 0),
            candidate_module_count=int(row[7] or 0),
            high_risk_module_count=int(row[8] or 0),
            entry_count=int(row[9] or 0),
            vuln_result_count=int(row[10] or 0),
            input_count=int(row[11] or 0),
            unpacked_firmware_count=int(row[12] or 0),
            failed_firmware_count=int(row[13] or 0),
        )

    def _build_project_stage_aggregates(
        self,
        db: Session,
        tasks: list[BinarySecurityTask],
        task_type: str | None = None,
    ) -> list[BinarySecurityProjectStageAggregate]:
        if task_type:
            stage_sequence = list(TASK_STAGE_SEQUENCES.get(task_type, STAGE_SEQUENCE))
        elif tasks and all(self._task_type(task) == TASK_TYPE_SOURCE for task in tasks):
            stage_sequence = list(TASK_STAGE_SEQUENCES[TASK_TYPE_SOURCE])
        else:
            stage_sequence = list(TASK_STAGE_SEQUENCES[TASK_TYPE_BINARY])

        aggregates = {
            stage_name: BinarySecurityProjectStageAggregate(stage_name=stage_name, sequence_no=index)
            for index, stage_name in enumerate(stage_sequence, start=1)
        }
        task_ids = [task.id for task in tasks if task.id]
        if not task_ids:
            return list(aggregates.values())

        stage_runs = db.query(BinarySecurityStageRun).filter(BinarySecurityStageRun.task_id.in_(task_ids)).all()
        task_counts_by_stage: dict[str, set[str]] = {}
        for run in stage_runs:
            stage_name = getattr(run, "stage_name", None)
            task_id = getattr(run, "task_id", None)
            if not stage_name or not task_id or stage_name not in aggregates:
                continue
            task_counts_by_stage.setdefault(stage_name, set()).add(task_id)
        for stage_name, task_ids_for_stage in task_counts_by_stage.items():
            aggregates[stage_name].business.task_count = len(task_ids_for_stage)

        stage_items = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.task_id.in_(task_ids)).all()
        for item in stage_items:
            stage_name = getattr(item, "stage_name", None)
            if not stage_name or stage_name not in aggregates:
                continue
            raw_status = getattr(item, "status", None)
            status = self._normalize_downstream_status(raw_status) or raw_status or "unknown"
            business = aggregates[stage_name].business
            business.total_items += 1
            business.status_counts[status] = business.status_counts.get(status, 0) + 1
            if status == "success":
                business.success_items += 1
            elif status == "failed":
                business.failed_items += 1
            elif status == "cancelled":
                business.cancelled_items += 1
            if status in {"pending", "queued", "running", "dispatching"}:
                business.running_items += 1

        archive_jobs = db.query(BinarySecurityArchiveJob).filter(BinarySecurityArchiveJob.task_id.in_(task_ids)).all()
        for job in archive_jobs:
            stage_name = getattr(job, "stage_name", None)
            if not stage_name or stage_name not in aggregates:
                continue
            status = str(getattr(job, "archive_status", None) or "unknown").strip().lower() or "unknown"
            archive = aggregates[stage_name].archive
            archive.job_count += 1
            archive.status_counts[status] = archive.status_counts.get(status, 0) + 1
            if status == "success":
                archive.success_count += 1
            elif status == "failed":
                archive.failed_count += 1
            elif status == "running":
                archive.running_count += 1
            elif status in {"archived", "applying"}:
                archive.applying_count += 1
            elif status == "pending":
                archive.pending_count += 1

        return list(aggregates.values())

    def _build_project_stage_aggregates_sql(
        self,
        db: Session,
        *,
        project_id: str,
        task_type: str | None = None,
    ) -> list[BinarySecurityProjectStageAggregate]:
        normalized_task_type = self._validate_task_type(task_type) if task_type else None
        if normalized_task_type:
            stage_sequence = list(TASK_STAGE_SEQUENCES.get(normalized_task_type, STAGE_SEQUENCE))
        else:
            stage_sequence = list(TASK_STAGE_SEQUENCES[TASK_TYPE_BINARY])

        aggregates = {
            stage_name: BinarySecurityProjectStageAggregate(stage_name=stage_name, sequence_no=index)
            for index, stage_name in enumerate(stage_sequence, start=1)
        }

        task_join_filters = [BinarySecurityTask.project_id == project_id]
        if normalized_task_type:
            if normalized_task_type == TASK_TYPE_BINARY:
                task_join_filters.append(
                    or_(
                        BinarySecurityTask.task_type == TASK_TYPE_BINARY,
                        BinarySecurityTask.task_type.is_(None),
                    )
                )
            else:
                task_join_filters.append(BinarySecurityTask.task_type == normalized_task_type)

        def _safe_all(query, section: str):
            try:
                return query.all()
            except Exception:
                logger.debug(
                    "Project stage aggregate SQL query failed; leaving section empty",
                    extra={"project_id": project_id, "task_type": normalized_task_type or "all", "section": section},
                    exc_info=True,
                )
                return []

        stage_run_rows = _safe_all(
            db.query(BinarySecurityStageRun.stage_name, func.count(func.distinct(BinarySecurityStageRun.task_id)))
            .join(BinarySecurityTask, BinarySecurityTask.id == BinarySecurityStageRun.task_id)
            .filter(*task_join_filters)
            .group_by(BinarySecurityStageRun.stage_name)
            ,
            "stage_runs",
        )
        for stage_name, task_count in stage_run_rows:
            if stage_name in aggregates:
                aggregates[stage_name].business.task_count = int(task_count or 0)

        stage_item_rows = _safe_all(
            db.query(
                BinarySecurityStageItem.stage_name,
                BinarySecurityStageItem.status,
                func.count(BinarySecurityStageItem.id),
            )
            .join(BinarySecurityTask, BinarySecurityTask.id == BinarySecurityStageItem.task_id)
            .filter(*task_join_filters)
            .group_by(BinarySecurityStageItem.stage_name, BinarySecurityStageItem.status)
            ,
            "stage_items",
        )
        for stage_name, raw_status, count in stage_item_rows:
            aggregate = aggregates.get(stage_name)
            if not aggregate:
                continue
            status = self._normalize_downstream_status(raw_status) or raw_status or "unknown"
            business = aggregate.business
            item_count = int(count or 0)
            business.total_items += item_count
            business.status_counts[status] = business.status_counts.get(status, 0) + item_count
            if status == "success":
                business.success_items += item_count
            elif status == "failed":
                business.failed_items += item_count
            elif status == "cancelled":
                business.cancelled_items += item_count
            if status in {"pending", "queued", "running", "dispatching"}:
                business.running_items += item_count

        archive_job_rows = _safe_all(
            db.query(
                BinarySecurityArchiveJob.stage_name,
                BinarySecurityArchiveJob.archive_status,
                func.count(BinarySecurityArchiveJob.id),
            )
            .join(BinarySecurityTask, BinarySecurityTask.id == BinarySecurityArchiveJob.task_id)
            .filter(*task_join_filters)
            .group_by(BinarySecurityArchiveJob.stage_name, BinarySecurityArchiveJob.archive_status)
            ,
            "archive_jobs",
        )
        for stage_name, raw_status, count in archive_job_rows:
            aggregate = aggregates.get(stage_name)
            if not aggregate:
                continue
            status = str(raw_status or "unknown").strip().lower() or "unknown"
            archive = aggregate.archive
            job_count = int(count or 0)
            archive.job_count += job_count
            archive.status_counts[status] = archive.status_counts.get(status, 0) + job_count
            if status == "success":
                archive.success_count += job_count
            elif status == "failed":
                archive.failed_count += job_count
            elif status == "running":
                archive.running_count += job_count
            elif status in {"archived", "applying"}:
                archive.applying_count += job_count
            elif status == "pending":
                archive.pending_count += job_count

        return list(aggregates.values())

    def _task_list_stage_state_by_task(
        self,
        db: Session,
        tasks: list[BinarySecurityTask],
    ) -> tuple[dict[str, list[BinarySecurityStageRun]], dict[str, list[BinarySecurityStageItem]]]:
        task_ids = [str(task.id) for task in tasks if getattr(task, "id", None)]
        if not task_ids:
            return {}, {}

        stage_runs = (
            db.query(BinarySecurityStageRun)
            .filter(BinarySecurityStageRun.task_id.in_(task_ids))
            .all()
        )
        stage_items = (
            db.query(BinarySecurityStageItem)
            .filter(BinarySecurityStageItem.task_id.in_(task_ids))
            .all()
        )
        stage_runs_by_task: dict[str, list[BinarySecurityStageRun]] = {}
        stage_items_by_task: dict[str, list[BinarySecurityStageItem]] = {}
        for run in stage_runs:
            task_id = str(getattr(run, "task_id", "") or "")
            if task_id:
                stage_runs_by_task.setdefault(task_id, []).append(run)
        for item in stage_items:
            task_id = str(getattr(item, "task_id", "") or "")
            if task_id:
                stage_items_by_task.setdefault(task_id, []).append(item)
        return stage_runs_by_task, stage_items_by_task

    def _task_runtime_lease_view(
        self,
        db: Session,
        task: BinarySecurityTask,
    ) -> tuple[str | None, datetime | None, str | None, str | None, str | None, int | None]:
        lease = self._runtime_lease_for_task(db, task.id)
        if lease is not None:
            if self._task_runtime_phase(task) == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION:
                return (
                    lease.owner_instance_id,
                    lease.lease_expires_at,
                    "tail_runtime_lease",
                    lease.owner_pod_uid,
                    lease.owner_boot_id,
                    lease.generation,
                )
            return (
                lease.owner_instance_id,
                lease.lease_expires_at,
                "runtime_lease",
                lease.owner_pod_uid,
                lease.owner_boot_id,
                lease.generation,
            )
        return (
            str(task.dispatcher_instance_id or "").strip() or None,
            task.lease_expires_at,
            "legacy_task_row" if task.lease_expires_at is not None else None,
            None,
            None,
            None,
        )

    def _has_active_owned_execution_holder(
        self,
        db: Session,
        task: BinarySecurityTask,
    ) -> bool:
        if self._task_runtime_phase(task) != TASK_RUNTIME_PHASE_OWNED_EXECUTION:
            return False
        lease_owner, lease_expires_at, lease_source, _lease_pod_uid, _lease_boot_id, _lease_generation = self._task_runtime_lease_view(db, task)
        if lease_source == "runtime_lease" and lease_owner and ((_seconds_until(lease_expires_at) or 0) > 0):
            return True
        # Legacy task-row dispatch/lease fields can outlive the real worker that
        # previously owned the task. For owned_execution takeover they are only
        # diagnostic context, not sufficient proof of a live holder.
        return False

    def _should_requeue_for_owned_execution(
        self,
        db: Session,
        task: BinarySecurityTask,
        *,
        next_stage: str | None = None,
        next_stage_status: str | None = None,
    ) -> bool:
        if self._task_runtime_phase(task) != TASK_RUNTIME_PHASE_OWNED_EXECUTION:
            return False
        if self._has_active_owned_execution_holder(db, task):
            return False
        if str(task.status or "").strip() not in {"running", "dispatching", "pending"}:
            return False
        stage_name = str(next_stage or task.current_stage or "").strip()
        if not stage_name:
            return False
        normalized_stage_status = str(next_stage_status or "").strip()
        if normalized_stage_status and normalized_stage_status not in {"pending", "queued", "running", "dispatching", "applying"}:
            return False
        return self._stage_has_real_runnable_work(db, task, stage_name)

    def _requeue_owned_execution_takeover(
        self,
        db: Session,
        task: BinarySecurityTask,
        *,
        stage_name: str | None,
        reason: str,
        event_type: str,
        message: str,
        event_level: str = "warning",
        event_payload: dict[str, Any] | None = None,
    ) -> None:
        task.current_stage = stage_name or task.current_stage
        task.status = "pending"
        self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
        task.tail_reconcile_state = "idle"
        task.dispatcher_instance_id = None
        task.dispatch_started_at = None
        task.lease_expires_at = None
        task.finished_at = None
        task.last_error = None
        self._clear_runtime_lease(db, task.id)
        self._release_tail_reconcile_owner(task.id)
        self._last_task_heartbeat_at.pop(task.id, None)
        self._record_event(
            db,
            task,
            event_type,
            message,
            level=event_level,
            stage_name=stage_name,
            payload={
                "takeover_reason": reason,
                "takeover_action": "requeue_owned_execution",
                **(event_payload or {}),
            },
        )
        self._sync_task_abnormal_reason_snapshot(db, task, None)
        self._enqueue_task(task.id)

    def _reconcile_lease_view(
        self,
        db: Session,
        task: BinarySecurityTask,
    ) -> tuple[str | None, datetime | None, str | None, str | None, int | None]:
        if self._task_runtime_phase(task) != TASK_RUNTIME_PHASE_TAIL_RECONCILIATION:
            return None, None, None, None, None
        lease = self._runtime_lease_for_task(db, task.id)
        if lease is None:
            return None, None, None, None, None
        return (
            str(lease.owner_instance_id or "").strip() or None,
            lease.lease_expires_at,
            str(lease.owner_pod_uid or "").strip() or None,
            str(lease.owner_boot_id or "").strip() or None,
            lease.generation,
        )

    def _task_sync_status_view(
        self,
        items: list[BinarySecurityStageItem] | None,
    ) -> tuple[datetime | None, datetime | None, datetime | None, str | None, str | None, int, int, int]:
        latest_success: datetime | None = None
        latest_attempt: datetime | None = None
        latest_error_at: datetime | None = None
        latest_error_type: str | None = None
        latest_error_message: str | None = None
        active_sync_error_item_count = 0
        never_synced_item_count = 0
        stale_synced_item_count = 0
        now = _now()
        for item in items or []:
            last_synced_at = self._stage_item_last_synced_at_value(item)
            if last_synced_at is not None and (latest_success is None or last_synced_at > latest_success):
                latest_success = last_synced_at
            result = self._load_stage_item_result_payload(item)
            sync_observation = dict(result.get("sync_observation") or {})
            raw_attempt = (
                sync_observation.get("last_attempt_at")
                or sync_observation.get("last_synced_at")
                or result.get("last_sync_attempt_at")
                or result.get("downstream_status_synced_at")
            )
            parsed_attempt: datetime | None = None
            if isinstance(raw_attempt, str) and raw_attempt.strip():
                try:
                    parsed_attempt = datetime.fromisoformat(raw_attempt)
                except ValueError:
                    parsed_attempt = None
            if parsed_attempt is not None and (latest_attempt is None or parsed_attempt > latest_attempt):
                latest_attempt = parsed_attempt
            raw_error_at = sync_observation.get("last_error_at") or result.get("last_sync_error_at")
            parsed_error_at: datetime | None = None
            if isinstance(raw_error_at, str) and raw_error_at.strip():
                try:
                    parsed_error_at = datetime.fromisoformat(raw_error_at)
                except ValueError:
                    parsed_error_at = None
            error_type = self._string_or_none(sync_observation.get("error_type")) or self._string_or_none(result.get("last_sync_error_type"))
            error_message = self._string_or_none(sync_observation.get("error_message")) or self._string_or_none(result.get("last_sync_error_message"))
            if parsed_error_at is not None:
                active_sync_error_item_count += 1
                if latest_error_at is None or parsed_error_at > latest_error_at:
                    latest_error_at = parsed_error_at
                    latest_error_type = error_type
                    latest_error_message = error_message
            elif error_type is not None or error_message is not None:
                latest_error_type = error_type
                latest_error_message = error_message
            if last_synced_at is None and parsed_attempt is not None:
                never_synced_item_count += 1
            if last_synced_at is not None and (now - last_synced_at).total_seconds() >= max(60, int(self.cfg.scheduler.downstream_reconcile_interval_seconds or 30) * 3):
                stale_synced_item_count += 1
        return (
            latest_success,
            latest_attempt,
            latest_error_at,
            latest_error_type,
            latest_error_message,
            active_sync_error_item_count,
            never_synced_item_count,
            stale_synced_item_count,
        )

    def _task_list_response(
        self,
        db: Session,
        task: BinarySecurityTask,
        *,
        queue_info: dict[str, Any] | None = None,
        stage_runs: list[BinarySecurityStageRun] | None = None,
        stage_items: list[BinarySecurityStageItem] | None = None,
        active_operation: BinarySecurityTaskOperation | None = None,
        cancel_operation: BinarySecurityTaskOperation | None = None,
    ) -> BinarySecurityTaskResponse:
        metrics = task.metrics or {}
        queue_info = queue_info or {"pending_positions": {}}
        queue_position = queue_info.get("pending_positions", {}).get(task.id)
        queue_state, recoverable_reason = self._task_queue_state(task, queue_info, db=db)
        stage_sequence = self._stage_sequence_for_task(task)
        stage_summaries = self._build_task_list_stage_summaries(
            db,
            task,
            stage_sequence,
                    stage_runs=stage_runs,
                    stage_items=stage_items,
                )
        abnormal_reason = None
        if isinstance(task.latest_abnormal_reason, dict):
            try:
                abnormal_reason = BinarySecurityAbnormalReason(**task.latest_abnormal_reason)
            except Exception:
                abnormal_reason = None
        tail_summary = self._tail_stage_work_summary(db, task)
        lease_owner, lease_expires_at, lease_source, lease_pod_uid, lease_boot_id, lease_generation = self._task_runtime_lease_view(db, task)
        runtime_phase = self._task_runtime_phase(task)
        task_control_mode = self._task_control_mode(task)
        reconcile_owner, reconcile_lease_expires_at, reconcile_pod_uid, reconcile_boot_id, reconcile_generation = self._reconcile_lease_view(db, task)
        base_policy = self._task_base_policy(task)
        runtime_override = self._task_runtime_override(task)
        effective_runtime_policy = self._effective_runtime_policy(task)
        (
            last_successful_sync_at,
            last_sync_attempt_at,
            last_sync_error_at,
            last_sync_error_type,
            last_sync_error_message,
            active_sync_error_item_count,
            never_synced_item_count,
            stale_synced_item_count,
        ) = self._task_sync_status_view(stage_items)
        manual_operation_state = self._build_task_list_manual_operation_state(
            task,
            stage_summaries=stage_summaries,
            active_operation=active_operation,
        )
        failure_snapshot = self._stage_failure_snapshot(
            task,
            next(
                (
                    run
                    for run in stage_runs or []
                    if str(run.stage_name or "").strip() == str(task.current_stage or "").strip()
                ),
                None,
            ),
        )
        terminal_failure = (
            self._task_status_is_terminal(task.status)
            and str(failure_snapshot.get("failure_category") or "").strip() == "business"
        )
        return BinarySecurityTaskResponse(
            id=task.id,
            project_id=task.project_id,
            task_type=self._task_type(task),
            name=task.name,
            status=task.status,
            runtime_phase=runtime_phase,
            task_control_mode=task_control_mode,
            current_operation_id=task.current_operation_id,
            execution_epoch=int(getattr(task, "execution_epoch", 0) or 0),
            current_stage=task.current_stage,
            last_error=task.last_error,
            terminal_failure=terminal_failure,
            requeue_suppressed=terminal_failure,
            failure_code=self._string_or_none(failure_snapshot.get("failure_code")) if terminal_failure else None,
            failure_category=self._string_or_none(failure_snapshot.get("failure_category")) if terminal_failure else None,
            failure_message=self._string_or_none(failure_snapshot.get("failure_message") or failure_snapshot.get("error")) if terminal_failure else None,
            firmware_path=task.firmware_path,
            stage_sequence=stage_sequence,
            is_queued=queue_state == "queued",
            queue_position=queue_position,
            queue_state=queue_state,
            recoverable_reason=recoverable_reason,
            last_reconcile_at=queue_info.get("last_reconcile_at"),
            dispatcher_instance_id=task.dispatcher_instance_id,
            task_lease_owner_instance_id=lease_owner,
            task_lease_expires_at=lease_expires_at,
            task_lease_source=lease_source,
            tail_control_mode=str(tail_summary.get("tail_control_mode") or "idle"),
            tail_has_runnable_unbound_items=bool(tail_summary.get("has_runnable_unbound_items")),
            tail_unbound_runnable_item_count=int(tail_summary.get("unbound_runnable_item_count", 0) or 0),
            tail_bound_active_item_count=int(tail_summary.get("bound_active_item_count", 0) or 0),
            tail_has_downstream_refs=bool(tail_summary.get("has_downstream_refs")),
            tail_takeover_required=bool(tail_summary.get("takeover_required")),
            tail_takeover_reason=self._string_or_none(tail_summary.get("takeover_reason")),
            tail_reconcile_state=self._tail_reconcile_state(task),
            reconcile_owner_instance_id=reconcile_owner,
            reconcile_lease_expires_at=reconcile_lease_expires_at,
            reconcile_owner_pod_uid=reconcile_pod_uid,
            reconcile_owner_boot_id=reconcile_boot_id,
            reconcile_generation=reconcile_generation,
            runtime_override_version=int(getattr(task, "runtime_override_version", 0) or 0),
            runtime_override_updated_at=getattr(task, "runtime_override_updated_at", None),
            runtime_override_updated_by=getattr(task, "runtime_override_updated_by", None),
            runtime_policy_effect_scope=self._runtime_policy_effect_scope(task),
            base_policy=base_policy,
            runtime_override=runtime_override,
            effective_runtime_policy=effective_runtime_policy,
            last_successful_downstream_sync_at=last_successful_sync_at,
            last_sync_attempt_at=last_sync_attempt_at,
            last_sync_error_at=last_sync_error_at,
            last_sync_error_type=last_sync_error_type,
            last_sync_error_message=last_sync_error_message,
            active_sync_error_item_count=active_sync_error_item_count,
            never_synced_item_count=never_synced_item_count,
            stale_synced_item_count=stale_synced_item_count,
            created_by=task.created_by,
            created_at=task.created_at,
            updated_at=task.updated_at,
            started_at=task.started_at,
            finished_at=task.finished_at,
            high_risk_module_count=int(metrics.get("high_risk_module_count", 0)),
            medium_risk_module_count=int(metrics.get("medium_risk_module_count", 0)),
            low_risk_module_count=int(metrics.get("low_risk_module_count", 0)),
            candidate_module_count=int(metrics.get("candidate_module_count", 0)),
            selected_module_count=int(metrics.get("selected_module_count", 0)),
            selected_risk_levels=_normalize_module_risk_levels(effective_runtime_policy.get("module_risk_levels")),
            module_selection_mode=self._module_selection_mode(task),
            entry_selection_mode=self._entry_selection_mode(task),
            candidate_entry_count=len(self._entry_candidates(task)),
            selected_entry_count=len(self._effective_entry_inputs(task)) if self._entry_selection_mode(task) == ENTRY_SELECTION_MODE_MANUAL_CONFIRM else len(self._entry_candidates(task)),
            entry_count=int(metrics.get("entry_count", 0)),
            vuln_result_count=int(metrics.get("vuln_result_count", 0)),
            firmware_item_count=int(metrics.get("firmware_item_count", 0)),
            unpacked_firmware_count=int(metrics.get("unpacked_firmware_count", 0)),
            failed_firmware_count=int(metrics.get("failed_firmware_count", 0)),
            task_retry_supported=False,
            task_retry_reason=None,
            task_continue_supported=False,
            task_continue_reason=None,
            task_retry_failed_items_supported=False,
            task_retry_failed_items_reason=None,
            abnormal_reason_title=abnormal_reason.title if abnormal_reason else None,
            abnormal_reason_code=abnormal_reason.code if abnormal_reason else None,
            abnormal_reason_category=abnormal_reason.category if abnormal_reason else None,
            abnormal_reason=abnormal_reason,
            stage_summaries=stage_summaries,
            manual_operation_state=manual_operation_state,
            cancel_state=self._cancel_state_from_operation(task, cancel_operation),
            cleanup_state=self._build_cleanup_state(task),
        )

    def _build_task_list_stage_summaries(
        self,
        db: Session,
        task: BinarySecurityTask,
        stage_sequence: list[str],
        *,
        stage_runs: list[BinarySecurityStageRun] | None = None,
        stage_items: list[BinarySecurityStageItem] | None = None,
    ) -> list[BinarySecurityStageSummary]:
        resolved_stage_runs = list(stage_runs or [])
        resolved_stage_items = list(stage_items or [])
        if resolved_stage_runs or resolved_stage_items:
            return self._build_stage_summaries(
                db,
                task,
                stage_sequence,
                resolved_stage_runs,
                resolved_stage_items,
                include_retry_support=False,
            )
        return self._build_stage_summaries_from_snapshot(task, stage_sequence)

    def _build_stage_summaries_from_snapshot(
        self,
        task: BinarySecurityTask,
        stage_sequence: list[str],
    ) -> list[BinarySecurityStageSummary]:
        snapshot = task.stage_summary if isinstance(task.stage_summary, dict) else {}
        summaries: list[BinarySecurityStageSummary] = []
        for index, stage_name in enumerate(stage_sequence, start=1):
            payload = snapshot.get(stage_name) if isinstance(snapshot.get(stage_name), dict) else {}
            summary = BinarySecurityStageSummary(
                stage_name=stage_name,
                sequence_no=int(payload.get("sequence_no") or index),
                status=str(payload.get("status") or ("pending" if stage_name != task.current_stage else task.status or "pending")),
                retry_count=int(payload.get("retry_count") or 0),
                retry_supported=False,
                retry_reason=None,
                retry_failed_supported=False,
                retry_failed_reason=None,
                retry_full_supported=False,
                retry_full_reason=None,
                total_items=int(payload.get("total_items") or 0),
                success_items=int(payload.get("success_items") or 0),
                failed_items=int(payload.get("failed_items") or 0),
                orchestration_failed_items=int(payload.get("orchestration_failed_items") or payload.get("failed_items") or 0),
                downstream_missing_items=int(payload.get("downstream_missing_items") or 0),
                skipped_items=int(payload.get("skipped_items") or 0),
                running_items=int(payload.get("running_items") or 0),
                cancelled_items=int(payload.get("cancelled_items") or 0),
                downstream_status_counts=dict(payload.get("downstream_status_counts") or {}),
                started_at=payload.get("started_at"),
                finished_at=payload.get("finished_at"),
                last_error=payload.get("last_error"),
            )
            abnormal_payload = payload.get("abnormal_reason") if isinstance(payload.get("abnormal_reason"), dict) else None
            if abnormal_payload:
                try:
                    summary.abnormal_reason = BinarySecurityAbnormalReason(**abnormal_payload)
                except Exception:
                    summary.abnormal_reason = None
            summaries.append(summary)
        return summaries

    def _build_task_list_manual_operation_state(
        self,
        task: BinarySecurityTask,
        *,
        stage_summaries: list[BinarySecurityStageSummary],
        active_operation: BinarySecurityTaskOperation | None = None,
    ) -> dict[str, Any]:
        if active_operation is not None:
            reason = f"当前任务正在执行 {active_operation.operation_type}，请稍后重试"
            return {
                "overall": "in_progress",
                "summary": reason,
                "blocking_code": "task_operation_in_progress",
                "blocking_reason": reason,
                "operation_in_progress": True,
                "operation_id": active_operation.id,
                "operation_type": active_operation.operation_type,
                "operation_status": active_operation.status,
                "operation_owner": active_operation.owner_instance_id,
                "operation_started_at": _isoformat_or_none(active_operation.started_at),
                "operation_expires_at": _isoformat_or_none(active_operation.claim_lease_expires_at),
                "operation_heartbeat_at": _isoformat_or_none(active_operation.heartbeat_at),
                "can_cancel": False,
                "can_continue": False,
                "can_retry": False,
                "can_retry_failed_items": False,
                "can_retry_stage": False,
                "can_retry_stage_failed_items": False,
                "can_retry_stage_full": False,
                "can_retry_archive": False,
                "can_retry_archive_failed_items": False,
                "can_retry_archive_full": False,
                "can_delete": False,
                "can_edit_policy": False,
                "can_confirm_modules": False,
            }
        running_statuses = {"pending", "dispatching", "running"}
        running = str(task.status or "").strip() in running_statuses
        has_failed_stage = any(summary.status in {"failed", "downstream_missing", "cancelled"} for summary in stage_summaries)
        return {
            "overall": "blocked" if running else "ready",
            "summary": "当前任务正在运行，详细手工操作能力请进入详情页查看" if running else ("当前任务存在失败阶段，可进入详情页执行重试/继续" if has_failed_stage else "可进入详情页查看详细操作"),
            "blocking_code": "task_running" if running else None,
            "blocking_reason": "当前任务正在运行，列表页不做实时重试能力判断" if running else None,
            "operation_in_progress": False,
            "operation_type": None,
            "operation_owner": None,
            "operation_expires_at": None,
            "operation_heartbeat_at": None,
            "can_cancel": False,
            "can_continue": False,
            "can_retry": False,
            "can_retry_failed_items": False,
            "can_retry_stage": False,
            "can_retry_stage_failed_items": False,
            "can_retry_stage_full": False,
            "can_retry_archive": False,
            "can_retry_archive_failed_items": False,
            "can_retry_archive_full": False,
            "can_delete": True,
            "can_edit_policy": not running,
            "can_confirm_modules": str(task.status or "").strip() in {TASK_STATUS_PENDING_MODULE_CONFIRMATION, "waiting_confirmation"},
        }

    def _task_list_operation_maps(
        self,
        db: Session,
        tasks: list[BinarySecurityTask],
    ) -> tuple[dict[str, BinarySecurityTaskOperation], dict[str, BinarySecurityTaskOperation]]:
        task_ids = [str(task.id) for task in tasks if getattr(task, "id", None)]
        if not task_ids:
            return {}, {}

        operations = (
            db.query(BinarySecurityTaskOperation)
            .filter(BinarySecurityTaskOperation.task_id.in_(task_ids))
            .order_by(BinarySecurityTaskOperation.created_at.desc(), BinarySecurityTaskOperation.id.desc())
            .all()
        )

        active_operations_by_task: dict[str, BinarySecurityTaskOperation] = {}
        cancel_operations_by_task: dict[str, BinarySecurityTaskOperation] = {}
        for operation in operations:
            task_id = str(getattr(operation, "task_id", "") or "")
            if not task_id:
                continue
            status_value = str(getattr(operation, "status", "") or "").strip()
            operation_type = str(getattr(operation, "operation_type", "") or "").strip()
            if task_id not in active_operations_by_task and status_value in TASK_OPERATION_ACTIVE_STATUSES:
                active_operations_by_task[task_id] = operation
            if task_id not in cancel_operations_by_task and operation_type == TASK_ACTION_CANCEL:
                if task_id in active_operations_by_task and str(active_operations_by_task[task_id].operation_type or "").strip() != TASK_ACTION_CANCEL:
                    continue
                cancel_operations_by_task[task_id] = operation
        return active_operations_by_task, cancel_operations_by_task

    def _load_task_list_cached_value(
        self,
        *,
        cache_group: str,
        project_id: str,
        task_type: str | None,
        ttl_seconds: float,
        loader,
        fallback,
    ):
        cache_key = (cache_group, project_id, str(task_type or "all"))
        now_ts = time.monotonic()
        with self._task_list_cache_lock:
            cached = self._task_list_cache.get(cache_key)
            if cached and now_ts < cached[0]:
                return copy.deepcopy(cached[1])
        try:
            value = loader()
        except Exception:
            logger.warning(
                "binary-security task list cache loader failed group=%s project_id=%s task_type=%s",
                cache_group,
                project_id,
                task_type or "all",
                exc_info=True,
            )
            with self._task_list_cache_lock:
                cached = self._task_list_cache.get(cache_key)
                if cached:
                    return copy.deepcopy(cached[1])
            return copy.deepcopy(fallback)
        with self._task_list_cache_lock:
            self._task_list_cache[cache_key] = (now_ts + max(0.1, float(ttl_seconds)), copy.deepcopy(value))
        return value

    def _load_readonly_projection_cached_value(
        self,
        *,
        cache_group: str,
        project_id: str,
        task_id: str,
        ttl_seconds: float,
        loader: Callable[[], Any],
    ) -> tuple[Any, bool]:
        if self._service_role() != "api":
            return loader(), False
        cache_key = (cache_group, project_id, task_id)
        now_ts = time.monotonic()
        with self._readonly_projection_cache_lock:
            cached = self._readonly_projection_cache.get(cache_key)
            if cached and now_ts < cached[0]:
                return copy.deepcopy(cached[1]), True
        value = loader()
        with self._readonly_projection_cache_lock:
            self._readonly_projection_cache[cache_key] = (
                now_ts + max(0.1, float(ttl_seconds)),
                copy.deepcopy(value),
            )
        return value, False

    def _log_task_read_projection_built(
        self,
        *,
        projection_kind: str,
        task: Any,
        stage_items_count: int,
        active_stage_name: str | None,
        used_cached_projection: bool,
    ) -> None:
        logger.info(
            "binary-security %s projection_only=true task_id=%s active_stage_name=%s stage_items_count=%s used_cached_projection=%s",
            projection_kind,
            task.id,
            str(active_stage_name or "").strip() or "-",
            int(stage_items_count or 0),
            bool(used_cached_projection),
        )

    def _log_task_list_query(
        self,
        *,
        project_id: str,
        task_type: str,
        page: int,
        page_size: int,
        total: int | None,
        item_count: int | None,
        duration_seconds: float,
        stage_durations: dict[str, float],
        result: str = "success",
    ) -> None:
        stage_summary = " ".join(
            f"{name}={duration:.3f}s"
            for name, duration in sorted(stage_durations.items(), key=lambda item: item[0])
        )
        level = logging.INFO
        if duration_seconds > 3.0:
            level = logging.ERROR
        elif duration_seconds > 1.0:
            level = logging.WARNING
        logger.log(
            level,
            "binary-security task list query result=%s project_id=%s task_type=%s page=%s page_size=%s total=%s item_count=%s duration=%.3fs stages=%s",
            result,
            project_id,
            task_type,
            page,
            page_size,
            total if total is not None else "-",
            item_count if item_count is not None else "-",
            duration_seconds,
            stage_summary or "-",
        )

    def _task_response(
        self,
        db: Session,
        task: BinarySecurityTask,
        queue_info: dict[str, Any] | None = None,
        detail_ctx: _TaskDetailContext | None = None,
        *,
        projection_only: bool = False,
    ) -> BinarySecurityTaskResponse:
        if detail_ctx is None:
            active_stage_name = self._active_reconcile_stage_name(task)
            if active_stage_name and not projection_only:
                self._refresh_stage_from_authoritative_items(db, task, active_stage_name)
            stage_runs = (
                db.query(BinarySecurityStageRun)
                .filter(BinarySecurityStageRun.task_id == task.id)
                .order_by(BinarySecurityStageRun.sequence_no.asc())
                .all()
            )
            items = db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.task_id == task.id).all()
            archive_jobs = db.query(BinarySecurityArchiveJob).filter(BinarySecurityArchiveJob.task_id == task.id).all()
            stage_sequence = self._stage_sequence_for_task(task)
            stage_summaries = (
                self._build_stage_summaries_readonly(db, task, stage_sequence, stage_runs, items)
                if projection_only
                else self._build_stage_summaries(db, task, stage_sequence, stage_runs, items)
            )
            abnormal_reason = None
            if isinstance(task.latest_abnormal_reason, dict):
                try:
                    abnormal_reason = BinarySecurityAbnormalReason(**task.latest_abnormal_reason)
                except Exception:
                    abnormal_reason = None
            if abnormal_reason is None:
                abnormal_reason = self._task_abnormal_reason(task, stage_summaries, items, archive_jobs)
        else:
            stage_runs = detail_ctx.stage_runs
            items = detail_ctx.stage_items
            archive_jobs = detail_ctx.archive_jobs
            stage_sequence = detail_ctx.stage_sequence
            stage_summaries = detail_ctx.stage_summaries
            abnormal_reason = detail_ctx.abnormal_reason
        metrics = task.metrics or {}
        queue_info = queue_info or {"pending_positions": {}}
        queue_position = queue_info.get("pending_positions", {}).get(task.id)
        queue_state, recoverable_reason = self._task_queue_state(task, queue_info, db=db)
        task_retry_supported, task_retry_reason, _ = self._task_retry_support(db, task)
        task_continue_supported, task_continue_reason, _ = self._task_continue_support(db, task)
        task_retry_failed_supported, task_retry_failed_reason, _, _ = self._task_retry_failed_items_support(db, task)
        lease_owner, lease_expires_at, lease_source, lease_pod_uid, lease_boot_id, lease_generation = self._task_runtime_lease_view(db, task)
        runtime_phase = self._task_runtime_phase(task)
        task_control_mode = self._task_control_mode(task)
        reconcile_owner, reconcile_lease_expires_at, reconcile_pod_uid, reconcile_boot_id, reconcile_generation = self._reconcile_lease_view(db, task)
        base_policy = self._task_base_policy(task)
        runtime_override = self._task_runtime_override(task)
        effective_runtime_policy = self._effective_runtime_policy(task)
        if detail_ctx is not None:
            last_successful_sync_at = detail_ctx.last_successful_sync_at
            last_sync_attempt_at = detail_ctx.last_sync_attempt_at
            last_sync_error_at = detail_ctx.last_sync_error_at
            last_sync_error_type = detail_ctx.last_sync_error_type
            last_sync_error_message = detail_ctx.last_sync_error_message
            active_sync_error_item_count = detail_ctx.active_sync_error_item_count
            never_synced_item_count = detail_ctx.never_synced_item_count
            stale_synced_item_count = detail_ctx.stale_synced_item_count
        else:
            stage_items_for_sync = [
                item
                for stage_name in stage_sequence
                for item in self._stage_items(db, task.id, stage_name)
            ]
            (
                last_successful_sync_at,
                last_sync_attempt_at,
                last_sync_error_at,
                last_sync_error_type,
                last_sync_error_message,
                active_sync_error_item_count,
                never_synced_item_count,
                stale_synced_item_count,
            ) = self._task_sync_status_view(stage_items_for_sync)
        manual_operation_state = self._build_manual_operation_state(
            db,
            task,
            task_retry_supported=task_retry_supported,
            task_retry_reason=task_retry_reason,
            task_continue_supported=task_continue_supported,
            task_continue_reason=task_continue_reason,
            task_retry_failed_supported=task_retry_failed_supported,
            task_retry_failed_reason=task_retry_failed_reason,
            stage_summaries=stage_summaries,
        )
        active_stage_run = next(
            (
                run
                for run in stage_runs
                if str(run.stage_name or "").strip() == str(task.current_stage or "").strip()
            ),
            None,
        )
        tail_summary = self._tail_stage_work_summary(db, task)
        failure_snapshot = self._stage_failure_snapshot(task, active_stage_run)
        terminal_failure = (
            self._task_status_is_terminal(task.status)
            and str(failure_snapshot.get("failure_category") or "").strip() == "business"
        )
        active_operation = self._active_operation(db, task.id)
        if active_operation is not None and str(active_operation.operation_type or "").strip() != TASK_ACTION_CANCEL:
            cancel_operation = None
        else:
            cancel_operation = self._active_cancel_operation(db, task.id) or self._latest_cancel_operation(db, task.id)
        return BinarySecurityTaskResponse(
            id=task.id,
            project_id=task.project_id,
            task_type=self._task_type(task),
            name=task.name,
            status=task.status,
            runtime_phase=runtime_phase,
            task_control_mode=task_control_mode,
            current_operation_id=task.current_operation_id,
            execution_epoch=int(getattr(task, "execution_epoch", 0) or 0),
            current_stage=task.current_stage,
            last_error=task.last_error,
            terminal_failure=terminal_failure,
            requeue_suppressed=terminal_failure,
            failure_code=self._string_or_none(failure_snapshot.get("failure_code")) if terminal_failure else None,
            failure_category=self._string_or_none(failure_snapshot.get("failure_category")) if terminal_failure else None,
            failure_message=self._string_or_none(failure_snapshot.get("failure_message") or failure_snapshot.get("error")) if terminal_failure else None,
            firmware_path=task.firmware_path,
            stage_sequence=stage_sequence,
            is_queued=queue_state == "queued",
            queue_position=queue_position,
            queue_state=queue_state,
            recoverable_reason=recoverable_reason,
            last_reconcile_at=queue_info.get("last_reconcile_at"),
            dispatcher_instance_id=task.dispatcher_instance_id,
            task_lease_owner_instance_id=lease_owner,
            task_lease_expires_at=lease_expires_at,
            task_lease_source=lease_source,
            tail_control_mode=str(tail_summary.get("tail_control_mode") or "idle"),
            tail_has_runnable_unbound_items=bool(tail_summary.get("has_runnable_unbound_items")),
            tail_unbound_runnable_item_count=int(tail_summary.get("unbound_runnable_item_count", 0) or 0),
            tail_bound_active_item_count=int(tail_summary.get("bound_active_item_count", 0) or 0),
            tail_has_downstream_refs=bool(tail_summary.get("has_downstream_refs")),
            tail_takeover_required=bool(tail_summary.get("takeover_required")),
            tail_takeover_reason=self._string_or_none(tail_summary.get("takeover_reason")),
            reconcile_owner_instance_id=reconcile_owner,
            reconcile_lease_expires_at=reconcile_lease_expires_at,
            runtime_override_version=int(getattr(task, "runtime_override_version", 0) or 0),
            runtime_override_updated_at=getattr(task, "runtime_override_updated_at", None),
            runtime_override_updated_by=getattr(task, "runtime_override_updated_by", None),
            runtime_policy_effect_scope=self._runtime_policy_effect_scope(task),
            base_policy=base_policy,
            runtime_override=runtime_override,
            effective_runtime_policy=effective_runtime_policy,
            last_successful_downstream_sync_at=last_successful_sync_at,
            last_sync_attempt_at=last_sync_attempt_at,
            last_sync_error_at=last_sync_error_at,
            last_sync_error_type=last_sync_error_type,
            last_sync_error_message=last_sync_error_message,
            active_sync_error_item_count=active_sync_error_item_count,
            never_synced_item_count=never_synced_item_count,
            stale_synced_item_count=stale_synced_item_count,
            created_by=task.created_by,
            created_at=task.created_at,
            updated_at=task.updated_at,
            started_at=task.started_at,
            finished_at=task.finished_at,
            high_risk_module_count=int(metrics.get("high_risk_module_count", 0)),
            medium_risk_module_count=int(metrics.get("medium_risk_module_count", 0)),
            low_risk_module_count=int(metrics.get("low_risk_module_count", 0)),
            candidate_module_count=int(metrics.get("candidate_module_count", 0)),
            selected_module_count=int(metrics.get("selected_module_count", 0)),
            selected_risk_levels=_normalize_module_risk_levels(effective_runtime_policy.get("module_risk_levels")),
            module_selection_mode=self._module_selection_mode(task),
            entry_selection_mode=self._entry_selection_mode(task),
            candidate_entry_count=len(self._entry_candidates(task)),
            selected_entry_count=len(self._effective_entry_inputs(task)) if self._entry_selection_mode(task) == ENTRY_SELECTION_MODE_MANUAL_CONFIRM else len(self._entry_candidates(task)),
            entry_count=int(metrics.get("entry_count", 0)),
            vuln_result_count=int(metrics.get("vuln_result_count", 0)),
            firmware_item_count=int(metrics.get("firmware_item_count", 0)),
            unpacked_firmware_count=int(metrics.get("unpacked_firmware_count", 0)),
            failed_firmware_count=int(metrics.get("failed_firmware_count", 0)),
            task_retry_supported=task_retry_supported,
            task_retry_reason=task_retry_reason,
            task_continue_supported=task_continue_supported,
            task_continue_reason=task_continue_reason,
            task_retry_failed_items_supported=task_retry_failed_supported,
            task_retry_failed_items_reason=task_retry_failed_reason,
            abnormal_reason_title=abnormal_reason.title if abnormal_reason else None,
            abnormal_reason_code=abnormal_reason.code if abnormal_reason else None,
            abnormal_reason_category=abnormal_reason.category if abnormal_reason else None,
            abnormal_reason=abnormal_reason,
            stage_summaries=stage_summaries,
            manual_operation_state=manual_operation_state,
            cancel_state=self._cancel_state_from_operation(task, cancel_operation),
            cleanup_state=self._build_cleanup_state(task),
        )

    def _build_manual_operation_state(
        self,
        db: Session,
        task: BinarySecurityTask,
        *,
        task_retry_supported: bool,
        task_retry_reason: str | None,
        task_continue_supported: bool,
        task_continue_reason: str | None,
        task_retry_failed_supported: bool,
        task_retry_failed_reason: str | None,
        stage_summaries: list[BinarySecurityStageSummary],
    ) -> dict[str, Any]:
        active_operation = self._active_operation(db, task.id)
        if active_operation is not None:
            blocking_reason = f"当前任务正在执行 {active_operation.operation_type}，请稍后重试"
            result_payload = dict(active_operation.result_payload or {})
            item_actions = [dict(row) for row in list(result_payload.get("item_actions") or []) if isinstance(row, dict)]
            validation = dict(result_payload.get("validation") or {})
            requeue = dict(result_payload.get("requeue") or {})
            cleanup_result = dict(result_payload.get("cleanup_result") or {})
            downstream_cleanup_results = [
                dict(row)
                for row in list(cleanup_result.get("downstream_cleanup_results") or result_payload.get("downstream_cleanup_results") or [])
                if isinstance(row, dict)
            ]
            downstream_cleanup_blocking_refs = [
                dict(row)
                for row in list(cleanup_result.get("downstream_cleanup_blocking_refs") or result_payload.get("downstream_cleanup_blocking_refs") or [])
                if isinstance(row, dict)
            ]
            downstream_cleanup_deferred_refs = [
                dict(row)
                for row in list(cleanup_result.get("downstream_cleanup_deferred_refs") or result_payload.get("downstream_cleanup_deferred_refs") or [])
                if isinstance(row, dict)
            ]
            cleanup_partial_failed = bool(cleanup_result.get("cleanup_partial_failed")) or bool(downstream_cleanup_deferred_refs)
            return {
                "overall": "in_progress",
                "summary": blocking_reason,
                "blocking_code": "task_operation_in_progress",
                "blocking_reason": blocking_reason,
                "operation_in_progress": True,
                "operation_id": active_operation.id,
                "operation_type": active_operation.operation_type,
                "operation_status": active_operation.status,
                "operation_owner": active_operation.owner_instance_id,
                "operation_started_at": _isoformat_or_none(active_operation.started_at),
                "operation_expires_at": _isoformat_or_none(active_operation.claim_lease_expires_at),
                "operation_heartbeat_at": _isoformat_or_none(active_operation.heartbeat_at),
                "current_step": active_operation.current_step,
                "target_stage": active_operation.target_stage,
                "item_actions": item_actions,
                "item_actions_count": len(item_actions),
                "validation": validation,
                "issues": list(validation.get("issues") or []),
                "requeue": requeue,
                "error_code": active_operation.error_code,
                "error_message": active_operation.error_message,
                "downstream_cleanup_results": downstream_cleanup_results,
                "downstream_cleanup_blocking_refs": downstream_cleanup_blocking_refs,
                "downstream_cleanup_deferred_refs": downstream_cleanup_deferred_refs,
                "downstream_cleanup_result_count": len(downstream_cleanup_results),
                "downstream_cleanup_blocking_count": len(downstream_cleanup_blocking_refs),
                "downstream_cleanup_deferred_count": len(downstream_cleanup_deferred_refs),
                "cleanup_partial_failed": cleanup_partial_failed,
                "downstream_cleanup_warning_summary": (
                    f"下游清理仍有 {len(downstream_cleanup_deferred_refs)} 个任务待后台补偿"
                    if downstream_cleanup_deferred_refs else None
                ),
                "can_cancel": False,
                "can_continue": False,
                "can_retry": False,
                "can_retry_failed_items": False,
                "can_retry_stage": False,
                "can_retry_stage_failed_items": False,
                "can_retry_stage_full": False,
                "can_retry_archive": False,
                "can_retry_archive_failed_items": False,
                "can_retry_archive_full": False,
                "can_delete": False,
                "can_edit_policy": False,
                "can_confirm_modules": False,
            }
        has_stage_retry = any(bool(summary.retry_full_supported) for summary in stage_summaries)
        has_stage_retry_failed = any(bool(summary.retry_failed_supported) for summary in stage_summaries)
        has_item_level_stage_retry_failed = self._has_retryable_failed_stage_items(db, task)
        streaming_auto_progressing = self._streaming_tail_auto_progressing(db, task)
        running = task.status in {"dispatching", "running"} or streaming_auto_progressing
        waiting_modules = task.status in {TASK_STATUS_PENDING_MODULE_CONFIRMATION, "waiting_confirmation"}
        can_retry_archive = not running and any(
            self._archive_retry_support(db, task, summary.stage_name)[0] or self._archive_full_retry_support(db, task, summary.stage_name)[0]
            for summary in stage_summaries
        )

        can_cancel = task.status not in TASK_TERMINAL_STATUSES
        can_continue = bool(task_continue_supported)
        can_retry = bool(task_retry_supported)
        can_retry_failed_items = bool(task_retry_failed_supported)
        can_retry_stage = (has_stage_retry or has_stage_retry_failed) and not running
        can_retry_stage_failed_items = has_stage_retry_failed or has_item_level_stage_retry_failed
        can_delete = True
        blocked_policy_statuses = {"dispatching", "running"}
        can_edit_policy = task.status not in blocked_policy_statuses
        can_confirm_modules = waiting_modules

        blocking_code: str | None = None
        blocking_reason: str | None = None
        overall = "ready"
        summary = "当前任务允许手工操作"
        if waiting_modules:
            blocking_code = "pending_module_confirmation"
            blocking_reason = "当前任务等待模块确认，请先确认模块后再执行其他操作"
            overall = "blocked"
            summary = blocking_reason
        elif streaming_auto_progressing:
            blocking_code = "task_running"
            blocking_reason = (
                "当前任务处于 streaming tail 自动推进中，当前仅建议等待系统继续收敛或执行取消/同步状态"
            )
            overall = "blocked"
            summary = blocking_reason
        elif running and not can_retry_stage_failed_items:
            blocking_code = "task_running"
            blocking_reason = (
                "当前任务处于 streaming tail 自动推进中，当前仅建议等待系统继续收敛或执行取消/同步状态"
                if streaming_auto_progressing and task.status == "pending"
                else f"当前任务正在执行中，当前状态 {task.status} 下仅支持取消或同步状态"
            )
            overall = "blocked"
            summary = blocking_reason
        elif not any([can_cancel, can_continue, can_retry, can_retry_failed_items, can_retry_stage, can_retry_archive, can_delete, can_edit_policy, can_confirm_modules]):
            blocking_code = "no_manual_operation"
            blocking_reason = task_retry_failed_reason or task_continue_reason or task_retry_reason or "当前任务暂无可执行的手工操作"
            overall = "blocked"
            summary = blocking_reason

        cleanup_state = self._build_cleanup_state(task)
        deferred_count = int(cleanup_state.get("deferred_ref_count") or 0)
        cleanup_warning_summary = (
            f"下游清理仍有 {deferred_count} 个任务待后台补偿"
            if bool(cleanup_state.get("partial_failed")) and deferred_count > 0
            else None
        )

        return {
            "overall": overall,
            "summary": summary,
            "blocking_code": blocking_code,
            "blocking_reason": blocking_reason,
            "operation_in_progress": False,
            "operation_type": None,
            "operation_owner": None,
            "operation_expires_at": None,
            "operation_heartbeat_at": None,
            "can_cancel": can_cancel,
            "can_continue": can_continue,
            "can_retry": can_retry,
            "can_retry_failed_items": can_retry_failed_items,
            "can_retry_stage": can_retry_stage,
            "can_retry_stage_failed_items": can_retry_stage_failed_items,
            "can_retry_stage_full": has_stage_retry and not running,
            "can_retry_archive": can_retry_archive,
            "can_retry_archive_failed_items": can_retry_archive,
            "can_retry_archive_full": can_retry_archive,
            "can_delete": can_delete,
            "can_edit_policy": can_edit_policy,
            "can_confirm_modules": can_confirm_modules,
            "cleanup_partial_failed": bool(cleanup_state.get("partial_failed")),
            "downstream_cleanup_deferred_count": deferred_count,
            "downstream_cleanup_warning_summary": cleanup_warning_summary,
            "downstream_cleanup_deferred_refs": [
                dict(row)
                for row in list(dict(task.cleanup_snapshot or {}).get("deferred_downstream_refs") or [])
                if isinstance(row, dict)
            ],
        }

    def _stage_item_response(
        self,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        *,
        archive_jobs: list[BinarySecurityArchiveJob] | None = None,
    ) -> BinarySecurityStageItemResponse:
        result = self._load_stage_item_result_payload(item)
        output_ref = dict(item.output_ref or {})
        resolved_archive_refs = self._resolved_stage_item_archive_refs(item, archive_jobs=archive_jobs)
        for key in ("artifact_root", "archive_root", "archive_copy_stats", "archive_job_id", "archive_status"):
            value = resolved_archive_refs.get(key)
            if value is None:
                continue
            output_ref.setdefault(key, value)
        for key in ("artifact_root", "archive_root", "archive_copy_stats"):
            value = resolved_archive_refs.get(key)
            if value is None:
                continue
            result.setdefault(key, value)
        downstream_status, sync_observation, repaired = self._effective_stage_item_downstream_status(item, result=result)
        downstream_payload = dict(result.get("downstream") or {})
        last_synced_at = result.get("last_sync_success_at") or result.get("downstream_status_synced_at")
        last_attempt_at = result.get("last_sync_attempt_at") or sync_observation.get("last_attempt_at") or sync_observation.get("last_synced_at")
        last_error_at = result.get("last_sync_error_at") or sync_observation.get("last_error_at")
        raw_sync_status = result.get("sync_status")
        sync_status = str(raw_sync_status).strip().lower() if raw_sync_status is not None else None
        if sync_status == "transport_error" and (downstream_status or last_synced_at):
            # Keep surfacing the latest observation error fields, but do not let
            # a transient fetch failure permanently override the last known good
            # child state in the primary sync_status badge.
            sync_status = "synced"
        if not sync_status:
            if item.downstream_task_id and (downstream_status or last_synced_at):
                sync_status = "synced" if last_synced_at else "pending"
                if downstream_status and not last_synced_at:
                    sync_status = "synced"
            else:
                sync_status = "not_applicable"
        if repaired and sync_status in {None, "", "pending"}:
            sync_status = "synced"
        parsed_last_synced_at = last_synced_at
        if isinstance(last_synced_at, str):
            try:
                parsed_last_synced_at = datetime.fromisoformat(last_synced_at)
            except ValueError:
                parsed_last_synced_at = None
        parsed_last_attempt_at = last_attempt_at
        if isinstance(last_attempt_at, str):
            try:
                parsed_last_attempt_at = datetime.fromisoformat(last_attempt_at)
            except ValueError:
                parsed_last_attempt_at = None
        parsed_last_error_at = last_error_at
        if isinstance(last_error_at, str):
            try:
                parsed_last_error_at = datetime.fromisoformat(last_error_at)
            except ValueError:
                parsed_last_error_at = None
        first_started_at = self._stage_item_first_started_at(item)
        latest_started_at = item.started_at
        total_retry_count = int(item.retry_count or 0) + int(item.rerun_count or 0)
        binding = self._downstream_binding_snapshot(item)
        binding_state = self._downstream_binding_state(item)
        latest_binding_mismatch = dict(result.get("latest_binding_mismatch") or {}) or None
        archive_bound_downstream_task_id = None
        if archive_jobs:
            for job in reversed(archive_jobs):
                archive_bound_downstream_task_id = self._archive_job_bound_downstream_task_id(job) or archive_bound_downstream_task_id
                if archive_bound_downstream_task_id:
                    break
        freshness_state = self._stage_item_sync_freshness_state(
            item,
            last_attempt_at=parsed_last_attempt_at if isinstance(parsed_last_attempt_at, datetime) else None,
            last_success_at=parsed_last_synced_at if isinstance(parsed_last_synced_at, datetime) else None,
            last_error_at=parsed_last_error_at if isinstance(parsed_last_error_at, datetime) else None,
        )
        return BinarySecurityStageItemResponse(
            id=item.id,
            stage_name=item.stage_name,
            item_key=item.item_key,
            item_name=item.item_name,
            parent_key=item.parent_key,
            status=item.status,
            retry_count=int(item.retry_count or 0),
            rerun_count=int(item.rerun_count or 0),
            auto_retry_count=int(item.retry_count or 0),
            total_retry_count=total_retry_count,
            downstream_service=item.downstream_service,
            downstream_task_id=item.downstream_task_id,
            archive_bound_downstream_task_id=archive_bound_downstream_task_id,
            latest_binding_mismatch=latest_binding_mismatch,
            downstream_status=downstream_status,
            downstream_binding_state=binding_state,
            downstream_create_attempts=max(0, int(binding.get("attempts") or 0)),
            downstream_create_last_attempt_at=self._parse_comparable_datetime(binding.get("last_attempt_at")),
            downstream_create_next_retry_at=self._parse_comparable_datetime(binding.get("next_retry_at")),
            downstream_create_last_error=self._string_or_none(binding.get("last_error")),
            downstream_create_last_error_type=self._string_or_none(binding.get("last_error_type")),
            downstream_create_recoverable=self._bool_or_none(binding.get("recoverable")),
            downstream_binding_message=self._string_or_none(binding.get("message")) or self._downstream_binding_status_message(item),
            downstream_cancel_phase=self._string_or_none(downstream_payload.get("cancel_phase")),
            downstream_summary=self._stage_item_downstream_summary(item, result=result),
            input_ref=item.input_ref,
            output_ref=output_ref,
            result=result,
            error_message=item.error_message,
            abnormal_reason=self._stage_item_abnormal_reason(item, task=task),
            sync_status=str(sync_status) if sync_status is not None else None,
            last_synced_at=parsed_last_synced_at,
            last_sync_attempt_at=parsed_last_attempt_at if isinstance(parsed_last_attempt_at, datetime) else None,
            last_sync_success_at=parsed_last_synced_at if isinstance(parsed_last_synced_at, datetime) else None,
            last_sync_error_at=parsed_last_error_at if isinstance(parsed_last_error_at, datetime) else None,
            last_sync_error_message=self._string_or_none(sync_observation.get("error_message")) or self._string_or_none(result.get("last_sync_error_message")),
            last_sync_error_type=self._string_or_none(sync_observation.get("error_type")) or self._string_or_none(result.get("last_sync_error_type")),
            sync_freshness_state=freshness_state,
            downstream_raw_status=self._string_or_none(sync_observation.get("status_raw")),
            downstream_mapped_status=self._string_or_none(sync_observation.get("mapped_status")),
            downstream_state_applied=self._bool_or_none(sync_observation.get("state_applied")),
            sync_observation_error_message=self._string_or_none(sync_observation.get("error_message")),
            sync_observation_error_type=self._string_or_none(sync_observation.get("error_type")),
            sync_observation_http_status=self._int_or_none(sync_observation.get("http_status")),
            first_started_at=first_started_at,
            latest_started_at=latest_started_at,
            started_at=item.started_at,
            finished_at=item.finished_at,
        )

    def _stage_item_sync_freshness_state(
        self,
        item: BinarySecurityStageItem,
        *,
        last_attempt_at: datetime | None,
        last_success_at: datetime | None,
        last_error_at: datetime | None,
    ) -> str:
        if not item.downstream_task_id:
            return "not_applicable"
        if last_success_at is None and last_error_at is not None:
            return "never_succeeded"
        if last_success_at is not None and last_error_at is not None and last_error_at > last_success_at:
            return "failing_after_success"
        if last_success_at is not None:
            stale_after_seconds = max(60, int(self.cfg.scheduler.downstream_reconcile_interval_seconds or 30) * 3)
            if (_now() - last_success_at).total_seconds() >= stale_after_seconds:
                return "stale_success"
            return "healthy"
        if last_attempt_at is not None:
            return "never_succeeded"
        return "not_applicable"

    def _stage_item_downstream_summary(
        self,
        item: BinarySecurityStageItem,
        *,
        result: dict[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        candidates: list[dict[str, Any]] = []
        result_payload = dict(result or item.result or {})
        output_ref = dict(item.output_ref or {})
        for payload in (
            result_payload,
            output_ref,
            dict(result_payload.get("summary") or {}),
            dict(output_ref.get("summary") or {}),
            dict(result_payload.get("system_analysis_result") or {}),
            dict((result_payload.get("system_analysis_result") or {}).get("summary") or {}),
            dict(output_ref.get("system_analysis_result") or {}),
            dict((output_ref.get("system_analysis_result") or {}).get("summary") or {}),
        ):
            if payload:
                candidates.append(payload)

        summary: dict[str, Any] = {}
        metric_keys = (
            "high_risk_module_count",
            "medium_risk_module_count",
            "low_risk_module_count",
            "entry_count",
        )
        for key in metric_keys:
            for payload in candidates:
                value = payload.get(key)
                if value is None or value == "":
                    continue
                try:
                    summary[key] = int(value)
                    break
                except (TypeError, ValueError):
                    continue
        return summary or None

    def _stage_run_summary_path(self, task: BinarySecurityTask, stage_run: BinarySecurityStageRun) -> Path:
        return Path(task.workspace_root) / "run" / "stage-summaries" / f"{int(stage_run.sequence_no or 0):02d}_{stage_run.stage_name}.json"

    def _load_stage_run_output_summary_full(self, task: BinarySecurityTask, stage_run: BinarySecurityStageRun) -> dict[str, Any]:
        db_summary = dict(stage_run.output_summary or {})
        summary_file = db_summary.get("summary_file")
        candidate = Path(str(summary_file)) if summary_file else self._stage_run_summary_path(task, stage_run)
        if candidate.is_file():
            try:
                payload = json.loads(_read_text(candidate) or "{}")
                if isinstance(payload, dict):
                    return payload
            except Exception:
                pass
        return {}

    def _compact_stage_output_item_preview(self, stage_name: str, item: dict[str, Any]) -> dict[str, Any]:
        row = dict(item)
        if stage_name == "system_analysis":
            modules = [dict(module) for module in row.get("modules") or [] if isinstance(module, dict)]
            row["modules"] = self._lightweight_modules_for_storage(modules, limit=5)
            if "system_analysis_result" in row:
                result = dict(row.get("system_analysis_result") or {})
                result["modules"] = self._lightweight_modules_for_storage(list(result.get("modules") or []), limit=5)
                warnings = result.get("warnings") or []
                if isinstance(warnings, list):
                    result["warnings"] = warnings[:10]
                    result["warning_count"] = len(warnings)
                row["system_analysis_result"] = result
            return row
        if stage_name == "entry_analysis":
            entries = [dict(entry) for entry in row.get("entries") or row.get("entries_preview") or [] if isinstance(entry, dict)]
            return {
                "firmware_key": row.get("firmware_key"),
                "firmware_name": row.get("firmware_name"),
                "module_key": row.get("module_key"),
                "module_name": row.get("module_name"),
                "module_dir": row.get("module_dir"),
                "source_dir": row.get("source_dir"),
                "artifact_root": row.get("artifact_root"),
                "entry_count": row.get("entry_count") if row.get("entry_count") is not None else len(entries),
                "entries_preview": self._compact_entry_rows(entries[:5]),
            }
        if normalize_stage_name(stage_name) == "dataflow_vuln_scan":
            artifact_files = row.get("artifact_files_preview") or row.get("artifact_files") or []
            return {
                "entry_key": row.get("entry_key"),
                "module_key": row.get("module_key"),
                "module_name": row.get("module_name"),
                "function_name": row.get("function_name"),
                "file_name": row.get("file_name"),
                "line_no": row.get("line_no"),
                "source_dir": row.get("source_dir"),
                "data_flow_file": row.get("data_flow_file"),
                "workspace_root": row.get("workspace_root"),
                "archive_root": row.get("archive_root"),
                "artifact_file_count": row.get("artifact_file_count") if row.get("artifact_file_count") is not None else len(artifact_files),
                "artifact_files_preview": list(artifact_files[:5]) if isinstance(artifact_files, list) else [],
            }
        if normalize_stage_name(stage_name) == "dataflow_vuln_scan":
            return self._compact_vuln_summary_item(row)
        if stage_name == "binary_to_source":
            return self._compact_b2s_summary_item(row)
        if stage_name == "firmware_unpack":
            return self._compact_firmware_unpack_summary_item(row)
        return row

    def _compact_stage_output_summary_for_db(
        self,
        task: BinarySecurityTask,
        stage_run: BinarySecurityStageRun,
        full_summary: dict[str, Any] | None,
        *,
        summary_file: str | None = None,
    ) -> dict[str, Any]:
        summary = dict(full_summary or {})
        compact: dict[str, Any] = {
            "summary_externalized": bool(summary_file),
        }
        if summary_file:
            compact["summary_file"] = summary_file
        scalar_keys = [
            "status",
            "sync_status",
            "error",
            "reason",
            "failure_code",
            "failure_category",
            "failure_message",
            "reclaimed",
            "archive_blocked",
            "waiting_manual_confirmation",
            "success_count",
            "failed_count",
            "cancelled_count",
            "entry_count",
            "vuln_result_count",
            "module_count",
            "high_risk_module_count",
            "medium_risk_module_count",
            "low_risk_module_count",
            "candidate_module_count",
            "selected_module_count",
            "total_items",
            "success_items",
            "failed_items_count",
            "running_items",
            "cancelled_items_count",
            "skipped_items",
            "items_truncated",
            "failed_items_truncated",
            "cancelled_items_truncated",
            "status_synced",
        ]
        for key in scalar_keys:
            value = summary.get(key)
            if value is not None:
                compact[key] = value
        for count_key, alias in (("failed_items", "failed_items_count"), ("cancelled_items", "cancelled_items_count")):
            rows = summary.get(count_key)
            if isinstance(rows, list):
                compact[alias] = len(rows)
        items = summary.get("items")
        if isinstance(items, list):
            compact["item_count"] = len(items)
            compact["items_preview"] = [
                self._compact_stage_output_item_preview(stage_run.stage_name, item)
                for item in items[:10]
                if isinstance(item, dict)
            ]
        failed_items = summary.get("failed_items")
        if isinstance(failed_items, list):
            compact["failed_items_preview"] = [
                self._lightweight_stage_failure(item if isinstance(item, dict) else {"item": {}, "error": str(item)})
                for item in failed_items[:10]
            ]
        cancelled_items = summary.get("cancelled_items")
        if isinstance(cancelled_items, list):
            compact["cancelled_items_preview"] = [
                self._lightweight_stage_failure(item if isinstance(item, dict) else {"item": {}, "error": str(item)})
                for item in cancelled_items[:10]
            ]
        return self._fit_stage_output_summary_for_db(compact)

    def _fit_stage_output_summary_for_db(self, compact: dict[str, Any], *, max_bytes: int = 32768) -> dict[str, Any]:
        payload = dict(compact or {})

        def encoded_size(value: dict[str, Any]) -> int:
            return len(json.dumps(value, ensure_ascii=False, default=str).encode("utf-8"))

        if encoded_size(payload) <= max_bytes:
            return payload

        items_preview = payload.get("items_preview")
        if isinstance(items_preview, list):
            shrunk_items: list[dict[str, Any]] = []
            for item in items_preview:
                if not isinstance(item, dict):
                    continue
                row = dict(item)
                entries_preview = row.get("entries_preview")
                if isinstance(entries_preview, list):
                    row["entries_preview_count"] = len(entries_preview)
                    row["entries_preview"] = entries_preview[:1]
                shrunk_items.append(row)
            payload["items_preview"] = shrunk_items[:5]
            payload["items_preview_truncated_for_db"] = True
        if encoded_size(payload) <= max_bytes:
            return payload

        for preview_key in ("failed_items_preview", "cancelled_items_preview"):
            rows = payload.get(preview_key)
            if isinstance(rows, list):
                payload[f"{preview_key}_count"] = len(rows)
                payload[preview_key] = rows[:3]
        if encoded_size(payload) <= max_bytes:
            return payload

        scalar_allowlist = {
            "summary_externalized",
            "summary_file",
            "status",
            "sync_status",
            "error",
            "reason",
            "failure_code",
            "failure_category",
            "failure_message",
            "reclaimed",
            "archive_blocked",
            "waiting_manual_confirmation",
            "success_count",
            "failed_count",
            "cancelled_count",
            "entry_count",
            "vuln_result_count",
            "module_count",
            "high_risk_module_count",
            "medium_risk_module_count",
            "low_risk_module_count",
            "candidate_module_count",
            "selected_module_count",
            "total_items",
            "success_items",
            "failed_items_count",
            "running_items",
            "cancelled_items_count",
            "skipped_items",
            "item_count",
            "items_truncated",
            "failed_items_truncated",
            "cancelled_items_truncated",
            "status_synced",
        }
        fitted = {key: value for key, value in payload.items() if key in scalar_allowlist}
        fitted["db_summary_truncated"] = True
        if encoded_size(fitted) <= max_bytes:
            return fitted

        for verbose_key in ("error", "failure_message", "reason"):
            if isinstance(fitted.get(verbose_key), str):
                fitted[verbose_key] = str(fitted[verbose_key])[:1000]
        return fitted

    @staticmethod
    def _json_payload_size_bytes(value: Any) -> int:
        return len(json.dumps(value, ensure_ascii=False, default=str).encode("utf-8"))

    def _event_payload_path(self, task: BinarySecurityTask, *, event_id: str, event_type: str, state_event: bool) -> Path:
        folder_name = "state-event-payloads" if state_event else "timeline-event-payloads"
        return Path(task.workspace_root) / "run" / folder_name / f"{event_id}_{_slug(event_type)}.json"

    def _event_payload_preview_value(self, value: Any, *, depth: int = 0) -> Any:
        if depth >= 2:
            if isinstance(value, dict):
                return {"field_count": len(value)}
            if isinstance(value, list):
                return {"item_count": len(value)}
            if isinstance(value, str):
                return value[:200]
            return value
        if isinstance(value, dict):
            preview: dict[str, Any] = {}
            for index, (key, current) in enumerate(value.items()):
                if index >= 8:
                    preview["preview_truncated"] = True
                    break
                if isinstance(current, (dict, list)):
                    preview[f"{key}_count"] = len(current)
                    preview[f"{key}_preview"] = self._event_payload_preview_value(current, depth=depth + 1)
                elif isinstance(current, str):
                    preview[key] = current[:500]
                else:
                    preview[key] = current
            return preview
        if isinstance(value, list):
            return [self._event_payload_preview_value(current, depth=depth + 1) for current in value[:3]]
        if isinstance(value, str):
            return value[:500]
        return value

    def _fit_event_payload_for_db(self, compact: dict[str, Any], *, max_bytes: int = DB_EVENT_PAYLOAD_LIMIT_BYTES) -> dict[str, Any]:
        payload = dict(compact or {})
        if self._json_payload_size_bytes(payload) <= max_bytes:
            return payload
        for key in list(payload.keys()):
            value = payload.get(key)
            if isinstance(value, list):
                payload[f"{key}_count"] = len(value)
                payload[key] = value[:1]
            elif isinstance(value, dict) and key.endswith("_preview"):
                payload[key] = self._event_payload_preview_value(value, depth=1)
            elif isinstance(value, str) and len(value) > 1000:
                payload[key] = value[:1000]
        if self._json_payload_size_bytes(payload) <= max_bytes:
            return payload
        minimal = {
            key: value
            for key, value in payload.items()
            if key in {
                "payload_externalized",
                "payload_file",
                "summary_externalized",
                "summary_file",
                "stage_name",
                "status",
                "stage_retry_mode",
                "task_retry_mode",
                "target_stage_name",
                "error",
                "reason",
            }
        }
        minimal["db_payload_truncated"] = True
        return minimal

    def _resolve_task_for_event_payload(
        self,
        db: Session,
        *,
        task: BinarySecurityTask | None,
        task_id: str | None,
        project_id: str | None,
    ) -> BinarySecurityTask | None:
        if task is not None:
            return task
        if not task_id or not project_id:
            return None
        return db.query(BinarySecurityTask).filter(
            BinarySecurityTask.id == task_id,
            BinarySecurityTask.project_id == project_id,
        ).first()

    def _compact_state_terminal_payload_for_db(
        self,
        db: Session,
        *,
        task: BinarySecurityTask,
        stage_name: str | None,
        payload: dict[str, Any],
        payload_file: str | None,
    ) -> dict[str, Any]:
        compact = {
            "stage_name": payload.get("stage_name") or stage_name,
            "status": payload.get("status"),
            "stage_retry_mode": bool(payload.get("stage_retry_mode")),
            "task_retry_mode": bool(payload.get("task_retry_mode")),
            "target_stage_name": payload.get("target_stage_name"),
            "payload_externalized": bool(payload_file),
        }
        if payload_file:
            compact["payload_file"] = payload_file
        summary = dict(payload.get("summary") or {})
        stage_run = None
        effective_stage_name = str(compact.get("stage_name") or "").strip()
        if effective_stage_name:
            stage_run = db.query(BinarySecurityStageRun).filter(
                BinarySecurityStageRun.task_id == task.id,
                BinarySecurityStageRun.stage_name == effective_stage_name,
            ).first()
        if stage_run is not None:
            summary_compact = self._compact_stage_output_summary_for_db(
                task,
                stage_run,
                summary,
                summary_file=payload_file,
            )
        else:
            summary_compact = self._fit_event_payload_for_db(
                {
                    "summary_externalized": bool(payload_file),
                    "summary_file": payload_file,
                    "summary_preview": self._event_payload_preview_value(summary),
                }
            )
        compact["summary"] = summary_compact
        return self._fit_event_payload_for_db(compact)

    def _compact_generic_event_payload_for_db(self, payload: dict[str, Any], *, payload_file: str | None) -> dict[str, Any]:
        compact: dict[str, Any] = {
            "payload_externalized": bool(payload_file),
        }
        if payload_file:
            compact["payload_file"] = payload_file
        for key, value in (payload or {}).items():
            if isinstance(value, (str, int, float, bool)) or value is None:
                compact[key] = value[:1000] if isinstance(value, str) else value
            elif isinstance(value, list):
                compact[f"{key}_count"] = len(value)
                compact[f"{key}_preview"] = self._event_payload_preview_value(value)
            elif isinstance(value, dict):
                compact[f"{key}_preview"] = self._event_payload_preview_value(value)
        return self._fit_event_payload_for_db(compact)

    def _prepare_event_payload_for_db(
        self,
        db: Session,
        *,
        task: BinarySecurityTask | None,
        event_id: str,
        event_type: str,
        stage_name: str | None,
        payload: dict[str, Any],
        state_event: bool,
        task_id: str | None = None,
        project_id: str | None = None,
    ) -> dict[str, Any]:
        normalized_payload = dict(payload or {})
        if self._json_payload_size_bytes(normalized_payload) <= DB_EVENT_PAYLOAD_LIMIT_BYTES:
            return normalized_payload
        resolved_task = self._resolve_task_for_event_payload(
            db,
            task=task,
            task_id=task_id,
            project_id=project_id,
        )
        payload_file: str | None = None
        if resolved_task is not None and str(resolved_task.workspace_root or "").strip():
            try:
                path = self._event_payload_path(
                    resolved_task,
                    event_id=event_id,
                    event_type=event_type,
                    state_event=state_event,
                )
                _write_json(path, normalized_payload)
                payload_file = str(path)
            except Exception:
                payload_file = None
        if state_event and event_type == "stage_worker_terminal_observed" and resolved_task is not None:
            return self._compact_state_terminal_payload_for_db(
                db,
                task=resolved_task,
                stage_name=stage_name,
                payload=normalized_payload,
                payload_file=payload_file,
            )
        return self._compact_generic_event_payload_for_db(normalized_payload, payload_file=payload_file)

    def _load_externalized_event_payload(self, task: BinarySecurityTask, payload: dict[str, Any] | None) -> dict[str, Any]:
        normalized_payload = dict(payload or {})
        payload_file = str(normalized_payload.get("payload_file") or "").strip()
        if not payload_file:
            return normalized_payload
        candidate = Path(payload_file)
        if not candidate.is_absolute():
            candidate = Path(task.workspace_root) / candidate
        try:
            if candidate.is_file():
                loaded = json.loads(candidate.read_text(encoding="utf-8") or "{}")
                if isinstance(loaded, dict):
                    return loaded
        except Exception:
            return normalized_payload
        return normalized_payload

    def _persist_stage_run_output_summary(
        self,
        task: BinarySecurityTask,
        stage_run: BinarySecurityStageRun,
        full_summary: dict[str, Any] | None,
    ) -> dict[str, Any]:
        summary_payload = dict(full_summary or {})
        summary_file: str | None = None
        try:
            path = self._stage_run_summary_path(task, stage_run)
            _write_json(path, summary_payload)
            summary_file = str(path)
        except Exception:
            summary_file = None
        compact = self._compact_stage_output_summary_for_db(task, stage_run, summary_payload, summary_file=summary_file)
        stage_run.output_summary = compact
        return compact

    def _update_task_stage_summary_entry(self, task: BinarySecurityTask, stage_run: BinarySecurityStageRun) -> None:
        task.stage_summary = {
            **(task.stage_summary or {}),
            stage_run.stage_name: {
                "status": stage_run.status,
                "counts": dict(stage_run.counts or {}),
                "finished_at": stage_run.finished_at.isoformat() if stage_run.finished_at else None,
                "last_error": stage_run.last_error,
            },
        }

    def _merge_task_stage_summary_entry(
        self,
        task: BinarySecurityTask,
        stage_run: BinarySecurityStageRun,
        extra: dict[str, Any] | None = None,
    ) -> None:
        self._update_task_stage_summary_entry(task, stage_run)
        task.stage_summary = {
            **(task.stage_summary or {}),
            stage_run.stage_name: {
                **dict((task.stage_summary or {}).get(stage_run.stage_name) or {}),
                **dict(extra or {}),
            },
        }

    async def _persist_stage_run_output_summary_async(
        self,
        task: BinarySecurityTask,
        stage_run: BinarySecurityStageRun,
        full_summary: dict[str, Any] | None,
    ) -> dict[str, Any]:
        summary_payload = dict(full_summary or {})
        summary_file: str | None = None
        try:
            path = self._stage_run_summary_path(task, stage_run)
            await asyncio.to_thread(_write_json, path, summary_payload)
            summary_file = str(path)
        except Exception:
            summary_file = None
        compact = self._compact_stage_output_summary_for_db(task, stage_run, summary_payload, summary_file=summary_file)
        stage_run.output_summary = compact
        return compact

    def _merge_stage_run_output_summary(
        self,
        task: BinarySecurityTask,
        stage_run: BinarySecurityStageRun,
        patch: dict[str, Any] | None,
    ) -> dict[str, Any]:
        merged = {**self._load_stage_run_output_summary_full(task, stage_run), **(patch or {})}
        return self._persist_stage_run_output_summary(task, stage_run, merged)

    async def _merge_stage_run_output_summary_async(
        self,
        task: BinarySecurityTask,
        stage_run: BinarySecurityStageRun,
        patch: dict[str, Any] | None,
    ) -> dict[str, Any]:
        merged = {**self._load_stage_run_output_summary_full(task, stage_run), **(patch or {})}
        return await self._persist_stage_run_output_summary_async(task, stage_run, merged)

    def _item_stats(self, items: list[BinarySecurityStageItem]) -> dict[str, dict[str, int]]:
        stats: dict[str, dict[str, int]] = {}
        for item in items:
            entry = stats.setdefault(item.stage_name, {"total": 0, "success": 0, "failed": 0, "skipped": 0, "running": 0, "cancelled": 0})
            entry["total"] += 1
            normalized_status = self._normalize_downstream_status(item.status) or item.status
            if normalized_status in entry:
                entry[normalized_status] += 1
        return stats

    def _next_incomplete_stage(self, db: Session, task: BinarySecurityTask) -> str | None:
        stage_runs = db.query(BinarySecurityStageRun).filter(BinarySecurityStageRun.task_id == task.id).all()
        runs_by_stage = {run.stage_name: run for run in stage_runs}
        for stage_name in self._stage_sequence_for_task(task):
            if not self._stage_enabled(task, stage_name):
                continue
            upstream_retried, _ = self._upstream_stage_retried(db, task, stage_name)
            if upstream_retried:
                continue
            run = runs_by_stage.get(stage_name)
            if run is None:
                if self._should_finalize_without_entries(db, task, stage_name):
                    continue
                if (
                    self._is_streaming_tail_stage(task, stage_name)
                    and normalize_stage_name(stage_name) == "dataflow_vuln_scan"
                    and self._continue_stage_input_error(db, task, stage_name)
                ):
                    continue
                return stage_name
            items = self._stage_items(db, task.id, stage_name)
            if items:
                item_status = self._aggregate_item_statuses([item.status for item in items])
                if item_status in {"pending", "queued", "running", "dispatching"}:
                    return stage_name
                if self._stage_has_nonterminal_items(items):
                    return stage_name
                if self._stage_archive_success_blocked(task, stage_name, items, db=db):
                    return stage_name
            elif (
                self._is_streaming_tail_stage(task, stage_name)
                and normalize_stage_name(stage_name) == "dataflow_vuln_scan"
                and self._continue_stage_input_error(db, task, stage_name)
            ):
                continue
            if self._should_finalize_without_entries(db, task, stage_name):
                continue
            if run.status == "partial_success":
                if not self._partial_success_advancement_enabled(task, stage_name):
                    return stage_name
                continue
            normalized_status = self._normalize_downstream_status(run.status) or str(run.status or "").strip()
            if (
                normalized_status in {"pending", "queued", "running", "dispatching"}
                and self._is_streaming_tail_stage(task, stage_name)
                and not items
            ):
                if str(task.status or "").strip() in {"pending", "queued", "running", "dispatching"}:
                    continue
                return stage_name
            if normalized_status in {"pending", "queued", "running", "dispatching"}:
                return stage_name
            if normalized_status not in {"success", "failed", "cancelled", "downstream_missing", "partial_success", "skipped"}:
                return stage_name
        return None

    def _first_failed_terminal_stage(self, db: Session, task: BinarySecurityTask) -> str | None:
        stage_runs = db.query(BinarySecurityStageRun).filter(BinarySecurityStageRun.task_id == task.id).all()
        runs_by_stage = {str(run.stage_name or "").strip(): run for run in stage_runs}
        failure_statuses = {"failed", "downstream_missing", "cancelled", "partial_success"}
        for stage_name in self._stage_sequence_for_task(task):
            if not self._stage_enabled(task, stage_name):
                continue
            items = self._stage_items(db, task.id, stage_name)
            if any(self._normalize_item_status(item.status) in {"failed", "cancelled", "downstream_missing"} for item in items):
                return stage_name
            run = runs_by_stage.get(stage_name)
            if run is None:
                continue
            normalized_status = self._normalize_downstream_status(run.status) or str(run.status or "").strip()
            if normalized_status not in failure_statuses:
                continue
            if items and self._stage_has_nonterminal_items(items):
                continue
            return stage_name
        return None

    def _retry_plan(self, task: BinarySecurityTask) -> dict[str, Any]:
        summary = dict(task.summary or {})
        plan = summary.get("retry_plan") or {}
        return dict(plan) if isinstance(plan, dict) else {}

    def _set_retry_plan(self, task: BinarySecurityTask, plan: dict[str, Any] | None) -> None:
        summary = dict(task.summary or {})
        if plan:
            summary["retry_plan"] = dict(plan)
        else:
            summary.pop("retry_plan", None)
        task.summary = summary

    def _clear_retry_execution_context(
        self,
        db: Session,
        task: BinarySecurityTask,
        *,
        stage_name: str | None,
        payload: dict[str, Any] | None = None,
    ) -> None:
        had_context = bool(task.execution_mode or task.target_stage_name or self._retry_plan(task))
        task.execution_mode = None
        task.target_stage_name = None
        task_summary = dict(task.summary or {})
        task_summary.pop("stage_retry_context", None)
        task_summary.pop("task_retry_context", None)
        task_summary.pop("retry_plan", None)
        task.summary = task_summary
        if had_context:
            self._record_event(
                db,
                task,
                "stage_retry_context_cleared",
                f"阶段重试上下文已清理: {stage_name or task.current_stage or '-'}",
                stage_name=stage_name,
                payload=dict(payload or {}),
            )

    def _normalize_item_status(self, status: str | None) -> str:
        return (self._normalize_downstream_status(status) or str(status or "").strip().lower() or "unknown")

    def _is_failed_retry_candidate_status(self, status: str | None) -> bool:
        return self._normalize_item_status(status) in FAILED_ITEM_RETRYABLE_STATUSES

    def _stage_retry_candidate_items(
        self,
        db: Session,
        task: BinarySecurityTask,
        stage_name: str,
    ) -> list[BinarySecurityStageItem]:
        return [
            item
            for item in self._stage_items(db, task.id, stage_name)
            if self._is_failed_retry_candidate_status(item.status)
            and (
                str(item.downstream_task_id or "").strip()
                or self._latest_observed_downstream_status(item) in RETRY_CHILD_ABNORMAL_STATUSES
            )
        ]

    def _has_retryable_failed_stage_items(self, db: Session, task: BinarySecurityTask) -> bool:
        for stage_name in self._stage_sequence_for_task(task):
            if self._stage_retry_candidate_items(db, task, stage_name):
                return True
        return False

    @staticmethod
    def _comparable_datetime(value: datetime | None) -> datetime | None:
        if value is None:
            return None
        if value.tzinfo is not None:
            return value.astimezone().replace(tzinfo=None)
        return value

    @classmethod
    def _parse_comparable_datetime(cls, value: Any) -> datetime | None:
        if isinstance(value, datetime):
            return cls._comparable_datetime(value)
        if not value:
            return None
        text = str(value).strip()
        if not text:
            return None
        normalized = text.replace("Z", "+00:00")
        try:
            return cls._comparable_datetime(datetime.fromisoformat(normalized))
        except ValueError:
            return None

    def _upstream_stage_retried(self, db: Session, task: BinarySecurityTask, stage_name: str) -> tuple[bool, str | None]:
        stage_sequence = self._stage_sequence_for_task(task)
        if stage_name not in stage_sequence:
            return False, None
        target_index = stage_sequence.index(stage_name)
        upstream_stages = stage_sequence[:target_index]
        stage_runs = db.query(BinarySecurityStageRun).filter(BinarySecurityStageRun.task_id == task.id).all()
        runs_by_stage = {run.stage_name: run for run in stage_runs}
        target_items = [
            item
            for item in self._stage_items(db, task.id, stage_name)
            if item.stage_name == stage_name
        ]
        target_created_at = [
            comparable
            for comparable in (self._comparable_datetime(item.created_at) for item in target_items)
            if comparable is not None
        ]
        earliest_target_created_at = min(target_created_at) if target_created_at else None
        retried_upstream_completed_at = [
            comparable
            for comparable in (
                self._comparable_datetime(run.finished_at or run.started_at)
                for run in runs_by_stage.values()
                if run
                and str(run.stage_name or "").strip() in upstream_stages
                and int(run.retry_count or 0) > 0
            )
            if comparable is not None
        ]
        latest_retried_upstream_completed_at = max(retried_upstream_completed_at) if retried_upstream_completed_at else None
        if (
            earliest_target_created_at is not None
            and latest_retried_upstream_completed_at is not None
            and earliest_target_created_at >= latest_retried_upstream_completed_at
        ):
            return False, None
        summary = dict(task.summary or {})
        stale_stages = set(summary.get("stale_stages") or [])
        stale_from_stage = str(summary.get("stale_from_stage") or "").strip()
        if stage_name in stale_stages and stale_from_stage in upstream_stages:
            return True, stale_from_stage

        for upstream_stage in upstream_stages:
            run = runs_by_stage.get(upstream_stage)
            if not run or int(run.retry_count or 0) <= 0:
                continue
            upstream_completed_at = self._comparable_datetime(run.finished_at or run.started_at)
            if earliest_target_created_at and upstream_completed_at and earliest_target_created_at >= upstream_completed_at:
                continue
            if run and int(run.retry_count or 0) > 0:
                return True, upstream_stage
        return False, None

    def _first_failed_retry_stage(self, db: Session, task: BinarySecurityTask) -> tuple[str | None, list[BinarySecurityStageItem]]:
        for stage_name in self._stage_sequence_for_task(task):
            if not self._stage_enabled(task, stage_name):
                continue
            items = self._stage_retry_candidate_items(db, task, stage_name)
            if items:
                return stage_name, items
        return None, []

    @staticmethod
    def _clear_failure_fields_from_summary(summary: dict[str, Any]) -> dict[str, Any]:
        cleaned = dict(summary or {})
        for key in ("failure_code", "failure_category", "failure_message", "error"):
            cleaned.pop(key, None)
        return cleaned

    @staticmethod
    def _task_status_is_terminal(status: str | None) -> bool:
        return str(status or "").strip() in {"success", "failed", "downstream_missing", "partial_success", "cancelled"}

    def _stage_failure_snapshot(
        self,
        task: BinarySecurityTask,
        stage_run: BinarySecurityStageRun | None,
    ) -> dict[str, Any]:
        candidates: list[dict[str, Any]] = []
        if stage_run is not None:
            candidates.append(_failure_shape(stage_run.output_summary))
        summary = _failure_shape(task.summary)
        stage_name = str(getattr(stage_run, "stage_name", "") or "").strip()
        if stage_name:
            candidates.append(_failure_shape(summary.get(stage_name)))
        candidates.append(summary)

        merged: dict[str, Any] = {}
        for payload in candidates:
            for key in ("failure_code", "failure_category", "failure_message", "error", "sync_status", "status_synced"):
                value = payload.get(key)
                if value is not None and value != "":
                    merged.setdefault(key, value)
        return merged

    def _is_terminal_business_stage_failure(
        self,
        task: BinarySecurityTask,
        stage_run: BinarySecurityStageRun | None,
    ) -> bool:
        snapshot = self._stage_failure_snapshot(task, stage_run)
        return str(snapshot.get("failure_category") or "").strip() == "business"

    def _record_business_failure_terminalization(
        self,
        db: Session,
        task: BinarySecurityTask,
        stage_run: BinarySecurityStageRun | None,
    ) -> None:
        snapshot = self._stage_failure_snapshot(task, stage_run)
        stage_name = str(getattr(stage_run, "stage_name", "") or task.current_stage or "").strip() or None
        payload = {
            "stage_name": stage_name,
            "failure_code": snapshot.get("failure_code"),
            "failure_category": snapshot.get("failure_category"),
            "failure_message": snapshot.get("failure_message") or snapshot.get("error"),
            "requeue_suppressed": True,
        }
        existing = (
            db.query(BinarySecurityEvent)
            .filter(
                BinarySecurityEvent.task_id == task.id,
                BinarySecurityEvent.event_type == "task_finalized_after_business_failure",
                BinarySecurityEvent.stage_name == stage_name,
            )
            .order_by(BinarySecurityEvent.created_at.desc())
            .first()
        )
        existing_payload = dict(getattr(existing, "payload", None) or {}) if existing is not None else {}
        if (
            existing is not None
            and str(existing_payload.get("failure_code") or "").strip() == str(payload.get("failure_code") or "").strip()
            and str(existing_payload.get("failure_category") or "").strip() == str(payload.get("failure_category") or "").strip()
        ):
            return
        self._record_event(
            db,
            task,
            "task_finalized_after_business_failure",
            "业务终态失败已直接收口，不再进入补偿重排",
            level="warning",
            stage_name=stage_name,
            payload=payload,
        )
        logger.info(
            "binary-security business failure requeue suppressed task_id=%s stage_name=%s failure_code=%s failure_category=%s decision=terminal_failed requeue_suppressed=true",
            task.id,
            stage_name or "-",
            payload.get("failure_code") or "-",
            payload.get("failure_category") or "-",
        )

    def _should_terminalize_parent_for_failed_stage(
        self,
        task: BinarySecurityTask,
        stage_run: BinarySecurityStageRun | None,
    ) -> bool:
        if stage_run is None or str(stage_run.status or "").strip() != "failed":
            return False
        error_text = " ".join(
            str(part or "").strip()
            for part in (
                stage_run.last_error,
                getattr(stage_run, "error_message", None),
                getattr(stage_run, "reason", None),
            )
            if str(part or "").strip()
        )
        if self._is_owner_lost_recoverable_failure(
            failure_message=error_text,
            failure_category=self._stage_failure_snapshot(task, stage_run).get("failure_category"),
        ):
            return False
        if "task owner pod lost" in error_text.lower() or "owner pod lost" in error_text.lower():
            return True
        return self._is_terminal_business_stage_failure(task, stage_run)

    def _current_stage_authoritative_failure_context(
        self,
        db: Session,
        task: BinarySecurityTask,
        *,
        stage_runs: list[BinarySecurityStageRun] | None = None,
    ) -> dict[str, Any] | None:
        stage_name = str(task.current_stage or "").strip()
        if not stage_name:
            return None
        if stage_runs is None:
            stage_runs = db.query(BinarySecurityStageRun).filter(BinarySecurityStageRun.task_id == task.id).all()
        stage_run = next((run for run in stage_runs if str(run.stage_name or "").strip() == stage_name), None)
        if str(task.status or "").strip() == "failed":
            failure_message = str(task.last_error or "").strip()
            if failure_message and ("总任务产物归档失败" in failure_message or "archive" in failure_message.lower()):
                return {
                    "stage_name": stage_name,
                    "stage_run": stage_run,
                    "failure_code": "stage_archive_blocked",
                    "failure_category": "archive_blocked",
                    "failure_message": failure_message,
                    "reason": "authoritative_archive_blocked",
                }
        if stage_run is not None and self._should_terminalize_parent_for_failed_stage(task, stage_run):
            snapshot = self._stage_failure_snapshot(task, stage_run)
            return {
                "stage_name": stage_name,
                "stage_run": stage_run,
                "failure_code": snapshot.get("failure_code"),
                "failure_category": snapshot.get("failure_category"),
                "failure_message": snapshot.get("failure_message") or snapshot.get("error") or stage_run.last_error,
                "reason": "stage_run_failed",
            }
        items = self._stage_items(db, task.id, stage_name)
        if not items:
            return None
        normalized_statuses = [
            self._normalize_downstream_status(item.status) or str(item.status or "").strip().lower()
            for item in items
        ]
        if any(status in {"pending", "queued", "running", "dispatching"} for status in normalized_statuses):
            return None
        aggregate_status = self._aggregate_item_statuses(normalized_statuses)
        if aggregate_status not in {"failed", "cancelled", "downstream_missing", "partial_success"}:
            return None
        snapshot = self._stage_failure_snapshot(task, stage_run)
        if aggregate_status == "failed":
            exhausted_owner_lost_items = [item for item in items if self._owner_lost_retry_exhausted(task, item)]
            if exhausted_owner_lost_items:
                exhausted_item = exhausted_owner_lost_items[0]
                return {
                    "stage_name": stage_name,
                    "stage_run": stage_run,
                    "failure_code": "owner_lost_retry_exhausted",
                    "failure_category": "infrastructure",
                    "failure_message": str(exhausted_item.error_message or "").strip() or "owner_lost_retry_exhausted",
                    "reason": "owner_lost_retry_exhausted",
                }
            for item in items:
                if self._is_owner_lost_recoverable_failure(
                    failure_message=str(item.error_message or "").strip() or None,
                    failure_category=snapshot.get("failure_category"),
                    error_type=self._stage_item_sync_error_type_value(item),
                    item=item,
                ):
                    return None
        failure_message = next((str(item.error_message or "").strip() for item in items if str(item.error_message or "").strip()), None)
        return {
            "stage_name": stage_name,
            "stage_run": stage_run,
            "failure_code": snapshot.get("failure_code"),
            "failure_category": snapshot.get("failure_category"),
            "failure_message": snapshot.get("failure_message") or snapshot.get("error") or failure_message or getattr(stage_run, "last_error", None),
            "reason": "authoritative_stage_items_terminal",
        }

    def _earlier_stage_authoritative_failure_context(
        self,
        db: Session,
        task: BinarySecurityTask,
        *,
        stage_runs: list[BinarySecurityStageRun] | None = None,
    ) -> dict[str, Any] | None:
        current_stage = str(task.current_stage or "").strip()
        if not current_stage:
            return None
        if stage_runs is None:
            stage_runs = db.query(BinarySecurityStageRun).filter(BinarySecurityStageRun.task_id == task.id).all()
        ordered_stage_names = [
            str(name or "").strip()
            for name in self._stage_sequence_for_task(task)
            if str(name or "").strip()
        ]
        try:
            current_index = ordered_stage_names.index(current_stage)
        except ValueError:
            return None
        for stage_name in reversed(ordered_stage_names[:current_index]):
            stage_run = next((run for run in stage_runs if str(run.stage_name or "").strip() == stage_name), None)
            if stage_run is not None and self._should_terminalize_parent_for_failed_stage(task, stage_run):
                snapshot = self._stage_failure_snapshot(task, stage_run)
                return {
                    "stage_name": stage_name,
                    "stage_run": stage_run,
                    "failure_code": snapshot.get("failure_code"),
                    "failure_category": snapshot.get("failure_category"),
                    "failure_message": snapshot.get("failure_message") or snapshot.get("error") or stage_run.last_error,
                    "reason": "earlier_stage_run_failed",
                }
            items = self._stage_items(db, task.id, stage_name)
            if not items:
                continue
            normalized_statuses = [
                self._normalize_downstream_status(item.status) or str(item.status or "").strip().lower()
                for item in items
            ]
            if any(status in {"pending", "queued", "running", "dispatching"} for status in normalized_statuses):
                continue
            aggregate_status = self._aggregate_item_statuses(normalized_statuses)
            if aggregate_status not in {"failed", "cancelled", "downstream_missing", "partial_success"}:
                continue
            if aggregate_status == "failed":
                snapshot = self._stage_failure_snapshot(task, stage_run)
                exhausted_owner_lost_items = [item for item in items if self._owner_lost_retry_exhausted(task, item)]
                if exhausted_owner_lost_items:
                    exhausted_item = exhausted_owner_lost_items[0]
                    return {
                        "stage_name": stage_name,
                        "stage_run": stage_run,
                        "failure_code": "owner_lost_retry_exhausted",
                        "failure_category": "infrastructure",
                        "failure_message": str(exhausted_item.error_message or "").strip() or "owner_lost_retry_exhausted",
                        "reason": "owner_lost_retry_exhausted",
                    }
                recoverable_items = [
                    item for item in items
                    if self._is_owner_lost_recoverable_failure(
                        failure_message=str(item.error_message or "").strip() or None,
                        failure_category=snapshot.get("failure_category"),
                        error_type=self._stage_item_sync_error_type_value(item),
                        item=item,
                    )
                ]
                if recoverable_items:
                    continue
            snapshot = self._stage_failure_snapshot(task, stage_run)
            failure_message = next((str(item.error_message or "").strip() for item in items if str(item.error_message or "").strip()), None)
            return {
                "stage_name": stage_name,
                "stage_run": stage_run,
                "failure_code": snapshot.get("failure_code"),
                "failure_category": snapshot.get("failure_category"),
                "failure_message": snapshot.get("failure_message") or snapshot.get("error") or failure_message or getattr(stage_run, "last_error", None),
                "reason": "earlier_stage_items_terminal",
            }
        return None

    def _later_stage_names(self, task: BinarySecurityTask, stage_name: str | None) -> list[str]:
        current_stage = str(stage_name or "").strip()
        if not current_stage:
            return []
        sequence = [str(name or "").strip() for name in self._stage_sequence_for_task(task) if str(name or "").strip()]
        try:
            current_index = sequence.index(current_stage)
        except ValueError:
            return []
        return sequence[current_index + 1 :]

    def _suppress_later_stage_items_after_archive_blocked(
        self,
        db: Session,
        task: BinarySecurityTask,
        *,
        stage_name: str,
        error_message: str,
        archive_job_id: str | None = None,
        downstream_task_id: str | None = None,
    ) -> list[str]:
        blocked_item_ids: list[str] = []
        blocked_stages = self._later_stage_names(task, stage_name)
        if not blocked_stages:
            return blocked_item_ids
        blocked_at = _now()
        for blocked_stage_name in blocked_stages:
            touched_stage = False
            for item in self._stage_items(db, task.id, blocked_stage_name):
                if not self._is_active_item_status(item.status):
                    continue
                touched_stage = True
                item.status = "skipped"
                item.error_message = error_message
                item.finished_at = blocked_at
                result_payload = self._merge_stage_item_result(
                    item,
                    {
                        "blocked_by_upstream_archive_failure": True,
                        "blocked_from_stage": stage_name,
                        "blocked_reason": error_message,
                        "blocked_at": _isoformat_or_none(blocked_at),
                        "blocking_archive_job_id": archive_job_id,
                        "blocking_downstream_task_id": downstream_task_id,
                    },
                )
                self._clear_stage_item_sync_observation_errors(
                    item,
                    result_payload=result_payload,
                    touched=False,
                )
                blocked_item_ids.append(str(item.id or ""))
                self._record_event(
                    db,
                    task,
                    "downstream_stage_item_blocked_after_archive_failure",
                    f"上游阶段归档失败，已阻断后续阶段项: {blocked_stage_name}:{item.item_key}",
                    level="warning",
                    stage_name=blocked_stage_name,
                    item=item,
                    payload={
                        "blocked_from_stage": stage_name,
                        "blocking_archive_job_id": archive_job_id,
                        "blocking_downstream_task_id": downstream_task_id,
                        "blocked_reason": error_message,
                    },
                )
            if touched_stage:
                self._refresh_stage_from_authoritative_items(db, task, blocked_stage_name)
        return blocked_item_ids

    def _finalize_task_after_authoritative_failure(
        self,
        db: Session,
        task: BinarySecurityTask,
        *,
        failure_ctx: dict[str, Any],
        previous_status: str | None = None,
        event_type: str = "dispatching_state_force_terminalized",
    ) -> None:
        stage_name = str(failure_ctx.get("stage_name") or task.current_stage or "").strip() or None
        failure_code = self._string_or_none(failure_ctx.get("failure_code"))
        failure_category = self._string_or_none(failure_ctx.get("failure_category"))
        failure_message = self._string_or_none(failure_ctx.get("failure_message")) or task.last_error
        stage_run = failure_ctx.get("stage_run")
        task.status = "failed"
        if stage_name:
            task.current_stage = stage_name
        task.finished_at = task.finished_at or _now()
        task.last_error = failure_message
        self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_TERMINAL)
        task.dispatcher_instance_id = None
        task.dispatch_started_at = None
        task.lease_expires_at = None
        self._record_event(
            db,
            task,
            event_type,
            "检测到当前阶段已进入终态失败，父任务已自动结束 dispatching 收口",
            level="warning",
            stage_name=stage_name,
            payload={
                "stage_name": stage_name,
                "failure_code": failure_code,
                "failure_category": failure_category,
                "failure_message": failure_message,
                "previous_status": previous_status,
                "reason": self._string_or_none(failure_ctx.get("reason")),
            },
        )
        if str(failure_category or "").strip() == "business":
            self._record_business_failure_terminalization(db, task, stage_run)
        else:
            self._record_event(
                db,
                task,
                "task_finalized_after_child_failure",
                "下游子任务已终态失败，父任务已直接收口为 failed",
                level="warning",
                stage_name=stage_name,
                payload={
                    "stage_name": stage_name,
                    "failure_code": failure_code,
                    "failure_category": failure_category,
                    "failure_message": failure_message,
                    "requeue_suppressed": True,
                },
            )
        if failure_code == "owner_lost_retry_exhausted":
            self._sync_task_abnormal_reason_snapshot(
                db,
                task,
                self._build_abnormal_reason(
                    category="infrastructure",
                    code="owner_lost_retry_exhausted",
                    title="下游 owner 丢失自动恢复失败",
                    message=failure_message or "下游 owner 丢失自动恢复次数耗尽",
                    source_layer="task",
                    status="failed",
                    service="binary-security",
                    stage_name=stage_name,
                    evidence=[
                        self._abnormal_reason_evidence("current_stage", "当前阶段", stage_name),
                        self._abnormal_reason_evidence("last_error", "原始错误", failure_message),
                    ],
                    recommended_action="检查 rollout、worker 与 lease 变更，并手工重试或排查下游恢复能力。",
                    terminal=True,
                ),
            )
        else:
            self._clear_task_abnormal_reason_snapshot(db, task)

    def _retry_snapshot_for_item(self, task: BinarySecurityTask, stage_name: str, item_key: str) -> dict[str, Any] | None:
        summary = task.summary or {}
        stage_context = (summary.get("stage_retry_context") or {}).get(stage_name) or {}
        snapshot = stage_context.get(item_key)
        return dict(snapshot) if isinstance(snapshot, dict) else None

    def _stage_result_keys(self, stage_name: str) -> list[str]:
        stage_name = normalize_stage_name(stage_name)
        return list(STAGE_SUMMARY_RESULT_KEYS.get(stage_name, []))

    def _stage_expected_service(self, stage_name: str) -> str | None:
        stage_name = normalize_stage_name(stage_name)
        mapping = STAGE_RETRY_ENDPOINTS.get(stage_name)
        return mapping[0] if mapping else None

    async def _fetch_downstream_task_payload(self, task: BinarySecurityTask, item: BinarySecurityStageItem, token: str) -> dict[str, Any]:
        return await self._downstream_fetch_item_payload(task, item, token)

    async def _refresh_terminal_item_result_from_downstream(
        self,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        payload: dict[str, Any],
        *,
        mapped_status: str,
        archived_dir: Path | None,
    ) -> None:
        if item.stage_name != "system_analysis" or item.downstream_service != "system_analyse":
            return
        if mapped_status != "success":
            return
        result_payload: dict[str, Any] = {}
        try:
            result_payload = await self._downstream_fetch_item_result(item)
        except Exception:
            result_payload = {}
        firmware = self._system_analysis_input_for_item(task, item)
        artifact_root = archived_dir or self._service_output_dir(
            task,
            item.downstream_service or item.stage_name,
            item.item_key,
            item.downstream_task_id,
        )
        modules = self._parse_system_analysis_modules(artifact_root, firmware, result_payload)
        self._persist_stage_item_result(
            task,
            item,
            stage_name=item.stage_name,
            result={
                **self._lightweight_system_analysis_input(firmware),
                "modules": self._lightweight_modules_for_storage(modules),
                "module_count": len(modules),
                "downstream": self._lightweight_downstream_payload(payload),
                "system_analysis_result": self._lightweight_system_analysis_result(result_payload),
                "downstream_status_synced_at": _now().isoformat(),
            },
        )
        item.output_ref = {
            **(item.output_ref or {}),
            "artifact_root": str(artifact_root),
            "archive_root": str(artifact_root),
        }

    def _refresh_firmware_unpack_item_result(
        self,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        *,
        archived_dir: Path | None,
        bound_downstream_task_id: str | None = None,
        downstream_payload: dict[str, Any] | None = None,
    ) -> None:
        input_ref = dict(item.input_ref or {})
        result = self._load_stage_item_result_payload(item)
        firmware_key = str(item.item_key or input_ref.get("firmware_key") or result.get("firmware_key") or "")
        filename = str(input_ref.get("filename") or item.item_name or result.get("filename") or firmware_key)
        effective_downstream_task_id = str(bound_downstream_task_id or item.downstream_task_id or "").strip()
        metadata_sources = self._resolve_downstream_output_sources(
            downstream_payload or result.get("downstream") or {},
            downstream_task_id=effective_downstream_task_id,
            task=task,
            downstream_service=item.downstream_service,
        )
        runtime_output_path = str(metadata_sources[0]) if metadata_sources else ""
        unpacked_root = str(archived_dir) if archived_dir else (
            self._stage_item_archive_root(item)
            or str(result.get("unpacked_root") or runtime_output_path)
        )
        self._persist_stage_item_result(
            task,
            item,
            stage_name=item.stage_name,
            result={
                **result,
                "firmware_key": firmware_key,
                "firmware_name": str(result.get("firmware_name") or Path(filename).stem or firmware_key),
                "filename": filename,
                "input_path": str(input_ref.get("path") or result.get("input_path") or ""),
                "unpacked_root": unpacked_root,
                "source_root": str(result.get("source_root") or unpacked_root),
                "task_type": result.get("task_type", TASK_TYPE_BINARY),
                "downstream": self._lightweight_downstream_payload(downstream_payload or result.get("downstream") or {}),
                "downstream_status_synced_at": _now().isoformat(),
                "bound_downstream_task_id": effective_downstream_task_id or None,
            },
        )
        item.output_ref = {
            **(item.output_ref or {}),
            "runtime_output_path": runtime_output_path,
            "unpacked_root": unpacked_root,
            **({"archive_root": str(archived_dir)} if archived_dir else {}),
        }

    def _system_analysis_input_for_item(self, task: BinarySecurityTask, item: BinarySecurityStageItem) -> dict[str, Any]:
        for candidate in self._system_analysis_inputs(task):
            if str(candidate.get("firmware_key") or "") == str(item.item_key or ""):
                return dict(candidate)
        input_ref = dict(item.input_ref or {})
        return {
            "firmware_key": str(item.item_key or input_ref.get("firmware_key") or SOURCE_TASK_INPUT_KEY),
            "firmware_name": str(item.item_name or task.name),
            "filename": str(item.item_name or input_ref.get("filename") or item.item_key or "source-project"),
            "unpacked_root": str(input_ref.get("input_path") or input_ref.get("unpacked_root") or Path(task.workspace_root) / "input"),
            "source_root": str(input_ref.get("source_root") or input_ref.get("input_path") or Path(task.workspace_root) / "input"),
            "task_type": self._task_type(task),
        }

    def _map_downstream_status(self, status: str) -> str | None:
        normalized = (status or "").lower()
        if normalized in {"downstream_missing", "not_found", "missing", "task_not_found"}:
            return "downstream_missing"
        if normalized in {"pending", "queued", "created", "ready", "ready_to_start", "awaiting_takeover", "retry_preparing"}:
            return "pending"
        if normalized == "dispatching":
            return "dispatching"
        if normalized in {"running", "processing", "in_progress", "cancelling", "started"}:
            return "running"
        if normalized in {"success", "succeeded", "passed", "completed", "complete", "done"}:
            return "success"
        if normalized == "partial_success":
            return "partial_success"
        if normalized == "skipped":
            return "failed"
        if normalized in {"invalid_input", "completed_limited"}:
            return "failed"
        if normalized in {"failed", "error", "failure"}:
            return "failed"
        if normalized in {"cancelled", "canceled"}:
            return "cancelled"
        return None

    @staticmethod
    def _is_owner_lost_recoverable_message(message: str | None) -> bool:
        normalized = str(message or "").strip().lower()
        if not normalized:
            return False
        if "owner_lost_retry_exhausted" in normalized:
            return False
        tokens = (
            "task owner pod lost",
            "owner pod lost",
            "owner lost",
            "staletaskexecution",
            "当前执行 token 已失效",
            "runtime lease owner 已变更",
            "lease owner 已变更",
            "token 已失效",
            "awaiting_takeover",
            "retry_preparing",
        )
        return any(token.lower() in normalized for token in tokens)

    def _is_owner_lost_recoverable_failure(
        self,
        *,
        failure_message: str | None,
        failure_category: str | None = None,
        error_type: str | None = None,
        item: BinarySecurityStageItem | None = None,
    ) -> bool:
        if str(failure_category or "").strip().lower() == "business":
            return False
        if self._is_owner_lost_recoverable_message(failure_message):
            return True
        if self._is_owner_lost_recoverable_message(error_type):
            return True
        if item is not None:
            if self._is_owner_lost_recoverable_message(item.error_message):
                return True
            observed_error_type = self._stage_item_sync_error_type_value(item)
            if self._is_owner_lost_recoverable_message(observed_error_type):
                return True
            observed_error_message = self._stage_item_sync_error_message_value(item)
            if self._is_owner_lost_recoverable_message(observed_error_message):
                return True
        return False

    def _owner_lost_retry_exhausted(self, task: BinarySecurityTask, item: BinarySecurityStageItem) -> bool:
        return self._is_owner_lost_recoverable_failure(
            failure_message=str(item.error_message or "").strip() or None,
            error_type=self._stage_item_sync_error_type_value(item),
            item=item,
        ) and int(item.retry_count or 0) > self._max_retries_per_item(task)

    def _aggregate_item_statuses(self, statuses: list[str]) -> str:
        if not statuses:
            return "pending"
        if any(status == "running" for status in statuses):
            return "running"
        if any(status == "dispatching" for status in statuses):
            return "dispatching"
        if any(status in {"pending", "queued"} for status in statuses):
            return "pending"
        if all(status == "success" for status in statuses):
            return "success"
        if any(status == "success" for status in statuses) and any(status in {"failed", "cancelled", "partial_success", "downstream_missing"} for status in statuses):
            return "partial_success"
        if all(status == "cancelled" for status in statuses):
            return "cancelled"
        if all(status == "downstream_missing" for status in statuses):
            return "downstream_missing"
        if any(status in {"failed", "partial_success"} for status in statuses):
            return "failed"
        if any(status == "downstream_missing" for status in statuses):
            return "downstream_missing"
        return statuses[0]

    def _is_active_item_status(self, status: str | None) -> bool:
        normalized = self._normalize_downstream_status(status) or str(status or "").strip().lower()
        return normalized in {"pending", "queued", "running", "dispatching"}

    def _is_terminal_item_status(self, status: str | None) -> bool:
        normalized = self._normalize_downstream_status(status) or str(status or "").strip().lower()
        return normalized in {"success", "failed", "cancelled", "downstream_missing", "skipped", "partial_success"}

    def _stage_has_active_items(self, items: list[BinarySecurityStageItem]) -> bool:
        return any(self._is_active_item_status(item.status) for item in items)

    def _stage_has_nonterminal_items(self, items: list[BinarySecurityStageItem]) -> bool:
        return any(not self._is_terminal_item_status(item.status) for item in items)

    def _stage_has_live_downstream_children(
        self,
        items: list[BinarySecurityStageItem],
    ) -> bool:
        return self._stage_has_active_items(items)

    def _stage_has_sync_degraded_items(self, items: list[BinarySecurityStageItem]) -> bool:
        for item in items:
            if not str(item.downstream_task_id or "").strip():
                continue
            if self._stage_item_sync_error_budget_exhausted(item):
                return True
            if self._stage_item_sync_in_retry_backoff(item):
                return True
            if self._item_downstream_sync_stale(item):
                return True
            if self._stage_item_sync_consecutive_error_count(item) > 0:
                return True
        return False

    def _stage_has_orchestration_degraded_items(self, items: list[BinarySecurityStageItem]) -> bool:
        for item in items:
            if self._stage_item_orchestration_error_budget_exhausted(item):
                return True
            if self._stage_item_orchestration_in_retry_backoff(item):
                return True
        return False

    def _stage_has_real_runnable_work(
        self,
        db: Session,
        task: BinarySecurityTask,
        stage_name: str,
    ) -> bool:
        upstream_retried, _ = self._upstream_stage_retried(db, task, stage_name)
        if upstream_retried:
            return False
        items = self._stage_items(db, task.id, stage_name)
        if items:
            if self._is_streaming_tail_stage(task, stage_name):
                return any(
                    (self._normalize_downstream_status(item.status) or str(item.status or "").strip()) in {"pending", "queued"}
                    and not str(item.downstream_task_id or "").strip()
                    for item in items
                ) or any(self._is_streaming_active_item_status(item.status) for item in items)
            return True
        if self._is_streaming_tail_stage(task, stage_name):
            return False
        return self._stage_has_materialized_inputs(db, task, stage_name)

    def _stage_requires_materialized_inputs(self, task: BinarySecurityTask, stage_name: str) -> bool:
        normalized_stage = normalize_stage_name(stage_name)
        return normalized_stage in {"binary_to_source", "entry_analysis", "dataflow_vuln_scan"}

    def _stage_has_materialized_inputs(
        self,
        db: Session,
        task: BinarySecurityTask,
        stage_name: str,
    ) -> bool:
        self._ensure_stage_inputs_available(db, task, stage_name)
        summary = dict(task.summary or {})
        normalized_stage = normalize_stage_name(stage_name)
        if normalized_stage == "system_analysis":
            return bool(self._system_analysis_inputs(task, db=db))
        if normalized_stage == "binary_to_source":
            return bool(list(summary.get("selected_modules") or []))
        if normalized_stage == "entry_analysis":
            return bool(self._entry_analysis_inputs(db, task))
        if normalized_stage == "dataflow_vuln_scan":
            return bool(self._effective_entry_inputs(task))
        return True

    def _should_hold_task_on_stage_after_requeue(
        self,
        db: Session,
        task: BinarySecurityTask,
        stage_name: str,
    ) -> bool:
        if not stage_name:
            return False
        items = self._stage_items(db, task.id, stage_name)
        if any(self._is_active_item_status(item.status) for item in items):
            return True
        target_stage = str(task.target_stage_name or "").strip()
        return (
            task.execution_mode == TASK_ACTION_RETRY_STAGE_FULL
            and bool(target_stage)
            and target_stage == stage_name
            and self._stage_has_real_runnable_work(db, task, stage_name)
        )

    def _empty_streaming_stage_run_status(self, task: BinarySecurityTask, stage_run: BinarySecurityStageRun) -> str:
        if not self._streaming_mode_enabled(task) or not self._is_streaming_tail_stage(task, stage_run.stage_name):
            return "pending"
        current = str(stage_run.status or "").strip()
        if current == "success":
            return current
        if current in {"failed", "downstream_missing", "cancelled", "partial_success"}:
            return "pending"
        if current in {"running", "dispatching"}:
            return "running"
        if current in {"queued", "pending"}:
            return "pending"
        return "pending"

    def _empty_streaming_stage_run_last_error(self, task: BinarySecurityTask, stage_run: BinarySecurityStageRun) -> str | None:
        if not self._streaming_mode_enabled(task) or not self._is_streaming_tail_stage(task, stage_run.stage_name):
            return None
        current_status = str(stage_run.status or "").strip()
        if current_status in {"failed", "downstream_missing", "partial_success"}:
            return stage_run.last_error
        return None

    def _refresh_streaming_tail_stage_state(self, db: Session, task: BinarySecurityTask, stage_name: str) -> None:
        self._refresh_stage_run_from_items(db, task, stage_name)
        if stage_name == "entry_analysis":
            self._rebuild_entry_results_from_stage_items(db, task)
        elif normalize_stage_name(stage_name) == "dataflow_vuln_scan":
            self._rebuild_summary_results_from_stage_items(db, task, "dataflow_vuln_scan", "dataflow_results")

    def _refresh_stage_from_authoritative_items_once(self, db: Session, task: BinarySecurityTask, stage_name: str) -> BinarySecurityStageRun | None:
        if stage_name == "system_analysis":
            self._refresh_system_analysis_stage_from_synced_items(db, task)
        elif self._is_streaming_tail_stage(task, stage_name):
            self._refresh_streaming_tail_stage_state(db, task, stage_name)
        else:
            self._refresh_stage_run_from_items(db, task, stage_name)
        return db.query(BinarySecurityStageRun).filter(
            BinarySecurityStageRun.task_id == task.id,
            BinarySecurityStageRun.stage_name == stage_name,
        ).first()

    def _refresh_stage_from_authoritative_items(
        self,
        db: Session,
        task: BinarySecurityTask,
        stage_name: str,
        *,
        retry_on_lock: bool = True,
        operation: str = "authoritative_stage_refresh",
    ) -> BinarySecurityStageRun | None:
        attempts = self._retryable_write_attempts() if retry_on_lock else 1
        task_id = str(task.id or "").strip()
        for attempt in range(1, attempts + 1):
            try:
                return self._refresh_stage_from_authoritative_items_once(db, task, stage_name)
            except OperationalError as exc:
                if not self._is_retryable_lock_error(exc):
                    raise
                result = "retry_scheduled" if attempt < attempts else "failed"
                observe_task_snapshot_lock_retry(
                    operation=operation,
                    stage=stage_name,
                    result=result,
                )
                logger.warning(
                    "binary-security task snapshot lock conflict task_id=%s stage_name=%s operation=%s attempt=%s result=%s runtime_role=%s",
                    task_id or "-",
                    stage_name or "-",
                    operation,
                    attempt,
                    result,
                    self._service_role(),
                    exc_info=(attempt >= attempts),
                )
                with suppress(Exception):
                    db.rollback()
                if attempt >= attempts:
                    raise
                self._sleep_after_retryable_lock_error(attempt)
                refreshed_task = (
                    db.query(BinarySecurityTask)
                    .filter(BinarySecurityTask.id == task_id)
                    .first()
                )
                if refreshed_task is not None:
                    task = refreshed_task
        return None

    def _reconcile_stage_and_task_state_after_item_update(
        self,
        db: Session,
        task: BinarySecurityTask,
        stage_name: str,
    ) -> BinarySecurityStageRun | None:
        stage_run = self._refresh_stage_from_authoritative_items(db, task, stage_name)
        self._refresh_task_status_after_sync(db, task)
        return stage_run

    def _refresh_stage_run_from_items(self, db: Session, task: BinarySecurityTask, stage_name: str) -> None:
        stage_run = db.query(BinarySecurityStageRun).filter(
            BinarySecurityStageRun.task_id == task.id,
            BinarySecurityStageRun.stage_name == stage_name,
        ).first()
        if not stage_run:
            return
        items = self._stage_items(db, task.id, stage_name)
        deduped_items: list[BinarySecurityStageItem] = []
        seen_item_ids: set[str] = set()
        seen_identity_keys: set[str] = set()
        for item in items:
            item_id = str(item.id or "").strip()
            if item_id and item_id in seen_item_ids:
                continue
            identity_key = str(getattr(item, "item_identity_key", "") or "").strip()
            if not identity_key:
                identity_key = self._stage_item_identity(item.item_key, item.parent_key)
            if identity_key and identity_key in seen_identity_keys:
                continue
            if item_id:
                seen_item_ids.add(item_id)
            if identity_key:
                seen_identity_keys.add(identity_key)
            deduped_items.append(item)
        items = deduped_items
        if items:
            status = self._aggregate_item_statuses([item.status for item in items])
            if status in {"success", "partial_success"} and self._stage_has_sync_degraded_items(items):
                status = "running" if any(str(item.status or "").strip() in {"running", "dispatching"} for item in items) else "pending"
            if status in {"success", "partial_success"} and self._stage_has_orchestration_degraded_items(items):
                status = "running" if any(str(item.status or "").strip() in {"running", "dispatching"} for item in items) else "pending"
        else:
            status = self._empty_streaming_stage_run_status(task, stage_run)
        stage_run.status = status
        stage_run.counts = self._stage_counts(db, stage_run)
        if items:
            if status in {"failed", "partial_success", "downstream_missing", "cancelled"}:
                stage_run.last_error = next(
                    (
                        item.error_message
                        for item in items
                        if item.status in {"failed", "downstream_missing", "cancelled"} and item.error_message
                    ),
                    None,
                )
            else:
                stage_run.last_error = None
        else:
            stage_run.last_error = self._empty_streaming_stage_run_last_error(task, stage_run)
        self._merge_stage_run_output_summary(
            task,
            stage_run,
            {
                "status_synced": True,
                "sync_status": status,
                **stage_run.counts,
            },
        )
        items_present = bool(items)
        active_items_present = any(str(item.status or "").strip() in {"running", "dispatching"} for item in items)
        should_start = False
        if status in {"running", "dispatching"}:
            should_start = items_present
        elif status in {"pending", "queued"}:
            should_start = items_present
        if status in {"running", "pending", "queued", "dispatching"}:
            stage_run.finished_at = None
            if should_start:
                stage_run.started_at = stage_run.started_at or _now()
            elif self._is_streaming_tail_stage(task, stage_name) and stage_run.started_at is None:
                self._record_event(
                    db,
                    task,
                    "streaming_tail_stage_start_suppressed",
                    f"流式尾段尚无真实子项，保留未启动态: {stage_name}",
                    stage_name=stage_name,
                    payload={
                        "stage_name": stage_name,
                        "status": status,
                        "items_present": items_present,
                        "active_items_present": active_items_present,
                    },
                )
        else:
            stage_run.finished_at = stage_run.finished_at or _now()
        if stage_name == "firmware_unpack":
            success_items = [self._load_stage_item_result_payload(item) for item in items if item.status == "success"]
            compact_success = self._compact_stage_success_items("firmware_unpack_results", success_items)
            task.summary = {**(task.summary or {}), "firmware_unpack_results": compact_success}
            task.metrics = {
                **(task.metrics or {}),
                "unpacked_firmware_count": int(stage_run.counts.get("success_items", 0)),
                "failed_firmware_count": int(stage_run.counts.get("failed_items", 0)),
            }
        elif stage_name == "entry_analysis":
            self._rebuild_entry_results_from_stage_items(db, task, stage_run)
        self._update_task_stage_summary_entry(task, stage_run)

    def _rebuild_entry_results_from_stage_items(
        self,
        db: Session,
        task: BinarySecurityTask,
        stage_run: BinarySecurityStageRun | None = None,
    ) -> list[dict[str, Any]]:
        """Rebuild full entry_results after downstream sync only updated stage items.

        Stage item result_json intentionally stores only entries_preview to keep DB rows
        small, so the authoritative source for full entries is the archived artifact.
        """
        items = [
            item
            for item in self._stage_items(db, task.id, "entry_analysis")
            if item.status == "success"
        ]
        rebuilt: list[dict[str, Any]] = []
        for item in items:
            result = self._load_stage_item_result_payload(item)
            input_ref = dict(item.input_ref or {})
            output_ref = dict(item.output_ref or {})
            module = {
                **input_ref,
                **result,
                "module_key": str(result.get("module_key") or input_ref.get("module_key") or item.item_key or ""),
                "module_name": str(result.get("module_name") or input_ref.get("module_name") or item.item_name or ""),
                "source_dir": self._resolve_entry_source_dir({**input_ref, **result}) or str(task.firmware_path or ""),
            }
            if not module["module_key"] or not module["module_name"]:
                continue
            artifact_root_value = self._stage_item_artifact_root(item)
            entries = [dict(entry) for entry in result.get("entries") or [] if isinstance(entry, dict)]
            if artifact_root_value:
                artifact_root = Path(str(artifact_root_value))
                parsed_entries = self._parse_entries(artifact_root, module)
                if parsed_entries:
                    entries = parsed_entries
                    module["artifact_root"] = str(artifact_root)
            if not entries:
                entries = [dict(entry) for entry in result.get("entries_preview") or [] if isinstance(entry, dict)]
            if not entries:
                continue
            normalized_entries = []
            for entry in entries:
                row = dict(entry)
                row["source_dir"] = self._resolve_entry_source_dir({**module, **row}) or module["source_dir"]
                normalized_entries.append(row)
            rebuilt.append(self._compact_entry_summary_item({**module, "entries": normalized_entries}))

        summary = {**(task.summary or {}), "entry_results": rebuilt}
        task.summary = summary
        entry_count = self._entry_count_for_summary("entry_results", rebuilt)
        task.metrics = {**(task.metrics or {}), "entry_count": entry_count}
        if stage_run is not None:
            stage_summary = {
                "items": self._compact_stage_success_items_for_db("entry_results", rebuilt),
                "failed_items": [
                    self._lightweight_stage_failure(
                        {
                            "item": {
                                **dict(item.input_ref or {}),
                                **self._load_stage_item_result_payload(item),
                            },
                            "error": item.error_message,
                        }
                    )
                    for item in self._stage_items(db, task.id, "entry_analysis")
                    if item.status in {"failed", "cancelled", "downstream_missing"}
                ],
                "success_count": len(rebuilt),
                "failed_count": int((stage_run.counts or {}).get("failed_items") or 0),
                "cancelled_count": int((stage_run.counts or {}).get("cancelled_items") or 0),
                "entry_count": entry_count,
                "status_synced": True,
                "sync_status": stage_run.status,
                **(stage_run.counts or {}),
            }
            self._persist_stage_run_output_summary(task, stage_run, stage_summary)
        return rebuilt

    def _refresh_system_analysis_stage_from_synced_items(self, db: Session, task: BinarySecurityTask) -> None:
        stage_run = db.query(BinarySecurityStageRun).filter(
            BinarySecurityStageRun.task_id == task.id,
            BinarySecurityStageRun.stage_name == "system_analysis",
        ).first()
        if not stage_run:
            return
        items = self._stage_items(db, task.id, "system_analysis")
        success = []
        failed = [
            {"status": item.status, "error": item.error_message, "item_key": item.item_key}
            for item in items
            if item.status in {"failed", "cancelled", "downstream_missing"}
        ]
        archive_jobs_by_item = self._stage_archive_jobs_by_item(db, task.id, "system_analysis")
        all_modules: list[dict[str, Any]] = []
        for item in items:
            if item.status != "success":
                continue
            result = self._load_stage_item_result_payload(item)
            item_modules = self._system_analysis_modules_from_item(
                task,
                item,
                archive_jobs=archive_jobs_by_item.get(str(item.id or ""), []),
            )
            all_modules.extend(item_modules)
            success.append({**result, "modules": self._lightweight_modules_for_storage(item_modules), "module_count": len(item_modules)})
        status = self._aggregate_item_statuses([item.status for item in items])
        candidate_modules = self._filter_candidate_modules(all_modules, self._module_selection_candidate_levels(task))
        summary = dict(task.summary or {})
        existing_selected_modules = [
            dict(module)
            for module in list(summary.get("selected_modules") or [])
            if isinstance(module, dict) and str(module.get("module_key") or "").strip()
        ]
        candidate_keys = {
            str(module.get("module_key") or "").strip()
            for module in candidate_modules
            if str(module.get("module_key") or "").strip()
        }
        existing_selected_map = {
            str(module.get("module_key") or "").strip(): module
            for module in existing_selected_modules
        }
        confirmed_selected_modules = [
            {
                **dict(next(module for module in candidate_modules if str(module.get("module_key") or "").strip() == module_key)),
                **{
                    "selected_by": existing_selected_map[module_key].get("selected_by"),
                    "selected_at": existing_selected_map[module_key].get("selected_at"),
                },
            }
            for module_key in existing_selected_map.keys()
            if module_key in candidate_keys
        ]
        has_confirmed_manual_selection = any(
            str(module.get("selected_by") or "").strip() == MODULE_SELECTION_MODE_MANUAL_CONFIRM
            for module in confirmed_selected_modules
        )
        selected_modules: list[dict[str, Any]] = []
        if status in {"success", "partial_success"} and candidate_modules:
            if self._module_selection_mode(task) == MODULE_SELECTION_MODE_AUTO:
                selected_modules = self._mark_selected_modules(candidate_modules, selected_by=MODULE_SELECTION_MODE_AUTO)
            elif has_confirmed_manual_selection:
                selected_modules = confirmed_selected_modules
            else:
                task.status = TASK_STATUS_PENDING_MODULE_CONFIRMATION
                self._record_event(
                    db,
                    task,
                    "module_selection_required",
                    "系统分析已同步完成，等待人工确认模块",
                    stage_name="system_analysis",
                    payload={"candidate_module_count": len(candidate_modules)},
                )
        no_candidate_modules_failure = status == "success" and not failed and not candidate_modules
        if no_candidate_modules_failure:
            failure = _no_candidate_modules_failure()
            status = "failed"
            failed = failed or [{"status": "failed", **failure}]
        summary.update(
            {
                "system_analysis_results": self._lightweight_system_analysis_items(success),
                "system_analysis_modules": self._lightweight_modules_for_storage(all_modules),
                "system_analysis_module_count": len(all_modules),
                "candidate_modules": candidate_modules,
                "selected_modules": selected_modules,
                "high_risk_modules": selected_modules,
                **(_no_candidate_modules_failure() if no_candidate_modules_failure else {}),
            }
        )
        task.summary = summary
        task.metrics = {
            **(task.metrics or {}),
            **self._module_metrics(all_modules, candidate_modules, selected_modules),
        }
        stage_run.status = "waiting_confirmation" if task.status == TASK_STATUS_PENDING_MODULE_CONFIRMATION else status
        stage_run.finished_at = None if stage_run.status in {"running", "pending", "queued"} else (stage_run.finished_at or _now())
        stage_run.started_at = stage_run.started_at or _now()
        stage_run.counts = self._stage_counts(db, stage_run)
        stage_run.last_error = failed[0].get("error") if failed and status == "failed" else None
        if no_candidate_modules_failure and stage_run.last_error == NO_CANDIDATE_MODULES_FAILURE_MESSAGE:
            task.last_error = stage_run.last_error
            self._record_event(
                db,
                task,
                "system_analysis_no_candidate_modules",
                NO_CANDIDATE_MODULES_FAILURE_MESSAGE,
                level="error",
                stage_name="system_analysis",
                payload=_no_candidate_modules_failure(),
            )
        else:
            task.last_error = None
        self._persist_stage_run_output_summary(
            task,
            stage_run,
            {
                "items": self._lightweight_system_analysis_items(success),
                "failed_items": failed,
                "success_count": len(success),
                "failed_count": len(failed),
                "module_count": len(all_modules),
                "high_risk_module_count": sum(1 for module in all_modules if str(module.get("risk_level") or "").strip() == "高"),
                "medium_risk_module_count": sum(1 for module in all_modules if str(module.get("risk_level") or "").strip() == "中"),
                "low_risk_module_count": sum(1 for module in all_modules if str(module.get("risk_level") or "").strip() == "低"),
                "candidate_module_count": len(candidate_modules),
                "selected_module_count": len(selected_modules),
                "status_synced": True,
                "sync_status": stage_run.status,
                "error": stage_run.last_error,
                **(_no_candidate_modules_failure() if no_candidate_modules_failure else {}),
                **stage_run.counts,
            },
        )
        self._merge_task_stage_summary_entry(
            task,
            stage_run,
            {
                "sequence_no": stage_run.sequence_no,
                "status": stage_run.status,
                "total_items": int((stage_run.counts or {}).get("total_items") or len(items)),
                "success_items": int((stage_run.counts or {}).get("success_items") or len(success)),
                "failed_items": int((stage_run.counts or {}).get("failed_items") or len(failed)),
                "orchestration_failed_items": int(
                    (stage_run.counts or {}).get("failed_items") or len(failed)
                ),
                "downstream_missing_items": int((stage_run.counts or {}).get("downstream_missing_items") or 0),
                "skipped_items": int((stage_run.counts or {}).get("skipped_items") or 0),
                "running_items": int((stage_run.counts or {}).get("running_items") or 0),
                "cancelled_items": int((stage_run.counts or {}).get("cancelled_items") or 0),
                "downstream_status_counts": {},
                "started_at": stage_run.started_at.isoformat() if stage_run.started_at else None,
                "finished_at": stage_run.finished_at.isoformat() if stage_run.finished_at else None,
                "last_error": stage_run.last_error,
            },
        )

    def _refresh_task_status_after_sync(self, db: Session, task: BinarySecurityTask) -> None:
        current_status = str(task.status or "").strip()
        active_cancel_operation = self._active_cancel_operation(db, task.id)
        if self._ensure_task_remains_cancelling(db, task, active_cancel_operation=active_cancel_operation) is not None:
            return
        if self._recover_failed_cancelled_task_state(db, task):
            return
        active_operation = self._active_operation(db, task.id)
        if task.status == "cancelled":
            self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_TERMINAL)
            self._invalidate_task_execution(task)
            task.finished_at = task.finished_at or _now()
            return
        if task.status == TASK_STATUS_CANCEL_FAILED:
            self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_TERMINAL)
            self._invalidate_task_execution(task)
            task.finished_at = task.finished_at or _now()
            return
        if task.status == TASK_STATUS_PENDING_MODULE_CONFIRMATION:
            self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
            task.dispatcher_instance_id = None
            task.dispatch_started_at = None
            task.lease_expires_at = None
            task.finished_at = None
            return
        if active_operation is not None:
            if self._task_runtime_phase(task) != TASK_RUNTIME_PHASE_TAIL_RECONCILIATION:
                self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
            task.finished_at = None
            task.last_error = None if str(active_operation.status or "").strip() in {"accepted", "queued", "running"} else task.last_error
            task.current_operation_id = active_operation.id
            return
        stage_runs = db.query(BinarySecurityStageRun).filter(BinarySecurityStageRun.task_id == task.id).all()
        runs_by_stage = {str(run.stage_name or "").strip(): run for run in stage_runs}
        if (
            task.status == "failed"
            and not stage_runs
            and not db.query(BinarySecurityStageItem).filter(BinarySecurityStageItem.task_id == task.id).first()
        ):
            self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_TERMINAL)
            self._invalidate_task_execution(task)
            task.finished_at = task.finished_at or _now()
            return
        for stage_name in self._stage_sequence_for_task(task):
            if not self._stage_enabled(task, stage_name):
                continue
            stage_run = runs_by_stage.get(stage_name)
            stage_items = self._stage_items(db, task.id, stage_name)
            stage_run_status = str(stage_run.status or "").strip() if stage_run is not None else ""
            if stage_items or (
                self._is_streaming_tail_stage(task, stage_name)
                and normalize_stage_name(stage_name) == "dataflow_vuln_scan"
                and stage_run_status in {"failed", "downstream_missing", "cancelled", "partial_success"}
            ):
                self._refresh_stage_from_authoritative_items(db, task, stage_name)
        stage_runs = db.query(BinarySecurityStageRun).filter(BinarySecurityStageRun.task_id == task.id).all()
        if self._recover_streaming_parent_running_state_locked(
            db,
            task,
            record_event=current_status == "dispatching",
            reason="refresh_task_status_after_sync",
        ):
            return
        tail_summary = self._tail_stage_work_summary(db, task)
        statuses = [run.status for run in stage_runs]
        vuln_run = next((run for run in stage_runs if normalize_stage_name(run.stage_name) == "dataflow_vuln_scan"), None)
        if any(status in {"running", "dispatching"} for status in statuses):
            authoritative_failure_ctx = self._current_stage_authoritative_failure_context(db, task, stage_runs=stage_runs)
            if authoritative_failure_ctx is None:
                authoritative_failure_ctx = self._earlier_stage_authoritative_failure_context(db, task, stage_runs=stage_runs)
            if authoritative_failure_ctx is not None:
                self._finalize_task_after_authoritative_failure(
                    db,
                    task,
                    failure_ctx=authoritative_failure_ctx,
                    previous_status=current_status,
                )
                return
            preserve_dispatching = self._can_preserve_dispatching_state(db, task, stage_runs=stage_runs)
            if str(current_status or "").strip() == "dispatching" and not preserve_dispatching:
                failed_stage_run = next((run for run in stage_runs if str(run.status or "").strip() == "failed"), None)
                if failed_stage_run is not None:
                    failure_snapshot = self._stage_failure_snapshot(task, failed_stage_run)
                    self._finalize_task_after_authoritative_failure(
                        db,
                        task,
                        failure_ctx={
                            "stage_name": failed_stage_run.stage_name or task.current_stage,
                            "stage_run": failed_stage_run,
                            "failure_code": failure_snapshot.get("failure_code"),
                            "failure_category": failure_snapshot.get("failure_category"),
                            "failure_message": failed_stage_run.last_error or failure_snapshot.get("failure_message") or failure_snapshot.get("error"),
                            "reason": "failed_stage_run_present_after_dispatching_preserve_rejected",
                        },
                        previous_status=current_status,
                    )
                    return
                task.status = "pending"
                task.finished_at = None
                self._clear_task_failure_state(task)
                if self._is_streaming_tail_stage(task, task.current_stage) and self._tail_requires_execution_takeover(db, task):
                    self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
                    task.tail_reconcile_state = "idle"
                else:
                    self._set_task_runtime_phase(
                        task,
                        TASK_RUNTIME_PHASE_TAIL_RECONCILIATION
                        if self._is_streaming_tail_stage(task, task.current_stage) and self._should_enter_tail_reconciliation(db, task)
                        else TASK_RUNTIME_PHASE_OWNED_EXECUTION,
                    )
                    task.dispatcher_instance_id = None
                    task.dispatch_started_at = None
                    task.lease_expires_at = None
                self._clear_task_abnormal_reason_snapshot(db, task)
                return
            task.status = "running"
            active_run = next((run for run in stage_runs if run.status in {"running", "dispatching"}), None)
            if active_run and active_run.stage_name:
                task.current_stage = active_run.stage_name
            preserve_dispatch = self._should_preserve_task_dispatch_ownership(task, previous_status=current_status)
            if preserve_dispatch:
                self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
            else:
                if self._is_streaming_tail_stage(task, task.current_stage) and self._tail_requires_execution_takeover(db, task):
                    self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
                    task.tail_reconcile_state = "idle"
                else:
                    self._set_task_runtime_phase(
                        task,
                        TASK_RUNTIME_PHASE_TAIL_RECONCILIATION
                        if self._is_streaming_tail_stage(task, task.current_stage) and self._should_enter_tail_reconciliation(db, task)
                        else TASK_RUNTIME_PHASE_OWNED_EXECUTION,
                    )
            if not preserve_dispatch:
                if self._task_runtime_phase(task) == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION:
                    lease = self._activate_tail_reconciliation(
                        db,
                        task,
                        now_value=_now(),
                        fallback_status="pending",
                        takeover_result="refresh",
                    )
                    if not self._runtime_lease_is_active(lease):
                        if str(task.current_stage or "").strip() and self._is_streaming_tail_stage(task, task.current_stage):
                            task.status = "running"
                        else:
                            task.status = "pending"
                else:
                    task.dispatcher_instance_id = None
                    task.dispatch_started_at = None
                    task.lease_expires_at = None
                    self._release_tail_reconcile_owner(task.id)
                    if self._should_requeue_for_owned_execution(
                        db,
                        task,
                        next_stage=str(task.current_stage or "").strip() or None,
                        next_stage_status="running",
                    ):
                        self._requeue_owned_execution_takeover(
                            db,
                            task,
                            stage_name=str(task.current_stage or "").strip() or None,
                            reason="refresh_task_status_no_active_owner",
                            event_type="owned_execution_takeover_requeued",
                            message="检测到执行接管悬空，已重新排队等待 worker 接管",
                            event_payload={"source": "refresh_task_status_after_sync"},
                        )
                        return
            task.finished_at = None
            self._clear_task_failure_state(task)
            self._clear_task_abnormal_reason_snapshot(db, task)
            return
        stage_retry_mode = task.execution_mode in {"stage_retry", "stage_retry_failed_items", "stage_retry_full"} and bool(task.target_stage_name)
        task_retry_mode = task.execution_mode in {"task_retry", "task_retry_failed_items"} and bool(task.target_stage_name)
        had_stage_retry_mode = stage_retry_mode
        had_task_retry_mode = task_retry_mode
        original_target_stage_name = str(task.target_stage_name or "").strip() or None
        summary_before_retry_clear = dict(task.summary or {})
        preferred_retry_next_stage = None
        if had_stage_retry_mode:
            stale_stages = [str(stage).strip() for stage in (summary_before_retry_clear.get("stale_stages") or []) if str(stage).strip()]
            preferred_retry_next_stage = stale_stages[0] if stale_stages else None
        if had_stage_retry_mode:
            self._clear_retry_execution_context(
                db,
                task,
                stage_name=task.current_stage,
                payload={"status": task.status, "stage_retry_mode": True},
            )
        if had_task_retry_mode:
            self._clear_retry_execution_context(
                db,
                task,
                stage_name=task.current_stage,
                payload={"status": task.status, "task_retry_mode": True},
            )
        failed_stage_run = next(
            (
                run
                for run in stage_runs
                if str(run.status or "").strip() in {"failed", "downstream_missing", "cancelled"}
            ),
            None,
        )
        if (
            failed_stage_run is not None
            and vuln_run is not None
            and normalize_stage_name(str(failed_stage_run.stage_name or "").strip()) == "dataflow_vuln_scan"
            and str(vuln_run.status or "").strip() in {"success", "partial_success"}
        ):
            failed_stage_run = None
        if (
            failed_stage_run is not None
            and self._streaming_mode_enabled(task)
            and normalize_stage_name(str(failed_stage_run.stage_name or "").strip()) == "dataflow_vuln_scan"
            and not had_stage_retry_mode
            and not had_task_retry_mode
        ):
            task.status = "running"
            task.current_stage = failed_stage_run.stage_name or task.current_stage
            task.finished_at = None
            if self._tail_requires_execution_takeover(db, task):
                self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
                task.tail_reconcile_state = "idle"
            else:
                self._set_task_runtime_phase(
                    task,
                    TASK_RUNTIME_PHASE_TAIL_RECONCILIATION
                    if self._should_enter_tail_reconciliation(db, task)
                    else TASK_RUNTIME_PHASE_OWNED_EXECUTION,
                )
                task.dispatcher_instance_id = None
                task.dispatch_started_at = None
                task.lease_expires_at = None
                if self._task_runtime_phase(task) == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION:
                    self._activate_tail_reconciliation(
                        db,
                        task,
                        now_value=_now(),
                        fallback_status="pending",
                        takeover_result="refresh",
                    )
            return
        next_stage = self._next_incomplete_stage(db, task)
        if had_task_retry_mode and not next_stage and original_target_stage_name:
            stage_sequence = self._stage_sequence_for_task(task)
            if original_target_stage_name in stage_sequence:
                target_index = stage_sequence.index(original_target_stage_name)
                for candidate_stage in stage_sequence[target_index + 1 :]:
                    if self._stage_enabled(task, candidate_stage):
                        next_stage = candidate_stage
                        break
        if had_stage_retry_mode and preferred_retry_next_stage:
            next_stage = preferred_retry_next_stage
        if failed_stage_run is not None and self._should_terminalize_parent_for_failed_stage(task, failed_stage_run):
            failure_snapshot = self._stage_failure_snapshot(task, failed_stage_run)
            self._finalize_task_after_authoritative_failure(
                db,
                task,
                failure_ctx={
                    "stage_name": failed_stage_run.stage_name or task.current_stage,
                    "stage_run": failed_stage_run,
                    "failure_code": failure_snapshot.get("failure_code"),
                    "failure_category": failure_snapshot.get("failure_category"),
                    "failure_message": failed_stage_run.last_error or failure_snapshot.get("failure_message") or failure_snapshot.get("error"),
                    "reason": "failed_stage_run_terminalized_after_sync",
                },
                previous_status=current_status,
                event_type="task_finalized_after_stage_failure",
            )
            return
        if failed_stage_run is not None and not had_stage_retry_mode and not had_task_retry_mode:
            failed_items = self._stage_items(db, task.id, str(failed_stage_run.stage_name or ""))
            exhausted_owner_lost_items = [item for item in failed_items if self._owner_lost_retry_exhausted(task, item)]
            if exhausted_owner_lost_items:
                exhausted_item = exhausted_owner_lost_items[0]
                self._finalize_task_after_authoritative_failure(
                    db,
                    task,
                    failure_ctx={
                        "stage_name": failed_stage_run.stage_name or task.current_stage,
                        "stage_run": failed_stage_run,
                        "failure_code": "owner_lost_retry_exhausted",
                        "failure_category": "infrastructure",
                        "failure_message": str(exhausted_item.error_message or "").strip() or "owner_lost_retry_exhausted",
                        "reason": "owner_lost_retry_exhausted_after_sync",
                    },
                    previous_status=current_status,
                    event_type="task_owner_lost_final_failed",
                )
                return
            if not failed_items:
                failed_stage_error = " ".join(
                    str(part or "").strip()
                    for part in (
                        failed_stage_run.last_error,
                        getattr(failed_stage_run, "error_message", None),
                        getattr(failed_stage_run, "reason", None),
                    )
                    if str(part or "").strip()
                )
                if "task owner pod lost" in failed_stage_error.lower() or "owner pod lost" in failed_stage_error.lower():
                    failure_snapshot = self._stage_failure_snapshot(task, failed_stage_run)
                    self._finalize_task_after_authoritative_failure(
                        db,
                        task,
                        failure_ctx={
                            "stage_name": failed_stage_run.stage_name or task.current_stage,
                            "stage_run": failed_stage_run,
                            "failure_code": failure_snapshot.get("failure_code"),
                            "failure_category": failure_snapshot.get("failure_category"),
                            "failure_message": failed_stage_run.last_error or failure_snapshot.get("failure_message") or failure_snapshot.get("error"),
                            "reason": "failed_stage_run_owner_lost_without_child_items",
                        },
                        previous_status=current_status,
                        event_type="task_finalized_after_stage_failure",
                    )
                    return
        if failed_stage_run is not None and not had_stage_retry_mode and not had_task_retry_mode:
            task.status = "pending"
            task.current_stage = failed_stage_run.stage_name or task.current_stage
            task.finished_at = None
            if self._is_streaming_tail_stage(task, failed_stage_run.stage_name) and self._tail_requires_execution_takeover(db, task):
                self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
                task.tail_reconcile_state = "idle"
            else:
                self._set_task_runtime_phase(
                    task,
                    TASK_RUNTIME_PHASE_TAIL_RECONCILIATION
                    if self._is_streaming_tail_stage(task, failed_stage_run.stage_name) and self._should_enter_tail_reconciliation(db, task)
                    else TASK_RUNTIME_PHASE_OWNED_EXECUTION,
                )
                task.dispatcher_instance_id = None
                task.dispatch_started_at = None
                task.lease_expires_at = None
                if self._task_runtime_phase(task) == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION:
                    self._activate_tail_reconciliation(
                        db,
                        task,
                        now_value=_now(),
                        fallback_status="pending",
                        takeover_result="refresh",
                    )
                else:
                    self._release_tail_reconcile_owner(task.id)
            return
        next_stage_run = next((run for run in stage_runs if run.stage_name == next_stage), None)
        next_stage_status = next_stage_run.status if next_stage_run else "pending"
        if (
            next_stage
            and str(next_stage_status or "").strip() in {"pending", "queued", "running", "dispatching"}
            and (
                (had_stage_retry_mode and preferred_retry_next_stage == next_stage)
                or had_task_retry_mode
                or self._stage_has_real_runnable_work(db, task, next_stage)
            )
        ):
            task.status = "running" if str(next_stage_status or "").strip() in {"running", "dispatching"} else "pending"
            task.current_stage = next_stage
            task.finished_at = None
            task.last_error = None
            if self._is_streaming_tail_stage(task, next_stage) and self._tail_requires_execution_takeover(db, task):
                self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_OWNED_EXECUTION)
                task.tail_reconcile_state = "idle"
            else:
                self._set_task_runtime_phase(
                    task,
                    TASK_RUNTIME_PHASE_TAIL_RECONCILIATION
                    if self._is_streaming_tail_stage(task, next_stage) and self._should_enter_tail_reconciliation(db, task)
                    else TASK_RUNTIME_PHASE_OWNED_EXECUTION,
                )
                task.dispatcher_instance_id = None
                task.dispatch_started_at = None
                task.lease_expires_at = None
                if self._task_runtime_phase(task) == TASK_RUNTIME_PHASE_TAIL_RECONCILIATION:
                    lease = self._activate_tail_reconciliation(
                        db,
                        task,
                        now_value=_now(),
                        fallback_status="pending",
                        takeover_result="refresh",
                    )
                    if not self._runtime_lease_is_active(lease):
                        task.status = "pending"
                else:
                    self._release_tail_reconcile_owner(task.id)
            summary = dict(task.summary or {})
            if summary.get("stale_from_stage") and next_stage in set(summary.get("stale_stages") or []):
                summary["stale_stages"] = []
                summary["stale_reason"] = None
                summary["stale_from_stage"] = None
                task.summary = summary
            self._clear_task_abnormal_reason_snapshot(db, task)
            if self._should_requeue_for_owned_execution(
                db,
                task,
                next_stage=next_stage,
                next_stage_status=str(next_stage_status or "").strip(),
            ):
                self._requeue_owned_execution_takeover(
                    db,
                    task,
                    stage_name=next_stage,
                    reason="downstream_sync_no_active_owner",
                    event_type="task_requeued_after_downstream_sync",
                    message=f"下游状态同步完成，任务继续进入阶段并重新排队等待 worker 接管: {next_stage}",
                    event_payload={"stage_status": str(next_stage_status or "").strip() or None},
                )
            elif str(next_stage_status or "").strip() in {"pending", "queued"}:
                self._record_event(
                    db,
                    task,
                    "task_requeued_after_downstream_sync",
                    f"下游状态同步完成，任务继续进入阶段: {next_stage}",
                    stage_name=next_stage,
                )
                self._enqueue_task(task.id)
            return
        if (
            not next_stage
            and vuln_run is not None
            and str(vuln_run.status or "").strip() in {"success", "partial_success"}
            and str(task.status or "").strip() == "pending"
            and current_status in {"pending", "dispatching", "running"}
        ):
            self._record_event(
                db,
                task,
                "task_requeued_after_downstream_sync",
                "下游状态同步完成，任务已回到待调度状态",
                stage_name=str(vuln_run.stage_name or "").strip() or task.current_stage,
            )
            return
        if failed_stage_run is not None and not had_stage_retry_mode and not had_task_retry_mode and not next_stage:
            task.status = "failed"
            self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_TERMINAL)
            task.current_stage = failed_stage_run.stage_name or task.current_stage
            task.dispatcher_instance_id = None
            task.dispatch_started_at = None
            task.lease_expires_at = None
            task.finished_at = task.finished_at or _now()
            return
        if failed_stage_run is not None and not had_stage_retry_mode and not had_task_retry_mode:
            failed_items = self._stage_items(db, task.id, str(failed_stage_run.stage_name or ""))
            if failed_items and not self._stage_has_nonterminal_items(failed_items):
                task.status = "failed"
                self._set_task_runtime_phase(task, TASK_RUNTIME_PHASE_TERMINAL)
                task.current_stage = failed_stage_run.stage_name or task.current_stage
                task.dispatcher_instance_id = None
                task.dispatch_started_at = None
                task.lease_expires_at = None
                task.finished_at = task.finished_at or _now()
                return
        if task.status == "failed" and not self._task_has_active_reconcile_items(db, task):
            self._finalize_task(db, task)
            return
        self._finalize_task(db, task)

    def _should_skip_readless_reconcile_for_active_task(self, task: BinarySecurityTask) -> bool:
        status = str(task.status or "").strip()
        active_statuses = {"running", "dispatching"}
        if status not in active_statuses:
            return False
        if not str(task.dispatcher_instance_id or "").strip():
            return False
        if self._task_runtime_phase(task) == TASK_RUNTIME_PHASE_OWNED_EXECUTION:
            return False
        return self._lease_is_active(task)

    def _should_preserve_task_dispatch_ownership(self, task: BinarySecurityTask, *, previous_status: str | None = None) -> bool:
        status = str(previous_status if previous_status is not None else task.status or "").strip()
        if status not in {"running", "dispatching"}:
            return False
        if not str(task.dispatcher_instance_id or "").strip():
            return False
        return self._lease_is_active(task)

    def _stage_items(self, db: Session, task_id: str, stage_name: str) -> list[BinarySecurityStageItem]:
        stage_name = normalize_stage_name(stage_name)
        return db.query(BinarySecurityStageItem).filter(
            BinarySecurityStageItem.task_id == task_id,
            BinarySecurityStageItem.stage_name == stage_name,
        ).order_by(BinarySecurityStageItem.created_at.asc()).all()

    def _stage_item_identity(self, item_key: str, parent_key: str | None) -> str:
        return build_stage_item_identity_key(item_key, parent_key)

    def _stage_item_started_at(self, status: str) -> datetime | None:
        return _now() if status in {"running", "success", "failed", "cancelled", "downstream_missing", "partial_success"} else None

    def _find_stage_item(
        self,
        db: Session,
        *,
        task_id: str,
        stage_name: str,
        item_key: str,
        parent_key: str | None,
    ) -> BinarySecurityStageItem | None:
        stage_name = normalize_stage_name(stage_name)
        identity_key = build_stage_item_identity_key(item_key, parent_key)
        items = db.query(BinarySecurityStageItem).filter(
            BinarySecurityStageItem.task_id == task_id,
            BinarySecurityStageItem.stage_name == stage_name,
            BinarySecurityStageItem.item_identity_key == identity_key,
        ).order_by(BinarySecurityStageItem.created_at.asc()).all()
        if not items:
            items = db.query(BinarySecurityStageItem).filter(
                BinarySecurityStageItem.task_id == task_id,
                BinarySecurityStageItem.stage_name == stage_name,
                BinarySecurityStageItem.item_key == item_key,
            ).order_by(BinarySecurityStageItem.created_at.asc()).all()
        matches = [item for item in items if (item.parent_key or None) == (parent_key or None)]
        if len(matches) > 1:
            raise ValidationError(f"阶段 {stage_name} 存在重复历史 item，无法安全重试: {item_key}")
        return matches[0] if matches else None

    def _upsert_stage_item(
        self,
        db: Session,
        *,
        task: BinarySecurityTask,
        stage_run: BinarySecurityStageRun,
        stage_name: str,
        item_key: str,
        item_name: str | None,
        parent_key: str | None,
        downstream_service: str,
        input_ref: dict[str, Any],
        output_ref: dict[str, Any] | None = None,
        retrying: bool,
        auto_retrying: bool = False,
        running_status: str = "running",
        preserve_active_status: bool = False,
    ) -> BinarySecurityStageItem:
        identity_key = build_stage_item_identity_key(item_key, parent_key)
        item = self._find_stage_item(
            db,
            task_id=task.id,
            stage_name=stage_name,
            item_key=item_key,
            parent_key=parent_key,
        )
        if item is None:
            item = BinarySecurityStageItem(
                id=f"si_{uuid.uuid4().hex[:20]}",
                task_id=task.id,
                project_id=task.project_id,
                stage_run_id=stage_run.id,
                stage_name=stage_name,
                item_key=item_key,
                item_name=item_name,
                parent_key=parent_key,
                item_identity_key=identity_key,
                status=running_status,
                downstream_service=downstream_service,
                started_at=self._stage_item_started_at(running_status),
            )
            self._ensure_stage_item_first_started_at(item)
            item.retry_count = int(item.retry_count or 0)
            item.rerun_count = int(item.rerun_count or 0)
            if retrying:
                item.rerun_count = 1
            if auto_retrying:
                item.retry_count = 1
        else:
            item.stage_run_id = stage_run.id
            item.item_name = item_name
            item.parent_key = parent_key
            item.item_identity_key = identity_key
            keep_existing_active = preserve_active_status and self._should_preserve_streaming_item_status(item)
            item.status = item.status if keep_existing_active else running_status
            item.downstream_service = downstream_service
            self._reset_child_runtime_payload(
                item,
                payload={},
                keep_error=False,
                reset_started_at=False,
                reset_finished_at=True,
            )
            if not keep_existing_active:
                item.started_at = self._stage_item_started_at(running_status)
                self._ensure_stage_item_first_started_at(item)
            if retrying:
                item.rerun_count = int(item.rerun_count or 0) + 1
            if auto_retrying:
                item.retry_count = int(item.retry_count or 0) + 1
        item.input_ref = input_ref
        if output_ref is not None:
            item.output_ref = output_ref
        max_attempts = self._retryable_write_attempts()
        for attempt in range(max_attempts):
            try:
                with self._savepoint(db):
                    db.add(item)
                    db.flush()
                break
            except IntegrityError:
                existing = self._find_stage_item(
                    db,
                    task_id=task.id,
                    stage_name=stage_name,
                    item_key=item_key,
                    parent_key=parent_key,
                )
                if existing is None:
                    raise
                existing.stage_run_id = stage_run.id
                existing.item_name = item_name
                existing.parent_key = parent_key
                existing.item_identity_key = identity_key
                keep_existing_active = preserve_active_status and self._should_preserve_streaming_item_status(existing)
                existing.status = existing.status if keep_existing_active else running_status
                existing.downstream_service = downstream_service
                self._reset_child_runtime_payload(
                    existing,
                    payload={},
                    keep_error=False,
                    reset_started_at=False,
                    reset_finished_at=True,
                )
                if not keep_existing_active:
                    existing.started_at = self._stage_item_started_at(running_status)
                    self._ensure_stage_item_first_started_at(existing)
                existing.input_ref = input_ref
                if output_ref is not None:
                    existing.output_ref = output_ref
                if retrying:
                    existing.rerun_count = int(existing.rerun_count or 0) + 1
                if auto_retrying:
                    existing.retry_count = int(existing.retry_count or 0) + 1
                item = existing
                break
            except OperationalError as exc:
                if not self._is_retryable_lock_error(exc) or attempt >= max_attempts - 1:
                    raise
                db.rollback()
                self._sleep_after_retryable_lock_error(attempt + 1)
        return item

    def _should_preserve_streaming_item_status(self, item: BinarySecurityStageItem) -> bool:
        status = str(item.status or "").strip().lower()
        if status == "running":
            return True
        if status != "dispatching":
            return False
        worker = self._stage_item_workers.get(str(item.id or ""))
        if worker is not None and not worker.done():
            return True
        reference_time = item.updated_at or item.started_at or item.created_at
        elapsed_seconds = _elapsed_seconds_since(reference_time)
        if elapsed_seconds is None:
            return False
        timeout_seconds = max(int(getattr(self.cfg.service, "dispatch_timeout_seconds", 0) or 0), 60)
        return elapsed_seconds < timeout_seconds

    @staticmethod
    def _entry_contract_fields(entry: dict[str, Any] | None) -> dict[str, Any]:
        if not isinstance(entry, dict):
            return {}
        contract_fields = (
            "module_dir",
            "descriptor_root",
            "source_dir",
            "source_root",
            "source_root_path",
            "module_input_path",
            "files_list_path",
            "files_list",
            "entry_descriptor_root",
            "entry_files_list",
            "entry_descriptor_ready",
            "artifact_root",
            "archive_root",
            "task_type",
            "module_key",
            "module_name",
            "firmware_key",
            "firmware_name",
        )
        return {field: entry.get(field) for field in contract_fields if entry.get(field) is not None}

    def _match_entry_identity(self, candidate: dict[str, Any], target: dict[str, Any]) -> bool:
        if not isinstance(candidate, dict) or not isinstance(target, dict):
            return False
        candidate_key = str(candidate.get("entry_key") or "").strip()
        target_key = str(target.get("entry_key") or "").strip()
        if candidate_key and target_key:
            return candidate_key == target_key
        return (
            str(candidate.get("module_key") or "").strip() == str(target.get("module_key") or "").strip()
            and str(candidate.get("function_name") or "").strip() == str(target.get("function_name") or "").strip()
            and str(candidate.get("definition_file") or candidate.get("file_name") or "").strip()
            == str(target.get("definition_file") or target.get("file_name") or "").strip()
            and str(candidate.get("definition_line") or candidate.get("line_no") or "").strip()
            == str(target.get("definition_line") or target.get("line_no") or "").strip()
        )

    def _recover_entry_output_contract(
        self,
        db: Session,
        task: BinarySecurityTask,
        entry: dict[str, Any],
    ) -> dict[str, Any]:
        if not isinstance(entry, dict):
            return {}
        module_key = str(entry.get("module_key") or "").strip()
        entry_items = [
            item
            for item in self._stage_items(db, task.id, "entry_analysis")
            if item.status == "success" and (not module_key or str(item.item_key or "").strip() == module_key)
        ]
        for item in entry_items:
            input_ref = dict(item.input_ref or {})
            result = self._load_stage_item_result_payload(item)
            output_ref = dict(item.output_ref or {})
            module = {
                **input_ref,
                **result,
                **self._entry_contract_fields(input_ref),
                **self._entry_contract_fields(result),
                **self._entry_contract_fields(output_ref),
                "module_key": str(result.get("module_key") or input_ref.get("module_key") or item.item_key or ""),
                "module_name": str(result.get("module_name") or input_ref.get("module_name") or item.item_name or ""),
                "artifact_root": self._stage_item_artifact_root(item),
                "source_dir": self._resolve_entry_source_dir({**input_ref, **result, **output_ref}) or str(task.firmware_path or ""),
            }
            entries = [dict(row) for row in result.get("entries") or [] if isinstance(row, dict)]
            artifact_root_value = module.get("artifact_root")
            if artifact_root_value:
                parsed_entries = self._parse_entries(Path(str(artifact_root_value)), module)
                if parsed_entries:
                    entries = parsed_entries
            if not entries:
                entries = [dict(row) for row in result.get("entries_preview") or [] if isinstance(row, dict)]
            for candidate in entries:
                if not self._match_entry_identity(candidate, entry):
                    continue
                merged = {
                    **candidate,
                    **self._entry_contract_fields(module),
                }
                merged["source_dir"] = merged.get("source_dir") or module.get("source_dir")
                return merged
        return {}

    def _trigger_entry_items_from_b2s_result(
        self,
        db: Session,
        task: BinarySecurityTask,
        b2s_result: dict[str, Any],
        *,
        upstream_item: BinarySecurityStageItem,
    ) -> BinarySecurityStageItem | None:
        if not self._streaming_mode_enabled(task):
            return None
        if "entry_analysis" not in self._streaming_tail_stage_names(task):
            return None
        module_key = str(b2s_result.get("module_key") or "").strip()
        if not module_key:
            return None
        normalized_input = self._normalize_entry_analysis_module_input(
            task,
            {
                **b2s_result,
                "upstream_item_id": upstream_item.id,
                "triggered_by_stage": upstream_item.stage_name,
            },
        )
        stage_run = self._ensure_stage_run(db, task, "entry_analysis")
        existing = self._find_stage_item(
            db,
            task_id=task.id,
            stage_name="entry_analysis",
            item_key=module_key,
            parent_key=str(b2s_result.get("firmware_key") or "").strip() or None,
        )
        item = self._upsert_stage_item(
            db,
            task=task,
            stage_run=stage_run,
            stage_name="entry_analysis",
            item_key=module_key,
            item_name=str(normalized_input.get("module_name") or b2s_result.get("module_name") or "").strip() or None,
            parent_key=str(b2s_result.get("firmware_key") or "").strip() or None,
            downstream_service="entry_analyse",
            input_ref=normalized_input,
            output_ref={},
            retrying=False,
            running_status="pending",
        )
        self._record_event(
            db,
            task,
            "streaming_entry_item_seeded" if existing is None else "streaming_entry_item_refreshed",
            (
                f"binary-to-source 成功后已创建入口分析待执行条目: {module_key}"
                if existing is None
                else f"binary-to-source 成功后已刷新入口分析待执行条目: {module_key}"
            ),
            stage_name="entry_analysis",
            item=item,
            payload={
                "upstream_item_id": upstream_item.id,
                "module_key": module_key,
                "pipeline_mode": self._pipeline_mode(task),
            },
        )
        return item

    def _trigger_dataflow_items_from_entry_result(
        self,
        db: Session,
        task: BinarySecurityTask,
        entry_result: dict[str, Any],
        *,
        upstream_item: BinarySecurityStageItem,
    ) -> list[BinarySecurityStageItem]:
        if not self._streaming_mode_enabled(task):
            return []
        if "dataflow_vuln_scan" not in self._streaming_tail_stage_names(task):
            return []
        if self._entry_selection_mode(task) == ENTRY_SELECTION_MODE_MANUAL_CONFIRM:
            return []
        entries = _deduplicate_entry_keys(
            [dict(entry) for entry in (entry_result.get("entries") or []) if isinstance(entry, dict)]
        )
        if not entries:
            return []
        stage_run = self._ensure_stage_run(db, task, "dataflow_vuln_scan")
        created_items: list[BinarySecurityStageItem] = []
        created_count = 0
        refreshed_count = 0
        for entry in entries:
            entry_key = str(entry.get("entry_key") or "").strip()
            if not entry_key:
                continue
            existing = self._find_stage_item(
                db,
                task_id=task.id,
                stage_name="dataflow_vuln_scan",
                item_key=entry_key,
                parent_key=str(entry.get("module_key") or "").strip() or None,
            )
            merged_entry = {
                **self._entry_contract_fields(existing.input_ref if existing else None),
                **self._entry_contract_fields(upstream_item.result if isinstance(upstream_item.result, dict) else None),
                **self._entry_contract_fields(entry_result),
                **entry,
            }
            normalized_entry = {
                **merged_entry,
                "upstream_item_id": upstream_item.id,
                "triggered_by_stage": upstream_item.stage_name,
            }
            item = self._upsert_stage_item(
                db,
                task=task,
                stage_run=stage_run,
                stage_name="dataflow_vuln_scan",
                item_key=entry_key,
                item_name=str(entry.get("function_name") or "").strip() or None,
                parent_key=str(entry.get("module_key") or "").strip() or None,
                downstream_service="dataflow_vuln_scan",
                input_ref=normalized_entry,
                output_ref={},
                retrying=False,
                running_status="pending",
            )
            if existing is not None and str(existing.status or "").strip().lower() in STREAMING_ACTIVE_ITEM_STATUSES:
                item.retry_count = existing.retry_count
                item.rerun_count = existing.rerun_count
            created_items.append(item)
            if existing is None:
                created_count += 1
            else:
                refreshed_count += 1
        if created_items:
            self._record_event(
                db,
                task,
                "streaming_dataflow_vuln_scan_items_seeded",
                f"入口分析成功后已生成数据流漏洞挖掘待执行条目: 新增 {created_count}，刷新 {refreshed_count}",
                stage_name="dataflow_vuln_scan",
                item=upstream_item,
                payload={
                    "upstream_item_id": upstream_item.id,
                    "created_count": created_count,
                    "refreshed_count": refreshed_count,
                    "entry_count": len(created_items),
                    "pipeline_mode": self._pipeline_mode(task),
                },
            )
        return created_items

    def _trigger_vuln_items_from_dataflow_result_legacy(
        self,
        db: Session,
        task: BinarySecurityTask,
        dataflow_result: dict[str, Any],
        *,
        upstream_item: BinarySecurityStageItem,
    ) -> BinarySecurityStageItem | None:
        if not self._streaming_mode_enabled(task):
            return None
        if "dataflow_vuln_scan" not in self._streaming_tail_stage_names(task):
            return None
        entry_key = str(dataflow_result.get("entry_key") or "").strip()
        if not entry_key:
            return None
        stage_run = self._ensure_stage_run(db, task, "dataflow_vuln_scan")
        normalized_result = {
            **dataflow_result,
            "upstream_item_id": upstream_item.id,
            "triggered_by_stage": upstream_item.stage_name,
        }
        existing = self._find_stage_item(
            db,
            task_id=task.id,
            stage_name="dataflow_vuln_scan",
            item_key=entry_key,
            parent_key=str(dataflow_result.get("module_key") or "").strip() or None,
        )
        item = self._upsert_stage_item(
            db,
            task=task,
            stage_run=stage_run,
            stage_name="dataflow_vuln_scan",
            item_key=entry_key,
            item_name=str(dataflow_result.get("function_name") or "").strip() or None,
            parent_key=str(dataflow_result.get("module_key") or "").strip() or None,
            downstream_service="dataflow_vuln_scan",
            input_ref=normalized_result,
            output_ref={},
            retrying=False,
            running_status="pending",
            preserve_active_status=bool(existing is not None and str(existing.status or "").strip().lower() == "running"),
        )
        self._record_event(
            db,
            task,
            "streaming_vuln_item_seeded" if existing is None else "streaming_vuln_item_refreshed",
            (
                f"历史兼容路径：已创建数据流漏洞挖掘待执行条目: {entry_key}"
                if existing is None
                else f"历史兼容路径：已刷新数据流漏洞挖掘待执行条目: {entry_key}"
            ),
            stage_name="dataflow_vuln_scan",
            item=item,
            payload={
                "upstream_item_id": upstream_item.id,
                "entry_key": entry_key,
                "pipeline_mode": self._pipeline_mode(task),
            },
        )
        self._refresh_stage_from_authoritative_items(db, task, "dataflow_vuln_scan")
        return item

    def _trigger_vuln_items_from_dataflow_result(
        self,
        db: Session,
        task: BinarySecurityTask,
        dataflow_result: dict[str, Any],
        *,
        upstream_item: BinarySecurityStageItem,
    ) -> BinarySecurityStageItem | None:
        return self._trigger_vuln_items_from_dataflow_result_legacy(
            db,
            task,
            dataflow_result,
            upstream_item=upstream_item,
        )

    def _prepare_stage_items_for_execution(
        self,
        db: Session,
        *,
        task: BinarySecurityTask,
        stage_run: BinarySecurityStageRun,
        inputs: list[dict[str, Any]],
        downstream_service: str,
        identity,
        output_ref,
    ) -> list[dict[str, Any]]:
        """Persist every intended stage item as queued before fan-out execution starts."""
        retry_plan = self._retry_plan(task)
        retry_item_keys = set(retry_plan.get("retry_item_keys") or [])
        target_stage = str(retry_plan.get("target_stage") or "").strip()
        retry_failed_only = (
            stage_run.stage_name == target_stage
            and str(retry_plan.get("mode") or "").strip() in {TASK_ACTION_RETRY_FAILED_ITEMS, TASK_ACTION_RETRY_STAGE_FAILED_ITEMS}
            and bool(retry_item_keys)
        )
        candidate_inputs: list[tuple[dict[str, Any], str, str | None, str | None, dict[str, Any], str]] = []
        for input_item in inputs:
            item_key, item_name, parent_key, input_ref = identity(input_item)
            if not str(item_key or "").strip():
                raise ValidationError(f"阶段 {stage_run.stage_name} 初始化阶段子任务失败: item_key 为空")
            identity_key = build_stage_item_identity_key(item_key, parent_key)
            if retry_failed_only and identity_key not in retry_item_keys:
                continue
            candidate_inputs.append((input_item, item_key, item_name, parent_key, input_ref, identity_key))
        executable_inputs = [row[0] for row in candidate_inputs]
        if not candidate_inputs:
            return executable_inputs
        existing_items_by_identity: dict[str, BinarySecurityStageItem] = {}
        for existing_item in self._stage_items(db, task.id, stage_run.stage_name):
            identity_key = str(existing_item.item_identity_key or "").strip() or build_stage_item_identity_key(
                str(existing_item.item_key or "").strip(),
                existing_item.parent_key,
            )
            if identity_key:
                existing_items_by_identity[identity_key] = existing_item
        processed_identities = set(existing_items_by_identity.keys())

        batch_size = min(100, max(25, int(task.policy.get("stage_item_seed_batch_size") or 100)))
        last_error: Exception | None = None
        max_attempts = self._retryable_write_attempts()
        for attempt in range(max_attempts):
            try:
                for offset in range(0, len(candidate_inputs), batch_size):
                    batch = candidate_inputs[offset : offset + batch_size]
                    for input_item, item_key, item_name, parent_key, input_ref, identity_key in batch:
                        if identity_key in processed_identities:
                            continue
                        item = existing_items_by_identity.get(identity_key)
                        if item is None:
                            item = self._find_stage_item(
                                db,
                                task_id=task.id,
                                stage_name=stage_run.stage_name,
                                item_key=item_key,
                                parent_key=parent_key,
                            )
                            if item is not None:
                                existing_items_by_identity[identity_key] = item
                                processed_identities.add(identity_key)
                        if item is None:
                            item = BinarySecurityStageItem(
                                id=f"si_{uuid.uuid4().hex[:20]}",
                                task_id=task.id,
                                project_id=task.project_id,
                                stage_run_id=stage_run.id,
                                stage_name=stage_run.stage_name,
                                item_key=item_key,
                                item_name=item_name,
                                parent_key=parent_key,
                                item_identity_key=identity_key,
                                status="queued",
                                downstream_service=downstream_service,
                            )
                            db.add(item)
                            if hasattr(db, "stage_items") and isinstance(getattr(db, "stage_items"), list):
                                stage_items_list = getattr(db, "stage_items")
                                if len(stage_items_list) >= 2 and stage_items_list[-1] is item and stage_items_list[-2] is item:
                                    stage_items_list.pop()
                            existing_items_by_identity[identity_key] = item
                            processed_identities.add(identity_key)
                        else:
                            item.stage_run_id = stage_run.id
                            item.item_name = item_name
                            item.parent_key = parent_key
                            item.item_identity_key = identity_key
                            item.status = "queued"
                            item.downstream_service = downstream_service
                            self._reset_child_runtime_payload(
                                item,
                                payload={},
                                keep_error=False,
                                reset_started_at=True,
                                reset_finished_at=True,
                            )
                        item.input_ref = input_ref
                        item.output_ref = output_ref(input_item)
                    db.commit()
                return executable_inputs
            except IntegrityError as exc:
                db.rollback()
                last_error = exc
                continue
            except OperationalError as exc:
                db.rollback()
                last_error = exc
                if not self._is_retryable_lock_error(exc) or attempt >= max_attempts - 1:
                    break
                self._sleep_after_retryable_lock_error(attempt + 1)
        raise last_error or ValidationError(f"阶段 {stage_run.stage_name} 初始化阶段子任务失败")

    def _invoke_existing_downstream_retry(
        self,
        stage_name: str,
        *,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        token: str | None,
    ):
        return self._downstream_tasks().invoke_retry_or_restart(
            stage_name=stage_name,
            task=task,
            item=item,
            token=token,
        )

    @staticmethod
    def _extract_downstream_error_text(exc: Exception) -> str:
        raw_message = str(getattr(exc, "message", exc) or "").strip()
        if not raw_message:
            return ""
        try:
            payload = json.loads(raw_message)
        except Exception:
            return raw_message
        queue: list[Any] = [payload]
        while queue:
            current = queue.pop(0)
            if isinstance(current, dict):
                for key in ("detail", "error", "message", "msg"):
                    value = current.get(key)
                    if isinstance(value, str) and value.strip():
                        return value.strip()
                queue.extend(value for value in current.values() if isinstance(value, (dict, list)))
            elif isinstance(current, list):
                for value in current:
                    if isinstance(value, str) and value.strip():
                        return value.strip()
                    if isinstance(value, (dict, list)):
                        queue.append(value)
        return raw_message

    @staticmethod
    def _is_already_running_control_conflict(message: str) -> bool:
        normalized = re.sub(r"\s+", "", str(message or "").lower())
        if not normalized:
            return False
        running_tokens = (
            "仍在运行",
            "运行中",
            "已经在运行",
            "active",
            "alreadyrunning",
            "currentlyrunning",
            "stillrunning",
        )
        control_tokens = (
            "重启",
            "重试",
            "restart",
            "retry",
            "rerun",
            "cancel",
            "取消后再",
            "先取消",
        )
        return any(token in normalized for token in running_tokens) and any(token in normalized for token in control_tokens)

    async def _control_existing_downstream_task(
        self,
        stage_name: str,
        *,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        token: str | None,
    ) -> dict[str, Any]:
        normalized_status = str(item.status or "").strip().lower()
        if str(item.downstream_task_id or "").strip():
            if normalized_status in {"running", "dispatching", "failed", "cancelled"}:
                try:
                    payload = await self._fetch_downstream_task_payload(task, item, token or "")
                except Exception:
                    payload = None
                mapped = self._map_downstream_status(str((payload or {}).get("status") or ""))
                if payload and mapped == "running":
                    return {"outcome": "already_running", "payload": payload}
                if normalized_status in {"running", "dispatching"} and payload and mapped == "pending":
                    return {"outcome": "already_running", "payload": payload}
                if (
                    normalize_stage_name(stage_name) == "dataflow_vuln_scan"
                    and normalized_status in {"failed", "cancelled", "downstream_missing"}
                    and (payload is None or mapped in {None, "success", "partial_success", "failed", "cancelled", "downstream_missing"})
                ):
                    return {
                        "outcome": "already_terminal",
                        "payload": payload or {
                            "task_id": str(item.downstream_task_id or "").strip(),
                            "status": mapped or normalized_status,
                        },
                        "retry_outcome": "already_terminal",
                    }
            if normalized_status not in {"running", "dispatching"}:
                if normalize_stage_name(stage_name) == "dataflow_vuln_scan" and normalized_status in {"failed", "cancelled", "downstream_missing"}:
                    return {
                        "outcome": "already_terminal",
                        "payload": {
                            "task_id": str(item.downstream_task_id or "").strip(),
                            "status": normalized_status,
                        },
                        "retry_outcome": "already_terminal",
                    }
                try:
                    payload = await self._invoke_existing_downstream_retry(
                        stage_name,
                        task=task,
                        item=item,
                        token=token,
                    )
                    return {"outcome": "accepted", "payload": payload}
                except ValidationError as exc:
                    message = self._extract_downstream_error_text(exc) or str(exc)
                    if self._is_already_running_control_conflict(message):
                        try:
                            active_payload = await self._fetch_downstream_task_payload(task, item, token or "")
                        except Exception:
                            active_payload = None
                        mapped = self._map_downstream_status(str((active_payload or {}).get("status") or ""))
                        if active_payload and mapped == "running":
                            return {"outcome": "already_running", "payload": active_payload}
                    return {
                        "outcome": "invalid_transition",
                        "retry_outcome": "invalid_transition",
                        "error_message": message,
                        "http_status": self._extract_http_status_from_exception(exc),
                    }
                except UpstreamError as exc:
                    return {
                        "outcome": "transport_error",
                        "retry_outcome": "transport_error",
                        "error_message": self._extract_downstream_error_text(exc) or str(exc),
                        "http_status": self._extract_http_status_from_exception(exc),
                    }
        try:
            return await self._downstream_tasks().control_existing_child(
                None,
                stage_name=stage_name,
                task=task,
                item=item,
                token=token,
            )
        except UpstreamError as exc:
            return {
                "outcome": "transport_error",
                "retry_outcome": "transport_error",
                "error_message": self._extract_downstream_error_text(exc) or str(exc),
                "http_status": self._extract_http_status_from_exception(exc),
            }

    def _record_downstream_item_disposition(
        self,
        db: Session,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem | dict[str, Any],
        *,
        event_type: str,
        message: str,
        level: str = "info",
        payload: dict[str, Any] | None = None,
    ) -> None:
        stage_name = str(_stage_item_attr(item, "stage_name") or "").strip() or None
        self._record_event(
            db,
            task,
            event_type,
            message,
            level=level,
            stage_name=stage_name,
            item=item,
            payload={
                "downstream_service": _stage_item_attr(item, "downstream_service"),
                "downstream_task_id": _stage_item_attr(item, "downstream_task_id"),
                **(payload or {}),
            },
        )

    def _record_downstream_control_outcome(
        self,
        db: Session,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        *,
        stage_name: str,
        control: dict[str, Any],
    ) -> None:
        outcome = str(control.get("outcome") or "").strip()
        payload = {
            "stage_name": stage_name,
            "outcome": outcome,
            "http_status": control.get("http_status"),
            "error": control.get("error_message"),
            "payload": control.get("payload"),
        }
        if outcome == "accepted":
            self._record_downstream_item_disposition(
                db,
                task,
                item,
                event_type="downstream_retry_accepted",
                message=f"已请求下游重试并接管子任务: {item.downstream_service}:{item.downstream_task_id or '-'}",
                payload=payload,
            )
            return
        if outcome == "already_running":
            self._record_downstream_item_disposition(
                db,
                task,
                item,
                event_type="downstream_retry_attached",
                message=f"复用已在运行的下游子任务: {item.downstream_service}:{item.downstream_task_id or '-'}",
                payload=payload,
            )
            return
        if outcome == "already_terminal":
            self._record_downstream_item_disposition(
                db,
                task,
                item,
                event_type="downstream_retry_terminal_reused",
                message=f"复用已终态的下游子任务结果: {item.downstream_service}:{item.downstream_task_id or '-'}",
                payload=payload,
            )
            return
        if outcome == "not_found":
            self._record_downstream_item_disposition(
                db,
                task,
                item,
                event_type="downstream_retry_target_missing",
                message=f"下游重试目标不存在: {item.downstream_service}:{item.downstream_task_id or '-'}",
                level="warning",
                payload=payload,
            )
            return
        if outcome == "transport_error":
            self._record_downstream_item_disposition(
                db,
                task,
                item,
                event_type="downstream_retry_deferred",
                message=f"下游重试通信异常，保留当前子任务等待后续自动对账: {item.downstream_service}:{item.downstream_task_id or '-'}",
                level="warning",
                payload=payload,
            )
            return
        self._record_downstream_item_disposition(
            db,
            task,
            item,
            event_type="downstream_retry_rejected" if outcome == "invalid_transition" else "downstream_retry_failed",
            message=f"下游重试未被接受: {item.downstream_service}:{item.downstream_task_id or '-'}",
            level="warning",
            payload=payload,
        )

    def _defer_item_after_downstream_transport_error(
        self,
        session: Session,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        *,
        operation: str,
        exc: Exception,
        response_item: dict[str, Any],
    ) -> dict[str, Any]:
        has_downstream_ref = bool(str(item.downstream_task_id or "").strip())
        if normalize_stage_name(item.stage_name) == "dataflow_vuln_scan" and not has_downstream_ref:
            self._mark_downstream_binding_retry(
                item,
                error_message=str(exc),
                error_type=self._classify_downstream_sync_error(exc),
                recoverable=True,
            )
        replacement_state = self._replacement_in_progress_state(item)
        deferred_mode = "reconcile" if has_downstream_ref else "redispatch"
        if replacement_state["replacement_in_progress"] and replacement_state["binding_cleared"] and not has_downstream_ref:
            deferred_status = "queued"
        else:
            deferred_status = "running" if has_downstream_ref else "queued"
        http_status = self._extract_http_status_from_exception(exc)
        is_http_429 = http_status == 429
        error_type = self._classify_downstream_sync_error(exc)
        state = self._build_next_http_429_failure_state(item) if is_http_429 else self._build_next_downstream_sync_failure_state(item)
        sync_status = "rate_limited" if is_http_429 else "transport_error"
        child_event_type = "downstream_http_429_retry_scheduled" if is_http_429 else "child_transport_failed"
        child_change_source = "rate_limited" if is_http_429 else "transport_error"
        disposition_event_type = "downstream_http_429_retry_scheduled" if is_http_429 else "downstream_transport_deferred"
        disposition_message = (
            f"下游返回 429，智能体将在 {self._next_http_429_retry_backoff_seconds(state.consecutive_error_count)} 秒后重试"
            if is_http_429
            else (
                "下游通信异常，保留当前子任务等待后续自动对账"
                if has_downstream_ref
                else "下游通信异常，保留当前子任务等待重新调度创建"
            )
        )
        self._apply_child_task_status_change(
            session,
            task=task,
            item=item,
            change_source=child_change_source,
            after_status=deferred_status,
            sync_status=sync_status,
            downstream_status_raw=None,
            downstream_status_mapped=deferred_status,
            downstream_status=None,
            state_applied=False,
            error_message=str(exc),
            error_type=error_type,
            http_status=http_status,
            event_type=child_event_type,
            extra_payload={
                "operation": operation,
                "deferred_mode": deferred_mode,
                "retry_attempt_count": state.consecutive_error_count,
                "retry_delay_seconds": None if state.next_retry_at is None else self._next_http_429_retry_backoff_seconds(state.consecutive_error_count) if is_http_429 else None,
                "rate_limited": is_http_429,
            },
        )
        self._mark_stage_item_sync_observation(
            item,
            sync_status=sync_status,
            synced_at=_now(),
            error_message=str(exc),
            http_status=http_status,
            error_type=error_type,
            state_applied=False,
            consecutive_error_count=state.consecutive_error_count,
            budget_exhausted=state.budget_exhausted,
            next_retry_at=state.next_retry_at,
            last_sync_result="error",
        )
        if replacement_state["replacement_in_progress"]:
            self._mark_replacement_in_progress(
                item,
                old_downstream_task_id=replacement_state["old_downstream_task_id"],
                binding_cleared=replacement_state["binding_cleared"],
                verification_status=replacement_state["verification_status"] or "pending",
            )
        session.commit()
        self._record_downstream_item_disposition(
            session,
            task,
            item,
            event_type=disposition_event_type,
            message=disposition_message,
            level="warning",
            payload={
                "operation": operation,
                "error": str(exc),
                "http_status": http_status,
                "error_type": error_type,
                "error_type_detail": getattr(exc, "error_type_detail", None) or getattr(exc, "transport_error_kind", None),
                "transport_error_kind": getattr(exc, "transport_error_kind", None) or getattr(exc, "error_type_detail", None),
                "retry_attempted": bool(getattr(exc, "retry_attempted", False)),
                "client_recreated": bool(getattr(exc, "client_recreated", False)),
                "state_applied": False,
                "deferred_mode": deferred_mode,
                "item_status": item.status,
                "consecutive_sync_error_count": state.consecutive_error_count,
                "next_sync_retry_at": _isoformat_or_none(state.next_retry_at),
                "sync_error_budget_exhausted": state.budget_exhausted,
                "retry_attempt_count": state.consecutive_error_count,
                "retry_delay_seconds": self._next_http_429_retry_backoff_seconds(state.consecutive_error_count) if is_http_429 else None,
                "binding_state": self._downstream_binding_state(item),
                "binding_attempts": self._downstream_binding_attempts(item),
                "binding_next_retry_at": _isoformat_or_none(self._downstream_binding_time(item, "next_retry_at")),
            },
        )
        session.commit()
        return {
            "status": "running" if has_downstream_ref else "pending",
            "error": str(exc),
            "item": response_item,
            "deferred_mode": deferred_mode,
            "sync_degraded": True,
        }

    def _defer_item_after_orchestration_error(
        self,
        session: Session,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        *,
        operation: str,
        exc: Exception,
        response_item: dict[str, Any],
        has_downstream_ref: bool | None = None,
    ) -> dict[str, Any]:
        if has_downstream_ref is None:
            has_downstream_ref = bool(str(item.downstream_task_id or "").strip())
        state = self._build_next_stage_item_orchestration_failure_state(item)
        deferred_mode = "reconcile" if has_downstream_ref else "redispatch"
        deferred_status = "running" if has_downstream_ref else "queued"
        item.status = deferred_status
        item.error_message = str(exc)
        item.finished_at = None
        self._mark_stage_item_orchestration_observation(
            item,
            source=operation,
            observed_at=_now(),
            error_message=str(exc),
            error_type=self._classify_orchestration_error(exc),
            last_result="error",
            consecutive_error_count=state.consecutive_error_count,
            budget_exhausted=state.budget_exhausted,
            next_retry_at=state.next_retry_at,
        )
        self._record_event(
            session,
            task,
            "stage_item_orchestration_error_budget_exhausted" if state.budget_exhausted else "stage_item_orchestration_retry_scheduled",
            "阶段子任务推进异常，已进入延迟恢复" if not state.budget_exhausted else "阶段子任务推进异常预算耗尽，等待后台恢复",
            level="warning",
            stage_name=item.stage_name,
            item=item,
            payload={
                "operation": operation,
                "error_type": self._classify_orchestration_error(exc),
                "error_message": str(exc),
                "consecutive_error_count": state.consecutive_error_count,
                "next_retry_at": _isoformat_or_none(state.next_retry_at),
                "budget_exhausted": state.budget_exhausted,
                "resolution_reason": "recoverable_orchestration_error",
                "deferred_mode": deferred_mode,
            },
        )
        session.commit()
        return {
            "status": "running" if has_downstream_ref else "pending",
            "error": str(exc),
            "item": response_item,
            "deferred_mode": deferred_mode,
            "sync_degraded": True,
            "orchestration_degraded": True,
        }

    def _status_from_downstream_payload(self, payload: dict[str, Any], *, success_statuses: set[str]) -> str:
        downstream_status = str(payload.get("status") or "").lower()
        if downstream_status in success_statuses:
            return "success"
        mapped_status = self._map_downstream_status(downstream_status)
        if mapped_status == "success":
            return "success"
        if mapped_status in {"pending", "queued", "dispatching", "running"}:
            return mapped_status
        if mapped_status == "cancelled":
            return "cancelled"
        if mapped_status == "downstream_missing":
            return "downstream_missing"
        return "failed"

    def _is_self_healing_downstream_failure_observation(
        self,
        *,
        mapped_status: str | None,
        downstream_status: str | None = None,
        payload: dict[str, Any] | None = None,
        error_message: str | None = None,
        error_type: str | None = None,
    ) -> bool:
        normalized_mapped = str(mapped_status or "").strip().lower()
        if normalized_mapped != "failed":
            return False
        raw_parts = [
            str(downstream_status or "").strip().lower(),
            str(error_message or "").strip().lower(),
            str(error_type or "").strip().lower(),
            str((payload or {}).get("message") or "").strip().lower(),
            str((payload or {}).get("error") or "").strip().lower(),
            str((payload or {}).get("error_message") or "").strip().lower(),
        ]
        joined = " ".join(part for part in raw_parts if part)
        self_healing_tokens = (
            "stale active runtime",
            "assumed failed",
            "awaiting recovery",
            "kept running by run evidence",
            "requeued",
            "pending recovery",
            "run_vuln_scan.py running",
            "http_5xx",
            "transport_error",
            "upstreamerror",
        )
        return any(token in joined for token in self_healing_tokens)

    def _latest_observed_downstream_status(self, item: BinarySecurityStageItem) -> str | None:
        result = self._load_stage_item_result_payload(item)
        observed, _sync_observation, _repaired = self._effective_stage_item_downstream_status(item, result=result)
        mapped = self._map_downstream_status(str(observed or ""))
        return mapped or (str(observed or "").strip().lower() or None)

    def _has_retryable_downstream_task(self, item: BinarySecurityStageItem) -> bool:
        if not str(item.downstream_task_id or "").strip():
            return False
        return str(item.status or "").strip().lower() != "downstream_missing"

    def _clear_item_downstream_runtime_state(self, item: BinarySecurityStageItem) -> None:
        item.downstream_task_id = None
        item.downstream_status = None
        item.sync_status = None
        item.last_synced_at = None
        item.downstream_raw_status = None
        item.downstream_mapped_status = None
        item.downstream_state_applied = False
        item.sync_observation_error_message = None
        item.sync_observation_error_type = None
        item.sync_observation_http_status = None
        item.error_message = None
        result = dict(item.result or {})
        for key in (
            "downstream_status_sync",
            "downstream_status_synced_at",
            "downstream_status",
            "sync_observation",
            "downstream",
            "sync_status",
        ):
            result.pop(key, None)
        item.result = result

    def _mark_superseded_downstream_state(
        self,
        item: BinarySecurityStageItem,
        *,
        old_downstream_task_id: str | None,
        message: str | None = None,
    ) -> None:
        result = dict(item.result or {})
        sync_observation = dict(result.get("sync_observation") or {})
        sync_observation["superseded_downstream_task_id"] = str(old_downstream_task_id or "").strip() or None
        for key in (
            "next_retry_at",
            "last_error_at",
            "consecutive_error_count",
            "budget_exhausted",
            "last_attempt_at",
            "sync_status",
            "error_message",
            "error_type",
            "http_status",
            "last_result",
            "verification_status",
            "replacement_in_progress",
            "binding_cleared",
            "old_downstream_task_id",
        ):
            sync_observation.pop(key, None)
        if message:
            sync_observation["message"] = message
        result["sync_observation"] = sync_observation
        item.result = result

    def _mark_replacement_in_progress(
        self,
        item: BinarySecurityStageItem,
        *,
        old_downstream_task_id: str | None,
        binding_cleared: bool,
        verification_status: str = "pending",
    ) -> None:
        result = dict(item.result or {})
        sync_observation = dict(result.get("sync_observation") or {})
        sync_observation["replacement_in_progress"] = True
        sync_observation["old_downstream_task_id"] = str(old_downstream_task_id or "").strip() or None
        sync_observation["binding_cleared"] = bool(binding_cleared)
        sync_observation["verification_status"] = str(verification_status or "pending")
        result["sync_observation"] = sync_observation
        item.result = result

    def _replacement_in_progress_state(self, item: BinarySecurityStageItem) -> dict[str, Any]:
        result = dict(item.result or {})
        sync_observation = dict(result.get("sync_observation") or {})
        return {
            "replacement_in_progress": bool(sync_observation.get("replacement_in_progress")),
            "binding_cleared": bool(sync_observation.get("binding_cleared")),
            "verification_status": str(sync_observation.get("verification_status") or "").strip().lower() or None,
            "old_downstream_task_id": str(sync_observation.get("old_downstream_task_id") or "").strip() or None,
        }

    def _clear_replacement_in_progress(self, item: BinarySecurityStageItem) -> None:
        result = dict(item.result or {})
        sync_observation = dict(result.get("sync_observation") or {})
        changed = False
        for key in ("replacement_in_progress", "binding_cleared", "verification_status", "old_downstream_task_id"):
            if key in sync_observation:
                sync_observation.pop(key, None)
                changed = True
        if changed:
            result["sync_observation"] = sync_observation
            item.result = result

    def _archive_job_is_active(self, archive_status: str | None) -> bool:
        return str(archive_status or "").strip() in {"pending", "running", "archived", "applying", "success"}

    def _supersede_archive_jobs_for_downstream_task(
        self,
        db: Session,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        *,
        old_downstream_task_id: str | None,
        reason: str,
    ) -> list[BinarySecurityArchiveJob]:
        old_task_id = str(old_downstream_task_id or "").strip()
        if not old_task_id:
            return []
        jobs = (
            db.query(BinarySecurityArchiveJob)
            .filter(
                BinarySecurityArchiveJob.item_id == item.id,
                BinarySecurityArchiveJob.archive_status.in_(["pending", "running", "archived", "applying"]),
            )
            .order_by(BinarySecurityArchiveJob.created_at.asc(), BinarySecurityArchiveJob.id.asc())
            .all()
        )
        superseded: list[BinarySecurityArchiveJob] = []
        now = _now()
        for job in jobs:
            if self._archive_job_bound_downstream_task_id(job) != old_task_id:
                continue
            job.archive_status = "superseded"
            job.error_message = None
            job.owner_id = None
            job.completed_at = job.completed_at or now
            job.updated_at = now
            payload = dict(job.payload or {})
            payload["superseded"] = True
            payload["superseded_reason"] = reason
            payload["superseded_downstream_task_id"] = old_task_id
            payload["superseded_at"] = now.isoformat()
            job.payload = payload
            superseded.append(job)
        if superseded:
            logger.warning(
                "binary-security superseded archive jobs: task_id=%s stage=%s item_id=%s old_downstream_task_id=%s archive_job_ids=%s reason=%s",
                task.id,
                item.stage_name,
                item.id,
                old_task_id,
                ",".join(str(job.id) for job in superseded),
                reason,
            )
            self._record_event(
                db,
                task,
                "superseded_archive_jobs_cancelled",
                "旧 child 绑定的归档任务已废弃",
                stage_name=item.stage_name,
                item=item,
                level="warning",
                payload={
                    "old_downstream_task_id": old_task_id,
                    "archive_job_ids": [job.id for job in superseded],
                    "reason": reason,
                    "superseded": True,
                },
            )
        return superseded

    async def _replace_active_child_binding(
        self,
        db: Session,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        *,
        new_downstream_task_id: str | None,
        token: str | None,
        reason: str,
    ) -> str | None:
        new_task_id = str(new_downstream_task_id or "").strip() or None
        old_task_id = str(item.downstream_task_id or "").strip() or None
        if not old_task_id:
            item.downstream_task_id = new_task_id or item.downstream_task_id
            self._clear_replacement_in_progress(item)
            return None
        if new_task_id and new_task_id == old_task_id:
            self._clear_replacement_in_progress(item)
            return old_task_id

        logger.warning(
            "binary-security child binding replace requested: task_id=%s stage=%s item_id=%s item_key=%s old_downstream_task_id=%s new_downstream_task_id=%s reason=%s",
            task.id,
            item.stage_name,
            item.id,
            item.item_key,
            old_task_id,
            new_task_id,
            reason,
        )

        self._mark_replacement_in_progress(
            item,
            old_downstream_task_id=old_task_id,
            binding_cleared=False,
            verification_status="pending",
        )
        self._supersede_archive_jobs_for_downstream_task(
            db,
            task,
            item,
            old_downstream_task_id=old_task_id,
            reason=reason,
        )
        self._mark_superseded_downstream_state(
            item,
            old_downstream_task_id=old_task_id,
            message="旧 child 已失效，等待新 child 接管",
        )

        refs = [{
            "service": item.downstream_service,
            "task_id": old_task_id,
            "project_id": task.project_id,
            "stage_name": item.stage_name,
            "item_id": item.id,
            "item_key": item.item_key,
        }]
        try:
            await self._downstream_cancel_refs(db, task, refs, token)
        except NotFoundError:
            pass
        except Exception:
            self._clear_replacement_in_progress(item)
            raise
        try:
            await self._delete_downstream_refs(db, task, refs, token, cleanup_scope="binding_replace")
        except NotFoundError:
            pass
        except Exception:
            self._clear_replacement_in_progress(item)
            raise

        item.downstream_task_id = new_task_id
        self._clear_replacement_in_progress(item)
        logger.info(
            "binary-security child binding replaced: task_id=%s stage=%s item_id=%s item_key=%s old_downstream_task_id=%s new_downstream_task_id=%s reason=%s",
            task.id,
            item.stage_name,
            item.id,
            item.item_key,
            old_task_id,
            new_task_id,
            reason,
        )
        self._record_event(
            db,
            task,
            "child_binding_replaced",
            "阶段项已切换到新的 authoritative child",
            stage_name=item.stage_name,
            item=item,
            level="warning",
            payload={
                "old_downstream_task_id": old_task_id,
                "new_downstream_task_id": new_task_id,
                "reason": reason,
            },
        )
        self._record_event(
            db,
            task,
            "superseded_downstream_sync_ignored",
            "旧 child 的后续同步与归档触发将被忽略",
            stage_name=item.stage_name,
            item=item,
            level="warning",
            payload={
                "old_downstream_task_id": old_task_id,
                "new_downstream_task_id": new_task_id,
                "reason": reason,
                "superseded": True,
            },
        )
        return old_task_id

    def _may_queue_archive_for_current_binding(
        self,
        item: BinarySecurityStageItem,
        *,
        payload: dict[str, Any],
        mapped_status: str,
    ) -> tuple[bool, str | None]:
        if mapped_status not in ARCHIVE_SUCCESS_MAPPED_STATUSES:
            return False, "non_success_status"
        replacement_state = self._replacement_in_progress_state(item)
        if replacement_state["replacement_in_progress"] or replacement_state["binding_cleared"]:
            return False, "replacement_in_progress"
        current_downstream_task_id = self._current_downstream_task_id(item)
        payload_downstream_task_id = self._payload_downstream_task_id(payload)
        if current_downstream_task_id and payload_downstream_task_id and payload_downstream_task_id != current_downstream_task_id:
            return False, "stale_child_payload"
        return True, None

    def _should_preserve_terminal_status(
        self,
        item: BinarySecurityStageItem,
        *,
        mapped_status: str | None,
        current_item_status: str | None,
        payload: dict[str, Any],
    ) -> bool:
        if not mapped_status or not current_item_status or current_item_status == mapped_status:
            return False
        replacement_state = self._replacement_in_progress_state(item)
        if replacement_state["replacement_in_progress"] or replacement_state["binding_cleared"] or replacement_state["verification_status"] == "pending":
            return normalize_stage_name(item.stage_name) != "dataflow_vuln_scan"
        observed_task_id = str(payload.get("task_id") or payload.get("id") or "").strip() or None
        current_task_id = str(item.downstream_task_id or "").strip() or None
        if normalize_stage_name(item.stage_name) != "dataflow_vuln_scan":
            if not observed_task_id or not current_task_id:
                return True
            if observed_task_id != current_task_id:
                return True
            if mapped_status in {"success", "partial_success"}:
                return False
            return True
        if observed_task_id and current_task_id and observed_task_id != current_task_id:
            return False
        return True

    def _retry_item_action_snapshot(
        self,
        item: BinarySecurityStageItem,
        *,
        strategy: str,
        observed_status: str | None,
        old_downstream_task_id: str | None,
        cleanup_performed: bool,
        binding_cleared: bool,
        cleanup_status: str | None = None,
        create_required: bool | None = None,
        create_status: str | None = None,
        verification_status: str | None = None,
        error: str | None = None,
    ) -> dict[str, Any]:
        return {
            "stage_name": item.stage_name,
            "item_id": item.id,
            "item_key": item.item_key,
            "parent_key": item.parent_key,
            "downstream_service": item.downstream_service,
            "old_downstream_task_id": old_downstream_task_id,
            "current_downstream_task_id": str(item.downstream_task_id or "").strip() or None,
            "new_downstream_task_id": str(item.downstream_task_id or "").strip() or None,
            "strategy": strategy,
            "observed_status": observed_status,
            "cleanup_performed": bool(cleanup_performed),
            "binding_cleared": bool(binding_cleared),
            "cleanup_required": bool(strategy == RETRY_CHILD_STRATEGY_RECREATE_FROM_ABNORMAL),
            "cleanup_status": cleanup_status or ("pending" if strategy == RETRY_CHILD_STRATEGY_RECREATE_FROM_ABNORMAL else "not_required"),
            "create_required": bool(create_required if create_required is not None else strategy == RETRY_CHILD_STRATEGY_RECREATE_FROM_ABNORMAL),
            "create_status": create_status or ("pending" if strategy == RETRY_CHILD_STRATEGY_RECREATE_FROM_ABNORMAL else "not_required"),
            "verification_status": verification_status or "pending",
            "error": error,
        }

    def _store_retry_item_action(self, task: BinarySecurityTask, action: dict[str, Any] | None) -> None:
        if not isinstance(action, dict):
            return
        plan = self._retry_plan(task)
        actions = [dict(row) for row in list(plan.get("item_actions") or []) if isinstance(row, dict)]
        item_key = str(action.get("item_key") or "").strip()
        parent_key = str(action.get("parent_key") or "").strip()
        normalized: list[dict[str, Any]] = []
        replaced = False
        for row in actions:
            if (
                str(row.get("item_key") or "").strip() == item_key
                and str(row.get("parent_key") or "").strip() == parent_key
            ):
                normalized.append(dict(action))
                replaced = True
            else:
                normalized.append(row)
        if not replaced:
            normalized.append(dict(action))
        plan["item_actions"] = normalized
        self._set_retry_plan(task, plan)

    def _retry_item_actions(self, task: BinarySecurityTask) -> list[dict[str, Any]]:
        plan = self._retry_plan(task)
        return [dict(row) for row in list(plan.get("item_actions") or []) if isinstance(row, dict)]

    def _set_retry_item_actions(self, task: BinarySecurityTask, actions: list[dict[str, Any]]) -> None:
        plan = self._retry_plan(task)
        plan["item_actions"] = [dict(row) for row in actions if isinstance(row, dict)]
        self._set_retry_plan(task, plan)

    def _update_retry_item_action(
        self,
        task: BinarySecurityTask,
        *,
        item_id: str,
        updates: dict[str, Any],
    ) -> dict[str, Any] | None:
        actions = self._retry_item_actions(task)
        updated: dict[str, Any] | None = None
        normalized: list[dict[str, Any]] = []
        for row in actions:
            if str(row.get("item_id") or "").strip() == str(item_id or "").strip():
                updated = {**row, **dict(updates or {})}
                normalized.append(updated)
            else:
                normalized.append(row)
        self._set_retry_item_actions(task, normalized)
        return updated

    def _validate_retry_prepare_state(
        self,
        db: Session,
        task: BinarySecurityTask,
        *,
        target_stage: str,
        retry_item_keys: list[str],
        item_actions: list[dict[str, Any]],
        affected_stages: list[str],
        phase: str = "prepare",
    ) -> dict[str, Any]:
        stage_items = self._stage_items(db, task.id, target_stage)
        keyed_items = {
            self._stage_item_identity(item.item_key, item.parent_key): item
            for item in stage_items
        }
        issues: list[dict[str, Any]] = []
        validated_item_count = 0
        failed_item_count = 0
        for item_key in retry_item_keys:
            item = keyed_items.get(item_key)
            if item is None:
                issues.append({"item_key": item_key, "issue": "missing_retry_item"})
                failed_item_count += 1
                continue
            validated_item_count += 1
            action = next((row for row in item_actions if str(row.get("item_key") or "") == item_key), None)
            if action is None:
                action = next(
                    (
                        row
                        for row in item_actions
                        if self._stage_item_identity(str(row.get("item_key") or ""), row.get("parent_key")) == item_key
                    ),
                    None,
                )
            strategy = str((action or {}).get("strategy") or "").strip()
            if strategy == RETRY_CHILD_STRATEGY_RECREATE_FROM_ABNORMAL:
                old_task_id = str((action or {}).get("old_downstream_task_id") or "").strip()
                current_task_id = str(item.downstream_task_id or "").strip()
                if phase == "prepare":
                    if str(item.status or "").strip() not in {"pending", "queued", "dispatching", "running", "failed", "cancelled", "downstream_missing"}:
                        issues.append({"item_key": item_key, "issue": "status_not_retryable", "status": item.status})
                    continue
                if phase == "verify":
                    if not current_task_id:
                        issues.append({"item_key": item_key, "issue": "replacement_binding_missing"})
                    elif old_task_id and old_task_id == current_task_id:
                        issues.append({"item_key": item_key, "issue": "replacement_reused_old_child", "downstream_task_id": current_task_id})
                    replacement_state = self._replacement_in_progress_state(item)
                    if (
                        replacement_state["replacement_in_progress"]
                        and replacement_state["binding_cleared"]
                        and str(item.status or "").strip() in {"failed", "cancelled", "downstream_missing"}
                    ):
                        issues.append(
                            {
                                "item_key": item_key,
                                "issue": "replacement_terminal_reapplied_from_old_child",
                                "status": item.status,
                                "old_downstream_task_id": replacement_state["old_downstream_task_id"],
                            }
                        )
                elif current_task_id:
                    issues.append({"item_key": item_key, "issue": "binding_not_cleared", "downstream_task_id": item.downstream_task_id})
                if any(
                    [
                        getattr(item, "downstream_status", None),
                        getattr(item, "sync_status", None),
                        getattr(item, "last_synced_at", None),
                        getattr(item, "downstream_raw_status", None),
                        getattr(item, "downstream_mapped_status", None),
                        getattr(item, "sync_observation_error_message", None),
                        getattr(item, "sync_observation_error_type", None),
                        getattr(item, "sync_observation_http_status", None),
                    ]
                ):
                    issues.append({"item_key": item_key, "issue": "stale_sync_snapshot_present"})
                normalized_status = str(item.status or "").strip()
                allowed_statuses = {"pending", "queued", "dispatching", "running"} if phase == "verify" else {"pending"}
                if phase == "verify" and current_task_id and normalized_status == "success":
                    allowed_statuses = allowed_statuses | {"success"}
                if normalized_status not in allowed_statuses:
                    issues.append({"item_key": item_key, "issue": "status_not_reset", "status": item.status})
                if normalized_status != "success" and item.finished_at is not None:
                    issues.append({"item_key": item_key, "issue": "finished_at_not_cleared"})
            elif strategy == RETRY_CHILD_STRATEGY_REUSE_SUCCESS:
                if str(item.status or "").strip() != "success":
                    issues.append({"item_key": item_key, "issue": "success_child_not_preserved", "status": item.status})
            elif strategy == RETRY_CHILD_STRATEGY_ADOPT_ACTIVE:
                if not str(item.downstream_task_id or "").strip():
                    issues.append({"item_key": item_key, "issue": "active_binding_missing"})
                observed_active_status = self._map_downstream_status(str(self._latest_observed_downstream_status(item) or ""))
                if (
                    self._normalize_item_status(item.status) not in {"pending", "queued", "dispatching", "running"}
                    and observed_active_status not in {"pending", "queued", "dispatching", "running"}
                ):
                    issues.append({"item_key": item_key, "issue": "active_status_not_preserved", "status": item.status})
        for stage_name in affected_stages:
            stage_run = db.query(BinarySecurityStageRun).filter(
                BinarySecurityStageRun.task_id == task.id,
                BinarySecurityStageRun.stage_name == stage_name,
            ).first()
            if stage_run is None:
                continue
            if stage_name == target_stage:
                allowed_target_statuses = {"pending", "queued", "running", "dispatching"} if phase == "verify" else {"pending", "queued", "running"}
                if str(stage_run.status or "").strip() not in allowed_target_statuses:
                    issues.append({"stage_name": stage_name, "issue": "target_stage_not_reset", "status": stage_run.status})
            elif str(stage_run.status or "").strip() not in {"pending", "queued"}:
                issues.append({"stage_name": stage_name, "issue": "downstream_stage_not_reset", "status": stage_run.status})
        return {
            "validated": not issues,
            "validated_item_count": validated_item_count,
            "failed_item_count": failed_item_count + len(issues),
            "issues": issues,
        }

    def _classify_retry_downstream_strategy(
        self,
        item: BinarySecurityStageItem,
        *,
        active_payload: dict[str, Any] | None = None,
        observed_payload: dict[str, Any] | None = None,
    ) -> tuple[str, str | None]:
        if active_payload is not None:
            status = self._map_downstream_status(str(active_payload.get("status") or ""))
            if status in {"pending", "queued", "dispatching", "running"}:
                return RETRY_CHILD_STRATEGY_ADOPT_ACTIVE, status
        payload = observed_payload if isinstance(observed_payload, dict) else None
        raw_status = None
        if payload is not None:
            raw_status = self._status_from_downstream_payload(payload, success_statuses={"success", "partial_success", "completed", "passed", "succeeded"})
        mapped_status = raw_status or self._latest_observed_downstream_status(item) or str(item.status or "").strip().lower() or None
        mapped_status = self._map_downstream_status(str(mapped_status or "")) or (str(mapped_status or "").strip().lower() or None)
        if mapped_status == "success":
            return RETRY_CHILD_STRATEGY_REUSE_SUCCESS, mapped_status
        if mapped_status in {"pending", "queued", "dispatching", "running"}:
            return RETRY_CHILD_STRATEGY_ADOPT_ACTIVE, mapped_status
        if mapped_status in RETRY_CHILD_ABNORMAL_STATUSES:
            return RETRY_CHILD_STRATEGY_RECREATE_FROM_ABNORMAL, mapped_status
        return RETRY_CHILD_STRATEGY_RECREATE_FROM_ABNORMAL, mapped_status

    async def _prepare_retry_child_for_reuse_or_recreate(
        self,
        session: Session,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        *,
        strategy: str,
        observed_status: str | None,
        token: str | None,
    ) -> dict[str, Any]:
        old_task_id = str(item.downstream_task_id or "").strip() or None
        self._record_downstream_item_disposition(
            session,
            task,
            item,
            event_type="retry_item_strategy_selected",
            message=f"重试子任务策略已确定: {strategy}",
            payload={
                "stage_name": item.stage_name,
                "item_id": item.id,
                "item_key": item.item_key,
                "old_downstream_task_id": old_task_id,
                "new_downstream_task_id": None,
                "strategy": strategy,
                "old_downstream_status": observed_status,
            },
        )
        if strategy == RETRY_CHILD_STRATEGY_REUSE_SUCCESS:
            self._record_downstream_item_disposition(
                session,
                task,
                item,
                event_type="retry_item_reuse_success_child",
                message="重试复用已成功的下游子任务",
                payload={
                    "stage_name": item.stage_name,
                    "item_id": item.id,
                    "item_key": item.item_key,
                    "old_downstream_task_id": old_task_id,
                    "new_downstream_task_id": old_task_id,
                    "strategy": strategy,
                    "old_downstream_status": observed_status,
                },
            )
            return self._retry_item_action_snapshot(
                item,
                strategy=strategy,
                observed_status=observed_status,
                old_downstream_task_id=old_task_id,
                cleanup_performed=False,
                binding_cleared=False,
            )
        if strategy == RETRY_CHILD_STRATEGY_ADOPT_ACTIVE:
            self._mark_replacement_in_progress(
                item,
                old_downstream_task_id=old_task_id,
                binding_cleared=False,
                verification_status="pending",
            )
            self._record_downstream_item_disposition(
                session,
                task,
                item,
                event_type="retry_item_adopt_active_child",
                message="重试接管仍在运行中的下游子任务",
                payload={
                    "stage_name": item.stage_name,
                    "item_id": item.id,
                    "item_key": item.item_key,
                    "old_downstream_task_id": old_task_id,
                    "new_downstream_task_id": old_task_id,
                    "strategy": strategy,
                    "old_downstream_status": observed_status,
                },
            )
            return self._retry_item_action_snapshot(
                item,
                strategy=strategy,
                observed_status=observed_status,
                old_downstream_task_id=old_task_id,
                cleanup_performed=False,
                binding_cleared=False,
            )
        self._record_downstream_item_disposition(
            session,
            task,
            item,
            event_type="retry_item_recreate_from_abnormal_child",
            message="重试检测到异常下游子任务，准备删旧重建",
            level="warning",
            payload={
                "stage_name": item.stage_name,
                "item_id": item.id,
                "item_key": item.item_key,
                "old_downstream_task_id": old_task_id,
                "new_downstream_task_id": None,
                "strategy": strategy,
                "old_downstream_status": observed_status,
            },
        )
        self._mark_replacement_in_progress(
            item,
            old_downstream_task_id=old_task_id,
            binding_cleared=False,
            verification_status="pending",
        )
        if old_task_id:
            self._record_downstream_item_disposition(
                session,
                task,
                item,
                event_type="retry_item_old_child_cancel_requested",
                message=f"重试前请求取消旧下游子任务: {item.downstream_service}:{old_task_id}",
                level="warning",
                payload={
                    "stage_name": item.stage_name,
                    "item_id": item.id,
                    "item_key": item.item_key,
                    "old_downstream_task_id": old_task_id,
                    "new_downstream_task_id": None,
                    "strategy": strategy,
                    "old_downstream_status": observed_status,
                },
            )
            session.commit()
            try:
                await self._downstream_cancel_refs(
                    session,
                    task,
                    [
                        {
                            "service": item.downstream_service,
                            "task_id": old_task_id,
                            "project_id": task.project_id,
                            "stage_name": item.stage_name,
                            "item_id": item.id,
                            "item_key": item.item_key,
                        }
                    ],
                    token,
                )
            except Exception:
                session.rollback()
            self._record_downstream_item_disposition(
                session,
                task,
                item,
                event_type="retry_item_old_child_delete_requested",
                message=f"重试前请求删除旧下游子任务: {item.downstream_service}:{old_task_id}",
                level="warning",
                payload={
                    "stage_name": item.stage_name,
                    "item_id": item.id,
                    "item_key": item.item_key,
                    "old_downstream_task_id": old_task_id,
                    "new_downstream_task_id": None,
                    "strategy": strategy,
                    "old_downstream_status": observed_status,
                },
            )
            session.commit()
            await self._delete_downstream_refs(
                session,
                task,
                [
                    {
                        "service": item.downstream_service,
                        "task_id": old_task_id,
                        "project_id": task.project_id,
                        "stage_name": item.stage_name,
                        "item_id": item.id,
                        "item_key": item.item_key,
                    }
                ],
                token,
            )
            self._record_downstream_item_disposition(
                session,
                task,
                item,
                event_type="retry_item_old_child_verified_absent",
                message=f"旧下游子任务已确认不可见: {item.downstream_service}:{old_task_id}",
                payload={
                    "stage_name": item.stage_name,
                    "item_id": item.id,
                    "item_key": item.item_key,
                    "old_downstream_task_id": old_task_id,
                    "new_downstream_task_id": None,
                    "strategy": strategy,
                    "old_downstream_status": observed_status,
                },
            )
        self._clear_item_downstream_runtime_state(item)
        item.finished_at = None
        self._mark_replacement_in_progress(
            item,
            old_downstream_task_id=old_task_id,
            binding_cleared=True,
            verification_status="pending",
        )
        self._record_downstream_item_disposition(
            session,
            task,
            item,
            event_type="retry_item_old_child_cleared",
            message="旧下游绑定与同步快照已清空，准备创建新子任务",
            payload={
                "stage_name": item.stage_name,
                "item_id": item.id,
                "item_key": item.item_key,
                "old_downstream_task_id": old_task_id,
                "new_downstream_task_id": None,
                "strategy": strategy,
                "old_downstream_status": observed_status,
            },
        )
        return self._retry_item_action_snapshot(
            item,
            strategy=strategy,
            observed_status=observed_status,
            old_downstream_task_id=old_task_id,
            cleanup_performed=bool(old_task_id or observed_status == "downstream_missing"),
            binding_cleared=True,
        )

    def _is_vuln_retry_recreate_outcome(self, control: dict[str, Any]) -> bool:
        outcome = str(control.get("retry_outcome") or control.get("outcome") or "").strip()
        if outcome == "not_found":
            return True
        if outcome != "invalid_transition":
            return False
        if control.get("http_status") == 405:
            return True
        error_message = str(control.get("error_message") or "").lower()
        recreate_tokens = (
            "not support",
            "unsupported",
            "not allowed",
            "cannot be retried",
            "cannot retry",
            "retry not supported",
            "invalid status",
            "invalid transition",
            "terminal",
            "终态",
            "重试",
            "不支持重试",
            "无法重试",
            "不能重试",
            "非法状态",
            "状态迁移",
        )
        return any(token in error_message for token in recreate_tokens)

    async def _recreate_vuln_downstream_task(
        self,
        session: Session,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        dataflow_result: dict[str, Any],
        token: str | None,
        *,
        control: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        old_task_id = str(item.downstream_task_id or "").strip() or None
        error_message = str(control.get("error_message") or "").strip() if isinstance(control, dict) else ""
        http_status = control.get("http_status") if isinstance(control, dict) else None
        outcome = str(control.get("outcome") or "").strip() if isinstance(control, dict) else ""

        if old_task_id:
            self._record_downstream_item_disposition(
                session,
                task,
                item,
                event_type="downstream_retry_fallback_delete_requested",
                message=f"下游重试不可复用，准备删除旧下游任务并重建: {item.downstream_service}:{old_task_id}",
                level="warning",
                payload={
                    "stage_name": item.stage_name,
                    "old_downstream_task_id": old_task_id,
                    "new_downstream_task_id": None,
                    "control_outcome": outcome or None,
                    "http_status": http_status,
                    "error": error_message or None,
                },
            )
            session.commit()
            try:
                await self._downstream_tasks().delete_child_task(
                    service="dataflow_vuln_scan",
                    project_id=task.project_id,
                    task_id=old_task_id,
                    token=token,
                )
            except NotFoundError:
                delete_status = 404
            except Exception as exc:
                payload_error = self._extract_downstream_error_text(exc) or str(exc)
                self._record_downstream_item_disposition(
                    session,
                    task,
                    item,
                    event_type="downstream_retry_fallback_delete_failed",
                    message=(
                        f"删除旧下游任务时通信异常，暂不重建: {item.downstream_service}:{old_task_id}"
                        if self._is_retryable_downstream_transport_error(exc)
                        else f"删除旧下游任务失败，无法继续重建: {item.downstream_service}:{old_task_id}"
                    ),
                    level="warning",
                    payload={
                        "stage_name": item.stage_name,
                        "old_downstream_task_id": old_task_id,
                        "new_downstream_task_id": None,
                        "control_outcome": outcome or None,
                        "http_status": self._extract_http_status_from_exception(exc),
                        "error": payload_error,
                    },
                )
                session.commit()
                if self._is_retryable_downstream_transport_error(exc):
                    raise UpstreamError(payload_error)
                raise ValidationError(payload_error)
            else:
                delete_status = 200

            self._record_downstream_item_disposition(
                session,
                task,
                item,
                event_type="downstream_retry_fallback_delete_succeeded",
                message=(
                    f"旧下游任务已删除，继续重建: {item.downstream_service}:{old_task_id}"
                    if delete_status == 200 else
                    f"旧下游任务已不存在，继续重建: {item.downstream_service}:{old_task_id}"
                ),
                payload={
                    "stage_name": item.stage_name,
                    "old_downstream_task_id": old_task_id,
                    "new_downstream_task_id": None,
                    "control_outcome": outcome or None,
                    "http_status": delete_status,
                    "error": error_message or None,
                },
            )
            session.commit()

        dataflow_input_dir = self._resolve_vuln_scan_dataflow_input_dir(dataflow_result)
        source_dir = str(dataflow_result.get("source_root_path") or dataflow_result.get("source_dir") or "")
        if not dataflow_input_dir:
            raise ValidationError("数据流漏洞挖掘输入缺少 data_flow_root/dataflow_dir")
        if not source_dir:
            raise ValidationError("数据流漏洞挖掘输入缺少 source_dir")
        created = await self._downstream_create_task(
            session,
            task,
            item,
            service="dataflow_vuln_scan",
            token=token,
            payload={
                "title": f"{task.name}-{dataflow_result['function_name']}-scan",
                "data_flow_path": dataflow_input_dir,
                "source_dir": source_dir,
                "origin": _downstream_origin_payload(task, item),
            },
        )
        new_task_id = str(created.get("task_id") or created.get("id") or "").strip() or None
        item.downstream_task_id = new_task_id or item.downstream_task_id
        item.status = self._map_downstream_status(str(created.get("status") or "")) or "pending"
        item.started_at = item.started_at or _now()
        item.finished_at = None
        item.error_message = None
        self._clear_replacement_in_progress(item)
        self._record_downstream_item_disposition(
            session,
            task,
            item,
            event_type="downstream_retry_fallback_recreated",
            message=f"已重建新的下游任务: {item.downstream_service}:{new_task_id or '-'}",
            payload={
                "stage_name": item.stage_name,
                "old_downstream_task_id": old_task_id,
                "new_downstream_task_id": new_task_id,
                "control_outcome": outcome or None,
                "http_status": 200,
                "error": error_message or None,
            },
        )
        session.commit()
        return created

    async def _active_downstream_payload(
        self,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        token: str | None = None,
    ) -> dict[str, Any] | None:
        if not self._has_retryable_downstream_task(item):
            return None
        try:
            payload = await self._fetch_downstream_task_payload(task, item, token or "")
        except Exception:
            return None
        if not isinstance(payload, dict):
            return None
        mapped_status = self._map_downstream_status(str(payload.get("status") or ""))
        if mapped_status in {"pending", "queued", "dispatching", "running"}:
            return payload
        return None

    def _sort_downstream_payload_priority(self, payload: dict[str, Any]) -> tuple[int, float, str]:
        status = str(payload.get("status") or "").strip().lower()
        mapped = self._map_downstream_status(status)
        if mapped == "running":
            priority = 0
        elif mapped == "success":
            priority = 1
        elif mapped == "queued":
            priority = 2
        elif mapped in {"failed", "cancelled"}:
            priority = 3
        else:
            priority = 4
        comparable = (
            self._parse_comparable_datetime(payload.get("updated_at"))
            or self._parse_comparable_datetime(payload.get("finished_at"))
            or self._parse_comparable_datetime(payload.get("started_at"))
            or self._parse_comparable_datetime(payload.get("created_at"))
            or datetime.min
        )
        timestamp = comparable.timestamp() if comparable != datetime.min else float("-inf")
        return (priority, -timestamp, str(payload.get("task_id") or payload.get("id") or ""))

    async def _find_reusable_dataflow_payload(
        self,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        *,
        allow_rebind: bool = True,
    ) -> dict[str, Any] | None:
        item_id = str(item.id or "").strip()
        if not item_id:
            return None
        try:
            listed = await self._downstream_list_tasks(
                service="dataflow_vuln_scan",
                project_id=task.project_id,
                token=self._resolve_downstream_token(),
                parent_task_id=task.id,
                parent_stage_item_id=item_id,
                per_page=100,
                sort_by="updated_at",
                sort_order="desc",
            )
        except Exception:
            return None
        rows = listed.get("items") if isinstance(listed, dict) else None
        if not isinstance(rows, list):
            return None
        candidates = [row for row in rows if isinstance(row, dict)]
        if not candidates:
            return None
        candidates.sort(key=self._sort_downstream_payload_priority)
        selected = candidates[0]
        selected_task_id = str(selected.get("task_id") or selected.get("id") or "").strip()
        current_task_id = str(item.downstream_task_id or "").strip()
        if allow_rebind and selected_task_id and selected_task_id != current_task_id:
            item.downstream_task_id = selected_task_id
        return selected

    async def _find_reusable_entry_payload(
        self,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        token: str | None = None,
    ) -> dict[str, Any] | None:
        item_id = str(item.id or "").strip()
        item_key = str(item.item_key or "").strip()
        if not item_id and not item_key:
            return None
        try:
            listed = await self._downstream_list_tasks(
                service="entry_analyse",
                project_id=task.project_id,
                token=token,
                parent_task_id=task.id,
                parent_stage_name=item.stage_name,
                parent_stage_item_id=item_id or None,
                parent_stage_item_key=None if item_id else (item_key or None),
                per_page=100,
                sort_by="updated_at",
                sort_order="desc",
            )
        except Exception:
            return None
        rows = listed.get("items") if isinstance(listed, dict) else None
        if not isinstance(rows, list):
            return None
        candidates = []
        for row in rows:
            if not isinstance(row, dict):
                continue
            origin_item_id = str(row.get("parent_stage_item_id") or "").strip()
            origin_item_key = str(row.get("parent_stage_item_key") or "").strip()
            if item_id and origin_item_id == item_id:
                candidates.append(row)
                continue
            if not item_id and item_key and origin_item_key == item_key:
                candidates.append(row)
        if not candidates:
            return None
        candidates.sort(key=self._sort_downstream_payload_priority)
        selected = candidates[0]
        selected_task_id = str(selected.get("task_id") or selected.get("id") or "").strip()
        current_task_id = str(item.downstream_task_id or "").strip()
        if selected_task_id and selected_task_id != current_task_id:
            item.downstream_task_id = selected_task_id
        return selected

    def _entry_payload_matches_stage_item(
        self,
        item: BinarySecurityStageItem,
        payload: dict[str, Any] | None,
    ) -> bool:
        if not isinstance(payload, dict):
            return False
        item_id = str(item.id or "").strip()
        item_key = str(item.item_key or "").strip()
        origin_item_id = str(payload.get("parent_stage_item_id") or "").strip()
        origin_item_key = str(payload.get("parent_stage_item_key") or "").strip()
        if item_id:
            return bool(origin_item_id and origin_item_id == item_id)
        if item_key:
            return bool(origin_item_key and origin_item_key == item_key)
        return False

    async def _reconcile_entry_payload_binding(
        self,
        task: BinarySecurityTask,
        item: BinarySecurityStageItem,
        payload: dict[str, Any],
        token: str | None,
    ) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
        if str(item.downstream_service or "").strip() != "entry_analyse":
            return payload, None
        if self._entry_payload_matches_stage_item(item, payload):
            return payload, None
        mismatch_payload = {
            "downstream_service": item.downstream_service,
            "downstream_task_id": str(item.downstream_task_id or "").strip() or None,
            "expected_parent_stage_item_id": str(item.id or "").strip() or None,
            "expected_parent_stage_item_key": str(item.item_key or "").strip() or None,
            "observed_parent_stage_item_id": str(payload.get("parent_stage_item_id") or "").strip() or None,
            "observed_parent_stage_item_key": str(payload.get("parent_stage_item_key") or "").strip() or None,
        }
        rebound = await self._find_reusable_entry_payload(task, item, token)
        if rebound is not None and self._entry_payload_matches_stage_item(item, rebound):
            mismatch_payload["rebound_downstream_task_id"] = str(rebound.get("task_id") or rebound.get("id") or "").strip() or None
            return rebound, mismatch_payload
        return None, mismatch_payload

